pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps.
    if post_residual > 0 {
        let dead = if post_residual < 10 { 1.0 } else if post_residual < 20 { 0.6 } else if post_residual < 30 { 0.25 } else { 0.0 };
        score += dead * 40.0;
    }

    // Reward near-perfect fills.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // Open-bin pressure: discourage spreading when many bins are open.
    score += (open_bins_count as f64) * 0.15;

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize unless this is a great fit or pressure is high.
    if bin_residual == bin_capacity {
        let waste = (bin_capacity - item_size) as f64;
        score += 20.0 + waste * 0.3;
        if post_residual <= 10 {
            score -= 35.0;
        }
        if open_bins_count == 0 {
            score -= 60.0;
        }
    }

    // Lookahead: bonus if next item fits the resulting gap.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size.min(10) {
        score += 6.0;
    }

    // Progress-coupled tightening: later in stream, be more frugal.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.2;

    // Mean-residual coupling: prefer bins close to mean residual (balanced packing).
    score += ((bin_residual as f64) - mean_residual).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover lies in "usable"
    // classes (multiples of 10, or >= 20) are more valuable to preserve.
    let pr = post_residual;
    let class_bonus = if pr == 0 {
        -60.0 // perfect fit: strongly reward
    } else if pr % 10 == 0 {
        -25.0 // residual on the canonical grid, likely reusable
    } else if pr >= 20 {
        -8.0 // still moderately usable
    } else {
        15.0 // dead space class (1..=9)
    };
    score += class_bonus;

    // Integer-division threshold: residual chunk size relative to capacity.
    let quarter = bin_capacity / 4;
    if pr >= 3 * quarter {
        score -= 12.0;
    } else if pr < quarter && pr > 0 {
        score += 10.0;
    }

    // Lookahead coupling: does next item fit in the post-residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 20.0; // chain two items: excellent
            // harmonic match: next item and post_residual share a class
            if pr % next_item_size == 0 || next_item_size % 10 == 0 && pr % 10 == 0 {
                score -= 10.0;
            }
        } else if next_item_size <= bin_residual {
            score += 5.0; // next item would have fit before this placement
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new one
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless current bins are crowded.
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64) * (mean_residual / bin_capacity as f64);
        score += 45.0 - 10.0 * pressure;
        // If next item is large, a fresh bin is more attractive
        if next_item_size > bin_capacity / 2 {
            score -= 15.0;
        }
    }

    // Stream progression: late in the stream, prefer tightening fills.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (bin_residual - post_residual) as f64 / item_size.max(1) as f64;

    // Deviation from mean residual: prefer bins tighter than average.
    score += 0.05 * ((post_residual as f64) - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold any
    // plausible future item (<= 10, or <= next item) are pure waste.
    let min_item = 1u32;
    if post_residual < min_item {
        score -= 1000.0; // perfect fit, no dead space at all
    } else if post_residual <= 10 {
        score += 60.0; // unusable sliver -> strong penalty
    } else if post_residual < item_size.min(next_item_size.max(1)) && post_residual < 20 {
        score += 25.0; // gap too small for likely successors
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * tightness;

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Pressure from number of open bins: consolidate when many bins are open.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (open_bins_count as f64) * (1.5 + 3.0 * progress);

    // Prefer bins with below-average residual (keep large residuals for large items).
    let avg = mean_residual.max(0.0);
    if (bin_residual as f64) > avg + 1.0 {
        score += 2.0 * (bin_residual as f64 - avg);
    } else {
        score -= 1.0 * (avg - bin_residual as f64);
    }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 120.0;
    } else if next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size <= 10 {
        score -= 40.0;
    }

    // New-bin candidate: baseline cost of opening a fresh bin, modulated by
    // how bad the alternatives look (many open bins with large residuals).
    if bin_residual == bin_capacity {
        score = 100.0 + (open_bins_count as f64) * 0.5 - 0.3 * avg;
        if fitting_bins_count == 1 {
            score += 200.0; // never open a new bin when only one bin fits
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold
    // anything (below the minimum plausible item footprint) are pure waste.
    // Penalize them heavily, more so as the stream progresses.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if post_residual < 10 {
        score += 60.0 + 40.0 * progress;
    } else if post_residual <= 15 {
        score += 25.0 + 15.0 * progress;
    }

    // Reward very tight fits (small but still usable post_residual).
    if post_residual >= 10 && post_residual <= 25 {
        score -= 18.0;
    } else if post_residual <= 40 {
        score -= 8.0;
    }

    // Perfect fill is ideal.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Open-bin pressure: discourage scattering items across many bins,
    // but relax pressure near the end of the stream (consolidation matters less).
    score += open_bins_count as f64 * (1.5 + 2.5 * progress);

    // Mean residual coupling: bins whose residual is far below the mean
    // are already tight; placing here is fine. Bins far above the mean
    // are loose; avoid dumping items there unless the fit is good.
    let dev = mean_residual - post_residual as f64;
    if dev < 0.0 {
        score += 0.15 * (-dev);
    }

    // Last-chance bin: if this is the ONLY bin that fits, strongly prefer
    // using it over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
        if post_residual < 10 {
            score += 35.0; // still punish truly dead gaps
        }
    }

    // Lookahead: if the next item fits exactly into the post_residual,
    // this placement chains perfectly — reward it.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // Next item still fits, but leaves a gap: mild reward.
        score -= 6.0;
    } else if next_item_size > post_residual && post_residual < 10 {
        // Dead gap the next item cannot use: extra penalty.
        score += 20.0;
    }

    // New-bin candidate: baseline attractiveness so a fresh bin is chosen
    // only when all open bins would create unusable dead space.
    if bin_residual == bin_capacity {
        score = 30.0 + open_bins_count as f64 * 2.0 - 10.0 * progress;
        // If some bin is a near-perfect fit, the new bin should lose.
        if post_residual == 0 { score = 200.0; }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small to be useful later
    // are heavily penalized. A residual gap is "dead" if it is smaller than
    // the smallest plausible item and also smaller than the lookahead item.
    let dead_threshold = 12u32.max(next_item_size.min(bin_capacity));
    if post_residual > 0 && post_residual < dead_threshold {
        // Dead space penalty grows non-linearly as the gap shrinks.
        let tightness = (dead_threshold - post_residual) as f64 / dead_threshold as f64;
        score += 40.0 + 60.0 * tightness * tightness;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 50.0;
    } else {
        // Usable leftover: mild reward proportional to how well it matches
        // the next item's size (a gap that can host the lookahead item is gold).
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0 + 0.2 * (post_residual - next_item_size) as f64;
        }
    }

    // Open-bin pressure: prefer keeping the number of open bins low, but
    // allow opening new bins early in the stream when few bins exist.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 6.0 * open_bins_count as f64 * (0.3 + 0.7 * progress);

    // Last-chance bonus: if this is the only bin that fits, strongly favor it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: make the empty bin attractive only when existing
    // residuals are large (poor fits everywhere) or the item is big relative
    // to typical remaining space.
    if bin_residual == bin_capacity {
        let poor_fits = mean_residual < item_size as f64 * 0.6;
        let big_item = item_size > 60;
        if poor_fits || big_item {
            score -= 25.0;
        } else {
            // Default: discourage opening a new bin when decent fits exist.
            score += 15.0 + 2.0 * open_bins_count as f64;
        }
    }

    // Mild alignment with global mean residual: prefer bins whose residual is
    // close to the item (tight packing across the fleet).
    score += 0.1 * (bin_residual as f64 - item_size as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Base: tight fit preferred (small post_residual), with non-linear polynomial coupling
    let mut score = pr * (1.0 + 0.8 * progress * progress);

    // Strong reward for very small residuals (near-perfect fit), smooth via cubic term
    let tightness = 1.0 - (pr / cap);
    score -= 25.0 * tightness * tightness * tightness;

    // Penalize residuals that are too small to fit typical future items (dead space)
    let min_future = if next_item_size > 0 { next_item_size.min(100) as f64 } else { 10.0 };
    if pr < min_future {
        score += (min_future - pr) * (1.5 + progress);
    } else {
        // Reward residuals that can still host the lookahead item
        score -= 2.0 * (1.0 - pr / cap);
    }

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0 + 30.0 * progress;
    }

    // New-bin candidate handling: mildly penalize opening new bins early,
    // but allow it when open bins are fragmented (high mean residual spread)
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - pr).abs();
        score += 15.0 - 10.0 * progress + 0.1 * open_bins_count as f64;
        // If no open bin fits well, opening a new bin is attractive
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
        if fragmentation > 30.0 {
            score -= 5.0;
        }
    }

    // Prefer bins whose residual deviates from the mean in a useful way (large residual used well)
    score -= 0.05 * (bin_residual as f64 - mean_residual) * (1.0 - progress);

    // Mild penalty for spreading across many bins
    score += 0.02 * open_bins_count as f64 * (0.5 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: which 10-wide slot it falls into.
    let res_class = post_residual / 10;
    let res_mod = post_residual % 10;

    // Residuals in classes that commonly match item sizes (0..=8 => 10..=90 usable)
    // are valuable; tiny unusable slivers (class 0 with nonzero mod) are dead space.
    if post_residual == 0 {
        score -= 60.0; // perfect closure, strongly reward
    } else if res_class == 0 {
        score += 45.0; // sliver < 10, almost surely dead space
    } else {
        // Reward residuals that are multiples of 10 (align with typical item sizes)
        if res_mod == 0 {
            score -= 12.0;
        }
        // Reward larger residual classes mildly (more future utility)
        score -= (res_class as f64) * 2.5;
    }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 55.0;
        } else if next_item_size < post_residual {
            // reward proportionally to how well next item uses the leftover
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 20.0 * fill;
        } else {
            // next item won't fit here: mild penalty for mismatch
            score += 8.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: an empty bin should only win when no open bin
    // offers a decent fit. Penalize it by the health of the open-bin population.
    if bin_residual == bin_capacity {
        // Base penalty so it loses against any reasonable fit...
        score += 30.0;
        // ...but relax the penalty when few bins can fit the item (scarcity),
        // and when open bins are already crowded (low mean residual).
        let scarcity = (3usize.saturating_sub(fitting_bins_count)) as f64;
        score -= scarcity * 12.0;
        let crowded = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        score -= crowded * 25.0;
        // Late in the stream, opening fresh bins is cheaper (fewer future regrets)
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= progress * 15.0;
    }

    // Slight preference for filling more-completed bins (waste-avoidance).
    let fill_frac = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 10.0 * fill_frac * fill_frac;

    // Mean-residual coupling: prefer bins deviating favorably from the average,
    // pushing selection toward bins whose residual is closer to typical sizes.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: residuals divisible by common
    // item-size classes (10, 20, 25, 50) are more reusable.
    let pr = post_residual;
    if pr == 0 {
        score -= 30.0; // perfect fit is ideal
    } else {
        // Dead-space penalty grows for small, "odd" leftovers.
        if pr < 10 {
            score += 45.0; // unusable dead space
        } else if pr % 10 == 0 {
            score -= 12.0; // aligns with decade class items
        }
        if pr % 25 == 0 {
            score -= 8.0;
        }
        if pr % 50 == 0 {
            score -= 10.0;
        }
        // Integer-division thresholds: big leftovers are flexible.
        if pr / 25 >= 2 {
            score -= 6.0;
        }
        if pr < 20 {
            score += 18.0;
        }
    }

    // Lookahead coupling: can the next item fit into the post-residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 15.0; // chains nicely
            // Harmonic bonus: next item exactly matches a divisor class of pr
            if pr % next_item_size == 0 {
                score -= 10.0;
            }
        } else {
            score += 8.0; // next item won't fit here
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate handling: only open a fresh bin when existing
    // residuals are poor (tight / fragmented).
    if bin_residual == bin_capacity {
        let pressure = (mean_residual / bin_capacity as f64).min(1.0);
        if pressure < 0.35 {
            score -= 25.0; // open bins are nearly full -> new bin is fine
        } else {
            score += 35.0; // prefer packing into existing bins
        }
        // Early stream: allow spreading slightly.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 10.0;
    }

    // Mild preference to balance across many open bins.
    score += open_bins_count as f64 * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold
    // even the smallest plausible future item are dead space -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Penalize residuals that cannot fit the lookahead item either.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0 + (next_item_size - post_residual) as f64;
    }

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 20.0 * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Open-bin pressure: discourage spreading into many bins unless fit is tight.
    let pressure = open_bins_count as f64 / (1.0 + step_index as f64 / total_items.max(1) as f64);
    score += 2.0 * pressure * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Mean residual coupling: prefer bins whose residual is below the mean
    // (concentrate filling), penalize filling already-large-residual bins.
    if (bin_residual as f64) > mean_residual {
        score += 5.0;
    } else {
        score -= 5.0;
    }

    // New-bin candidate: only attractive when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        let poor_options = if fitting_bins_count == 0 { 0.0 } else {
            (post_residual as f64).min(0.0)
        };
        score = 60.0 + poor_options
            - if next_item_size > 0 && next_item_size >= item_size { 10.0 } else { 0.0 };
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: subtract proportionally to how well the item fills the bin.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 40.0 * fill_ratio;

    // Lookahead: if the next item fits into the post-residual, this bin stays useful.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Excellent chaining: residual is reusable, heavily reward.
            let chain_fit = next_item_size as f64 / post_residual.max(1) as f64;
            score -= 25.0 * chain_fit;
        } else {
            // Residual becomes dead space unless it's tiny; penalize mid-size dead gaps.
            let dead = post_residual as f64;
