    } else if post_residual >= 10 && post_residual < 20 {
        score += 3.0; // awkward small gap
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space into
    // capacity-fraction buckets (0, (0,25], (25,50], (50,75], (75,100]).
    let cap = bin_capacity as f64;
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    let three_quarter = 3 * bin_capacity / 4;

    // Perfect fit is divine: heavily reward it.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize residuals that fall into "dead zone" classes — too small
        // to be useful for typical items (min item size 1, but realistically
        // small leftovers accumulate). Class = post_residual / quarter.
        let class = post_residual / quarter.max(1);
        score += class as f64 * 12.0;

        // Integer-division thresholds: residual that cannot hold any plausible
        // next item (next_item_size known) is dead space.
        if next_item_size > 0 {
            if post_residual >= next_item_size {
                // Reward leaving room for the lookahead item, scaled by how
                // snugly it fits (harmonic coupling of residual & next size).
                let slack = post_residual - next_item_size;
                score -= 40.0 - (slack.min(50) as f64) * 0.5;
            } else {
                // Dead space relative to the lookahead: penalize proportionally.
                score += (next_item_size - post_residual) as f64 * 0.8;
            }
        }

        // Modulo arithmetic: residuals that are divisors-friendly (multiples
        // of 10 or 25) pair well with common item sizes — slight reward.
        if post_residual % 10 == 0 {
            score -= 6.0;
        }
        if post_residual % 25 == 0 {
            score -= 4.0;
        }
        // Odd, awkward residuals get a small nudge penalty.
        if post_residual % 2 == 1 {
            score += 2.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: empty bin starts with full residual; encourage it
    // only when the current item is large relative to capacity (poor fit
    // anywhere else) or when mean residual across open bins is very low
    // (all open bins are nearly full).
    if bin_residual == bin_capacity {
        let frac = item_size as f64 / cap;
        score -= 10.0 + 40.0 * frac; // baseline attractiveness of fresh bin
        if mean_residual < 15.0 {
            score -= 25.0; // open bins are nearly full -> new bin is good
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 15.0; // fresh bin also accommodates the lookahead
        }
    } else {
        // Reward filling bins that are already relatively full (tight packing).
        let fill = (bin_capacity - bin_residual) as f64 / cap;
        score -= 20.0 * fill;
    }

    // Stream progression: late in the stream, prefer closing out bins
    // (minimize spread of residual across many open bins).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (1.0 - progress) * 0.5;
    score -= progress * 8.0;

    // Coupling with mean residual: bins far below mean residual are
    // under-filled; prefer them slightly to balance the pool.
    let dev = mean_residual - post_residual as f64;
    score += dev * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

