    // allow a new bin when the fit is bad.
    score += (open_bins_count as f64).sqrt() * 2.0;

    // New-bin candidate logic: an empty bin is attractive only if this bin's
    // fit would leave a large dead gap, or if the next item fits the residual
    // better than this one does.
    if bin_residual == bin_capacity {
        // Baseline cost of a fresh bin: mild, so it loses against decent fits
        // but wins against wasteful placements.
        score = 35.0;
        if next_item_size > 0 && next_item_size as f64 > item_size as f64 {
            score -= 10.0; // next item is bigger; fresh capacity is useful
        }
        if fitting_bins_count <= 2 && post_residual == bin_capacity {
            // no open bin fits well anyway
            score -= 15.0;
        }
    } else {
        // If the next item would fit this bin's post_residual better than the
        // current item, slightly penalize using this bin now.
        if next_item_size > post_residual && next_item_size <= bin_residual {
            score += 15.0;
        }
    }

    // Mild progression term: later in the stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 8.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
