}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Base: prefer minimal post residual (tight fit).
    let mut score = post_residual as f64;

    // Tightness ratio: reward near-full packing non-linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize unusable dead space: if post_residual is smaller than the
    // smallest plausible item (1), no penalty needed; larger residuals that
    // still can't hold next_item_size are wasted.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 12.0 + 0.15 * post_residual as f64;
    }
    // Reward bins whose post_residual exactly accommodates the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Global fragmentation pressure: when mean residual is low, conserve
    // open-bin space more aggressively.
    let frag = 1.0 - (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
    score += frag * 8.0 * (post_residual as f64 / bin_capacity as f64);

    // Time horizon: early in the stream, be more willing to open new bins
    // (better long-run structure); late in the stream, squeeze into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * 6.0 * (bin_residual == bin_capacity) as i32 as f64;
    score -= progress * 10.0 * (bin_residual < bin_capacity) as i32 as f64;

    // New-bin candidate: only attractive when the item is large relative to
    // capacity or when existing bins are very fragmented.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 / bin_capacity as f64;
        score = bin_capacity as f64 - 20.0 * large_item
            - 15.0 * frag
            - 10.0 * (fitting_bins_count == 0) as i32 as f64;
    }

    // Mild penalty for spreading across many open bins when item is small.
    score += 0.5 * open_bins_count as f64 * (1.0 - item_size as f64 / bin_capacity as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = (step_index as f64) / (total_items as f64).max(1.0);
    let mut score = pr;

    // Non-linear waste penalty: residuals are costlier as the stream progresses.
    let waste_curve = pr * pr / cap;
    score += 0.9 * waste_curve * (0.35 + 0.65 * progress * progress);

    // Reward tight fits (small post_residual) with a smooth saturating bonus.
    let tightness = 1.0 - pr / cap;
    score -= 8.0 * tightness.powf(3.0);

    // Lookahead coupling: bonus if next item fits the post residual smoothly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fit = (pr - nxt).max(0.0);
        let fit_quality = 1.0 - fit / cap;
        score -= 6.0 * fit_quality * fit_quality;
        // Penalize if next item cannot fit: dead-end risk grows with progress.
        if nxt > pr {
            score += 5.0 * progress;
        }
    }

    // Last-chance bonus: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 10.0;
    } else if fitting_bins_count > 1 {
        score += 1.5 * (fitting_bins_count as f64 - 1.0).sqrt();
    }

    // Mild penalty for spreading across many bins relative to mean residual.
    score += 0.4 * (open_bins_count as f64).ln() * (pr / cap - mean_residual / cap).abs();

    // New-bin candidate: neutral-ish baseline, slightly penalized early,
    // more acceptable late when open-bin residuals are large.
    if bin_residual == bin_capacity {
        let open_pressure = (mean_residual / cap).max(0.0);
        score = cap * (0.85 + 0.3 * progress) - 12.0 * open_pressure * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of the post residual (integer division buckets) ---
    // Perfect fit class (0..=3): reward strongly.
    if post_residual <= 3 {
        score -= 60.0;
    } else {
        // Class residuals into harmonic buckets of 10: smaller bucket = better.
        let class = post_residual / 10; // 0..10
        score += class as f64 * 4.0;
    }

    // Dead-space penalty: residual below the smallest plausible item is wasted.
    if post_residual > 0 && post_residual < 5 {
        score += 25.0;
    }

    // --- Coupling with next item (lookahead k=2) ---
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Bin remains usable for the next item: reward, more if snug.
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 + 10.0 * (1.0 - slack / bin_capacity as f64);
        } else if post_residual >= next_item_size / 2 {
            // Partial usability: mild penalty proportional to mismatch.
            score += 8.0;
        } else {
            // Bin becomes nearly useless for the next item: penalize.
            score += 12.0 + (post_residual as f64) * 0.2;
        }
    }

    // --- Last-chance bin (only fitting bin) ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Neutral base: opening a fresh bin costs ~ a full residual of waste.
        score = bin_capacity as f64 * 0.55;
        // Prefer new bin late in the stream or when open bins are fragmented.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 20.0 * progress;
        if open_bins_count == 0 {
            score -= 100.0; // must open first bin
        }
        // If mean residual of open bins is large, reusing them is fine; make new bin less attractive.
        score += (mean_residual / bin_capacity as f64).max(0.0) * 25.0;
        // If next item is large, a fresh bin is valuable.
        if next_item_size >= 50 {
            score -= 10.0;
        }
    }

    // --- Global fragmentation pressure ---
    // Encourage balancing residuals toward the mean when many bins are open.
    let diff = (post_residual as f64 - mean_residual).abs();
    score += diff * 0.05 * (open_bins_count as f64).min(10.0);

    // Mild progress modulation: tighter packing matters more later in the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny leftovers (1..=10) are almost certainly
    // unusable for future items; penalize them quadratically on top of the base.
    if post_residual > 0 && post_residual <= 10 {
        score += (11 - post_residual as f64) * (11 - post_residual as f64) * 3.0;
    }
    // Medium gaps (11..=19) are risky too: many items won't fit them.
    if post_residual >= 11 && post_residual <= 19 {
        score += (20.0 - post_residual as f64) * 2.0;
    }
    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 60.0;
    }
    // Post residual that could still host the lookahead item is valuable.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }
    // Post residual that can host nothing typical (items >= 1 but realistically >=10):
    // a gap of 1..=9 is dead space; already penalized above.
    // Reward filling a bin nearly full (residual was tight).
    let tightness = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= tightness * 10.0;

    // Open-bin pressure: discourage scattering across many bins unless the fit is good.
    score += (open_bins_count as f64) * 0.5;

    // Mean-residual coupling: if this bin is far below the mean residual,
    // it's the "junkiest" bin — prefer filling it to consolidate waste.
    score -= (mean_residual - bin_residual as f64) * 0.8;

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoids leaving a fitting bin stranded).
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin has no dead space yet, but opening
    // a new bin while open bins can fit is wasteful. Make the new bin moderately
    // unattractive, but attractive when the item fits poorly everywhere else
    // (large post_residual elsewhere is already penalized).
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; decays as stream progresses.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 35.0 - 10.0 * progress;
        // If the next item is large and would fit well in a fresh bin, slight bonus.
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits: small post_residual is excellent.
    if post_residual == 0 {
        score -= 500.0; // perfect closure, best possible outcome
    } else if post_residual <= 5 {
        score -= 120.0;
    } else if post_residual <= 15 {
        score -= 40.0;
    }

    // Aggressive 2-step lookahead: if the next item exactly fits the leftover,
    // this bin is a perfect pipeline target.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 300.0; // chained perfect fit across two steps
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 150.0 * (1.0 - slack / 50.0).max(0.0);
        } else {
            // Next item cannot use the leftover: leftover risks becoming dead space.
            let waste = (next_item_size - post_residual) as f64;
            score += 20.0 + waste * 0.5;
        }
    } else {
        // Last item: strongly prefer filling a bin as tightly as possible.
        score -= 80.0;
    }

    // Compare post_residual against mean residual: leaving a bin below-average
    // residual means we consumed the "scarce" space well.
    score -= (mean_residual - post_residual as f64) * 1.5;

    // Last-chance bin: if this is the only bin that fits, using it avoids
    // opening a new bin — strong reward, scaled by how well it fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0 + item_size as f64 * 0.3;
    }

    // New-bin candidate (pristine empty bin): only attractive when the item is
    // large relative to capacity or no open bin fits well. Penalize opening a
    // new bin for small items that existing bins could absorb.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        score += 90.0 - fill_ratio * 120.0;
        if next_item_size > 0 && next_item_size >= (bin_capacity - item_size) {
            // next item can't share the new bin anyway; opening is less useful
            score += 25.0;
        }
        // Early in the stream, having spare bins is cheaper; late, consolidate.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 30.0;
        // If many bins are open, discourage spreading further.
        score += open_bins_count as f64 * 4.0;
    }

    // Mild penalty for leaving large awkward residuals (dead space risk).
    if post_residual > 40 {
        score += (post_residual as f64 - 40.0) * 0.8;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Time horizon: progress through the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward tight fits: small post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 15.0;
    }

    // Penalize creating dead space too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Lookahead coupling: if the next item fits in the post residual, reward this placement.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item chains nicely; reward proportionally to how snugly it fits.
            let chain_slack = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - chain_slack / bin_capacity as f64);
        } else {
            // Next item won't fit here; penalize slightly more if we leave a large awkward gap.
            let gap = post_residual as f64;
            if gap > 0.0 && gap < next_item_size as f64 {
                score += 6.0 * (gap / bin_capacity as f64);
            }
        }
    } else {
        // Last item: prefer any fit, weight by tightness only.
        score -= 10.0;
    }

    // Last-chance bin: strongly favor using a bin that is the only one that can fit the item.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // Competition among fitting bins: mild penalty scaled by competition size,
        // letting tightness and lookahead dominate the ranking.
        score += 2.0 * (fitting_bins_count as f64 - 1.0).min(5.0);
    }

    // New-bin candidate logic: brand-new empty bin.
    if bin_residual == bin_capacity {
        // Early in the stream, opening bins is cheap; later, prefer reusing.
        let open_penalty = 20.0 + 40.0 * progress;
        // Penalize opening a new bin when many open bins exist (encourage consolidation).
        let consolidation = (open_bins_count as f64).ln().max(0.0) * 8.0;
        score += open_penalty + consolidation;
        // But if the item is huge and no open bin leaves room for the lookahead, opening is fine.
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 10.0;
        }
        // Very late in the stream, opening a fresh bin for a perfect-fill item is fine.
        if progress > 0.9 && item_size >= 90 {
            score -= 30.0;
        }
    } else {
        // Existing bin: slight reward for keeping bins consolidated.
        score -= 3.0;
    }

    // Global mean-residual coupling: if this bin's residual is far below the mean,
    // it is a "small" bin; prefer filling small bins to balance the pool.
    let residual_diff = mean_residual - bin_residual as f64;
    score += 0.05 * residual_diff;

    // Prefer using bins whose remaining space is least usable for future average items.
    let avg_item = if total_items > 0 {
        // crude estimate: item sizes 1..100, use current item as proxy blended with 50.
        0.5 * item_size as f64 + 25.0
    } else {
        50.0
    };
    if post_residual > 0 && (post_residual as f64) < avg_item * 0.5 {
        // Small leftover: nearly dead space, but small bins should be drained first.
        score -= 5.0 * (1.0 - (post_residual as f64) / (avg_item * 0.5));
    }

    // Mild penalty for spreading across many open bins early (keeps optionality later).
    if open_bins_count > 8 && progress < 0.5 {
        score += 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: quadratic in normalized post residual (prefer tight fits, punish both extremes mildly)
    let x = pr / cap;
    let mut score = x * x * cap;

    // Non-linear coupling of post residual with stream progress:
    // late in stream, tight fits matter more (waste penalized super-linearly)
    score += 0.8 * pr * progress * (1.0 + x);

    // Reward filling a bin nearly exactly, stronger as stream progresses
    let fill = 1.0 - x;
    score -= 0.5 * fill * fill * cap * (0.3 + 0.7 * progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 6.0 + 4.0 * progress;
    }

    // Lookahead: if next item fits in post residual, reward; else penalize
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            score -= 1.5 * (1.0 - (pr - nxt) / cap);
        } else {
            score += 1.0 * (nxt - pr) / cap;
        }
    }

    // Mild pressure to reuse existing bins vs opening new ones
    score += 0.05 * open_bins_count as f64;

    // Prefer bins below mean residual slightly (balance spread of dead space)
    score += 0.3 * (pr as f64 - mean_residual) / cap;

    // New-bin candidate: neutral-ish baseline, only chosen if open bins are bad fits
    if bin_residual == bin_capacity {
        score += 3.0 + 2.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the residual after placement: capacity fractions.
    // Class 0: post_residual == 0 (perfect fit) -> strongest reward.
    // Class 1: tiny dead space (<= cap/12) -> strong reward.
    // Class 2: medium (<= cap/4) -> mild reward.
    // Class 3: large but still next-item friendly -> neutral.
    // Class 4: large dead space that nothing small can use -> penalty.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let class = if post_residual == 0 { 0 }
        else if post_residual <= bin_capacity / 12 { 1 }
        else if post_residual <= bin_capacity / 4 { 2 }
        else if post_residual <= bin_capacity / 2 { 3 }
        else { 4 };

    match class {
        0 => { score -= 60.0; }
        1 => { score -= 40.0; }
        2 => { score -= 12.0; }
        3 => { score += 6.0; }
        _ => { score += 25.0; }
    }

    // Lookahead coupling: does next_item_size fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Reward scaled by how well the next item fills the leftover space.
            let fill = next_item_size as f64 / post;
            score -= 18.0 + 14.0 * fill;
            // Extra harmonic bonus: next item exactly divides leftover space.
            if post_residual % next_item_size == 0 { score -= 10.0; }
        } else {
            // Next item cannot use this bin's leftover: penalize dead space more.
            score += 8.0;
        }
    }

    // Last-chance bin: using it avoids opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Tightness reward: prefer bins where the item fills a large fraction.
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 10.0 * tightness;

    // Modulo-based harmonic tier on item size relative to capacity quarters.
    let quarter = bin_capacity / 4;
    let tier = match item_size % (2 * quarter) {
        0 => -6.0,          // exactly half-capacity multiples pair well
        q if q < quarter => -3.0,
        _ => 2.0,
    };
    score += tier;

    // Mild pressure to consolidate as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 4.0 * progress * (post / cap);

    // Prefer bins already below mean residual (filling looser bins first).
    score += 0.05 * (mean_residual - post);

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 0.0 } else { 1.0 };
        score += 30.0 * desperation + 10.0 * (post / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Strict dead-space avoidance: gaps that no plausible item (>=1) can use well.
    // A residual that is very small (< 10) is "dead" — penalize it extra hard.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual >= 10 && post_residual < 25 {
        // Awkward mid gap: partially dead depending on stream position.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 12.0 * (0.5 + 0.5 * progress);
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 60.0;
    }

    // Reward tight fits relative to the item (filling ratio).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill_ratio;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Open-bin pressure: when many bins are open, prefer consolidating into
    // existing bins (penalize new-bin tendency); when few are open, allow it.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize with pressure and by how much it wastes
        // capacity given the item, but allow it when existing residuals are poor.
        let waste = cap - item_size as f64;
        let mean_fit_quality = 1.0 - (mean_residual / cap).abs();
        score += 15.0 + 8.0 * pressure + 0.2 * waste - 20.0 * mean_fit_quality;
        // If no existing bin is a good fit, opening a new bin becomes attractive.
        if fitting_bins_count <= 1 {
            score -= 35.0;
        }
    } else {
        // Existing bin: mild reward to keep open-bin count low.
        score -= 4.0 * pressure;
    }

    // Lookahead: if the next item fits into the post residual, reward this placement.
    if next_item_size > 0 && (next_item_size as f64) <= post {
        score -= 18.0;
    } else if next_item_size > 0 && post > 0 {
        // Next item won't fit: residual becomes dead space until stream ends.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 6.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // ---- Aggressive 2-step lookahead matching ----
    if post_residual == 0 {
        // Bin closed exactly: ideal outcome, lookahead irrelevant.
        score -= 30.0;
    } else if next_item_size > 0 && (post_residual as u64) >= (next_item_size as u64) {
        // The next item also fits here: reward a tight two-item chain.
        let two_step_left = post_residual as f64 - next_item_size as f64;
        score -= 12.0 + 0.25 * next_item_size as f64 - 0.1 * two_step_left;
        if two_step_left == 0.0 {
            // Exact double fill: post_residual == next_item_size == 0 after two items.
            score -= 15.0;
        }
    } else if next_item_size > 0 {
        // Dead space: next item cannot use the remainder.
        let gap = next_item_size as f64 - post_residual as f64;
        score += 3.0 + 0.15 * gap;
    }

    // Prefer bins that are already tighter than the fleet average (best-fit flavor).
    score += 0.05 * (bin_residual as f64 - mean_residual).max(0.0);

    // Last-chance bin: if this is the only open bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate penalty: opening a fresh bin is discouraged early,
    // but becomes progressively more acceptable late in the stream.
    if bin_residual == bin_capacity {
        score += 10.0 - 4.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Prefer tight fits: reward small post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Penalize dead space that no plausible future item can fill.
    // Items can be as small as 1, so only huge residuals are truly dead,
    // but small residuals (< ~20) are hard to fill: penalize moderately.
    if post_residual < 20 {
        score += (20 - post_residual) as f64 * 0.5;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, strong bonus.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size < post_residual {
            // Next item fits: mild bonus scaled by how well it nests.
            let nest = next_item_size as f64 / post_residual as f64;
            score -= 10.0 * nest;
        } else {
            // Next item won't fit here: mild penalty if this placement
            // leaves a residual that is awkwardly just below next_item_size.
            let gap = (next_item_size - post_residual) as f64;
            if gap < 10.0 {
                score += 0.5 * (10.0 - gap);
            }
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // When many bins are open, consolidate into already-open bins
    // rather than spreading out; penalize opening new bins.
    if bin_residual == bin_capacity {
        // New-bin candidate: base penalty grows with number of open bins.
        score += 20.0 + 3.0 * open_bins_count as f64;
        // But if current item is large relative to mean residual and
        // would leave poor fits elsewhere, opening a fresh bin is fine.
        let mean_res = mean_residual;
        if mean_res > 0.0 {
            let fit_ratio = item_size as f64 / mean_res;
            if fit_ratio > 0.9 {
                score -= 25.0;
            }
        }
        // Early in the stream, new bins are cheap (few open bins).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * (1.0 - progress);
    } else {
        // Favor bins whose residual is close to the item (best fit style)
        // relative to the global mean residual.
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.1 * dev;
    }

    // Slight global pressure: as stream progresses, discourage waste.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (post_residual as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post-residual, with non-linear polynomial coupling to stream progress.
    // Early on, favor tight fits (low post_residual); late, tolerate larger residuals
    // less strictly but reward near-perfect fits more.
    let mut score = pr * (1.0 + 0.6 * progress);

    // Smooth non-linear interaction: quadratic-cubic coupling of normalized residual with progress.
    score += cap * (norm_pr * norm_pr) * (0.5 + 1.5 * progress * progress);
    score -= cap * (norm_pr * norm_pr * norm_pr) * (1.0 - progress);

    // Lookahead: if the next item fits the post-residual exactly or well, reward this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        let fit_ratio = next_item_size as f64 / pr.max(1.0);
        score -= 6.0 * fit_ratio * (1.0 - fit_ratio) * 4.0 * fit_ratio; // peaks at half-fit
        if next_item_size == post_residual {
            score -= 12.0; // perfect chaining
        }
    }

    // Last-chance bonus: this is the only fitting bin; strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 8.0 + 4.0 * progress;
    } else if fitting_bins_count > 1 {
        // Mild competition pressure: prefer bins among many candidates with tighter fits.
        score += 0.5 * (fitting_bins_count as f64).ln();
    }

    // Penalize bins far from the mean residual (outliers create fragmented space),
    // with strength that decays as stream progresses.
    let dev = (pr - mean_residual).abs();
    score += dev * 0.3 * (1.0 - 0.5 * progress);

    // New-bin candidate: only attractive when no open bin is a good fit.
    if bin_residual == bin_capacity {
        // Penalize opening new bins early / when plenty are open; allow late in stream.
        score += 10.0 + 25.0 * (1.0 - progress) - 3.0 * (open_bins_count as f64).ln().max(0.0);
        // If current item is large, a fresh bin is more acceptable.
        score -= 0.05 * item_size as f64;
    }

    // Small reward for filling bins nearly full (smoothly).
    score -= 4.0 * ((item_size as f64 / cap) * (1.0 - norm_pr)).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: exact fill (class 0) is ideal.
    let pr = post_residual;
    if pr == 0 {
        score -= 500.0; // perfect closure
    } else if pr < 10 {
        // dead space too small for any item (min size 1..100 stream): strong penalty
        score += 60.0 + (10 - pr) as f64 * 4.0;
    } else {
        // harmonic subclass via modulo: residuals divisible by 10 align with
        // common item granularities and are easier to combine later.
        if pr % 10 == 0 {
            score -= 8.0;
        } else if pr % 5 == 0 {
            score -= 3.0;
        }
        // integer-division threshold classes: large residual = very reusable
        let class = pr / 20; // 0..5 harmonic band
        score -= class as f64 * 6.0;
    }

    // Lookahead: does the next item fit in the resulting residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // reward leaving room for the known next item,
            // scaled by how snugly it fits (small leftover preferred)
            let leftover = pr - next_item_size;
            score -= 30.0 - (leftover as f64) * 0.3;
            if leftover == 0 {
                score -= 100.0; // chain fill: two perfect placements
            }
        } else {
            // next item won't fit here; penalize less if residual is large
            // enough to still be generically useful.
            if pr < 15 {
                score += 25.0;
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new
    // bin unless the fit is terrible (large post residual anyway dominates).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: brand-new empty bin.
    if bin_residual == bin_capacity {
        // Attractive when the current fit leaves large unusable residue
        // or when few bins fit the item (fragmentation risk).
        let bad_fit = pr as f64 / bin_capacity as f64; // high = wasteful placement
        score = score * 0.5 + 55.0 * bad_fit;
        if fitting_bins_count <= 1 {
            score -= 40.0; // no real alternative: opening fresh bin is fine
        }
        if next_item_size > 0 && next_item_size <= pr {
            score += 20.0; // don't open new bin when next item chains here anyway
        }
        // late in the stream, prefer consolidating into open bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 25.0 * progress;
    }

    // Mild pressure to prefer bins below mean residual (tighter bins first),
    // keeping mean residual balanced across the fleet.
    score += 0.05 * (mean_residual - bin_residual as f64).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps below the minimum item size are wasted forever.
    if post_residual < 10 && post_residual > 0 {
        score += 60.0 * (1.0 - post_residual as f64 / 10.0);
    }

    // Reward near-perfect fits strongly (sub-linear in post_residual).
    score -= 40.0 * (-post_residual as f64 / 12.0).exp();

    // If the next item fits exactly into the post-residual, big bonus.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 80.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // mild penalty if next item leaves yet another awkward gap
        let nxt_gap = post_residual - next_item_size;
        if nxt_gap < 10 {
            score += 15.0;
        } else {
            score -= 5.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Open-bin pressure: discourage scattering across many bins unless fit is good.
    score += (open_bins_count as f64).ln().max(0.0) * 4.0
        * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: prefer it only when this bin's fit is terrible.
    if bin_residual == bin_capacity {
        score += 25.0 - 40.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Slight preference to fill bins with larger mean residual (older, emptier bins).
    score -= (mean_residual - post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual).
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 20.0 * fit_ratio;

    // 2-step lookahead: strongly reward if the next item fits the post-residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 + 15.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here after placement: penalize proportionally to overshoot.
            let overshoot = (next_item_size - post_residual) as f64;
            score += 5.0 + 0.5 * overshoot;
        }
    }

    // Relative to mean residual: bins tighter than average are more valuable to fill.
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin: avoid opening a new bin when this is the only fitting one.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Penalize creating tiny unusable dead space (dead zone < 10).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Late in the stream, prefer closing bins (reduce open bin count pressure).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 5.0 * (open_bins_count as f64 / (1.0 + mean_residual / 50.0)).ln().abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual) nonlinearly.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 60.0 * tightness * tightness;

    // Penalize dead space: residuals too small for the smallest plausible item (1..100).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 18.0;
            // Extra reward for near-perfect two-item chain.
            let chain_waste = post_residual - next_item_size;
            if chain_waste < 8 {
                score -= 12.0;
            }
        } else {
            score += 10.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Many open bins: prefer consolidating into existing bins to reduce spread.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64) / (1.0 + mean_residual / 10.0);
    if bin_residual < bin_capacity {
        score -= 6.0 * pressure * (0.5 + progress);
    }

    // New-bin candidate: make it attractive only when existing fits are poor.
    if bin_residual == bin_capacity {
        // Base new-bin cost grows over time (discourage bin proliferation late).
        score += 20.0 + 25.0 * progress;
        // But reward opening a new bin when mean residual is fragmented/low.
        if mean_residual < (item_size as f64) * 0.9 {
            score -= 35.0;
        }
        if fitting_bins_count <= 1 {
            score -= 40.0;
        }
    }

    // Mild preference for filling bins that are already more depleted.
    let fill_ratio = 1.0 - (bin_residual as f64) / (bin_capacity as f64);
    score -= 8.0 * fill_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early: prefer tight fits but tolerate larger residuals (bins stay flexible).
    // Late: aggressively penalize wasted residual (dead space is costly).
    let t = progress;
    let poly = 1.0 + 2.0 * t * t + 1.5 * t * t * t;
    score += pr * pr / cap * 0.02 * poly;

    // Smooth interaction: residual relative to mean residual of open bins.
    let mr = if mean_residual > 0.0 { mean_residual } else { 1.0 };
    let rel = pr / mr;
    score -= (rel * rel - 1.0) * 3.0 / (1.0 + t * 2.0);

    // Reward filling bins nearly perfectly, stronger as stream progresses.
    let fill = 1.0 - pr / cap;
    score -= fill * fill * (10.0 + 20.0 * t);

    // Last-chance bin: strong smooth bonus to use it rather than open a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * t;
    }

    // Lookahead: bonus if the next item fits into the post-residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack = pr - nxt;
            score -= 8.0 - slack * 0.05 * poly;
        } else {
            score += (nxt - pr) * 0.1 * (1.0 + t);
        }
    }

    // Mild penalty for spreading across many open bins early on.
    score += open_bins_count as f64 * (0.5 - 0.4 * t);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: mod 10 buckets
    let pr = post_residual;
    let class = pr % 10;
    // Penalize residuals in awkward classes (1,2,3 are dead space; 10,20,... are reusable)
    let dead_penalty: f64 = match class {
        0 => -6.0,
        1 => 8.0,
        2 => 6.0,
        3 => 4.0,
        4 => 2.0,
        9 => -2.0,
        _ => 0.0,
    };
    score += dead_penalty;

    // Perfect-fit reward: post_residual divisible by common item sizes
    if pr == 0 {
        score -= 30.0;
    } else if pr % 10 == 0 {
        score -= 8.0;
    } else if pr % 5 == 0 {
        score -= 3.0;
    }

    // Integer-division thresholds: how many "next items" fit in post_residual
    if next_item_size > 0 {
        let nfit = pr / next_item_size;
        let nfit_f = nfit as f64;
        // Reward bins that can host the next item (chaining)
        if nfit >= 1 {
            score -= 5.0 + 3.0 * nfit_f.min(3.0);
            // Exact next-item fit is golden
            if pr == next_item_size {
                score -= 12.0;
            } else if pr % next_item_size == 0 {
                score -= 4.0;
            }
        } else {
            // Next item cannot follow here; penalize proportionally to wasted capacity fraction
            let frac = pr as f64 / cap;
            score += 4.0 * frac;
            // If next item barely misses (within 10), extra penalty (near-miss dead space)
            let miss = next_item_size as f64 - pr as f64;
            if miss > 0.0 && miss <= 10.0 {
                score += 3.0 * (1.0 - miss / 10.0);
            }
        }
    }

    // Capacity fraction coupling: prefer filling bins past half capacity
    let fill_frac = item_size as f64 / cap;
    score -= 10.0 * fill_frac;

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: neutral base, discourage when good fits exist
    if bin_residual == bin_capacity {
        // Base cost of opening a bin
        score += 12.0;
        // Open new bin if current bins are crowded (high mean fill)
        let mean_fill = 1.0 - mean_residual / cap;
        if mean_fill > 0.75 {
            score -= 10.0;
        }
        // Few fitting bins -> opening new bin is reasonable
        if fitting_bins_count <= 2 {
            score -= 5.0;
        }
        // Early stream: allow more bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 4.0 * (1.0 - progress);
    }

    // Mild preference for tightest existing fit among many options
    if fitting_bins_count > 1 {
        score += 1.5 * (fitting_bins_count.min(6) as f64 - 1.0);
    }

    // Small-bin residual consolidation: prefer placing into bins with small residual
    let res_frac = bin_residual as f64 / cap;
    score += 2.0 * res_frac * res_frac;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize gaps too small for any realistic item.
    if post_residual > 0 && post_residual < 10 {
