    }

    // Open-bin pressure: discourage spreading across many bins, but allow
    // opening a new bin when existing fits are poor (high post_residual).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.9 * open_bins_count as f64 * (1.0 + 0.5 * progress);

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Prefer bins tighter than the average residual (good consolidation).
    score -= 0.3 * (mean_residual - bin_residual as f64);

    // Slight preference for fuller bins overall.
    score -= 0.15 * (bin_capacity - bin_residual) as f64;

    // New-bin candidate: make it attractive only when item is large and
    // existing residuals would leave big dead space anyway.
    if bin_residual == bin_capacity {
        let waste_if_existing = mean_residual - item_size as f64;
        if waste_if_existing > 20.0 {
