}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (non-linear).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 60.0 * tightness * tightness;

    // 2-step lookahead: if the next item fits exactly in the post-residual, big reward.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let chain_fit = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - chain_fit / bin_capacity as f64);
        } else {
            // Penalize leaving residual that cannot host the next item,
            // scaled by how much dead space is wasted.
            let waste = post_residual as f64;
            score += 8.0 * (waste / bin_capacity as f64);
        }
    }

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Relative to mean residual: bins with residual below mean are more "loaded",
    // prefer filling those further to consolidate.
    score -= 5.0 * (mean_residual - bin_residual as f64) / bin_capacity as f64;

    // New-bin candidate handling: only attractive when no open bin is a decent fit
    // or open bins are nearly full.
    if bin_residual == bin_capacity {
        let mean_load = bin_capacity as f64 - mean_residual;
        let desperation = if fitting_bins_count == 0 {
            1.0
        } else {
            (mean_load / bin_capacity as f64).powi(3)
        };
        // Base cost of opening a new bin, discounted by desperation.
        score += 35.0 * (1.0 - desperation);
        // Early in the stream, opening bins is cheaper (builds a pool).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
    }

    // Mild penalty for many open bins (encourage consolidation).
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
