    // Penalize dead space that is too small to hold typical future items
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual >= 10 && post_residual < item_size {
        score += 5.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 {
            score += 0.35 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // current item is large and open bins are fragmented
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = (mean_residual - post_residual as f64).abs();
        let mut new_bin_penalty = 45.0;
        // Prefer opening a new bin for very large items that leave tiny slivers elsewhere
        if item_size >= 70 && fitting_bins_count > 0 && mean_residual < item_size as f64 + 5.0 {
            new_bin_penalty -= 40.0;
        }
        // Late in the stream, avoid opening too many bins
        new_bin_penalty += 20.0 * progress;
        // Many open bins with high mean residual => keep packing into them
        new_bin_penalty += 0.5 * open_bins_count as f64 * (mean_residual / bin_capacity as f64);
        // Fragmentation penalty: if this bin's residual deviates a lot from mean, new bin helps
        new_bin_penalty -= 0.15 * fragmentation;
        score += new_bin_penalty;
    }

    // Mild preference for bins with residual close to the mean (balance preservation)
    score += 0.1 * ((bin_residual as f64 - mean_residual).abs());

    // Early stream: be conservative, keep bins flexible; late stream: fill greedily
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 8.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let t = progress * (1.0 - progress) * 4.0; // peaks mid-stream
    score -= t * 12.0 * norm_pr * norm_pr * (1.0 - norm_pr);

    // Penalize dead space more as stream progresses (less chance to fill it)
    let late = progress * progress;
    score += late * pr * 0.35;

    // Reward tight fits (small post_residual) with non-linear term
    score -= (1.0 - norm_pr).powi(3) * 8.0;

    // Last-chance bin bonus, smoothly weighted by progress
    if fitting_bins_count == 1 {
        score -= 6.0 + 8.0 * progress;
    }

    // Lookahead: if next item fits in post_residual, reward this placement
    if next_item_size > 0 && (next_item_size as u32) <= post_residual {
        let fit_quality = 1.0 - (post_residual - next_item_size as u32) as f64 / cap;
        score -= 4.0 + 6.0 * fit_quality * (0.5 + progress);
    }

    // Slight preference to consolidate when many bins are open
    score -= (open_bins_count as f64).ln().max(0.0) * (1.0 - norm_pr) * 2.0;

    // Mean residual deviation coupling
    score += 0.15 * (pr - mean_residual).abs() * (1.0 - t);

    // New-bin candidate: penalize slightly unless current bin would be nearly perfect
    if bin_residual == bin_capacity {
        score += 3.0 - 10.0 * (1.0 - norm_pr);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongest reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: classify leftover into usable bands.
    // Small leftovers (<10) are dead space for future items (min size 10).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // dead space penalty
    }

    // Class of residual via integer division thresholds (capacity fractions)
    let cap = bin_capacity as f64;
    let frac = post_residual as f64 / cap; // fraction of capacity wasted

    // Non-linear waste penalty: quadratic in leftover fraction
    score += 30.0 * frac * frac;

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // next item fits: leftover after next placement
            let post2 = post_residual - next_item_size;
            score -= 40.0 - 2.0 * post2 as f64;
        } else {
            // next item won't fit here; penalize larger wasted residuals less
            score += 5.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 200.0;
    }

    // Prefer tighter bins: closeness of item to residual (best-fit sharpening)
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 20.0 * tightness;

    // Modulo arithmetic on post_residual: residuals that are multiples of
    // common item sizes (10, 20, 25, 50) are more reusable.
    let pr = post_residual;
    if pr % 10 == 0 && pr > 0 {
        score -= 8.0;
    }
    if pr % 25 == 0 && pr > 0 {
        score -= 6.0;
    }

    // Early stream: encourage opening bins / filling efficiently; late stream: consolidate
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.7 && bin_residual < bin_capacity {
        score += 3.0 * (post_residual as f64 - mean_residual).abs();
    }

    // Slight preference to spread when many bins open (avoid over-fragmenting one bin)
    if open_bins_count > 10 {
        score += 0.5 * post_residual as f64 / open_bins_count as f64;
    }

    // New-bin candidate: only attractive if no open bin fits well
    if bin_residual == bin_capacity {
        // baseline cost of opening a new bin; make it beat only bad fits
        score = cap * 0.85 + 10.0 * frac;
        if fitting_bins_count == 0 {
            score -= 1000.0; // must open a new bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps.
    if post_residual > 0 {
        let dead = if post_residual < 10 { 1.0 } else if post_residual < 20 { 0.6 } else if post_residual < 30 { 0.25 } else { 0.0 };
        score += dead * 40.0;
    }

    // Reward near-perfect fills.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // Open-bin pressure: discourage spreading when many bins are open.
    score += (open_bins_count as f64) * 0.15;

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize unless this is a great fit or pressure is high.
    if bin_residual == bin_capacity {
        let waste = (bin_capacity - item_size) as f64;
        score += 20.0 + waste * 0.3;
        if post_residual <= 10 {
            score -= 35.0;
        }
        if open_bins_count == 0 {
            score -= 60.0;
        }
    }

    // Lookahead: bonus if next item fits the resulting gap.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size.min(10) {
        score += 6.0;
    }

    // Progress-coupled tightening: later in stream, be more frugal.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.2;

    // Mean-residual coupling: prefer bins close to mean residual (balanced packing).
    score += ((bin_residual as f64) - mean_residual).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next item.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect chain fit: big reward.
        if post_residual == next_item_size {
            score -= 40.0;
        } else {
            score -= 25.0 / (1.0 + gap / 15.0);
        }
        // Penalize leaving residual too small for the next item (dead space for one step).
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.35;
        }
    } else {
        // Last item: pure tight-fit preference.
        score -= 10.0;
    }

    // Tightness reward: fraction of bin consumed by this item.
    let tightness = item_size as f64 / bin_capacity as f64;
    score -= 20.0 * tightness * tightness;

    // Perfect closure bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Last-chance bin: strong preference to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a bin unless current bin would waste a lot.
    if bin_residual == bin_capacity {
        score += 8.0;
        // But allow opening when mean residual across open bins is already small/dead.
        if mean_residual < item_size as f64 * 0.4 {
            score -= 20.0;
        }
        // Late in stream, prefer consolidation into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 6.0 * progress;
    }

    // Mild penalty for spreading across too many open bins.
    score += 0.15 * open_bins_count as f64;

    // Relative-to-mean coupling: bins tighter than average are better hosts.
    score -= (mean_residual - post_residual as f64) * 0.25;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to item size.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 40.0 * fit_ratio * fit_ratio;

    // Penalize dead space: post_residual too small to hold anything later.
    let dead = post_residual as f64;
    if dead > 0.0 && dead < 10.0 {
        score += 25.0 * (10.0 - dead);
    }

    // Lookahead: if the next item fits exactly in post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            score -= 12.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            score += 8.0 * (next_item_size as f64 / post_residual.max(1) as f64).min(3.0);
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    } else if fitting_bins_count > 1 {
        // Prefer the fullest among several candidates.
        score += 10.0 * (1.0 - (bin_residual as f64 / bin_capacity as f64));
    }

    // Time horizon: early in the stream, be conservative (prefer filling existing bins);
    // late in the stream, prioritize perfect packing.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 20.0 * t * fit_ratio;

    // Global state coupling: many open bins with high mean residual -> discourage
    // opening new bins; encourage consolidating into bins near mean residual.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize when open bins are plentiful and underused.
        let waste_pressure = (open_bins_count as f64) * (mean_residual / bin_capacity as f64);
        score += 30.0 + 15.0 * waste_pressure;
        // But if current item is huge and nothing else fits well, ease the penalty.
        if item_size as f64 > 0.7 * bin_capacity as f64 && fitting_bins_count == 0 {
            score -= 45.0;
        }
    } else {
        // Favor bins whose residual is close to (slightly above) the item.
        let gap = (bin_residual as f64 - item_size as f64).abs();
        score += 0.15 * gap;
        // Coupling with mean residual: prefer bins tighter than average.
        score += 8.0 * ((bin_residual as f64 - mean_residual) / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    // non-linear polynomial coupling of post_residual with progress
    let mut score = pr;
    score += 30.0 * norm_pr * norm_pr * (0.5 + progress);
    score -= 20.0 * norm_pr * progress * (1.0 - progress) * 4.0;
    // reward tight fits more as stream progresses
    score -= (item_size as f64 / cap) * 15.0 * progress;
    // last-chance bonus
    if fitting_bins_count == 1 {
        score -= 25.0;
    }
    // lookahead: if next item fits in post residual, reward
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 12.0 * (1.0 - (pr - next_item_size as f64) / cap);
    }
    // penalize opening new bin relative to open bins count
    if bin_residual == bin_capacity {
        score += 8.0 + mean_residual * 0.1;
    }
    // smooth interaction with mean residual
    score += 0.05 * (mean_residual - pr).abs() * (0.5 + progress);
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Harmonic class of post_residual: how "usable" is the leftover space?
    // Class 0: post == 0 (perfect fit) -> strong reward
    // Class 1: post in 1..=10 (dead space, likely unusable since min item is small) -> penalty
    // Class 2: post divisible by common item sizes -> mild reward
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score += 25.0; // tiny dead space is wasted capacity
    } else if post_residual % 10 == 0 {
        score -= 12.0; // aligns with round item sizes
    } else if post_residual % 5 == 0 {
        score -= 6.0;
    }

    // Lookahead: does next item fit in the post-residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item fits exactly or nearly: reward tight chaining
            let slack = (post_residual - next_item_size) as f64;
            score -= 18.0 * (1.0 - slack / cap);
        } else {
            // next item won't fit here: residual becomes dead if small
            if post_residual < next_item_size && post_residual < 20 {
                score += 15.0;
            }
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Prefer fuller bins when many bins are open (consolidation pressure)
    let fill_ratio = (bin_capacity - post_residual) as f64 / cap;
    score -= 20.0 * fill_ratio * (open_bins_count as f64 / (open_bins_count as f64 + 5.0));

    // New-bin candidate: only attractive when item fits poorly everywhere
    if bin_residual == bin_capacity {
        // base cost of opening a bin
        score += 45.0;
        // cheaper to open a new bin early in the stream or when few bins fit
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 25.0 * (1.0 - progress);
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below 10 are essentially unusable
    // (min item size 1..100 unknown, but small gaps waste capacity). Penalize
    // small nonzero post_residuals super-linearly.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64);
    }

    // Reward tight fits (post_residual small relative to item).
    let tightness = item_size as f64 / (item_size as f64 + post_residual as f64 + 1.0);
    score -= 25.0 * tightness;

    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; with few,
    // allow a new bin when the fit is bad.
    score += (open_bins_count as f64).sqrt() * 2.0;

    // New-bin candidate logic: an empty bin is attractive only if this bin's
    // fit would leave a large dead gap, or if the next item fits the residual
    // better than this one does.
    if bin_residual == bin_capacity {
        // Baseline cost of a fresh bin: mild, so it loses against decent fits
        // but wins against wasteful placements.
        score = 35.0;
        if next_item_size > 0 && next_item_size as f64 > item_size as f64 {
            score -= 10.0; // next item is bigger; fresh capacity is useful
        }
        if fitting_bins_count <= 2 && post_residual == bin_capacity {
            // no open bin fits well anyway
            score -= 15.0;
        }
    } else {
        // If the next item would fit this bin's post_residual better than the
        // current item, slightly penalize using this bin now.
        if next_item_size > post_residual && next_item_size <= bin_residual {
            score += 15.0;
        }
    }

    // Mild progression term: later in the stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 8.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post-residual matches the next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs();
        if diff == 0 {
            score -= 500.0; // next item fits this bin perfectly
        } else {
            score += diff as f64 * 0.5; // penalize mismatch
        }
        // If next item can't fit anywhere after this placement, prefer leaving room anyway.
        if next_item_size > post_residual && post_residual < 10 {
            score += 30.0; // tiny dead space is bad
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: only attractive when existing fits are poor.
    if bin_residual == bin_capacity {
        let base = 120.0 + mean_residual * 0.5;
        score += base;
        if next_item_size > 0 && next_item_size >= bin_capacity - item_size {
            score -= 60.0; // fresh bin pairs well with a large next item
        }
    }

    // Slightly prefer tighter-than-average bins.
    score += (mean_residual - bin_residual as f64) * 0.2;

    // Progression: be greedier with space as stream nears its end.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * (0.3 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let fit_ratio = item_size as f64 / bin_residual as f64;
    let mut score = post;

    // Reward tight fits: subtract based on how much of the residual is consumed
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize wasted dead space nonlinearly (small residuals are valuable)
    if post > 0.0 {
        score += (cap / post).ln() * 8.0;
    }

    // Lookahead: if next item fits exactly in the post residual, reward this placement strongly
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            score -= 12.0 * (next_item_size as f64 / post);
        } else {
            // next item won't fit here; slight penalty for leaving awkward leftover
            score += 5.0 * (1.0 - (next_item_size as f64 / cap));
        }
    } else {
        // last item: strongly prefer zero residual
        score -= 50.0 * (1.0 - post / cap);
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only attractive when current bins are poor fits
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_fits = (bin_residual - item_size) as f64; // waste if forced into an existing bin
        let threshold = 25.0 + 30.0 * (1.0 - progress) + 2.0 * (open_bins_count as f64).sqrt();
        if poor_fits > threshold {
            // opening a fresh bin is competitive
            score -= (poor_fits - threshold) * 0.8;
        } else {
            // keep using existing bins
            score += 40.0 + 10.0 * (open_bins_count as f64);
        }
        // prefer opening new bins when mean residual across open bins is low (bins nearly full)
        score -= (mean_residual / cap) * 15.0;
    } else {
        // existing bin: slight preference for fuller bins (smaller residual)
        score += 3.0 * (bin_residual as f64 / cap);
        // favor bins whose residual is below mean (they are the tight ones)
        if (bin_residual as f64) < mean_residual {
            score -= 4.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    let mut score = pr;

    // Smooth non-linear coupling: residual quality vs stream progress
    let tightness = 1.0 - norm_pr * norm_pr;
    score -= 14.0 * tightness * (0.3 + 0.7 * progress);

    // Penalize large post-residuals more heavily later in the stream (quartic term)
    score += 10.0 * norm_pr * norm_pr * norm_pr * norm_pr * progress;

    // Reward near-perfect fits with cubic boost
    let fit_quality = 1.0 - norm_pr;
    score -= 8.0 * fit_quality * fit_quality * fit_quality;

    // Lookahead: reward if post_residual can fit next item (smooth interaction)
    if next_item_size > 0 {
        let compat = (pr - norm_next * cap).max(0.0) / cap;
        score -= 6.0 * compat * (1.0 - progress) * compat;
    }

    // Last-chance bin bonus (smooth in fitting count)
    if fitting_bins_count == 1 {
        score -= 5.0 * (1.0 + progress);
    }

    // Mild penalty for spreading across many open bins
    score += 0.4 * (open_bins_count as f64).ln().max(0.0) * (1.0 - progress);

    // Mean residual coupling: prefer bins whose residual differs from mean when mean is large
    let dev = (pr - mean_residual) / cap;
    score += 3.0 * dev * dev * mean_residual / cap;

    // New-bin candidate: penalize opening a new bin unless residual would be well used
    if bin_residual == bin_capacity {
        score += 8.0 - 6.0 * norm_item * (1.0 + progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-fit residual: class 0 = perfectly full bin.
    let class = post_residual % 10;
    if class == 0 {
        score -= 40.0; // perfect fill, reward heavily
    } else if class <= 3 {
        score -= 12.0; // small dead space, likely usable by small items
    } else if class <= 6 {
        score += 6.0; // mid-range dead space, moderately wasteful
    } else {
        score += 14.0; // large dead space in 7..9, awkward
    }

    // Fractional capacity view: penalize leaving more than half a bin empty.
    let half = bin_capacity / 2;
    if post_residual > half {
        let over = (post_residual - half) as f64;
        score += 0.35 * over;
    }

    // Lookahead coupling: reward if next item exactly fills the post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size < post_residual {
            let nxt_class = (post_residual - next_item_size) % 10;
            if nxt_class == 0 {
                score -= 18.0;
            } else if nxt_class <= 3 {
                score -= 6.0;
            } else {
                score += 4.0 + 0.2 * ((post_residual - next_item_size) as f64);
            }
        } else {
            // next item cannot use this bin's remaining space: mild penalty
            score += 3.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Many open bins with slack: encourage consolidation (tight fits).
    if open_bins_count > 3 {
        score += 0.05 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);
    }

    // Early in the stream, keep bins tidy; late in the stream, accept loose fits.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 - 0.15 * progress;

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        let base = 55.0 + 0.5 * (post_residual as f64);
        // discourage new bins when a decent fitting bin exists
        score = base + if fitting_bins_count == 0 { -60.0 } else { 0.0 };
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (< min item size 1..100 -> threshold ~10)
    // are the worst outcome; amplify the penalty for tiny residuals.
    let dead_threshold: f64 = 12.0;
    let pr = post_residual as f64;
    if pr > 0.0 && pr < dead_threshold {
        // quadratic dead-space penalty for tiny gaps
        score += (dead_threshold - pr) * (dead_threshold - pr) * 2.0;
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 50.0;
    }

    // Tight fit reward: fraction of bin used by this placement
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 15.0;

    // Lookahead: if next item fits exactly in the post residual, strongly favor this bin
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        if gap < dead_threshold {
            score -= 25.0 - gap * 1.5;
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // residual too small for the next item: penalize proportionally
        score += 8.0;
    }

    // Open-bin pressure: discourage opening new bins when many bins are open
    if bin_residual == bin_capacity {
        // candidate new bin: base cost plus pressure from open bins
        score += 20.0 + open_bins_count as f64 * 3.0;
        // if this is the only fitting bin, opening a new bin is worse
        if fitting_bins_count == 1 {
            score += 15.0;
        }
        // early stream: prefer consolidating into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += (1.0 - progress) * 10.0;
    } else {
        // existing bin that is the last chance: strong reward to use it
        if fitting_bins_count == 1 {
            score -= 18.0;
        }
        // reward using bins with below-average residual (consolidation)
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        } else {
            score += 2.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction of the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // --- 2-step lookahead: reward when the next item fits exactly into post_residual ---
    if next_item_size > 0 {
        if next_item_size == post_residual {
            // Perfect chain: this placement leaves exactly the space the next item needs.
            score -= 60.0 + 25.0 * progress;
        } else if next_item_size < post_residual {
            // Next item fits: reward proportionally to how snugly it will fit.
            let slack = (post_residual - next_item_size) as f64;
            score -= 30.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item will NOT fit here: penalize leaving a large unusable gap
            // relative to what the next item needs.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.4 * gap.min(60.0);
        }
    } else {
        // Last item of the stream: just minimize leftover space.
        score -= 10.0;
    }

    // --- Mean-residual relative positioning ---
    // A bin with residual well below the mean is "tight": good to keep filling it,
    // but only if the item fits snugly (small post_residual).
    let residual_f = bin_residual as f64;
    if mean_residual > 0.0 {
        let tightness = (mean_residual - residual_f) / mean_residual;
        // Prefer filling bins that are tighter than average when the fit is snug.
        score -= 8.0 * tightness.clamp(-1.0, 1.0) * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // --- Last-chance bin: if this is the ONLY bin that fits, strongly prefer using it ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when no good fit exists:
        // penalize the fresh bin unless the current item leaves a lot of dead space
        // in every existing bin (i.e., the item is large relative to residuals).
        let snug_elsewhere = (mean_residual - item_size as f64).abs() < 5.0;
        if snug_elsewhere {
            score -= 20.0; // existing bins are all near-perfect fits anyway; fresh bin is neutral-worse
        } else {
            score += 35.0 + 30.0 * progress; // prefer squeezing into open bins
        }
        // A fresh bin never benefits from lookahead matching.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 5.0; // slight credit: fresh bin can serve the next item too
        }
    }

    // --- Waste shaping: gently convex penalty on large leftovers to avoid dead space ---
    let pr = post_residual as f64;
    score += 0.05 * (pr * pr) / bin_capacity as f64;

    // --- Small tie-break noise-free deterministic coupling ---
    score += 0.01 * (open_bins_count as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base tightness: strongly prefer small post_residual (nonlinear).
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score += 18.0 * tightness * tightness;

    // Lookahead: reward if the next item fits exactly into the leftover space.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chained fit
        } else if next_item_size <= post_residual {
            score -= 12.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Leftover too small for next item: penalize dead space more if it's tiny.
            if post_residual < 10 {
                score -= 6.0; // effectively closed bin, that's fine
            } else {
                score += 8.0 * ((post_residual - next_item_size) as f64 / bin_capacity as f64);
            }
        }
    }

    // Last-chance bin: strongly favor using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Prefer reusing bins over opening new ones when many bins are open.
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline penalty, relaxed late in the stream or when
        // open bins are on average too full to be useful.
        score += 22.0;
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 8.0 * progress;
        if mean_residual < item_size as f64 * 1.2 {
            score -= 15.0; // existing bins nearly useless, opening is good
        }
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size.min(bin_capacity) {
            score -= 4.0; // new bin leaves room for lookahead
        }
    } else {
        // Reward filling bins that are already mostly consumed.
        let fill = 1.0 - (bin_residual as f64 / bin_capacity as f64);
        score -= 10.0 * fill;
        // Slight preference to bins below mean residual (even out load) is bad;
        // instead prefer bins near-full: penalize deviation from tight fit.
        let dev = (bin_residual as f64 - item_size as f64 - mean_residual).abs();
        score += 0.05 * dev;
    }

    // Global pressure: with many open bins, discourage spreading into fresh space.
    score += 0.15 * open_bins_count as f64 * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);

    // Base: penalize leftover space, normalized.
    let mut score = post / cap;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early on, waste is cheap; later, waste becomes increasingly costly.
    let waste_coupling = (post / cap).powi(2) * (0.5 + 2.5 * progress * progress);
    score += waste_coupling;

    // Perfect fit reward: smooth bump near zero residual.
    score -= (1.0 - post / cap).powi(6) * (1.0 + progress);

    // Reward leaving a residual that still fits the lookahead item smoothly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fits_next = (post - nxt).max(0.0);
        let miss = (post - nxt).abs() / cap;
        score += miss * (1.0 - progress);      // early: care about lookahead
        score -= fits_next / cap * 0.3 * (1.0 - progress);
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin.
    if fitting_bins_count == 1 {
        score -= 1.5 + (bin_residual as f64 - item_size as f64) / cap;
    }

    // New-bin candidate: penalize slightly when many bins already fit the item,
    // but relax the penalty late in the stream when consolidation is done.
    let is_new_bin = (bin_residual as f64 - cap).abs() < 1e-6;
    if is_new_bin {
        score += 0.6 * (1.0 - progress) + 0.05 * open_bins_count as f64 / (1.0 + open_bins_count as f64);
        // If the item would leave a large dead space in any bin anyway, allow opening.
        score += (post / cap).powi(3) * progress;
    }

    // Mild preference for tighter bins (smaller residual) via smooth term.
    score += (bin_residual as f64 / cap).powi(2) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: perfect fits are golden.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Reward exact fits heavily.
    if post_residual == 0 {
        score -= 500.0;
    }

    // Small dead space (< 10) is nearly useless: penalize.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Harmonic classes: post_residual divisible by common item sizes (10..80 grid).
    if post_residual % 10 == 0 {
        score -= 25.0; // residual lands on a harmonic grid point, reusable
    } else if post_residual % 5 == 0 {
        score -= 8.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 200.0;
        } else if next_item_size < post_residual {
            let gap = post_residual - next_item_size;
            score -= 40.0 * (1.0 - gap as f64 / cap);
            if gap % 10 == 0 {
                score -= 15.0;
            }
        } else {
            // next item won't fit here: mild penalty proportional to wasted potential
            score += 10.0;
        }
    } else {
        // Last item: prefer tightest fill, ignore future concerns.
        score -= 30.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new one
    // unless fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
        if post_residual <= 20 {
            score -= 25.0;
        }
    }

    // New-bin candidate handling: penalize opening a new bin when stream is early
    // or many bins already open; reward when existing fits are bad.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * (1.0 - progress); // early on, new bins are okay-ish
        if fitting_bins_count > 0 {
            score += 55.0; // an open bin fits; don't open a new one lightly
        }
        if post_residual % 10 == 0 && post_residual > 0 {
            score -= 10.0; // fresh bin with harmonic residual potential
        }
    }

    // Mean residual coupling: prefer bins whose residual deviates favorably
    // (tighter than average gets rewarded).
    score -= 0.5 * (mean_residual - pr);

    // Fraction-of-capacity harmonic thresholds on post_residual.
    let frac = pr / cap;
    if frac < 0.05 { score -= 20.0; }
    else if frac < 0.15 { score += 15.0; }
    else if frac < 0.35 { score -= 5.0; }
    else if frac < 0.60 { score += 8.0; }

    // Integer-division threshold: residual >= half capacity is flexible.
    if post_residual >= bin_capacity / 2 {
        score -= 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that no item (min size 1..10) can
    // use are pure waste. Penalize small unusable gaps super-linearly.
    let pr = post_residual;
    if pr > 0 && pr < 10 {
        score += 60.0 * (10 - pr) as f64; // dead space: 1..9 residual is toxic
    } else if pr == 0 {
        // Perfect closure is the ideal outcome: reward strongly.
        score -= 80.0;
    } else if pr >= 10 && pr <= 20 {
        // Usable but awkward mid gap: mild penalty scaled by awkwardness.
        score += 8.0 * (20 - pr) as f64 / 10.0;
    }

    // Reward filling large fractions of the bin (tight fit preference).
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 25.0 * fill;

    // Open-bin pressure: with many open bins, prefer packing into existing
    // ones; a new empty-bin candidate (residual == capacity) gets penalized
    // progressively more as open_bins_count grows.
    if bin_residual == bin_capacity {
        score += 20.0 + 6.0 * open_bins_count as f64;
        // But if this bin is the last chance, opening a new bin is fine.
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    } else if fitting_bins_count == 1 {
        // Last-chance bin: strongly favor using it rather than wasting it.
        score -= 35.0;
    }

    // Lookahead: if next item fits exactly in the post residual, big reward
    // (this bin is perfectly chained for the next item).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack == 0 {
            score -= 45.0;
        } else if slack < 10 {
            score -= 15.0; // next item leaves only dead space: still good
        } else {
            score -= 5.0 * (1.0 - slack as f64 / bin_capacity as f64);
        }
    }

    // Mean residual coupling: prefer bins whose residual is below the mean
    // (close out tighter bins first, keep looser bins flexible).
    score += 0.15 * ((post_residual as f64) - mean_residual);

    // Early in the stream, be slightly more willing to open bins (build a
    // spread of residuals); late in the stream, pack aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * (1.0 - progress) * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let post = post_residual as f64;

    // --- 2-step lookahead: exact match between post_residual and next item ---
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (post - nxt).abs();
        // Perfect chain: residual exactly fits next item -> strong reward
        if gap < 0.5 {
            score -= 60.0 + 25.0 * (1.0 - progress);
        } else if gap <= 5.0 {
            score -= 30.0 * (1.0 - gap / 5.0);
        } else {
            // Penalize dead space the next item can't use
            let unusable = if post < nxt { post } else { post - nxt };
            score += 0.35 * unusable;
        }
        // If next item also fits this bin's remainder, mild extra reward
        if next_item_size <= post_residual {
            score -= 8.0;
        }
    }

    // --- Relative-to-mean coupling: keep residuals balanced unless exact fit ---
    let dev = (post - mean_residual).abs();
    score += 0.15 * dev * (1.0 - 0.5 * progress);

    // --- Last-chance bin: strongly favor using it to avoid opening a bin ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0 + 20.0 * (item_size as f64 / bin_capacity as f64);
    }

    // --- New-bin candidate: neutral baseline, slightly discouraged so we
    //     only open a new bin when no open bin has a decent fit ---
    if bin_residual == bin_capacity {
        // Baseline near mean residual: chosen only if all open bins score worse
        score = mean_residual + 12.0 + 10.0 * progress;
        if next_item_size > 0 && (bin_capacity as f64 - next_item_size as f64).abs() < 0.5 {
            score -= 20.0; // fresh bin chains perfectly with next item
        }
    }

    // --- Penalize tiny unusable slivers (dead space) ---
    if post > 0.0 && post < 5.0 && next_item_size > 0 {
        score += 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins whose leftover is minimal.
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score += tightness * tightness * 40.0;

    // Perfect-fit bonus: post_residual equal to next item closes the loop.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual < next_item_size {
            // Dead space that the next item cannot use.
            score += (next_item_size - post_residual) as f64 * 0.35;
        } else {
            // Leftover can host next item: mild reward scaled by how well it fits.
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 / (1.0 + slack * 0.08);
        }
    } else {
        // Last item: any placement is fine, prefer the emptiest-fit bin.
        score -= 5.0;
    }

    // Last-chance bin: avoid opening a new bin when only this one fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a bin unless the item is large
    // or existing residuals are all poor fits.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let large_item = (item_size as f64) > 0.6 * (bin_capacity as f64);
        let avg_gap = (mean_residual - item_size as f64).abs();
        let penalty = if large_item {
            8.0
        } else {
            30.0 + 25.0 * (1.0 - progress) + avg_gap * 0.3
        };
        // Late in the stream, opening fresh bins is less costly.
        score += penalty - 20.0 * progress;
    }

    // Prefer filling bins that deviate below the mean residual (compact bins first).
    if bin_residual != bin_capacity {
        let dev = mean_residual - bin_residual as f64;
        score += dev * 0.25;
    }

    // Mild load-balancing: many open bins -> prefer reusing rather than fragmenting.
    if open_bins_count > 4 {
        score -= 0.4 * (open_bins_count as f64).ln();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Non-linear waste penalty: quadratic in normalized post_residual, modulated by progress
    let post_norm = post / cap;
    score += 4.0 * post_norm * post_norm * cap * (0.5 + progress);

    // Tight-fit reward: cubic coupling of fill ratio with stream progress
    let fill_ratio = item_size as f64 / cap;
    score -= 12.0 * fill_ratio * fill_ratio * fill_ratio * cap * (1.0 - progress);

    // Exact-fit bonus (smooth surrogate of post_residual == 0)
    score -= 20.0 * (-post / 8.0).exp() * (1.0 + progress);

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 * (1.0 + post / cap);
    }

    // New-bin candidate handling: attractive early, less so late
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let openness = (1.0 - progress).powi(2);
        score = cap * (0.9 - 0.7 * openness) - 6.0 * openness;
        // Prefer new bin if item leaves large residual that could host the next item
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 8.0 * openness;
        }
    } else {
        // Lookahead: reward leaving room exactly sized for the next item
        if next_item_size > 0 {
            let gap = (post as i64 - next_item_size as i64).abs() as f64;
            score -= 10.0 * (-gap / 10.0).exp();
        }
        // Penalize bins whose residual is far above the mean residual (fragmentation risk)
        let dev = (bin_residual as f64 - mean_residual) / cap;
        score += 3.0 * dev * dev * cap;
    }

    // Mild pressure to consolidate when many bins are open
    score += 0.5 * open_bins_count as f64 * (1.0 - progress) * post_norm;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward "usable" leftover classes.
    // Residuals divisible by common item sizes (or >= 40) stay useful.
    let pr = post_residual;
    if pr == 0 {
        score -= 25.0; // perfect fill
    } else {
        // penalize small dead space that likely can never be used
        if pr < 10 {
            score += 15.0;
        }
        // harmonic classes: pr in [10,30] mid-usable, [30,60] good, >60 great
        if pr >= 30 && pr < 60 {
            score -= 6.0;
        } else if pr >= 60 {
            score -= 10.0;
        }
        // modulo arithmetic: leftover that is a multiple of 10 aligns with
        // typical item granularities -> more likely reusable
        if pr % 10 == 0 {
            score -= 4.0;
        }
    }

    // Lookahead: if the next item fits into post_residual, big reward.
    if next_item_size > 0 && next_item_size <= pr {
        score -= 12.0;
        // extra bonus if it exactly matches a harmonic class
        if next_item_size == pr {
            score -= 10.0;
        }
    } else if next_item_size > pr && next_item_size > 0 {
        // next item won't fit here regardless; slight penalty for wasting tight space
        score += 3.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // current fit is poor (large post_residual waste) or few bins fit the item.
    if bin_residual == bin_capacity {
        // base new-bin cost: discourage unless item is large relative to capacity
        score += 10.0;
        let frac = item_size as f64 / bin_capacity as f64;
        if frac > 0.7 {
            score -= 15.0; // large items pair well with fresh bins
        }
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
        // late in the stream, avoid spawning bins that may never be reused
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    } else {
        // existing bin: mild preference scaling with how many alternatives exist
        if fitting_bins_count > 3 {
            score += 1.0; // many options -> tie-break toward tightest anyway
        }
    }

    // Coupling with mean residual: prefer bins whose residual is below mean
    // (i.e., more filled bins) to consolidate filling.
    let bin_res_f = bin_residual as f64;
    if mean_residual > 0.0 && bin_res_f < mean_residual {
        score -= 2.0;
    } else if mean_residual > 0.0 {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny leftover gaps are almost unusable
    // (min item size is 1, but very small gaps invite fragmentation).
    if post_residual > 0 {
        if post_residual < 5 {
            score += 40.0; // nearly dead space
        } else if post_residual < 10 {
            score += 18.0;
        } else if post_residual < 20 {
            score += 6.0;
        }
    } else {
        // Perfect fit: strongly reward closing this bin out.
        score -= 60.0;
    }

    // Reward placements that still allow the lookahead item to fit here
    // (post_residual >= next_item_size), avoiding forcing a new bin next step.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
        // Extra reward if the lookahead would fit almost perfectly after this placement.
        let gap = post_residual - next_item_size;
        if gap <= 5 {
            score -= 6.0;
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // This bin will be dead after placement; penalize mildly.
        score += 4.0;
    }

    // Last-chance bin: if this is the ONLY bin that fits, using it avoids
    // opening a new bin — reward, scaled by how good the fit is.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing ones rather than opening new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln().max(0.0) * (1.0 + progress);
    score -= pressure * 2.0;

    // Prefer bins whose residual is already below average (tight bins),
    // nudging toward closing bins out rather than spreading fill evenly.
    score += (post_residual as f64 - mean_residual).max(0.0) * 0.15;

    // New-bin candidate: only attractive when the item is huge relative to
    // capacity and no tight fit exists elsewhere (handled implicitly by
    // post_residual = capacity - item being large for small items).
    if bin_residual == bin_capacity {
        // Mild penalty so an existing reasonable fit usually wins.
        score += 5.0;
        // But if the item nearly fills a fresh bin, opening is great.
        if item_size >= 80 {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post-residual exactly
    // matches the next item size (perfect 2-item packing).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Penalize post-residual that is smaller than the next item but still
    // "wasted" (dead space the lookahead item cannot use).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.8;
    }

    // Mild reward if post_residual can still fit the next item (chain potential).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }

    // Relative-to-mean-residual term: prefer bins tighter than average.
    score -= (mean_residual - bin_residual as f64) * 0.5;

    // Penalize leaving very small unusable slivers (< 10).
    if post_residual < 10 && post_residual > 0 {
        score += 15.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: keep it neutral-to-slightly-high so it only wins
    // when existing bins are poor fits; make it worse as stream progresses.
    if bin_residual == bin_capacity {
        score += 5.0 + 20.0 * (step_index as f64 / total_items.max(1) as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual) with a non-linear term.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * tightness * tightness;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 8.0;
        } else {
            // Next item won't fit here; penalize leaving large dead space.
            score += 0.5 * (post_residual as f64 - mean_residual).abs();
        }
    }

    // Penalize opening a new bin when decent open bins exist.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Only open a new bin if all fits are poor (large post_residual elsewhere).
            let best_possible = post_residual as f64; // residual of new bin
            if best_possible > mean_residual * 0.5 {
                score += 60.0 + 5.0 * fitting_bins_count as f64;
            } else {
                score += 20.0;
            }
        } else {
            score -= 10.0; // no alternative: opening a bin is required
        }
    }

    // Slight preference to fill bins with lower residual relative to mean (balance avoidance).
    if bin_residual < bin_capacity {
        score += 0.3 * (bin_residual as f64 - mean_residual);
    }

    // Mild time-horizon scaling: early in stream, be more conservative about waste.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.2 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr_norm = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early in the stream: mild waste penalty; late: harsh super-linear penalty.
    let coupling = pr_norm * pr_norm * (1.0 + 3.0 * progress) * cap;
    score += 0.35 * coupling;

    // Reward tight fits: subtract a smooth quadratic bonus when post_residual is small.
    let tightness = (1.0 - pr_norm).powi(3);
    score -= 18.0 * tightness * (1.0 - progress);

    // Perfect fit reward (post_residual near zero), stronger late in the stream.
    let perfect = (-pr / 12.0).exp();
    score -= 25.0 * perfect * (0.5 + progress);

    // Last-chance bin: strongly favor using the only bin that can fit the item.
    if fitting_bins_count == 1 {
        score -= 30.0 + 20.0 * (1.0 - pr_norm);
    }

    // Lookahead coupling: if the next item fits the resulting residual, reward this placement.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let slack = pr - nxt;
            score -= 12.0 * (1.0 - slack / cap).powi(2);
        } else {
            // Next item won't fit: penalize proportionally to overshoot, smoothed.
            let over = (nxt - pr) / cap;
            score += 10.0 * over * (1.0 + progress);
        }
    }

    // Penalize placements into bins whose residual deviates from the mean (keeps bin pool balanced).
    let dev = (bin_residual as f64 - mean_residual).abs() / cap;
    score += 6.0 * dev * dev;

    // New-bin candidate handling: opening a bin is penalized mildly early, more when open bins exist.
    if bin_residual == bin_capacity {
        let crowd = open_bins_count as f64;
        score += 8.0 + 4.0 * (crowd / (1.0 + crowd)) * (1.0 - progress);
        // But if the item is large relative to capacity, opening fresh is less penalized.
        score -= 10.0 * (item_size as f64 / cap);
    }

    // Mild preference for filling bins more heavily as stream progresses.
    score -= progress * (item_size as f64 / cap) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "small residue" classes are harder to reuse, so penalize them.
    let cap = bin_capacity as f64;
    let frac = post_residual as f64 / cap;

    // Integer-division thresholds on post_residual (harmonic buckets).
    let cls = post_residual / 10; // residue class bucket 0..=10
    match cls {
        0 => score += 6.0,            // nearly full: dead space, but tiny
        1 | 2 => score -= 3.0,        // sweet spot: 10..29 left, reusable for small items
        3 | 4 => score += 1.5,        // mid residue, moderate reuse
        5 | 6 => score += 4.0,        // ~50-69 left: wasteful if item was small
        _ => score += 2.0,            // large residue: item was tiny
    }

    // Reward if the next item exactly fills the post residual (perfect chaining).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 12.0;
        } else if next_item_size <= post_residual {
            let nf = next_item_size as f64 / post_residual.max(1) as f64;
            // Prefer leaving residue the next item can nearly fill.
            score -= 6.0 * nf;
            // Harmonic modulo: residue divisible by next item size class is good.
            if post_residual % next_item_size.max(1) == 0 {
                score -= 2.5;
            }
        } else {
            // Next item cannot use this residue: penalize proportionally.
            score += 2.0 * (next_item_size as f64 - post_residual as f64) / cap;
        }
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64;
        let tight = (item_size as f64) / cap;
        if fitting_bins_count == 0 {
            score -= 10.0; // nothing fits: new bin is necessary
        } else if tight > 0.7 {
            // Large item: prefer fresh bin over fragmenting a nearly-full bin.
            score -= 4.0 + 0.05 * pressure;
        } else {
            // Small item: discourage opening new bins.
            score += 8.0 + 0.1 * pressure;
        }
        // Late in the stream, consolidate more aggressively.
        let t = step_index as f64 / (total_items.max(1) as f64);
        score += 6.0 * t;
    }

    // Coupling with mean residual: if this bin's residual is far below mean,
    // it is already "tight" — using it is good (keeps loose bins loose).
    let diff = mean_residual - bin_residual as f64;
    score += 0.05 * diff;

    // Slight tie-break by fill ratio (harmonic fraction of capacity used).
    score -= 0.5 * (1.0 - frac);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold
    // anything (below the minimum plausible item footprint) are pure waste.
    // Penalize them heavily, more so as the stream progresses.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if post_residual < 10 {
        score += 60.0 + 40.0 * progress;
    } else if post_residual <= 15 {
        score += 25.0 + 15.0 * progress;
    }

    // Reward very tight fits (small but still usable post_residual).
    if post_residual >= 10 && post_residual <= 25 {
        score -= 18.0;
    } else if post_residual <= 40 {
        score -= 8.0;
    }

    // Perfect fill is ideal.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Open-bin pressure: discourage scattering items across many bins,
    // but relax pressure near the end of the stream (consolidation matters less).
    score += open_bins_count as f64 * (1.5 + 2.5 * progress);

    // Mean residual coupling: bins whose residual is far below the mean
    // are already tight; placing here is fine. Bins far above the mean
    // are loose; avoid dumping items there unless the fit is good.
    let dev = mean_residual - post_residual as f64;
    if dev < 0.0 {
        score += 0.15 * (-dev);
    }

    // Last-chance bin: if this is the ONLY bin that fits, strongly prefer
    // using it over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
        if post_residual < 10 {
            score += 35.0; // still punish truly dead gaps
        }
    }

    // Lookahead: if the next item fits exactly into the post_residual,
    // this placement chains perfectly — reward it.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // Next item still fits, but leaves a gap: mild reward.
        score -= 6.0;
    } else if next_item_size > post_residual && post_residual < 10 {
        // Dead gap the next item cannot use: extra penalty.
        score += 20.0;
    }

    // New-bin candidate: baseline attractiveness so a fresh bin is chosen
    // only when all open bins would create unusable dead space.
    if bin_residual == bin_capacity {
        score = 30.0 + open_bins_count as f64 * 2.0 - 10.0 * progress;
        // If some bin is a near-perfect fit, the new bin should lose.
        if post_residual == 0 { score = 200.0; }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate: neutral baseline, slightly penalized so real fits win
    if bin_residual == bin_capacity {
        return 60.0 + post_residual as f64 * 0.1;
    }

    // Aggressive 2-step lookahead: reward when next item fits into post_residual
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward proportional to how snugly the NEXT item will fit
            let slack_after_next = post_residual - next_item_size;
            score -= 12.0 * (1.0 - slack_after_next as f64 / bin_capacity as f64);
        } else {
            // Next item cannot follow into this bin: penalize
            score += 6.0 * (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
        }
    }

    // Reward tight fit of the current item
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 10.0 * fill_ratio;

    // Prefer bins whose residual is close to the item (best-fit coupling)
    let fit_gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.35 * fit_gap;

    // Coupling with mean residual: bins below mean residual are more "committed"
    if (bin_residual as f64) < mean_residual {
        score -= 1.5;
    } else {
        score += 0.8 * ((bin_residual as f64 - mean_residual) / bin_capacity as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        // spread items: slight penalty for crowding into popular bins
        score += 0.6 * (fitting_bins_count as f64);
    }

    // Early stream: keep bins flexible (avoid tiny residuals early)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 0.08 * post_residual as f64;

    // Penalize very small dead space that no typical item can use
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Base: strong best-fit pull with a mild convexity bonus for perfect fits.
    if post_residual == 0 {
        score -= 500.0; // perfect fill: always take it
    } else {
        // small post_residual is good; amplify discrimination near zero
        score -= 40.0 * (1.0 - post_residual as f64 / bin_capacity as f64).powi(3);
    }

    // Last-chance bin: strongly reward to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // Lookahead (k=2): reward if the next item fits into the post residual,
    // scaled by how snugly it fits (chained packing).
    if next_item_size > 0 && post_residual >= next_item_size {
        let snug = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
        score -= 25.0 + 45.0 * snug;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item won't fit here afterwards: mildly penalize leaving a big hole
        score += 8.0 + 10.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Penalize creating tiny unusable fragments (dead space < smallest plausible item).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Global state coupling: when many bins are open with high mean residual,
    // prefer consolidating into existing bins rather than opening new ones.
    let pressure = open_bins_count as f64 * mean_residual / (bin_capacity as f64 * 10.0);
    score += pressure * 5.0;

    // New-bin candidate logic: an empty bin should only win when it's genuinely
    // attractive — penalize it by default, less so late in the stream or when
    // existing bins are all nearly full (high mean residual pressure).
    if bin_residual == bin_capacity {
        let mut new_bin_penalty = 150.0;
        // late in the stream, opening bins is cheaper (fewer future items to fill them)
        new_bin_penalty -= 60.0 * progress;
        // if mean residual across open bins is tiny, existing bins are tight; relax penalty
        new_bin_penalty -= 40.0 * (1.0 - mean_residual / bin_capacity as f64).max(0.0);
        // if this bin is the only fitting bin, opening a bin is less necessary
        if fitting_bins_count <= 1 {
            new_bin_penalty += 100.0;
        }
        score += new_bin_penalty.max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalize stream progress.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Non-linear base: convex penalty on large post_residual (dead space), smoothed
    // so tiny residuals are strongly preferred.
    let pr = post_residual as f64;
    score += 0.35 * (pr / bin_capacity as f64).powi(3) * bin_capacity as f64;

    // Lookahead: reward bins whose post_residual can host the next item
    // (chained packing), with a smooth quadratic coupling.
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain = (post_residual - next_item_size) as f64;
        score -= 8.0 * (1.0 - chain / bin_capacity as f64).powi(2);
    } else if next_item_size > 0 {
        // Penalize bins that strand the next item.
        score += 3.0 + 0.05 * next_item_size as f64;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin for a mediocre fit.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Coupling with mean residual: prefer bins whose residual is below the mean
    // (i.e., tighter bins) via a smooth sigmoid-like interaction with progress.
    let diff = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    let sigmoid = 1.0 / (1.0 + (-4.0 * progress).exp());
    score += 6.0 * diff * sigmoid;

    // New-bin candidate handling: an empty bin is a valuable resource; penalize
    // opening one unless all open residuals are highly fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = if open_bins_count > 0 {
            (mean_residual / bin_capacity as f64).powi(2)
        } else {
            1.0
        };
        score += 15.0 - 10.0 * fragmentation * (0.5 + 0.5 * progress);
    }

    // Late-stream tightening: as the stream progresses, prioritize exact fits more.
    score -= 4.0 * progress * (1.0 - pr / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "small residue" classes (0..10, 11..20) are more valuable to preserve.
    let r = post_residual;
    let class = r / 10; // integer division threshold classes
    let class_penalty = match class {
        0 => -30.0,   // nearly perfect fit: reward strongly
        1 => -18.0,   // small leftover still usable by tiny items
        2 => -6.0,
        3 => 4.0,
        4 => 10.0,
        5 => 14.0,
        6 => 18.0,
        7 => 22.0,
        8 => 26.0,
        9 => 30.0,
        _ => 34.0,    // empty-ish bin placement wasted
    };
    score += class_penalty;

    // Modulo coupling: leftover that is congruent to common item sizes
    // (multiples of 10, 20, 25, 50) is more likely reusable.
    let reusable = (r % 10 == 0) || (r % 20 == 0) || (r % 25 == 0) || (r % 50 == 0);
    if reusable && r > 0 {
        score -= 12.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == r {
            score -= 40.0;
        } else if next_item_size <= r {
            // leftover after the lookahead also matters (second-order residual)
            let r2 = r - next_item_size;
            score -= 15.0 - (r2 as f64) * 0.15;
        } else {
            // next item cannot use this leftover: penalize proportionally
            score += ((next_item_size - r) as f64) * 0.25;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin should only win when the
    // item is large and no open bin gives a tight fit.
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / bin_capacity as f64;
        if tightness > 0.6 {
            score -= 10.0 + 20.0 * (tightness - 0.6);
        } else {
            score += 15.0 * (1.0 - tightness);
        }
        // Late in the stream, discourage spreading into new bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    // Prefer filling bins that are already below the mean residual
    // (balances load and closes bins sooner).
    score -= (mean_residual - bin_residual as f64) * 0.10;

    // Mild pressure to prefer bins over proliferation when many bins open.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold any plausible
    // future item (min size 1, but realistically small gaps < 10) are dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // unusable sliver
    } else if post_residual == 0 {
        score -= 40.0; // perfect fit, no dead space at all
    } else {
        // Usable residual: reward larger leftovers that can host future items.
        score -= 0.25 * post_residual as f64;
    }

    // If the lookahead item fits exactly in the post residual, strongly reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 15.0;
        // exact chain fit
        if next_item_size == post_residual {
            score -= 25.0;
        }
    } else if next_item_size > post_residual && next_item_size > 0 {
        // lookahead item cannot use this leftover: penalize proportionally
        score += 8.0;
    }

    // Last-chance bin before opening a new one: strong pull to use it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Open-bin pressure: penalize creating extra bins when many are open.
    let new_bin = bin_residual == bin_capacity;
    if new_bin {
        score += 12.0 + 3.0 * open_bins_count as f64;
        // but if no open bin fits well (post_residual huge relative to item), allow
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    }

    // Mean residual coupling: prefer bins whose residual deviates favorably
    // from the mean (tighter-than-average bins get priority).
    score += 0.15 * (bin_residual as f64 - mean_residual);

    // Late-stream pressure: as the stream ends, prefer filling existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if progress > 0.7 {
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: post_residual == 0 is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: if the next item fits exactly in post_residual, strongly favor.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // Next item fits: reward proportionally to how snug the chain is.
            let snug = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 100.0 * snug;
        } else {
            // Next item does NOT fit: penalize leaving awkward residuals.
            let progress = step_index as f64 / (total_items.max(1) as f64);
            score += 50.0 * (1.0 - progress) + 0.5 * post_residual as f64;
        }
    }

    // Relative to mean residual: prefer bins already below-average residual
    // (consolidating waste) and penalize draining above-average bins.
    let rel = post_residual as f64 - mean_residual;
    score += 0.3 * rel;

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate (empty bin): penalize opening a new bin unless the item
    // is large relative to capacity or no decent fit exists.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        score = 150.0 - 100.0 * fill_ratio;
        if fitting_bins_count == 0 {
            score -= 1000.0; // no alternative: must open new bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1)
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Fraction of residual consumed by this placement
    let fill = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fill * fill; // reward dense fills non-linearly

    // Lookahead: if the next item fits exactly into post_residual, strongly reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= 8.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here; penalize leaving awkward small gaps
            let gap = post_residual as f64;
            if gap > 0.0 && gap < next_item_size as f64 {
                score += 6.0 * (1.0 - gap / next_item_size as f64);
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Penalize bins whose residual deviates badly from the mean (keeps pool homogeneous)
    score += 0.5 * (bin_residual as f64 - mean_residual).abs();

    // New-bin candidate handling: prefer it only when few bins fit or residual is huge
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty so existing bins are usually preferred
        let mut penalty = 15.0;
        // If many bins can fit, definitely prefer reusing one of them
        if fitting_bins_count > 2 {
            penalty += 10.0;
        }
        // Early in the stream, opening bins is cheaper; late, conserve
        penalty += 20.0 * t;
        // If the item is huge relative to capacity, a fresh bin is natural
        if item_size as f64 > 0.7 * bin_capacity as f64 {
            penalty -= 10.0;
        }
        score += penalty;
    } else {
        // Slight bonus for keeping bin count low
        score -= 0.2 * (open_bins_count as f64).recip() * 10.0;
    }

    // Penalize creating tiny dead space that nothing (min size 1..100) may reuse well
    if post_residual > 0 && post_residual < 10 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Quadratic-cubic coupling of post_residual with progress
    let pr = post_residual as f64;
    let pr_norm = pr / bin_capacity as f64;
    score += 8.0 * pr_norm * pr_norm * (1.0 - progress);
    score -= 6.0 * pr_norm * pr_norm * progress;
    score += 4.0 * pr_norm * pr_norm * pr_norm * (0.5 + progress);

    // Smooth interaction: item size fraction vs residual (wasted-space penalty)
    let item_frac = item_size as f64 / bin_capacity as f64;
    score += 10.0 * item_frac * pr_norm * (1.0 - item_frac);

    // Tight fits rewarded smoothly (post_residual near zero)
    score -= 12.0 * (-pr / 15.0).exp() * (1.0 + progress);

    // Lookahead: if next item fits remaining residual, reward this bin
    if next_item_size > 0 {
        let fits_next = (post_residual >= next_item_size) as i32 as f64;
        let gap = (post_residual as f64 - next_item_size as f64).abs();
        score -= 7.0 * fits_next * (-gap / 20.0).exp();
        score += 3.0 * (1.0 - fits_next) * pr_norm * (0.5 + progress);
    }

    // Last-chance bin: strongly favor using it when it's the only fit
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0 + 10.0 * progress;
    }

    // Crowding penalty: many open bins with large mean residual -> discourage fragmentation
    let crowd = open_bins_count as f64 / (open_bins_count as f64 + 5.0);
    score += 6.0 * crowd * (mean_residual / bin_capacity as f64 - pr_norm).abs();

    // New-bin candidate: smooth sigmoid gate on preferring a fresh bin
    let new_bin = (bin_residual == bin_capacity) as i32 as f64;
    let poor_fit = (pr_norm * 4.0).min(1.0); // large post-residual => poor fit
    score += new_bin * (2.0 * poor_fit - 1.0) * (8.0 + 4.0 * progress);
    score -= new_bin * 2.0 * (1.0 - poor_fit);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: quantize leftover space into
    // capacity-fraction buckets. Small post residuals (tight fits) are good.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // 0..1

    // Class index: 0 = near-perfect fill, up to 9 = mostly empty bin.
    let class = (frac * 10.0).floor().min(9.0) as i32;

    // Non-linear penalty per class: tight classes rewarded heavily.
    let class_penalty = match class {
        0 => -18.0,
        1 => -10.0,
        2 => -5.0,
        3 => -1.0,
        4 => 2.0,
        5 => 5.0,
        6 => 8.0,
        7 => 11.0,
        8 => 14.0,
        _ => 17.0,
    };
    score += class_penalty;

    // Modulo arithmetic on post_residual: residuals that are multiples of
    // common item sizes (10, 20, 25) are "harmonic" and reusable.
    let p = post_residual;
    if p > 0 {
        if p % 10 == 0 { score -= 4.0; }
        if p % 25 == 0 { score -= 3.0; }
        if p % 50 == 0 { score -= 2.0; }
        // Odd, non-harmonic residuals create dead space risk.
        if p % 2 == 1 && p < 20 { score += 3.0; }
    }

    // Integer-division thresholds: can next item land in the leftover?
    if next_item_size > 0 && next_item_size <= p {
        // Lookahead fits: reward, more so for tight coupling.
        score -= 6.0;
        // Harmonic check: next item exactly consumes a harmonic chunk.
        if p % next_item_size == 0 {
            score -= 5.0;
        } else if (p / next_item_size.max(1)) >= 2 {
            score -= 2.0; // room for it twice
        }
    } else if next_item_size > p && p > 0 {
        // Leftover too small for lookahead: dead space unless tiny.
        if p < 10 {
            score -= 2.0; // negligible waste, fine
        } else {
            score += 4.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Crowding: many open bins -> prefer consolidation into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let crowd = (open_bins_count as f64).ln().max(0.0);
    score += crowd * (1.5 + 3.0 * progress);

    // Empty new-bin candidate: penalize unless current bin is a bad fit.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin, discounted when mean residual is low
        // (existing bins are nearly full anyway).
        let discount = if mean_residual < 15.0 { 10.0 } else { 0.0 };
        score += 30.0 - discount;
        // Opening early in stream is cheaper than late.
        score -= 8.0 * (1.0 - progress);
        // If lookahead is huge, a fresh bin is more attractive.
        if next_item_size as f64 > 0.8 * cap { score -= 6.0; }
    }

    // Mild preference toward bins whose residual is close to item size
    // (best-fit coupling via squared distance).
    let gap = (bin_residual as f64 - item_size as f64);
    score += gap * gap / (2.0 * cap);

    // Mean residual pull: prefer bins below mean (fill the emptiest last,
    // keep tight bins tight is wrong way; instead prefer bins near mean to
    // homogenize residuals for future items).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that no item can ever use are pure waste.
    // Items have size >= 1, but typical streams contain larger items; treat gaps
    // below a "salvage threshold" as dead space and penalize them heavily.
    let salvage_threshold: u32 = 10;
    if post_residual < salvage_threshold {
        // Unusable sliver: punish hard, scaled by how close it is to wasted.
        score += (salvage_threshold - post_residual) as f64 * 4.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 50.0;
    } else {
        // Usable gap: mild reward proportional to tightness of fit.
        let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
        score -= 6.0 * tightness;
    }

    // Reward bins whose residual matches the item well (item fills most of gap).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fill_ratio;

    // Open-bin pressure: prefer compacting into existing bins when many are open.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bonus: if this is the only bin that fits, avoid forcing a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && post_residual >= salvage_threshold {
        score -= 8.0;
    }

    // Lookahead: if the next item fits in the post residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 7.0;
    }

    // Slight preference for bins with smaller residuals (tighter bins first).
    score += bin_residual as f64 * 0.02;

    // Late in the stream, be more conservative about opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when post_residual exactly matches the
    // next item size (perfect chaining), penalize near-misses.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if diff == 0.0 {
            score -= 40.0; // perfect lookahead match
        } else if diff <= 5.0 {
            score -= 12.0;
        } else {
            score += diff * 0.15; // penalize wasted space relative to next item
        }
    }

    // Compare post_residual against the mean residual across open bins:
    // leaving a residual close to the mean is fine; extremes are penalized.
    let pr = post_residual as f64;
    let mean_gap = (pr - mean_residual).abs();
    score += mean_gap * 0.08;

    // Penalize large residuals if the next item cannot use them anyway.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += (post_residual as f64) * 0.3; // dead space smaller than next item
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate (pristine empty bin): only attractive when current bin
    // fit is poor or lookahead is bad. Penalize default opening of new bins.
    if bin_residual == bin_capacity {
        let poor_fit = if next_item_size > 0 && post_residual >= next_item_size { 0.0 } else { 1.0 };
        let tight = (fitting_bins_count == 1) as i32 as f64;
        // Opening a new bin is good only when no tight fit exists and lookahead
        // is fine; otherwise keep existing bins.
        score += 30.0 - 18.0 * (1.0 - poor_fit) - 20.0 * tight;
    }

    // Slight preference for filling bins tighter as the stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += pr * 0.05 * (1.0 - progress);

    // Mild pressure to consolidate: fewer open bins is better.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 12.0;
    }

    // Penalize leaving dead space that no plausible future item (>=1) can use well.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0; // tiny unusable slivers
    }

    // Lookahead: reward if next item fits exactly into the post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 10.0;
        } else {
            // next item would spill; slight penalty proportional to overflow
            score += 0.15 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0 + 0.2 * item_size as f64;
    }

    // Crowding pressure: many open bins with high mean residual -> prefer consolidating.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if open_bins_count > 3 && mean_residual > 30.0 {
        score -= 5.0 * (mean_residual / bin_capacity as f64) * (1.0 - progress);
    }

    // New-bin candidate handling: empty bin gets a baseline penalty that shrinks
    // as the stream progresses (late stream favors closing out bins).
    if bin_residual == bin_capacity {
        let new_bin_penalty = 20.0 + 25.0 * progress;
        // Exception: big items fit nowhere better if no open bin is tight.
        if item_size > 60 && mean_residual < item_size as f64 {
            score -= 30.0;
        }
        score += new_bin_penalty;
    }

    // Mild preference for bins below mean residual (balance spreading of slack).
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: quadratic waste penalty on post-residual
    let mut score = pr + 2.0 * pr * norm_pr;

    // Smooth non-linear coupling with stream progress:
    // late in the stream, waste matters more (fewer chances to fill gaps)
    let late = (progress * std::f64::consts::PI).sin();
    score += 12.0 * pr * norm_pr * late;

    // Tight fit reward: penalize large residuals, reward near-exact fits smoothly
    let tight = 1.0 - (norm_pr * std::f64::consts::PI / 2.0).cos();
    score -= 8.0 * tight * (item_size as f64 / cap);

    // Lookahead coupling: if next item fits exactly in post_residual, reward strongly
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score -= 10.0 * (-gap / 15.0).exp();
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0 + 5.0 * progress;
    }

    // Mean residual context: prefer bins deviating below mean residual
    // (fills the emptier bins, keeping tight bins for future small items)
    score += 0.5 * (mean_residual - pr);

    // Crowding: when many bins are open, discourage opening more implicitly
    // by mildly rewarding use of existing bins
    score -= (open_bins_count as f64).ln().max(0.0);

    // New-bin candidate: make empty bins moderately attractive only when
    // item is large and progress is early (future items can fill it)
    if bin_residual == bin_capacity {
        let size_frac = item_size as f64 / cap;
        let early_bonus = (1.0 - progress) * 10.0;
        score = pr + 2.0 * pr * norm_pr + 25.0 - early_bonus * size_frac;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify dead space into residue buckets.
    // Classes mod 10 capture "usable granularity" of leftover space for typical small items.
    let class = post_residual % 10;
    let class_penalty: f64 = match class {
        0 => -12.0, // perfectly aligned leftover: highly reusable
        1 | 9 => -6.0,
        2 | 8 => -3.0,
        3 | 7 => 0.0,
        4 | 6 => 3.0,
        5 => 6.0, // worst class: half-slot dead space
        _ => 0.0,
    };
    score += class_penalty;

    // Integer-division thresholds on post_residual: big leftovers are good,
    // tiny leftovers (< 10, unusable for min item) are dead space.
    let big_left = post_residual / 20; // 0..=5 tiers
    score -= (big_left as f64) * 4.0;
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // pure dead space penalty
    }

    // Exact fit reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead coupling: does the next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Harmonic match: leftover class aligns with next demand.
            let slack = (post_residual - next_item_size) % 10;
            score -= 18.0 - (slack as f64);
            // Stronger reward when leftover leaves a clean class for the item after next.
            if (post_residual % next_item_size.max(1)) == 0 {
                score -= 6.0;
            }
        } else {
            // Next item won't fit here; mild penalty scaled by overflow size.
            let overflow = (next_item_size - post_residual) as f64;
            score += (overflow * 0.15).min(15.0);
        }
    } else {
        // Last item: prefer filling existing bins completely.
        score -= 20.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0).min(5.0);
    }

    // New-bin candidate handling: only attractive when open bins are congested
    // or mean residual is too small to be useful.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let congestion = open_bins_count as f64;
        let mean_useful = mean_residual / bin_capacity as f64;
        // Penalize new bins when existing bins still have usable space.
        score += 45.0 - congestion * 2.0 - progress * 10.0;
        if mean_useful < item_size as f64 / bin_capacity as f64 {
            // Open bins can't hold future items well; new bin becomes attractive.
            score -= 25.0;
        }
        if next_item_size > 0 && next_item_size > mean_residual as u32 {
            score -= 15.0;
        }
    }

    // Mild preference for tighter bins overall (low residual before placement).
    score += (bin_residual as f64) * 0.05;

    // Slight normalization by mean residual state: avoid starving average bins.
    if (bin_residual as f64) < mean_residual * 0.5 {
        score += 5.0; // this bin is unusually full; using it is good, small bonus
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for any
    // future item (sizes >= 1, but realistically small fragments) are waste.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 6.0; // unusable sliver penalty
    } else if post_residual >= 10 && post_residual < 25 {
        // moderate gap: mildly penalize unless it matches the lookahead item
        score += 8.0;
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 12.0;
        }
    }

    // Reward very tight fits (post_residual near zero but usable).
    if post_residual == 0 {
        score -= 40.0; // perfect closure
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin, scaled by how many
    // bins are already open (bin-count pressure).
    if bin_residual == bin_capacity {
        score += 35.0 + open_bins_count as f64 * 4.0;
        // But if no open bin fits well, allow opening: soften penalty when
        // the item is large relative to capacity.
        if item_size * 4 >= bin_capacity * 3 {
            score -= 30.0;
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // nothing fits anywhere; must open
        }
    } else {
        // Open-bin pressure: with many open bins, prefer filling existing ones.
        score -= (open_bins_count as f64).sqrt() * 2.0;

        // Lookahead synergy: leaving room for the next item is good.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        } else if next_item_size > post_residual && post_residual > 0 {
            score += 5.0; // next item won't fit here anyway
        }

        // Prefer bins with residuals below the mean (fill the emptiest-tightest).
        score += (mean_residual - bin_residual as f64).clamp(-50.0, 50.0) * 0.3;
    }

    // Early stream: be slightly more conservative about fragmenting bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.15 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: perfect match with next item is highly desirable.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        // Strong reward when post_residual exactly equals next item size.
        if diff == 0.0 {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // Penalize gap so next item still fits comfortably.
            score += diff * 0.4;
        } else {
            // Next item won't fit here; penalize proportionally to shortfall.
            score += diff * 0.25;
        }
        // Bonus if both current and next item would nearly fill the bin.
        let two_step_fill = item_size as f64 + next_item_size as f64;
        if two_step_fill >= bin_capacity as f64 {
            score -= 40.0;
        } else {
            score += (bin_capacity as f64 - two_step_fill) * 0.15;
        }
    } else {
        // Last item: reward tight fits maximally.
        score -= 50.0;
    }

    // Relative-to-mean-residual coupling: prefer bins whose post residual
    // sits near the mean (keeps the pool of usable residuals balanced).
    let post = post_residual as f64;
    score += (post - mean_residual).abs() * 0.3;

    // Penalize small unusable dead space (fragmentation).
    if post > 0 && post < 10.0 {
        score += 25.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: neutral baseline, slightly penalized so we only
    // open new bins when existing fits are truly bad.
    if bin_residual == bin_capacity {
        score += 20.0;
        // Opening a new bin is more attractive early in the stream when the
        // item is large (little chance of later sharing).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        if item_size >= 50 {
            score -= 15.0 * (1.0 - progress);
        }
    }

    // Mild pressure to consolidate into fewer bins when many are open.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity && bin_capacity > 0;
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Reward small leftovers, more aggressively late in the stream.
        let tightness = post_residual as f64 / bin_capacity as f64;
        score += (tightness * tightness) * 120.0 * (0.5 + progress);
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if !is_new_bin && fitting_bins_count == 1 {
        score -= 60.0 + 40.0 * (1.0 - progress);
    }

    // Lookahead: if the next item fits exactly into the post-residual, reward;
    // if the leftover is too small for anything useful (below min size 1 but
    // below a practical threshold relative to next item), penalize.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 300.0;
        } else if post_residual > next_item_size {
            score -= 25.0;
        } else {
            // Dead space: leftover smaller than the next item.
            score += 15.0 + 0.5 * post_residual as f64;
        }
    }

    // New-bin candidate: baseline cost of opening a bin; make it cheaper when
    // existing bins are crowded (low mean residual) or no good fit exists,
    // more expensive when plenty of usable space remains in open bins.
    if is_new_bin {
        let crowding = mean_residual / bin_capacity as f64;
        score += 90.0 - 70.0 * (1.0 - crowding.min(1.0));
        if fitting_bins_count == 0 {
            score -= 500.0;
        }
    }

    // Mild preference to fill bins with larger residuals when many bins are open
    // (consolidation pressure).
    if !is_new_bin {
        score -= 0.05 * bin_residual as f64 / open_bins_count.max(1) as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 1 { step_index as f64 / (total_items as f64 - 1.0) } else { 0.0 };
    let cap = bin_capacity as f64;

    // Normalized fit quality: how well the item fills the bin.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;

    // Reward tight fits with a smooth polynomial in fill_ratio, amplified by progress.
    let tight_reward = fill_ratio.powi(2) * (30.0 + 40.0 * progress);
    score -= tight_reward;

    // Penalize leaving large dead space non-linearly (quartic growth in normalized post residual).
    let dead = post_residual as f64 / cap;
    score += 25.0 * dead.powi(4) * (1.0 + progress);

    // Penalize this bin more if it deviates below the mean residual (it is "wasted" space elsewhere).
    score += 0.35 * (mean_residual - bin_residual as f64).max(0.0);

    // Last-chance bonus: strongly prefer the only fitting bin to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 20.0 * (1.0 - gap / cap).max(0.0);
    }

    // New-bin candidate: make it unattractive unless the item is large relative to capacity
    // and few bins are open (smooth logistic-like gate instead of hard cutoff).
    if bin_residual == bin_capacity {
        let size_gate = 1.0 / (1.0 + (-6.0 * (item_size as f64 / cap - 0.6)).exp());
        let scarcity = 1.0 / (1.0 + open_bins_count as f64);
        score += 45.0 * (1.0 - size_gate * scarcity);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals that are multiples of 10
    // are more reusable (items span 1..100, but classic sizes cluster on 10s).
    let class = post_residual % 10;
    score += class as f64 * 1.5; // penalize off-class residuals

    // Integer-division thresholds: large leftovers vs. dead space.
    let half = bin_capacity / 2;
    if post_residual >= half {
        score -= 8.0; // half-full or better: very reusable
    } else if post_residual >= bin_capacity / 4 {
        score -= 3.0;
    } else if post_residual == 0 {
        score -= 20.0; // perfect fit, strongly reward
    } else {
        score += 4.0; // small dead space penalty
    }

    // Coupling with lookahead item: does the leftover fit the next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= (post_residual - next_item_size) as f64 * 0.3 + 5.0;
        } else {
            score += 6.0; // leftover useless for next item
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: prefer an open bin unless it's a poor fit.
    if bin_residual == bin_capacity {
        // Opening fresh is only attractive when open bins are fragmented.
        score = bin_capacity as f64 * 0.5 + mean_residual * 0.2;
        if open_bins_count == 0 {
            score -= 100.0; // must open first bin
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0; // big item coming, fresh capacity helps
        }
    } else {
        // Tighter fits win: reward small post_residual relative to capacity.
        score -= (1.0 - post_residual as f64 / bin_capacity as f64) * 10.0;
    }

    // Stream progression: late in stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 3.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold the smallest
    // plausible item are nearly worthless; penalize them heavily.
    let min_item = 1u32;
    if post_residual < 10 {
        // Dead gap: almost nothing fits later. Punish proportional to waste.
        score += (10 - post_residual) as f64 * 6.0;
    } else if post_residual < 20 {
        score += (20 - post_residual) as f64 * 1.5;
    }

    // Reward near-perfect fits nonlinearly.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 12.0;
    }

    // Prefer bins whose residual is close to the item (tight fit ratio).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 8.0;

    // Last-chance bin: if this is the only bin that fits, avoid forcing us
    // to open a new bin unless the fit is truly terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0 + 0.05 * post_residual as f64;
    }

    // Lookahead: if the next item fits exactly in the post residual,
    // strongly favor this bin (perfect chaining).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.3;
        } else {
            // Next item won't fit here; residual likely becomes dead space.
            score += 2.0;
        }
    }

    // Open-bin pressure: with many open bins, favor consolidation into
    // existing bins; when few bins are open, opening new ones is cheaper.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.15 + 0.25 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure, discounted early.
        score = 25.0 + pressure * 0.8 - 15.0 * (1.0 - progress);
        // Opening a bin is attractive if no open bin fits well.
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
    } else {
        score += pressure * 0.3;
        // Mild bonus for using bins that are already fragmented.
        if (bin_residual as f64) < mean_residual {
            score -= 1.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward when post_residual exactly matches the next item (perfect 2-step chain).
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 40.0 * (1.0 - diff / bin_capacity as f64);
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // Penalize leaving residual that is too small for the next item (dead space risk)
        if post_residual < next_item_size {
            score += 0.35 * (next_item_size - post_residual) as f64;
        }
    } else {
        // Last item: prefer tightest fill
        score -= 10.0;
    }

    // Prefer bins whose residual is below mean (tighter bins get filled first).
    score += 0.20 * (mean_residual - bin_residual as f64);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Penalize new-bin opening when open bins exist and fit is decent.
    if bin_residual == bin_capacity {
        score += 15.0 + 2.0 * open_bins_count as f64;
        // But allow new bin if item is large relative to residual structure
        score -= 0.1 * item_size as f64;
    }

    // Slight preference for larger items into tighter bins as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.05 * progress * (bin_residual as f64 - item_size as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Time horizon: early in stream -> prefer compacting; late -> keep bins flexible.
    let t = step_index as f64 / total_items.max(1) as f64;

    // Reward tight fits strongly (low post_residual is good).
    score -= (bin_capacity as f64 - post_residual as f64).powi(2) / (bin_capacity as f64 * bin_capacity as f64) * 30.0;

    // Penalize dead space that nothing reasonable can use.
    if post_residual < 10 {
        score -= 25.0; // near-perfect fill
    } else if post_residual < item_size {
        score += 6.0; // small awkward gap
    }

    // Lookahead coupling: if next item fits into the post-residual, reward.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0 * (1.0 - t);
        } else {
            score += 4.0 * (1.0 - t);
        }
        // If next item exactly fills post residual, big reward.
        if next_item_size == post_residual {
            score -= 20.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 18.0;
    } else if fitting_bins_count > 3 {
        score += 2.0 * (fitting_bins_count as f64 - 3.0).min(5.0);
    }

    // Global state: many open bins -> prefer consolidation into existing bins.
    let open_pressure = open_bins_count as f64 / (1.0 + t * 10.0);
    score -= open_pressure * 1.5;

    // Mean residual coupling: placing into a bin below mean residual spreads space evenly.
    if (bin_residual as f64) > mean_residual {
        score -= 3.0;
    } else {
        score += 2.0;
    }

    // New-bin candidate handling: empty bin should only win when existing fits are bad.
    if bin_residual == bin_capacity {
        let badness = (post_residual as f64) // post_residual == capacity - item for new bin
            + if next_item_size > 0 && next_item_size <= post_residual { 0.0 } else { 15.0 };
        score += 40.0 + badness * 0.5 - t * 10.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // nothing else fits: must open new bin
        }
    }

    // Mild exploration noise grounded in state, deterministic.
    score -= ((step_index as f64 * 0.37 + bin_residual as f64 * 0.11).sin()) * (1.5 * (1.0 - t));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / (total_items as f64 - 1.0) } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let fit_ratio = item_size as f64 / cap;

    // Base: waste after placement
    let mut score = pr;

    // Smooth non-linear coupling of post_residual with stream progress:
    // early on, larger residuals are acceptable; late, punish leftover space harder.
    let progress_coupling = pr * (0.5 + 1.5 * progress * progress);
    score += 0.8 * progress_coupling;

    // Reward tight fits (small post_residual) with a super-linear bonus.
    let tightness = (1.0 - pr / cap).max(0.0);
    score -= 30.0 * tightness * tightness * tightness;

    // Penalize dead space that no plausible item can fill:
    // if next_item_size doesn't fit, the leftover is likely wasted.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            let gap = (nxt - pr) / cap;
            score += 25.0 * gap * gap;
        } else {
            // Reward bins whose leftover fits the next item exactly-ish
            let use_ratio = nxt / pr;
            score -= 10.0 * (use_ratio * (2.0 - use_ratio)).max(0.0);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0 * (1.0 - progress * 0.5);
    } else if fitting_bins_count > 1 {
        // Prefer bins that are more filled among many candidates (Best-Fit flavor)
        score += 5.0 * (bin_residual as f64 / cap);
    }

    // New-bin candidate: empty bin. Attractive when open bins are poor fits or late in stream.
    if bin_residual == bin_capacity {
        let mean_fit_pressure = (mean_residual / cap).max(0.0);
        // Penalize new bins early (keep bins packed), relax later.
        score += 60.0 * (1.0 - progress) * (1.0 + 0.5 * (open_bins_count as f64).ln().max(0.0));
        // But if open bins have large mean residual, a new bin is less harmful.
        score -= 20.0 * mean_fit_pressure;
    }

    // Mild penalty for spreading across too many open bins early.
    score += 0.3 * (open_bins_count as f64) * (1.0 - progress);

    // Small smooth nudge favoring larger items in emptier bins.
    score -= 4.0 * fit_ratio * (1.0 - pr / cap).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: modulo arithmetic on capacity fractions.
    // Residuals divisible by large "harmonic" divisors are more reusable.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Class the post_residual into harmonic buckets via integer division thresholds.
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    let harmonic_bonus: f64 = if post_residual == 0 {
        -30.0 // perfect fit: strongly reward
    } else if post_residual % 10 == 0 {
        -8.0 // residual in multiples of 10 matches item granularity
    } else if post_residual >= half {
        -5.0 // still roomy, flexible
    } else if post_residual >= quarter {
        4.0 // awkward mid-class residual
    } else {
        10.0 // tiny dead space: penalize heavily
    };
    score += harmonic_bonus;

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            // next item fits: reward proportional to how well it packs the leftover
            let fill = next_item_size as f64 / pr.max(1.0);
            score -= 12.0 * fill;
            let left2 = post_residual - next_item_size;
            if left2 % 10 == 0 { score -= 4.0; }
        } else {
            // next item cannot use this residual: penalize small leftovers more
            score += 6.0 * (1.0 - pr / cap);
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: keep it attractive only when open bins are crowded.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / cap;
        // open new bin when existing residuals are small relative to item needs
        score -= 20.0 * pressure - 5.0;
        if fitting_bins_count == 0 {
            score -= 10.0;
        }
        // early in the stream, opening bins is cheap
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 5.0 * (1.0 - progress);
    } else {
        // mild preference for fuller bins as stream progresses
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 3.0 * progress * (1.0 - bin_residual as f64 / cap);
    }

    // Tie-break: prefer bins whose residual class matches item's harmonic class
    if (bin_residual % 20) == (item_size % 20) {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fit (low post_residual), but dead-space avoidance dominates.
    // A gap that cannot hold the next item (or the minimum plausible item) is "dead space".
    let min_item = 1u32;
    let gap_useless_for_next = next_item_size > 0 && post_residual < next_item_size;
    let gap_useless_abs = post_residual < min_item;

    // Strong penalty for creating unusable gaps, scaled by how close the gap is
    // to the next item size (near-miss gaps are the worst kind of dead space).
    if gap_useless_for_next {
        let near_miss = 1.0 - (next_item_size as f64 - post_residual as f64) / (next_item_size.max(1) as f64);
        score += 60.0 + 40.0 * near_miss;
    } else if gap_useless_abs {
        score += 100.0;
    }

    // Reward leaving a gap that exactly accommodates the next item (perfect chaining).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }

    // Reward small post_residual super-linearly (tight packing), but only when usable.
    if !gap_useless_for_next {
        let pr = post_residual as f64 / bin_capacity as f64;
        score += 10.0 * pr * pr; // extra quadratic penalty on large residual space
    }

    // Last-chance bin: strongly favor using it instead of opening a new bin.
    if fitting_bins_count == 1 {
        score -= 45.0;
    }

    // Open-bin pressure: many open bins -> prefer filling existing ones,
    // few open bins -> allow opening new bins (new-bin candidate wins then).
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += 6.0 * pressure;

    // New-bin candidate: give it a moderate baseline so it only wins when
    // all open bins would create dead space or the pressure is low.
    if bin_residual == bin_capacity {
        score += 15.0 + 8.0 * pressure;
        // But if next item is large and current fit would leave near-miss gap,
        // opening fresh is fine (handled by dead-space penalty on others).
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 10.0; // fresh bin can always take the next item
        }
    }

    // Slight progression term: late in stream, be more conservative with new bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 5.0 * progress;

    // Mean residual coupling: if this bin's residual is far below mean, it's an
    // outlier bin; filling it normalizes bin states (mild reward).
    let bin_res_f = bin_residual as f64;
    if mean_residual > 0.0 {
        let dev = (bin_res_f - mean_residual).abs() / mean_residual;
        score += 3.0 * dev;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size -> strong reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Post residual can still hold the next item: mild reward scaled by tightness.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 - 0.25 * slack;
    }

    // Post residual too small for next item: dead space penalty grows as stream progresses.
    if next_item_size > 0 && post_residual < next_item_size {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 8.0 + 12.0 * progress;
    }

    // Compare against mean residual: bins tighter than average are attractive.
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New empty bin candidate: penalize unless nothing else works well.
    if bin_residual == bin_capacity {
        let base = 45.0;
        let scarcity = if fitting_bins_count == 0 { 70.0 } else { 0.0 };
        score += base - scarcity;
    }

    // Prefer filling existing bins as their count grows.
    if bin_residual < bin_capacity {
        score -= 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post-residual) with a non-linear term.
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score += 8.0 * tightness * tightness;

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0 + 4.0 * (next_item_size as f64 / 100.0);
        } else {
            // Penalize leaving dead space the next item cannot use.
            score += 3.0 * (1.0 - (post_residual as f64 / bin_capacity as f64).max(0.0));
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0;
    } else if fitting_bins_count > 1 {
        // Mild penalty to discriminate among many fitting bins.
        score += 1.5 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        // Opening a new bin is cheap early, expensive when many bins are open
        // or when the stream is near its end (no time to fill it).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 10.0 + 25.0 * progress + 1.0 * open_bins_count as f64;
        // If no open bin leaves room for the next item, a fresh bin is fine.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 8.0;
        }
    }

    // Global state coupling: prefer bins whose residual is below the mean
    // (consolidate toward fuller bins), penalize above-mean residuals.
    score += 2.0 * ((bin_residual as f64) - mean_residual) / (bin_capacity as f64);

    // Time horizon: late in the stream, avoid wasting space in half-empty bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let p2 = progress * progress;
    let p3 = p2 * progress;
    score += norm_pr * norm_pr * (50.0 + 80.0 * p2) * (1.0 + 0.5 * p3);

    // Reward tight fits more strongly as stream progresses (smooth cubic ramp)
    score -= (cap - pr) * (0.3 + 0.9 * p2 + 0.6 * p3);

    // Penalize residual that cannot fit the lookahead item (smooth quadratic)
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr < ni {
            let gap = (ni - pr) / cap;
            score += gap * gap * (60.0 + 60.0 * progress);
        } else {
            let use_ratio = ni / pr.max(1.0);
            score -= use_ratio * 15.0 * (0.5 + 0.5 * progress);
        }
    }

    // Last-chance bin bonus (smooth sigmoid-like coupling with progress)
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    }

    // Mild pressure from mean residual across open bins
    score += (mean_residual - pr) * 0.05 * (1.0 + p2);

    // Slight preference for using existing bins over opening new ones, decaying with progress
    if bin_residual == bin_capacity {
        score += 8.0 * (1.0 - 0.5 * progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: residuals divisible by common
    // item granularities (10/20/25/50) are more reusable.
    let pr = post_residual;
    let mut harmony_bonus = 0.0;
    if pr == 0 { harmony_bonus += 60.0; }
    if pr % 10 == 0 { harmony_bonus += 18.0; }
    if pr % 20 == 0 { harmony_bonus += 10.0; }
    if pr % 25 == 0 { harmony_bonus += 8.0; }
    if pr % 50 == 0 { harmony_bonus += 6.0; }
    score -= harmony_bonus;

    // Penalize awkward "dead zone" residuals that few item classes can use.
    if pr > 0 && pr < 10 { score += 35.0; }
    else if pr > 10 && pr < 20 { score += 12.0; }
    else if pr > 80 { score += 4.0; }

    // Lookahead coupling: does the leftover match the next item's class?
    if next_item_size > 0 {
        if pr >= next_item_size {
            // Prefer leftovers that exactly (or near-exactly) host next item.
            let gap = pr - next_item_size;
            if gap == 0 { score -= 45.0; }
            else if gap <= 5 { score -= 20.0; }
            else if gap % 10 == 0 { score -= 10.0; }
            else { score += (gap as f64) * 0.15; }
        } else {
            // Leftover too small for next item: penalize proportionally.
            score += (next_item_size - pr) as f64 * 0.4;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 55.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded
    // or this item leaves a harmonious full-bin state impossible elsewhere.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowded = open_bins_count as f64 / (mean_residual / bin_capacity as f64 + 1.0);
        let mut new_bin_score = 30.0 + crowded * 5.0;
        if item_size > 50 { new_bin_score -= 15.0; }       // big items like fresh bins
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity { new_bin_score -= 10.0; }
        if progress > 0.8 { new_bin_score += 10.0; }        // late stream: consolidate
        // Must beat the default baseline to actually win.
        score = score * 0.9 + new_bin_score;
    }

    // Mild tie-break toward filling fuller bins first.
    score += (bin_capacity - bin_residual) as f64 * 0.05;

    // Small noise-free deterministic tie-break on residual class.
    score += ((pr % 7) as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the smallest item are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // unusable sliver
    } else if post_residual >= 10 && post_residual < 20 {
        score += 18.0; // nearly unusable for most items
    } else if post_residual == 0 {
        score -= 45.0; // perfect fit: strongly reward closing the bin
    }

    // Reward fitting into bins whose residual was already constrained (tight fit).
    let tightness = (item_size as f64) / (bin_residual.max(1) as f64);
    score -= 30.0 * tightness;

    // Lookahead: if the next item fits exactly in the post-residual, reward heavily.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 40.0;
    } else if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        // next item cannot use this gap -> slight penalty proportional to gap waste
        score += (post_residual as f64) * 0.15;
    }

    // Last-chance bin: strongly favor using the only bin that fits, avoid opening new.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Open-bin pressure: discourage opening new bins when many are open.
    if bin_residual == bin_capacity {
        // candidate new bin: penalize more when many bins already open
        score += 35.0 + 4.0 * open_bins_count as f64;
    } else {
        // using an existing bin relieves pressure
        score -= 2.0 * open_bins_count as f64;
    }

    // Mean residual coupling: prefer bins whose residual deviates below mean (consolidate waste).
    score += 0.3 * ((bin_residual as f64) - mean_residual);

    // Early stream: be slightly more willing to open bins for good structure.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score -= 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: strong reward for leaving little or no residual.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Tightness reward: smaller relative residual is better.
        let tight = (post_residual as f64) / (bin_capacity as f64);
        score -= 60.0 * (1.0 - tight) * (1.0 - tight);

        // 2-step lookahead: reward if next item fits exactly into post_residual.
        if next_item_size > 0 && next_item_size <= post_residual {
            let chain_residual = post_residual - next_item_size;
            if chain_residual == 0 {
                score -= 400.0; // perfect 2-item chain
            } else {
                let chain_tight = (chain_residual as f64) / (bin_capacity as f64);
                score -= 150.0 * (1.0 - chain_tight);
            }
        } else if next_item_size > 0 {
            // Next item cannot use this bin's leftover: penalize dead space,
            // scaled by how big the wasted chunk is.
            let waste = (post_residual as f64) / (bin_capacity as f64);
            score += 80.0 * waste * waste;
        }

        // Penalize residuals that are unusably small for typical items (1..100).
        if post_residual < 10 && post_residual > 0 {
            score += 120.0;
        }
    }

    // Compare against mean residual: prefer bins that are already tighter
    // than average (best-fit style), penalize squandering large residuals.
    if (bin_residual as f64) > mean_residual {
        score += 15.0 * ((bin_residual as f64) - mean_residual) / (bin_capacity as f64);
    } else {
        score -= 10.0 * (mean_residual - (bin_residual as f64)) / (bin_capacity as f64);
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // New-bin candidate: only attractive when it beats poor fits, i.e. when
    // no open bin offers a decent placement and many bins are open.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Slight bias against opening bins early, stronger when bins are few.
        score += 30.0 + 20.0 * (1.0 - progress) + 5.0 * (open_bins_count as f64).ln().max(0.0);
        // But if the item is huge relative to capacity, a fresh bin is clean.
        if item_size as f64 > 0.6 * bin_capacity as f64 {
            score -= 60.0;
        }
        // If lookahead item is small, new bin can absorb a chain: mild bonus.
        if next_item_size > 0 && next_item_size as f64 <= 0.25 * bin_capacity as f64 {
            score -= 40.0;
        }
    }

    // Mild preference for consolidating into fewer bins.
    score += 2.0 * (open_bins_count as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a non-linear bonus.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 60.0 * tightness * tightness;

    // Penalize dead space that cannot fit the lookahead item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Residual is reusable by the next item: reward proportionally.
            score -= 15.0 * (post_residual as f64 - next_item_size as f64 + 1.0).sqrt();
        } else {
            // Dead space for the next item: penalize, stronger early in stream.
            let t = step_index as f64 / total_items.max(1) as f64;
            let horizon = 1.0 + 2.0 * (1.0 - t);
            score += 25.0 * horizon * (next_item_size as f64 - post_residual as f64) / 100.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // Penalize opening a new bin when plenty of open bins exist with room.
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64 * mean_residual / bin_capacity as f64;
        // If mean residual across bins is large, opening a new bin is wasteful.
        score += 40.0 + 30.0 * pressure;
        // But near the end of the stream, opening a fresh bin is cheap.
        let t = step_index as f64 / total_items.max(1) as f64;
        score -= 45.0 * t;
        // If the item leaves a residual that fits the next item, a new bin is fine.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 50.0;
        }
    }

    // Mild penalty when this bin's residual deviates from the mean (fragmentation).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Slight preference for fuller bins (best-fit flavor) scaled by stream progress.
    let t = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * t * (bin_capacity - bin_residual) as f64 / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;

    // Base: minimize waste after placement
    let mut score = pr;

    // Non-linear tightness reward: strongly reward near-zero post-residual
    let tight = (1.0 - pr / cap).powi(6);
    score -= 12.0 * tight * (1.0 + 2.0 * progress);

    // Penalty that grows super-linearly with residual (dead space avoidance)
    score += 0.02 * (pr * pr) / cap;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate handling: penalize opening a new bin, more so early on
    // and when existing bins fit reasonably well
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let open_pressure = (open_bins_count as f64).ln().max(0.0);
        score += 15.0 + 5.0 * (1.0 - progress) + 2.0 * open_pressure;
    }

    // Lookahead coupling: reward bins whose post-residual matches next item size
    if next_item_size > 0 && !is_new_bin {
        let nxt = next_item_size as f64;
        let match_quality = 1.0 - ((pr - nxt) / cap).abs();
        if match_quality > 0.0 {
            score -= 6.0 * match_quality * match_quality;
        }
    }

    // Slight preference for bins with residuals below mean (consolidate waste)
    if !is_new_bin {
        let dev = (bin_residual as f64 - mean_residual) / cap;
        score += 1.5 * dev;
    }

    // Late-stream urgency: prefer filling existing bins as stream ends
    score -= 3.0 * progress * (1.0 - pr / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-fit residual: residuals near multiples of 4
    // are more reusable by typical item sizes (gcd structure mod small ints).
    let res_class = post_residual % 4;
    let res_bonus: f64 = match res_class {
        0 => 6.0,               // highly reusable (fits 4,8,12,...)
        2 => 3.0,               // even residual
        _ => -4.0,              // odd residual: dead space for even items
    };
    score -= res_bonus;

    // Harmonic class of next_item_size vs post_residual: perfect chaining reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0; // exact fill of this bin by the lookahead item
        } else if next_item_size <= post_residual {
            let gap = post_residual - next_item_size;
            // reward tight chains, penalize chains that leave awkward remainders
            if gap % 4 == 0 { score -= 8.0; } else { score += 3.0; }
        } else {
            // next item won't fit here: mild penalty proportional to mismatch class
            let m = (next_item_size - post_residual) % 8;
            score += 2.0 + m as f64;
        }
    } else {
        // last item: strongly prefer tightest fit / closing bins
        score -= 10.0;
    }

    // Integer-division thresholds on post_residual: classify dead space severity.
    let dead_class = post_residual / 12; // 0..8 bands
    score += match dead_class {
        0 => -4.0,               // nearly full: excellent
        1 => 0.0,                // 12..23 left
        2 => 2.0,                // 24..35
        3 => 4.0,                // 36..47
        _ => 6.0,                // large leftover: wasteful placement
    };

    // Last-chance bin: if this is the only fitting bin, opening a new bin is costly.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate: only attractive when open bins would leave bad residuals
    // or when congestion is low. Base new-bin cost keeps best-fit preferred.
    if bin_residual == bin_capacity {
        score = 55.0
            - 0.25 * mean_residual
            - 2.0 * open_bins_count as f64
            + 0.05 * step_index as f64;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0; // new bin pairs well with the lookahead stream
        }
    }

    // Mild global pressure: as stream progresses, prefer compacting into few bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 3.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Fraction-of-capacity harmony: reward residuals that are clean fractions of C.
    let frac = post_residual as f64 / bin_capacity as f64;
    if (frac * 4.0).fract() < 1e-9 && post_residual > 0 {
        score -= 5.0; // residual is exactly C/4, C/2, 3C/4: very reusable
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for any
    // future item (min size 1..~10) are pure waste. Penalize the
    // "unusable gap" band super-linearly.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 6.0;
    }
    // Mid-range awkward gaps (10..20) are semi-dead: mild penalty.
    if post_residual >= 10 && post_residual < 20 {
        score += (20 - post_residual) as f64 * 0.8;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 12.0;

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins; opening new bins is expensive.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (1.0 + 0.5 * progress);
    score += pressure * 0.6;

    // New-bin candidate handling: empty bin starts with a handicap so we
    // only open when existing fits are poor, but relax the handicap when
    // this is the only fitting option (avoid forced terrible fits).
    if bin_residual == bin_capacity {
        score += 15.0 + pressure * 0.3;
        if fitting_bins_count <= 1 {
            score -= 25.0;
        }
    }

    // Last-chance bin: if this is the ONLY bin that fits, strongly favor
    // using it rather than opening a new bin (unless fit is awful).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Lookahead: if the next item fits exactly into the post_residual,
    // reward this placement (chained packing).
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap < 10 {
            score -= 10.0;
        } else {
            score -= 3.0;
        }
    }
    // If next item would be blocked by this placement leaving a dead gap.
    if next_item_size > post_residual && post_residual < 10 && post_residual > 0 {
        score += 8.0;
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins
    // get filled first, keeping larger residuals available).
    score -= (mean_residual - post_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual).
    score = post_residual as f64 * 1.0;

    // Aggressive 2-step lookahead: if the next item fits into the post residual,
    // strongly reward this bin (perfect chaining).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Next item fits: reward proportionally to how snug the chain is.
            let chain_waste = (post_residual - next_item_size) as f64;
            score -= 40.0 - chain_waste * 0.5;
        } else {
            // Next item does not fit: mild penalty scaled by overflow size.
            let overflow = (next_item_size - post_residual) as f64;
            score += overflow * 0.3;
        }
    } else {
        // Last item: pure tight-fit greedy.
        score -= 10.0;
    }

    // Relative-to-mean coupling: bins with residual below mean are "precious"
    // small-capacity bins; using them for a fitting item is good (subtract).
    let res_f = post_residual as f64;
    let mean_gap = res_f - mean_residual;
    score -= mean_gap * 0.25;

    // Last-chance bonus: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Penalize new-bin candidate unless current bins are poor fits.
    if bin_residual == bin_capacity {
        // New bin baseline: its post_residual is large, but if no good fit
        // exists among open bins (high mean residual mismatch), allow opening.
        let stream_frac = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // Late in the stream, prefer consolidating into open bins.
        score += 25.0 - stream_frac * 10.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 15.0; // fresh bin can still chain the next item
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // nothing else fits: must open new bin
        }
    }

    // Small penalty for leaving tiny unusable slivers (< smallest plausible item).
    if res_f > 0.0 && res_f < 5.0 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits (small post-residual) non-linearly.
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 12.0 * tightness * tightness;

    // Penalize dead space: residuals too small to hold typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Last-chance bonus: only bin that fits -> avoid opening new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: reward if next item fits in post-residual.
    if next_item_size > 0 {
        if (post_residual as u64) >= next_item_size as u64 {
            score -= 8.0 + 0.15 * next_item_size as f64;
        } else {
            score += 4.0;
        }
    }

    // Prefer bins with below-mean residual (keep large holes for future items).
    score += 0.25 * (bin_residual as f64 - mean_residual).max(0.0);

    // Late in stream: consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 - 0.15 * progress;

    // When many bins are open, discourage opening new bins.
    if bin_residual == bin_capacity {
        score += 10.0 + 1.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: waste after placement, with non-linear growth for tiny residuals (dead space)
    let mut score = pr as f64;

    // Smooth polynomial coupling of post_residual with stream progress:
    // late in the stream, small residuals become more acceptable (bins get closed out),
    // large residuals become more penalized.
    let poly = norm_pr * norm_pr * (0.5 + 2.0 * progress) - norm_pr * (1.5 - progress);
    score += 40.0 * poly;

    // Reward near-perfect fits smoothly (continuum of the "best fit" idea)
    let fit_bonus = (1.0 - norm_pr).powi(6);
    score -= 30.0 * fit_bonus;

    // Lookahead: if next item fits into post_residual, reward this placement smoothly
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).max(0) as f64;
        let reuse = (gap / cap).clamp(0.0, 1.0);
        score -= 15.0 * (1.0 - reuse) * (1.0 - progress);
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 + 20.0 * progress;
    }

    // Mild penalty for spreading across too many open bins relative to mean residual
    score += 0.05 * (open_bins_count as f64).sqrt() * (mean_residual - pr).abs();

    // New-bin candidate: neutral-ish anchor; smooth quadratic in wasted space
    if bin_residual == bin_capacity {
        score = 0.5 * cap + 30.0 * norm_pr * norm_pr - 10.0 * (1.0 - norm_pr);
        if fitting_bins_count == 1 {
            score += 40.0; // don't open a new bin when a lone fitting bin exists
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space into capacity fractions.
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    let three_quarter = 3 * quarter;

    // Dead-space penalty via integer-division classes: residual < 10 is near-perfect.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 30.0;
    } else {
        // Penalize residuals in awkward harmonic bands (11..25 are hard to fill with 10..80 items).
        if post_residual <= 25 {
            score += 15.0;
        }
        // Reward residuals that are multiples of common item classes (10, 20, 25, 50).
        if post_residual % 10 == 0 {
            score -= 8.0;
        }
        if post_residual % 25 == 0 {
            score -= 5.0;
        }
        if post_residual % 50 == 0 {
            score -= 5.0;
        }
    }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 10.0;
            // harmonic match: next item leaves a small class again
            let next_post = post_residual - next_item_size;
            if next_post % 10 == 0 {
                score -= 6.0;
            }
            if next_post <= 10 {
                score -= 10.0;
            }
        } else {
            // next item won't fit here; penalize slightly more for large leftover classes
            if post_residual >= half {
                score += 10.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: discourage opening a new bin when a decent fit exists.
    if bin_residual == bin_capacity {
        score += 60.0;
        // But if no open bin fits well (item nearly fills a fresh bin), allow opening.
        if item_size >= three_quarter {
            score -= 70.0;
        }
        // Late in stream with many open bins, prefer consolidation.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    // Mean-residual coupling: placing into a bin far below mean residual reduces fragmentation.
    if bin_residual as f64 > mean_residual {
        score += (bin_residual as f64 - mean_residual) * 0.3;
    } else {
        score -= (mean_residual - bin_residual as f64) * 0.1;
    }

    // Modulo harmonic class on bin_residual itself: bins whose residual is a "nice" class
    // are easier to keep tidy.
    if bin_residual % 10 == 0 && bin_residual != bin_capacity {
        score -= 3.0;
    }

    // Many open bins: encourage filling existing ones tightly.
    if open_bins_count > 4 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (< 10) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual == 0 {
        // Perfect fit is highly rewarded.
        score -= 60.0;
    }

    // Penalize gaps that are too small for the known next item (likely dead space).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0 + 0.2 * (next_item_size as f64 - post_residual as f64);
    }
    // Reward gaps that can still host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 4.0;
    }

    // Reward tight fits relative to bin residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fill_ratio;

    // Open-bin pressure: with many open bins, discourage spreading; prefer filling existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.35 * open_bins_count as f64 * (0.5 + progress);

    // Mean-residual coupling: if this bin's residual is far below the mean, it's a "junk" bin; filling it is good.
    let residual_gap = mean_residual - bin_residual as f64;
    score += 0.15 * residual_gap;

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let scarcity = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let bad_open_options = (fitting_bins_count as f64).recip();
        score = 100.0
            - 45.0 * scarcity
            - 20.0 * bad_open_options
            - 10.0 * progress
            + 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: leave exactly the next item's size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 200.0;
    }

    // Near matches: reward small |post_residual - next_item_size|.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 30.0 / (1.0 + gap);
        // Penalize residuals that are too small for the next item (dead space).
        if post_residual < next_item_size {
            score += 0.35 * (next_item_size - post_residual) as f64;
        }
    } else {
        // Last item: strongly prefer the fullest bin.
        score -= 100.0;
    }

    // Penalize very small unusable residuals (< 10, min item size).
    if post_residual < 10 {
        score += 60.0;
    }

    // Compare against mean residual: bins already tighter than average are good targets.
    score -= 0.4 * (mean_residual - post_residual as f64);

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: penalize it unless no good fit exists.
    if bin_residual == bin_capacity {
        let good_fit_exists = next_item_size > 0 && post_residual == 0;
        let mut penalty = 150.0;
        if fitting_bins_count == 1 {
            penalty -= 90.0;
        }
        if item_size >= 70 {
            penalty -= 20.0; // large items: fresh bin often better
        }
        if good_fit_exists {
            penalty += 100.0;
        }
        // Early in stream, keep bins open fewer; later, allow new bins more freely.
        let progress = step_index as f64 / total_items.max(1) as f64;
        penalty -= 20.0 * progress;
        score += penalty;
    }

    // Mild preference for bins with larger current residual when item is large.
    score -= 0.05 * item_size as f64 * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual)
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 12.0 * fit_ratio;

    // Penalize dead space: post_residual too small to ever be useful
    if post_residual < 10 && post_residual > 0 {
        score += 18.0;
    }

    // Last-chance bin: strongly favor it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate logic: only attractive when it serves the lookahead item
    if bin_residual == bin_capacity {
        let mut bonus = 6.0; // mild default penalty
        if next_item_size > 0 {
            if next_item_size <= 100 && next_item_size >= post_residual {
                // new bin can host next item in its residual
                bonus -= 14.0;
            }
            if next_item_size + item_size <= bin_capacity {
                bonus -= 10.0;
            }
        }
        // Late in stream, prefer packing into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        bonus += 8.0 * progress;
        // Many open bins -> discourage opening more
        bonus += 1.5 * open_bins_count as f64;
        score += bonus;
    } else {
        // Lookahead synergy: if next item fits in post_residual, big reward
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 20.0;
        }
        // Penalize bins whose residual is far from mean (fragmentation)
        score += 0.08 * (bin_residual as f64 - mean_residual).abs();
    }

    // Global pressure: fewer fitting bins relative to open bins -> be more permissive
    if fitting_bins_count > 0 {
        let scarcity = 1.0 - (fitting_bins_count as f64 / open_bins_count.max(1) as f64);
        score -= 6.0 * scarcity;
    }

    // Encourage using bins that are already quite full
    let fullness = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 10.0 * fullness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    // Base: penalize residual, with non-linear polynomial shaping.
    // Small residuals are good (tight fit); huge residuals waste a bin.
    let mut score = pr as f64;
    score += 18.0 * x * (1.0 - x);          // hump penalizes mid-range waste
    score -= 30.0 * x * x * x;              // reward very tight fits (tiny x)
    score += 12.0 * x * x;                  // extra quadratic waste penalty

    // Stream-progress coupling: late in the stream, tighten fits more aggressively.
    let tighten = 1.0 + 0.8 * progress;
    score *= tighten;

    // Lookahead: if next item fits in the post-residual, reward this bin;
    // if next item barely misses, penalize leaving a teasing gap.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if n <= pr {
            score -= 14.0 * (1.0 - (pr - n) / cap);
        } else {
            score += 10.0 * (1.0 - pr / n);
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // Among many candidates, prefer tighter fits relatively more.
        score += 3.0 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // New-bin candidate: only attractive when existing bins would waste badly.
    if bin_residual == bin_capacity {
        let waste_if_forced = (mean_residual - pr).max(0.0);
        score = 55.0 + 40.0 * progress - 0.5 * waste_if_forced;
    }

    // Mild pressure against hoarding many open bins early.
    score += 0.15 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the item: coarse size classes via integer division
    let item_class = item_size / 10;
    let next_class = next_item_size / 10;

    // Post-residual harmonic class: how "usable" is the leftover space?
    let pr = post_residual;
    // Residuals that are multiples of small harmonics (e.g. 10, 20, 25, 50) are more reusable
    let harmonic_bonus = if pr == 0 {
        40.0 // perfect fit, strongly reward
    } else if pr % 50 == 0 {
        18.0
    } else if pr % 25 == 0 {
        12.0
    } else if pr % 10 == 0 {
        9.0
    } else if pr % 5 == 0 {
        5.0
    } else {
        0.0
    };
    score -= harmonic_bonus;

    // Penalize tiny unusable dead space non-linearly
    if pr > 0 && pr < 10 {
        score += 25.0 * (10 - pr) as f64 / 10.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 && next_item_size <= pr {
        let slack = pr - next_item_size;
        let lookahead_reward = if slack == 0 {
            30.0
        } else if slack % 10 == 0 {
            15.0
        } else {
            8.0
        };
        score -= lookahead_reward;
    } else if next_item_size > 0 && next_item_size > pr {
        // next item won't fit here; slight penalty proportional to mismatch class
        let mismatch = (next_class as i32 - (pr / 10) as i32).abs();
        score += 2.0 * mismatch as f64;
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are crowded
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowding = mean_residual / bin_capacity as f64;
        // open new bin only if mean residual is low (bins are full) or late in stream with many bins
        let open_penalty = 45.0 - 20.0 * (1.0 - crowding) - 10.0 * progress;
        score += open_penalty;
    } else {
        // reward packing into bins whose residual is close to item (tight fit)
        let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
        score += 10.0 * tightness;

        // prefer bins with residual near item size in harmonic classes
        if bin_residual / 10 == item_size / 10 + 1 {
            score -= 6.0;
        }
    }

    // Mild pressure to consolidate when many bins are open
    score += 0.3 * open_bins_count as f64 * (pr as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small nonzero gaps are nearly useless.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 18.0;
    }

    // Reward near-exact fits.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Dead space is worse if it can't host the lookahead item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }

    // Pressure from number of open bins: discourage opening new bins when many are open.
    if bin_residual == bin_capacity {
        score += 10.0 + 4.0 * open_bins_count as f64;
    } else {
        score -= 2.0;
    }

    // Last-chance bin: strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Mean residual coupling: prefer bins deviating below the mean (tighter usage).
    score += 0.5 * ((post_residual as f64) - mean_residual).max(0.0);

    // Early stream: be slightly conservative about tight fits to keep flexibility.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 - 0.1 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Post residual can accommodate the next item comfortably (within a slack band).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 20.0 * (1.0 - slack / (bin_capacity as f64 * 0.5)).max(0.0);
    }
    // Post residual too small for next item: dead-space penalty, scaled by how close to unusable.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        let gap = (next_item_size - post_residual) as f64;
        score += 12.0 * (1.0 - gap / next_item_size as f64);
    }

    // Reward tightening bins relative to the mean residual (best-fit flavor).
    let pr = post_residual as f64;
    if pr < mean_residual {
        score -= 8.0 * (mean_residual - pr) / bin_capacity as f64;
    } else {
        score += 6.0 * (pr - mean_residual) / bin_capacity as f64;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize mildly so it is chosen only when it beats poor fits,
    // but less harshly when many bins are open (consolidation pressure lower).
    if bin_residual == bin_capacity {
        score += 10.0 + 2.0 * (open_bins_count as f64).sqrt();
        // If no open bin gives a good lookahead match, allow new bin more easily.
        if next_item_size > 0 && post_residual != next_item_size {
            score -= 5.0;
        }
    }

    // Slight preference to fill bins later in the stream (fewer chances remain).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * (bin_capacity - post_residual) as f64 / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction of the stream
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tight-fit reward: strongly prefer bins whose residual is consumed well.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * tightness * tightness;

    // Penalize large unusable dead space after placement (post_residual < 10 is ideal).
    if post_residual > 0 {
        let dead = post_residual as f64;
        score += 0.6 * dead.sqrt();
        // Dead space is worse late in the stream when fewer chances remain to fill it.
        score += 1.5 * progress * (dead / bin_capacity as f64);
    }
    if post_residual == 0 {
        score -= 25.0; // perfect fill
    }

    // Lookahead: reward when post_residual exactly accommodates the next item (chaining).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            score -= 6.0 * (post_residual as f64 / next_item_size as f64).ln().max(0.0);
        } else {
            // Next item can't use this residual: penalize proportionally.
            score += 0.4 * (next_item_size as f64 - post_residual as f64).min(40.0);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0 + 15.0 * progress;
    }

    // New-bin candidate handling: penalize opening a new bin, more when many bins
    // are open (consolidation pressure) or early in the stream.
    if bin_residual == bin_capacity {
        let consolidation = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
        score += 18.0 + 30.0 * consolidation + 20.0 * (1.0 - progress);
        // But if mean residual across open bins is small (all bins nearly full),
        // opening a new bin becomes more attractive.
        score -= 0.5 * (bin_capacity as f64 - mean_residual).max(0.0);
        // If the item is large and no tight fit exists, new bin is less penalized.
        if item_size >= 60 {
            score -= 10.0;
        }
    } else {
        // Prefer using existing bins when they fit well: mild global pressure.
        score -= 0.3 * mean_residual.min(50.0) / 50.0;
    }

    // Small jitter-free tie-break: prefer bins with lower residual among equals.
    score += 0.01 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap;
    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = x * x * (1.0 - x) * (1.0 - x);
    score -= 40.0 * poly * (0.5 + progress);

    // Reward tight fits more strongly as the stream progresses
    let tightness = 1.0 - x;
    score -= tightness * tightness * 25.0 * (0.3 + 0.7 * progress);

    // Penalize large post residuals mildly, scaled by open bin count
    score += 0.05 * pr * (open_bins_count as f64).sqrt() * 0.1;

    // Last-chance bin bonus (smooth)
    let last_chance = if fitting_bins_count <= 1 { 1.0 } else { 0.0 };
    score -= 30.0 * last_chance * (1.0 - progress * 0.5);

    // Lookahead: reward leaving space compatible with next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let compat = if nx <= pr as f64 { (pr - nx) / cap } else { (nx - pr) / cap };
        score += 20.0 * compat * compat;
        score -= 10.0 * (1.0 - compat) * (1.0 - x);
    }

    // Mean residual context: penalize bins far from mean residual
    score += 0.15 * (pr - mean_residual).abs();

    // New bin candidate: penalize slightly so it only wins when open bins are bad
    if bin_residual == bin_capacity {
        score += 15.0 - 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: capacity fractions (1/2, 1/3, 1/4)
    let half = bin_capacity / 2;
    let third = bin_capacity / 3;
    let quarter = bin_capacity / 4;

    // Reward near-perfect fits strongly
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= quarter {
        score -= 60.0;
    } else if post_residual <= third {
        score -= 25.0;
    } else if post_residual <= half {
        score -= 5.0;
    } else {
        // Large dead space penalty, superlinear
        score += (post_residual - half) as f64 * 0.8;
    }

    // Modulo arithmetic on post_residual: multiples of small divisors are reusable slots
    if post_residual > 0 && post_residual % 10 == 0 {
        score -= 8.0;
    }
    if post_residual % 5 == 0 {
        score -= 3.0;
    }
    // Odd awkward residuals are less likely to be filled
    if post_residual % 2 == 1 && post_residual > quarter {
        score += 4.0;
    }

    // Lookahead coupling: if next item fits into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 30.0 + (post_residual - next_item_size) as f64 * 0.5;
        } else if next_item_size <= bin_residual {
            // next item fits in current residual but not post -> placing here kills that option
            score += 10.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Prefer denser bins (tight packing) when many bins are open
    score -= (bin_capacity as f64 - bin_residual as f64) * 0.3;

    // New-bin candidate: only attractive when nothing fits well
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Opening a new bin costs a fixed price, reduced early in the stream
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 120.0 - 20.0 * progress;
        if fitting_bins_count > 0 {
            // discourage new bin if some bin offers a decent fit
            if post_residual_would_be_good(item_size, bin_capacity) {
                score += 500.0;
            }
        }
    }

    // Small pressure to consolidate: fewer open bins is better
    score += open_bins_count as f64 * 0.05;

    // Slight preference for bins below mean residual (keeps residuals balanced)
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    }

    score
}

// helper inline (no extra state)
fn post_residual_would_be_good(item_size: u32, bin_capacity: u32) -> bool {
    let r = bin_capacity - item_size;
    r <= bin_capacity / 3
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // for typical future items are "dead space" -> heavy penalty.
    let dead_threshold = 20.0;
    if post_residual > 0 {
        let usable = (post_residual as f64 - dead_threshold).max(0.0);
        // Reward only the usable portion of residual, heavily discount dead part
        score = usable * 1.5 + (post_residual as f64).min(dead_threshold) * 4.0;
        if post_residual == 0 {
            // Perfect fit: strong reward
            score = -50.0;
        }
    } else {
        score = -50.0;
    }

    // Open bins pressure: discourage opening new bins when many bins are open
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 30.0 + 5.0 * open_bins_count as f64;
    } else {
        score -= 2.0 * open_bins_count.min(10) as f64;
    }

    // Last-chance bin: strongly prefer using the only bin that fits
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 40.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 && post_residual > 0 && next_item_size == post_residual {
        score -= 60.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= (post_residual - next_item_size) as f64 * 0.5;
    }

    // Mean residual coupling: prefer bins with residual below mean (tighter bins)
    if !is_new_bin {
        score += (mean_residual - bin_residual as f64) * 0.3;
    }

    // Late in stream: consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    if !is_new_bin {
        score -= 10.0 * progress;
    } else {
        score += 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit is the best possible outcome.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: if the next item exactly fills the new residual,
    // this bin is an ideal chain placement.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 500.0;
    }
    // Next item still fits comfortably in the leftover space: mild reward.
    else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 30.0 + (next_item_size as f64 / 10.0);
    }
    // Next item will NOT fit here: penalize dead space proportional to residual.
    else if next_item_size > 0 {
        score += 40.0 + post_residual as f64 * 0.5;
    }

    // Reward tight fits relative to capacity (small waste per placement).
    score -= (bin_capacity as f64 / (post_residual as f64 + 1.0)) * 5.0;

    // Compare against mean residual: prefer bins whose residual stays
    // near the mean (balanced packing), penalize outliers.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.3;

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        score += 150.0 + open_bins_count as f64 * 5.0;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 20.0; // pair fits fine in a fresh bin
        } else {
            score += 50.0;
        }
    }

    // Slight stream-progression pressure: as the stream matures, prefer
    // consolidating into existing bins over opening new ones.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        if bin_residual != bin_capacity {
            score -= progress * 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 50.0;
    } else {
        // Penalize small-but-nonzero dead space (unusable slivers).
        let dead = post / cap;
        if post <= 10.0 {
            score += (10.0 - post) * 3.0;
        }
        // Mild reward for leaving room that could fit a typical item.
        score += dead * 5.0;
    }

    // Lookahead: if the next item fits exactly in post_residual, reward heavily.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual > next_item_size {
            score -= 8.0;
        } else {
            // Next item can't fit here; slightly penalize wasting large residual.
            score += (next_item_size as f64 - post) * 0.3;
        }
    }

    // Last-chance bonus: this is the only bin that fits; avoid opening new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when open bins fit poorly.
    if bin_residual == bin_capacity {
        // Penalize opening a new bin when good options exist.
        score += 15.0;
        // But if the item is large relative to capacity and mean residual is low,
        // opening a fresh bin is reasonable.
        let fill = item_size as f64 / cap;
        if fill > 0.6 {
            score -= 10.0 * fill;
        }
        if mean_residual < fill * cap {
            score -= 10.0;
        }
        // Late in stream, prefer using existing bins.
        let t = step_index as f64 / total_items.max(1) as f64;
        score += t * 20.0;
    }

    // Global pressure: many open bins with high mean residual -> consolidate.
    if open_bins_count > 2 && bin_residual < bin_capacity {
        score -= mean_residual * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    // Base: prefer small post residual, non-linearly scaled
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, tolerate larger residuals; late, demand tight fits.
    let progress_weight = 0.35 + 0.9 * progress * (2.0 - progress);
    score += progress_weight * norm_pr * pr;

    // Penalize dead space that no future item can plausibly use
    if next_item_size > 0 {
        let gap = (next_item_size as f64 - pr).max(0.0);
        score += 0.6 * gap * (1.0 + progress);
        // Reward if next item fits exactly in the post residual
        if (next_item_size as f64) <= pr {
            score -= 0.5 * (next_item_size as f64 / cap) * (1.0 + 0.5 * progress);
        }
    } else {
        // Last item: strongly prefer fullest packing
        score -= 2.0 * norm_item * pr / cap;
    }

    // Last-chance bin bonus: avoid opening a new bin when this is the only fit
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 1.5 * (1.0 - progress);
    }

    // Compare against mean residual: bins tighter than average are valuable
    let mean_norm = mean_residual / cap;
    score += 0.4 * (norm_pr - mean_norm) * (1.0 + progress);

    // New-bin candidate handling: neutralize its raw post_residual advantage
    if bin_residual == bin_capacity {
        let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
        score += 3.0 * (1.0 - progress) * (1.0 + scarcity) + 0.5 * mean_norm;
    }

    // Mild penalty for proliferating open bins late in the stream
    score += 0.02 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead-space classes mod capacity fractions.
    // Residuals that are unusable for typical items are heavily penalized.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Class by quarter-capacity bands: residuals in the lowest band are near-dead.
    if post < 10.0 {
        score += 40.0; // tiny dead space: bin essentially full (good, but useless for others)
    } else if post < cap / 4.0 {
        score += 18.0; // narrow sliver: only tiny items can use it
    } else if post < cap / 2.0 {
        score -= 6.0; // mid band: still useful for mid-size items
    } else {
        score -= 12.0; // large residual: keep bins roomy
    }

    // Integer-division harmonic class: post_residual / item_size ratio.
    // Favor bins where the leftover could host the next item (perfect chaining).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Next item fits here afterwards: strong reward, scaled by tightness.
            let slack = (post_residual - next_item_size) as f64;
            score -= 14.0 - (slack / cap) * 10.0; // exact fit afterwards rewarded most
        } else {
            // Next item won't fit after this placement: mild penalty,
            // worse if this bin was the only one that could take current item.
            score += 6.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: bin_residual == bin_capacity means empty bin.
    // Penalize opening a new bin unless the current fit is poor (large post_residual
    // waste in every open bin, or no open bin fits well).
    if bin_residual == bin_capacity {
        // Base penalty for wasting a fresh bin.
        score += 30.0;
        // If the item leaves a large hole in a fresh bin relative to capacity,
        // opening new bins early is sometimes fine; scale with stream position:
        // early in stream, prefer consolidating; late, allow more bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 10.0;
        // If many bins are open and mean residual is low, new bin is less costly.
        score -= (open_bins_count as f64).min(10.0) * 0.5;
        // If mean residual across open bins is small (all bins nearly full),
        // a new bin is the natural choice.
        if mean_residual < 15.0 {
            score -= 20.0;
        }
    }

    // Modulo-class coupling: residual classes congruent to small values mod 10
    // pair well with item sizes that are multiples of 10 (harmonic alignment).
    let r_mod = post_residual % 10;
    let i_mod = item_size % 10;
    if r_mod == 0 && i_mod == 0 {
        score -= 4.0; // aligned harmonic class: clean packing
    } else if r_mod != 0 && i_mod != 0 && (r_mod + i_mod) == 10 {
        score -= 3.0; // complementary residues: fills to a multiple of 10
    }

    // Slight preference for tighter fits overall (fine-grained tiebreak).
    score += (item_size as f64) * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that no item can plausibly use are costly.
    // Treat post_residual < 10 as fully dead; scale penalty sharply.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - 6.0 * post_residual as f64; // dead gap penalty up to +54
    } else if post_residual == 0 {
        score -= 25.0; // perfect fit is gold
    }

    // Penalize gaps that are dead relative to the next item's needs:
    // a gap smaller than next_item_size (when next item won't fit) is wasted space.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }
    // Reward gaps that exactly or nearly fit the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 3.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
    }

    // Tight fit reward relative to bin capacity.
    score -= 10.0 * (item_size as f64 / bin_capacity as f64);

    // Open-bin pressure: discourage spreading across many bins when residuals are small.
    score += 0.35 * open_bins_count as f64 * (1.0 - mean_residual / bin_capacity as f64);

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: only attractive late in the stream or when it enables a
    // much better future fit; otherwise penalize so existing bins are preferred.
    if bin_residual == bin_capacity {
        score += 18.0 + 0.2 * open_bins_count as f64;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 15.0; // pairing lookahead items in a fresh bin is good
        }
        if total_items > 0 && (step_index as f64) / (total_items as f64) > 0.9 {
            score += 10.0; // near the end, don't open bins for leftovers
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: residual fully consumed -> strongly reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: if the next item exactly fills the post-residual,
    // this is a perfect chain -> big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            // Next item fits here too: good chaining.
            let slack_after_next = post_residual - next_item_size;
            score -= 100.0 * (1.0 - slack_after_next as f64 / bin_capacity as f64);
        } else {
            // Dead space: next item cannot use the leftover.
            let waste = next_item_size - post_residual;
            score += 30.0 + waste as f64;
        }
    } else {
        // Last item: prefer minimal leftover.
        score += 0.0;
    }

    // Compare post_residual against mean residual across open bins:
    // leaving less than average behind is efficient packing.
    score -= 2.0 * (mean_residual - post_residual as f64);

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New empty bin candidate: only attractive when the item is large
    // relative to residual space available elsewhere, or many bins already open.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 > 0.6 * bin_capacity as f64;
        let crowded = open_bins_count as f64 > 8.0;
        if large_item || crowded {
            score -= 60.0;
        } else {
            score += 120.0; // prefer filling existing bins
        }
    }

    // Slight progression bias: later in the stream, consolidation matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to capacity.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 12.0 * tightness * tightness;

    // Penalize very small dead space creation asymmetrically: residuals that
    // are too small for the smallest item are pure waste.
    if post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 8.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, strongly reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            let gap = post_residual - next_item_size;
            if gap < 10 {
                score -= 10.0;
            } else {
                score += gap as f64 * 0.15;
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it over
    // opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bins should only win when open bins
    // are mostly full or the item is large.
    if bin_residual == bin_capacity {
        let mean_fill = 1.0 - (mean_residual / bin_capacity as f64);
        let pressure = mean_fill * (open_bins_count as f64).sqrt();
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // High pressure / late stream => opening new bin is cheap.
        score += 30.0 - 25.0 * pressure - 15.0 * progress;
        if item_size > bin_capacity / 2 {
            score -= 10.0;
        }
    }

    // Global state: many open bins with large mean residual => prefer reusing
    // bins with residual close to mean (consolidate).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Slight preference for bins with residual just above item (best-fit flavor).
    score += 0.02 * (bin_residual - item_size) as f64;

    // Mild time-horizon coupling: early in stream, be conservative (favor
    // filling existing bins); later, allow more freedom.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 - 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: penalize wasted post residual, non-linearly
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Polynomial coupling of post_residual with stream progress:
    // late in the stream, tight fits (small post_residual) matter more
    let coupling = norm_pr * (1.0 - norm_pr);
    score -= 12.0 * coupling * (1.0 - progress) * (1.0 - progress);

    // Reward using a bin whose post-residual can host the lookahead item
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 6.0 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 {
        score += 4.0 * (1.0 - progress) * (next_item_size as f64 / cap);
    }

    // Last-chance bin: strongly favor to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * (1.0 - progress);
    }

    // Penalize bins far from mean residual (fragmentation avoidance)
    score += 0.3 * ((pr - mean_residual) / cap).abs();

    // Mild pressure to prefer fuller bins as open bins accumulate
    score += (open_bins_count as f64).ln() * norm_pr * 2.0;

    // New-bin candidate: neutral baseline with slight late-stream penalty
    if bin_residual == bin_capacity {
        score = cap * (0.55 + 0.45 * progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: classify post_residual into residue classes mod 10
    // and next_item_size into size classes mod 20.
    let post_class = post_residual % 10;
    let next_class = next_item_size % 20;

    // Reward when the post residual class aligns with the next item's class
    // (i.e. next item could fit into leftover space nicely).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
        // Harmonic bonus: post_residual is a multiple of a fraction of capacity
        if post_residual % 25 == 0 {
            score -= 4.0;
        }
        if post_residual % 50 == 0 {
            score -= 3.0;
        }
        // Next item's class matches leftover class -> strong reward
        if next_class == post_class {
            score -= 5.0;
        }
    } else if next_item_size > 0 {
        // Leftover too small for next item: penalize dead space, worse if tiny class
        score += (post_residual as f64) * 0.15;
        if post_class == 0 && post_residual > 0 {
            score -= 1.0; // still a clean multiple, slightly less bad
        }
    }

    // Integer-division thresholds on post_residual
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    if post_residual < quarter {
        score += 8.0; // very tight leftover: nearly full bin, but risk of dead space
        if post_residual == 0 {
            score -= 20.0; // perfect fit: best outcome
        }
    } else if post_residual < half {
        score -= 2.0;
    } else {
        score += 3.0; // leaving more than half: poor packing
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        // Opening a new bin is reasonable only if existing bins fit poorly
        let poor_fit = (post_residual as f64) > (bin_capacity as f64) * 0.5
            && next_item_size > 0 && next_item_size > post_residual;
        if poor_fit {
            score -= 10.0;
        } else {
            score += 25.0; // prefer filling existing bins
        }
        // Late in the stream, be more conservative about opening bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 5.0;
    }

    // Slight preference for tighter bins overall
    score -= (bin_residual as f64 / bin_capacity as f64) * 2.0;

    // Mean residual coupling: if mean residual is high, prefer bins below mean
    if (bin_residual as f64) < mean_residual {
        score -= 1.5;
    } else {
        score += 1.5;
    }

    // Many open bins: encourage consolidation
    if open_bins_count > 8 {
        score += 0.5 * open_bins_count as f64 * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small to ever hold an item are wasted forever.
    let min_item = 1u32;
    if post_residual < min_item {
        // perfect fit, ideal
        score -= 1000.0;
    } else if post_residual < 10 {
        // unusable dead space: heavy penalty scaled by how dead it is
        score += (10.0 - post_residual as f64) * 25.0;
    } else {
        // usable gap: mild reward proportional to tightness of fit
        score -= (bin_residual as f64 - post_residual as f64) * 0.5;
    }

    // Reward when the leftover can exactly host the lookahead item (k=2 chaining)
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }

    // Penalize waste relative to mean residual state of the system
    score += (post_residual as f64 - mean_residual).max(0.0) * 0.3;

    // Open-bin pressure: discourage opening new bins when many bins already exist,
    // but allow it when this bin is the last chance and the fit is tight.
    if bin_residual == bin_capacity {
        // new-bin candidate: bias against unless item is large relative to capacity
        score += 20.0 + 0.5 * (bin_capacity as f64 - item_size as f64);
        if fitting_bins_count == 0 {
            score -= 50.0; // forced to open a new bin
        }
    } else if fitting_bins_count == 1 {
        // last chance before opening a new bin: reward using it if fit is decent
        if post_residual < 10 {
            score += 100.0; // would create dead space anyway
        } else {
            score -= 40.0;
        }
    }

    // Mild pressure to consolidate into fewer bins over the stream
    score += open_bins_count as f64 * 0.05 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post-residual) with a super-linear penalty on slack.
    let tightness = (bin_residual as f64 - item_size as f64).max(0.0);
    score += (tightness * tightness) / (bin_capacity as f64);

    // Exact fit bonus: perfectly filling the bin is highly desirable.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when next_item_size exactly matches post_residual.
    if next_item_size > 0 {
        let lookahead_gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += lookahead_gap * 2.0;
        if post_residual == next_item_size {
            score -= 500.0; // perfect two-item chain
        }
        // Penalize leaving dead space that the next item cannot use.
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 1.5;
        }
        // Bonus if post_residual can still host the next item (keeps bin useful).
        if post_residual >= next_item_size {
            score -= 20.0;
        }
    }

    // Compare against mean residual: bins with residual far above mean waste space.
    score += ((bin_residual as f64 - mean_residual) * 0.5).max(0.0);

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: only attractive when it enables a good lookahead fit
    // (empty bin can chain item + next item) or late in the stream.
    if bin_residual == bin_capacity {
        let chain_bonus = if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            0.0
        } else {
            60.0
        };
        score += 80.0 + chain_bonus
            - (step_index as f64 / total_items.max(1) as f64) * 30.0;
        // Deter new bins when many bins are already open and one fits well.
        if open_bins_count > 0 && fitting_bins_count > 0 {
            score += 40.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near 0 is ideal.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 6.0 * tightness * tightness;

    // Penalize dead space that no plausible future item can use.
    // Small residuals (<10) are effectively dead; big residuals are reusable.
    if post_residual < 10 {
        score += 3.0;
    } else if post_residual <= 20 {
        score -= 1.5; // usable by mid items
    }

    // Lookahead coupling: if next item fits the post residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 4.0 + 0.05 * (post_residual - next_item_size) as f64;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item won't fit here; slight penalty proportional to mismatch
        score += 0.5;
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 5.0;
    }

    // Prefer fuller bins among many open bins (mild best-fit pressure).
    let fill = 1.0 - (bin_residual as f64) / (bin_capacity as f64);
    score -= 2.0 * fill;

    // Time horizon: early in stream, keep residuals large (future flexibility);
    // late in stream, prioritize filling bins tightly to avoid new bins.
    let t = step_index as f64 / total_items.max(1) as f64;
    score -= t * 3.0 * tightness;
    score += (1.0 - t) * 0.02 * post_residual as f64;

    // Global state: if mean residual is low and many bins are open, avoid
    // fragmenting; if mean residual is high, prefer using existing bins.
    if open_bins_count > 0 {
        let mr_ratio = mean_residual / bin_capacity as f64;
        score -= 2.0 * (1.0 - mr_ratio) * (open_bins_count as f64).ln();
    }

    // New-bin candidate: only attractive when no open bin fits well
    // (large item relative to all residuals) or late in the stream with
    // fragmented bins. Penalize opening new bins otherwise.
    if bin_residual == bin_capacity {
        let no_good_fit = fitting_bins_count == 0;
        let big_item = item_size as f64 > mean_residual;
        if no_good_fit || (big_item && t > 0.5) {
            score -= 4.0;
        } else {
            score += 8.0 + 0.1 * item_size as f64;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let p = progress;
    let poly = 1.0 + 2.0 * p * norm_pr + 3.0 * p * p * norm_pr * norm_pr;
    score *= poly;

    // Reward tight fits, more strongly late in the stream
    score -= (1.0 - norm_pr) * (1.0 - norm_pr) * (10.0 + 20.0 * p);

    // Penalize dead space below the smallest plausible item, scaled by progress
    if norm_pr < 0.1 {
        score += (0.1 - norm_pr) * 40.0 * (0.5 + p);
    }

    // Last-chance bonus: only one fitting bin -> strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * p;
    }

    // Lookahead: if the next item fits exactly into post_residual, reward
    if next_item_size > 0 && (next_item_size as f64) == pr {
        score -= 12.0;
    } else if next_item_size > 0 && next_item_size as u32 > post_residual {
        // next item won't fit here; slight penalty for wasting residual
        score += (next_item_size as f64 - pr).min(cap) * 0.05 * (1.0 - p);
    }

    // Mild penalty for spreading across many open bins when mean residual is low
    let mr = mean_residual / cap;
    score += (open_bins_count as f64).ln() * mr * 3.0 * (1.0 + p);

    // New-bin candidate adjustment: prefer new bin early, or when residuals are poor
    if bin_residual == bin_capacity {
        let new_bin_bias = 8.0 - 20.0 * p - 30.0 * (1.0 - mr);
        score += new_bin_bias;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: perfect fits get a strong bonus.
    let pr = post_residual;
    if pr == 0 {
        score -= 500.0;
    } else if pr <= 5 {
        score -= 200.0;
    } else if pr <= 10 {
        score -= 100.0;
    } else if pr <= 20 {
        score -= 30.0;
    }

    // Dead-space penalty grows super-linearly for unusable slivers:
    // residuals that few future items can exploit (1..=9) are poison.
    if pr > 0 && pr < 10 {
        score += 40.0 * (10 - pr) as f64;
    }

    // Integer-division class of residual capacity: bins whose residual is a
    // multiple of common item sizes are more reusable.
    let div_class = (pr / 10) as f64;
    score -= 8.0 * div_class;

    // Lookahead coupling: if the next item fits exactly in the post-residual,
    // strongly favor this bin (chains two placements).
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 300.0;
        } else if next_item_size <= pr {
            // next item fits: residual after that placement matters
            let pr2 = pr - next_item_size;
            if pr2 == 0 { score -= 150.0; }
            else if pr2 < 10 { score += 15.0 * (10 - pr2) as f64; }
        } else {
            // next item cannot use this residual: mild penalty for hoarding space
            score += 10.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, penalize opening
    // a new bin instead (new bin call will have higher base score).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: base cost of opening a fresh bin, discounted when
    // existing bins are all poor fits (high mean residual fragmentation).
    if bin_residual == bin_capacity {
        score += 120.0;
        // If the item is large and fits nowhere else, opening is fine.
        if item_size as f64 > 0.5 * cap {
            score -= 40.0;
        }
        if mean_residual < 15.0 {
            score -= 50.0; // existing bins nearly full anyway
        }
    }

    // Prefer filling bins that are already mostly full (small residual).
    score -= 0.5 * (cap - bin_residual as f64);

    // Slight preference for keeping the number of open bins bounded.
    score += 2.0 * open_bins_count as f64;

    // Modulo harmonic bonus: residuals that are multiples of 5 or 25 pair
    // well with typical item sizes.
    if pr % 25 == 0 && pr > 0 { score -= 25.0; }
    else if pr % 5 == 0 && pr > 0 { score -= 10.0; }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold
    // even the smallest plausible future item are dead space -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Penalize residuals that cannot fit the lookahead item either.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0 + (next_item_size - post_residual) as f64;
    }

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 20.0 * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Open-bin pressure: discourage spreading into many bins unless fit is tight.
    let pressure = open_bins_count as f64 / (1.0 + step_index as f64 / total_items.max(1) as f64);
    score += 2.0 * pressure * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Mean residual coupling: prefer bins whose residual is below the mean
    // (concentrate filling), penalize filling already-large-residual bins.
    if (bin_residual as f64) > mean_residual {
        score += 5.0;
    } else {
        score -= 5.0;
    }

    // New-bin candidate: only attractive when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        let poor_options = if fitting_bins_count == 0 { 0.0 } else {
            (post_residual as f64).min(0.0)
        };
        score = 60.0 + poor_options
            - if next_item_size > 0 && next_item_size >= item_size { 10.0 } else { 0.0 };
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact chain post_residual -> next_item_size
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        // Perfect chain: huge reward
        if post_residual == next_item_size {
            score -= 50.0;
        } else if post_residual > next_item_size {
            // item fits after, but leaves leftover: mild penalty proportional to gap
            score += 0.3 * gap;
        } else {
            // next item cannot chain into this bin: strong penalty
            score += 0.6 * gap;
        }
        // bonus when chain is near-perfect
        if gap <= 5.0 {
            score -= 10.0 - gap;
        }
    } else {
        // last item: just minimize waste
        score += 0.5 * post_residual as f64;
    }

    // Relative-to-mean coupling: bins with residual above mean are "loose" —
    // prefer packing into them to consolidate space.
    let r = post_residual as f64;
    if r < mean_residual {
        score -= 0.4 * (mean_residual - r);
    } else {
        score += 0.2 * (r - mean_residual);
    }

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        // with alternatives, prefer the tightest fit (post_residual already covers this)
        score += 0.1 * fitting_bins_count as f64;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when
    // existing residuals are large relative to the item (poor fits everywhere).
    if bin_residual == bin_capacity {
        // base cost of opening a bin
        score = 60.0;
        // cheaper to open a bin when open bins are fragmented
        score -= 0.15 * mean_residual;
        // if the next item chains perfectly into a fresh bin (item+next <= capacity)
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            let leftover = bin_capacity - item_size - next_item_size;
            score -= 25.0 - 0.5 * leftover as f64;
        }
        // early in the stream, opening bins is fine; late in stream, avoid sprawl
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
        // if very few bins can fit, new bin is competitive
        score -= 5.0 * (fitting_bins_count as f64);
    }

    // Slight preference to keep residual small in absolute terms (dead space)
    score += 0.05 * r * r / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 100.0;
    } else {
        // Penalize large dead space relative to capacity, nonlinearly
        let waste_frac = post_residual as f64 / bin_capacity as f64;
        score += waste_frac * waste_frac * 40.0;
    }

    // Reward tight fills relative to the bin's current residual
    let fill_frac = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_frac * 25.0;

    // Lookahead: if the next item could fit in the post-residual, reward leaving that space
    if next_item_size > 0 {
        if post_residual as f64 >= next_item_size as f64 {
            score -= 12.0;
        } else if (post_residual as u32) < next_item_size {
            // dead space unusable by next item: penalize proportionally
            score += (next_item_size as f64 - post_residual as f64) * 0.3;
        }
    }

    // Last-chance bonus: only bin that fits the item
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Penalize using a nearly-empty bin when many bins are open (fragmentation control)
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize slightly unless current fit is poor
        score += 15.0;
        if post_residual as f64 > 0.0 && fill_frac < 0.5 {
            score += 10.0;
        }
    } else if bin_residual as f64 > mean_residual * 1.5 && open_bins_count > 2 {
        // Avoid dumping small items into large-residual bins
        score += 8.0;
    }

    // Time horizon: late in the stream, prefer tighter packing (open fewer bins)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (mean_residual - post_residual as f64).abs() * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, with non-linear (quadratic/cubic) shaping
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Smooth interaction with stream progress: tight fits matter more later
    score -= (1.0 - progress) * 4.0 * (1.0 - norm_pr) * (1.0 - norm_pr);

    // Penalize dead space relative to mean residual of open bins (smooth coupling)
    score += 0.15 * (pr - mean_residual).abs() * (0.5 + 0.5 * progress);

    // Last-chance bonus: strongly favor the only fitting bin, scaled by fit quality
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 - norm_pr);
    }

    // Lookahead: reward residual that still fits the next item (smooth decay)
    if next_item_size > 0 {
        let fits_next = if (post_residual as u32) >= next_item_size { 1.0 } else { 0.0 };
        let tight = (next_item_size as f64 / cap).min(1.0);
        score -= 6.0 * fits_next * tight * (1.0 - norm_pr);
    } else {
        // Last item: only the immediate fit matters
        score -= 3.0 * (1.0 - norm_pr);
    }

    // Mild penalty for opening new bins when many already exist (smooth in count)
    if bin_residual == bin_capacity {
        score += 3.0 + 0.05 * open_bins_count as f64;
        // But allow new bin if it would create a very tight fit later via lookahead
        if next_item_size > 0 && (post_residual as u32) >= next_item_size {
            score -= 2.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: dead space in small remainders is costly.
    let pr = post_residual;
    if pr > 0 {
        // Class by integer division on capacity/8 buckets
        let class = pr / (bin_capacity / 8);
        score += match class {
            0 => 0.0,              // pr < 12.5: nearly perfect fit, fine
            1 => 4.0,              // small awkward gap
            2 => 2.0,
            3 => 0.5,
            _ => -2.0,             // large residual: still usable
        };
        // Modulo-4 harmonic penalty: gaps that can't hold common sizes (multiples of 4/5)
        if pr % 4 != 0 && pr < 20 { score += 1.5; }
        if pr % 5 != 0 && pr < 25 { score += 0.8; }
    } else {
        score -= 6.0; // perfect closure reward
    }

    // Lookahead: does post_residual fit next item? Strong reward.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 5.0;
            // Harmonic coupling: next item leaves a tiny remainder again
            let npr = post_residual - next_item_size;
            if npr < 10 { score -= 2.0; }
        } else {
            score += 3.0; // this bin will be dead after placement
        }
    }

    // Last-chance bin: strong preference to use it rather than open a new one
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 8.0;
    }

    // New-bin candidate handling: opening a bin is only attractive if current bin
    // would leave a bad harmonic class or no bin fits well.
    if bin_residual == bin_capacity {
        // Fresh bin: baseline competitive score, penalize when many bins fit item
        score = bin_capacity as f64 * 0.5;
        if fitting_bins_count == 0 { score -= 20.0; }
        if fitting_bins_count == 1 { score += 4.0; }
        if next_item_size > 0 && post_residual >= next_item_size { score -= 4.0; }
        // Late in stream, avoid proliferation of open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 3.0;
    }

    // Prefer fuller bins overall (deviation from mean residual)
    score -= (bin_residual as f64 - mean_residual) * 0.3;

    // Mild reward for tight fit relative to item size
    score -= (item_size as f64 / bin_capacity as f64) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps after placement.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 15.0;
    } else if post_residual <= 5 {
        score -= 5.0;
    }

    // Coupling: dead space is worse when many bins are already open (pressure to close bins out).
    let pressure = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
    score += pressure * (post_residual as f64) * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Lookahead: if next item fits in the post residual, reward keeping this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
    }
    // If next item is close to post residual but slightly larger, mild penalty for wasting.
    if next_item_size > post_residual && post_residual > 0 && next_item_size - post_residual < 10 {
        score += 8.0;
    }

    // New-bin candidate: prefer opening a new bin when open bins are crowded and fit is poor.
    if bin_residual == bin_capacity {
        let avg_fit_quality = mean_residual / bin_capacity as f64;
        if post_residual as f64 > 0.0 && avg_fit_quality < 0.35 {
            score -= 10.0;
        }
        // Mild default penalty so new bins are only chosen when justified.
        score += 12.0;
    }

    // Stream progression: late in the stream, tighten up and avoid fragmentation.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 3.0 * (post_residual as f64 / 10.0).min(4.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), with non-linear dead-space penalty.
    let frag = (post_residual as f64) / (bin_capacity as f64);
    score += 40.0 * frag * frag;

    // Aggressive 2-step lookahead: reward when the next item fits exactly or well into post_residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            // Perfect 2-chain: next item exactly fills the remaining space.
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // Next item fits: reward proportional to how well it matches.
            let slack = (post_residual - next_item_size) as f64;
            score -= 30.0 * (1.0 - slack / (bin_capacity as f64));
            score += 0.15 * slack; // still mildly penalize leftover slack
        } else {
            // Next item cannot use this bin's residual: penalize large residuals.
            score += 0.3 * (post_residual as f64);
        }

        // Two-item chain check: residual minus next item leaves room for a hypothetical
        // item of typical size; reward deep chains.
        if next_item_size < post_residual {
            let r2 = post_residual - next_item_size;
            if r2 >= 10 {
                score -= 5.0 * (r2 as f64 / 100.0);
            }
        }
    } else {
        // Last item: strongly minimize post_residual.
        score += 0.5 * (post_residual as f64);
    }

    // Last-chance bonus: if this is the only bin that fits, prefer using it over a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when current residuals are badly fragmented.
    if bin_residual == bin_capacity {
        let mean_frag = mean_residual / (bin_capacity as f64);
        // If open bins are mostly empty-ish, opening new bins is wasteful.
        score += 35.0 * (1.0 - mean_frag);
        // Late in the stream, avoid opening new bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * progress;
        // Few fitting bins means a new bin is reasonable.
        if fitting_bins_count <= 1 {
            score -= 15.0;
        }
        // Penalize new bins when many bins are already open.
        score += 2.0 * (open_bins_count as f64).sqrt();
    } else {
        // Prefer bins whose residual is below the mean (consolidating fragmented space).
        if (bin_residual as f64) < mean_residual {
            score -= 8.0;
        }
    }

    // Mild global pressure to fill bins tightly as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 10.0 * progress * frag;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual) more aggressively than linear.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 14.0 * tightness * tightness;

    // Penalize dead space: residuals too small for any plausible future item (1..=100).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if the next item fits exactly in post_residual, strongly favor.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 18.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > post_residual && next_item_size > 0 {
        // Next item won't fit here anyway; slight penalty for wasting this bin's future.
        score += 4.0;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Prefer bins with below-average residual (concentrate filling into tighter bins).
    score += 0.35 * ((bin_residual as f64) - mean_residual);

    // Late in the stream, prefer reusing open bins over opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses and many bins open.
        score += 10.0 + 60.0 * progress + 1.5 * open_bins_count as f64;
    } else {
        score -= 6.0 * progress;
    }

    // Mild penalty for opening bins when many are already open (fragmentation guard).
    if bin_residual == bin_capacity && open_bins_count > 3 {
        score += 2.0 * (open_bins_count as f64).ln();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: strongly prefer small post_residual (non-linear polynomial coupling)
    let mut score = 40.0 * norm_post * norm_post + 20.0 * norm_post;

    // Perfect/near-perfect fits get a big reward (subtracted)
    if post == 0 {
        score -= 50.0;
    } else if post < 10.0 {
        score -= 25.0 * (1.0 - norm_post / 0.1);
    }

    // Smooth interaction: residual waste matters more as the stream progresses
    score += 30.0 * norm_post * progress;

    // Dead-space penalty: residual too small for the smallest plausible item (smooth ramp)
    let dead = ((20.0 - norm_post * cap).max(0.0)) / 20.0;
    score += 15.0 * dead * dead;

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: penalize mildly, but more when many bins are open or mean residual is large
    if bin_residual == bin_capacity {
        score += 10.0 + 0.5 * open_bins_count as f64 + (mean_residual / cap).max(0.0) * 15.0;
        // Late in the stream, opening a fresh bin is less attractive
        score += 10.0 * progress;
    }

    // Lookahead: reward leaving room for the next item (smooth coupling)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            let slack = (post - nxt) / cap;
            score -= 8.0 * (1.0 - slack * slack);
        } else {
            score += 6.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo classes over capacity fractions.
    // Residuals in "dead zones" (very small leftovers) are penalized.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Class boundaries at capacity fractions 1/8, 1/4, 1/2
    if post_residual == 0 {
        score -= 25.0; // perfect fit: strongly reward
    } else if post_residual <= bin_capacity / 8 {
        score += 15.0; // dead space: hard to reuse
    } else if post_residual <= bin_capacity / 4 {
        score += 4.0; // only fits tiny items
    } else if post_residual <= bin_capacity / 2 {
        score -= 3.0; // good reusable window
    } else {
        score -= 6.0; // very roomy leftover
    }

    // Integer-division threshold coupling: does next_item_size fit the post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 8.0; // chains nicely with lookahead
            // harmonic bonus: next item leaves further divisible residual
            let nr = post_residual - next_item_size;
            if nr % 10 == 0 {
                score -= 2.0;
            }
            if nr <= bin_capacity / 8 && nr > 0 {
                score += 6.0; // chain creates dead space
            }
        } else {
            score += 5.0; // next item won't fit here
        }
    } else {
        // last item: prefer filling anything
        score -= pr * 0.3;
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // New-bin candidate handling: neutral-ish but penalize when many bins
    // could still fit and residuals are healthy; reward when residuals are tight.
    if bin_residual == bin_capacity {
        let avg_fit = mean_residual.max(0.0);
        let pressure = (open_bins_count as f64).ln().max(0.5);
        // open a new bin when mean residual is small (bins nearly full)
        score = 40.0 - avg_fit * 0.5 + pressure * 2.0;
        if fitting_bins_count == 0 {
            score -= 30.0; // no alternative
        }
        if next_item_size > 0 && next_item_size > (bin_capacity as u32) - (bin_capacity as u32) / 4 {
            score -= 5.0; // big next item: fresh bin useful
        }
    }

    // Mild progression coupling: late in stream, tighten packing (favor fuller bins)
    let progress = step_index as f64 / (total_items.max(1) as f64).max(1.0);
    score *= 1.0 + 0.15 * progress;

    // Small tie-breaker on tightness relative to mean residual
    score += (pr - mean_residual) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any item (1..100 => any gap < 1
    // impossible, but treat small gaps below the minimum plausible item size as dead space).
    // Gaps in [1, 12) are nearly unusable; penalize them quadratically.
    if post_residual < 12 {
