    } else if post_residual == 0 {
        // Perfect fit: strongly reward.
        score -= 150.0;
    } else {
        // Reward larger usable leftovers mildly.
        score -= post_residual as f64 * 0.15;
    }

    // Reward tight fits: fraction of bin used by this placement.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= fill * 30.0;

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones over new bins.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * 3.0;

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items as f64).max(1.0);
        score += 25.0 + progress * 20.0;
        // If many bins can fit the item, discourage opening a new bin.
        if fitting_bins_count > 1 {
            score += fitting_bins_count as f64 * 10.0;
        }
    }

    // Lookahead: if the next item fits into the post-residual, reward leaving that room.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.4;
        }
    }

    // Prefer bins whose residual is close to the mean (keeps bin states homogeneous).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual equals next item size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 45.0;
    }
    // Near match: next item fits with small leftover
    else if next_item_size > 0 && post_residual >= next_item_size {
        let leftover = (post_residual - next_item_size) as f64;
        score -= 12.0 - leftover * 0.25;
    }
    // Dead space: next item cannot use the leftover
    else if next_item_size > 0 {
        score += (next_item_size - post_residual) as f64 * 0.35;
    }

    // Reward tight fits relative to capacity
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 8.0;

    // Penalize leaving residuals below the minimum item size (unusable)
    if post_residual < 1 {
        score -= 20.0;
    } else if post_residual < 10 {
        score += 6.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when open bins are fragmented
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - post_residual as f64).abs();
        score += 25.0 - fragmentation * 0.5;
        if open_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Late-stream consolidation: prefer reusing existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual < bin_capacity {
        score -= progress * 5.0;
    }

    // Prefer bins whose residual deviates favorably from the mean
    score += (mean_residual - bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize large dead space nonlinearly (small post-residual is best).
    if post_residual > 0 {
        score += (post_residual as f64).powf(1.35) * 0.05;
    } else {
        score -= 25.0; // perfect fit bonus
    }

    // Tight-fill reward: fraction of bin used by this placement.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= fill * 20.0;

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    } else if fitting_bins_count > 2 {
        score += 3.0; // plenty of alternatives, less urgency
    }

    // Lookahead: reward leaving room for the next item.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            score -= 12.0 - (slack as f64).min(40.0) * 0.15;
        } else {
            // Next item won't fit here; penalize wasting residual it can't use.
            score += (next_item_size - post_residual) as f64 * 0.08;
        }
    } else {
        // Last item: maximize packing density aggressively.
        score -= 15.0;
    }

    // Global residual pressure: if mean residual is high, prefer filling existing bins.
    let mean_gap = mean_residual - post_residual as f64;
    score += mean_gap.max(0.0) * 0.25;

    // Time horizon: early in stream, be pickier (favor new bins for large items);
    // late in stream, consolidate into open bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let new_bin_bonus = 18.0 * (1.0 - progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus discount early / penalty late.
        score += 22.0 - new_bin_bonus;
        if item_size > bin_capacity / 2 {
            score -= 8.0; // big items justify fresh bins
        }
    } else {
        // Existing bin: small residual bonus late in stream.
        score -= 6.0 * progress;
    }

    // Crowding: many open bins -> discourage opening more, encourage filling.
    score += (open_bins_count as f64).ln().max(0.0) * if bin_residual == bin_capacity { 4.0 } else { -2.0 };

    // Item-to-residual ratio coupling: near-exact fits get extra reward.
    let ratio = item_size as f64 / bin_residual.max(1) as f64;
    if ratio > 0.85 && bin_residual != bin_capacity {
        score -= 10.0 * ratio;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = x * x * (1.0 + 0.8 * progress) + 0.6 * x * (1.0 - progress);

    // Penalize dead space that is too small to be useful later (smooth via polynomial)
    let useless = (1.0 - x) * x * x;
    score += 12.0 * useless;

    // Reward tight fits (small post residual) more strongly as stream progresses
    score -= 3.0 * progress * (1.0 - x) * (1.0 - x);

    // Last-chance bin bonus: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Lookahead: if next item fits in post residual, reward this placement
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if ni <= pr {
            score -= 2.5 * (ni / cap);
        } else {
            score += 1.5 * (1.0 - (cap - ni) / cap) * x;
        }
    }

    // Slight preference for consolidating into fewer bins
    score += 0.15 * open_bins_count as f64 * x;

    // New-bin candidate: keep it neutral-to-slightly-high so it wins only on poor fits
    if bin_residual == bin_capacity {
        score += 8.0 + 6.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: dead space that is "reusable"
    // for small items is less costly than awkward mid-range gaps.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Fraction of capacity wasted after placement
    let waste_frac = pr / cap;
    score += 40.0 * waste_frac * waste_frac;

    // Harmonic classes via integer division on post_residual:
    // classes [0..10), [10..25), [25..50), [50..100)
    let class = post_residual / 25;
    let class_bonus = match class {
        0 => -30.0,                       // near-perfect fit, heavily reward
        1 => -12.0,                       // small gap, still good
        2 => 5.0,                         // medium gap, mildly penalize
        _ => 15.0,                        // large gap, penalize
    };
    score += class_bonus;

    // Modulo-10 residue of post_residual: gaps that are multiples of 10
    // align with common item sizes, making them more reusable.
    let m10 = post_residual % 10;
    score -= 4.0 * (10 - m10 as f64).abs().min(5.0) as f64;

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // strongly reward this bin (perfect chaining).
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if (ni - pr).abs() < 0.5 {
            score -= 45.0;
        } else if ni <= pr {
            // next item fits: reward proportional to how well it fills
            let fill_after = (pr - ni) / cap;
            score -= 20.0 * (1.0 - fill_after);
        } else {
            // next item won't fit here: penalize leaving large gaps
            score += 8.0 * (ni / cap);
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is large
    // and current bins are fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = (mean_residual - pr).abs() / cap;
        let item_big = item_size as f64 > 0.6 * cap;
        let penalty = if item_big { -35.0 } else { 20.0 + 30.0 * (1.0 - progress) };
        score += penalty - 10.0 * fragmentation;
    }

    // Slight preference for tighter bins overall (best-fit bias)
    score -= 10.0 * (1.0 - bin_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps (< 10) are nearly unusable
    // given item sizes >= 10, so punish them heavily (non-linearly).
    if post_residual > 0 && post_residual < 10 {
        score += (11 - post_residual as f64) * 25.0;
    }
    if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 60.0;
    }

    // Reward tight fits relative to residual (high fill ratio of the bin).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 15.0;

    // Dead-zone coupling: mid-size leftovers (10..20) are only usable by small
    // items; mildly penalize to prefer spreading load.
    if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones and
    // encourage consolidating into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.4 + 0.6 * progress);

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (avoids bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Mean-residual coupling: if this bin's residual is far below the mean
    // (already tight), it is a good consolidation target.
    let dev = mean_residual - bin_residual as f64;
    score += dev * 0.3;

    // Lookahead: if the next item fits into the post-residual, reward keeping
    // this bin open with exactly that slack; otherwise penalize hoarding space.
    if next_item_size > 0 {
        if post_residual >= next_item_size && post_residual < next_item_size + 10 {
            score -= 20.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 5.0;
        }
    }

    // New-bin candidate: an empty bin should only win when existing bins would
    // leave bad dead space. Make the empty-bin baseline relatively unattractive.
    if bin_residual == bin_capacity {
        score += 45.0 + open_bins_count as f64 * 2.0;
        // Exception: very large items that would leave tiny gaps anywhere else.
        if item_size > bin_capacity * 9 / 10 {
            score -= 70.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: post_residual is the base cost; tighten it.
    score = post_residual as f64 * 1.0;

    // Perfect fit reward: waste-free placement is always best.
    if post_residual == 0 {
        score -= 200.0;
    }

    // 2-step lookahead: if next item exactly matches post_residual, strongly favor.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 150.0;
        } else if next_item_size < post_residual {
            // Next item can also fit here: penalize lightly to keep chain viable,
            // but leave residual slack for the chain.
            score -= 20.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Next item cannot use the leftover: penalize dead space.
            let dead = post_residual as f64;
            score += dead * dead / (bin_capacity as f64 * 2.0);
        }
    }

    // Compare residual against mean residual: prefer bins tighter than average.
    score -= (mean_residual - post_residual as f64) * 0.5;

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && post_residual <= bin_capacity / 2 {
        score -= 60.0;
    }

    // Prefer filling bins that are already relatively full (low residual).
    score += (bin_residual as f64 / bin_capacity as f64) * 10.0;

    // Early in the stream, allow more bin spreading; later, consolidate.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * 15.0;

    // Slight penalty for many open bins to encourage consolidation.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item nearly fills the residual.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 60.0 * tightness * tightness;

    // Penalize dead space that becomes unusable for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if the next item fits the post residual, reward this placement.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 20.0;
        } else if next_item_size == post_residual {
            score -= 45.0;
        } else {
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // Global pressure: many open bins with high mean residual -> consolidate.
    let pressure = mean_residual / bin_capacity as f64;
    score += pressure * 12.0;
    score += open_bins_count as f64 * 0.5;

    // Time horizon: early stream, be picky; late stream, accept looser fits.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.8 * (1.0 - t);

    // New-bin candidate: penalize opening a new bin unless current bin is a poor fit,
    // but allow it when tightness is low and there is lookahead room.
    if bin_residual == bin_capacity {
        score += 30.0 - 40.0 * tightness;
        if next_item_size > 0 && next_item_size >= bin_capacity - item_size {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let t = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Smooth non-linear coupling: post_residual shaped by stream progress
    let poly = norm_pr * norm_pr * (1.0 - t) + norm_pr * t * (1.0 - norm_pr);
    score += 6.0 * poly * cap * 0.1;

    // Penalize dead space more strongly as stream progresses
    score += (norm_pr * norm_pr) * 12.0 * t;

    // Reward tight fits (small post_residual) with a smooth saturating bonus
    let tight = 1.0 - (pr / (cap * 0.5)).tanh();
    score -= 8.0 * tight;

    // Last-chance bin: reward using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead coupling: penalize if next item cannot use the post residual
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if ns > pr {
            score += 5.0 * ((ns - pr) / cap).tanh();
        } else {
            score -= 4.0 * (1.0 - (ns / pr.max(1.0))).tanh();
        }
    }

    // Mild preference for fuller bins relative to mean residual
    score -= 2.0 * ((mean_residual - pr) / cap).tanh();

    // New-bin candidate: penalize opening a bin unless current residual is very small
    if bin_residual == bin_capacity {
        score += 10.0 * (1.0 - (norm_pr * 0.0 + (bin_residual as f64 - item_size as f64) / cap).tanh());
        score += 3.0 * t;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space into
    // capacity-fraction buckets (0, (0,25], (25,50], (50,75], (75,100]).
    let cap = bin_capacity as f64;
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    let three_quarter = 3 * bin_capacity / 4;

    // Perfect fit is divine: heavily reward it.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize residuals that fall into "dead zone" classes — too small
        // to be useful for typical items (min item size 1, but realistically
        // small leftovers accumulate). Class = post_residual / quarter.
        let class = post_residual / quarter.max(1);
        score += class as f64 * 12.0;

        // Integer-division thresholds: residual that cannot hold any plausible
        // next item (next_item_size known) is dead space.
        if next_item_size > 0 {
            if post_residual >= next_item_size {
                // Reward leaving room for the lookahead item, scaled by how
                // snugly it fits (harmonic coupling of residual & next size).
                let slack = post_residual - next_item_size;
                score -= 40.0 - (slack.min(50) as f64) * 0.5;
            } else {
                // Dead space relative to the lookahead: penalize proportionally.
                score += (next_item_size - post_residual) as f64 * 0.8;
            }
        }

        // Modulo arithmetic: residuals that are divisors-friendly (multiples
        // of 10 or 25) pair well with common item sizes — slight reward.
        if post_residual % 10 == 0 {
            score -= 6.0;
        }
        if post_residual % 25 == 0 {
            score -= 4.0;
        }
        // Odd, awkward residuals get a small nudge penalty.
        if post_residual % 2 == 1 {
            score += 2.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: empty bin starts with full residual; encourage it
    // only when the current item is large relative to capacity (poor fit
    // anywhere else) or when mean residual across open bins is very low
    // (all open bins are nearly full).
    if bin_residual == bin_capacity {
        let frac = item_size as f64 / cap;
        score -= 10.0 + 40.0 * frac; // baseline attractiveness of fresh bin
        if mean_residual < 15.0 {
            score -= 25.0; // open bins are nearly full -> new bin is good
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 15.0; // fresh bin also accommodates the lookahead
        }
    } else {
        // Reward filling bins that are already relatively full (tight packing).
        let fill = (bin_capacity - bin_residual) as f64 / cap;
        score -= 20.0 * fill;
    }

    // Stream progression: late in the stream, prefer closing out bins
    // (minimize spread of residual across many open bins).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (1.0 - progress) * 0.5;
    score -= progress * 8.0;

    // Coupling with mean residual: bins far below mean residual are
    // under-filled; prefer them slightly to balance the pool.
    let dev = mean_residual - post_residual as f64;
    score += dev * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small to be usable are heavily penalized.
    // A residual gap is "dead" if no plausible future item (1..=100) can ever combine usefully.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // tiny sliver, unusable
    } else if post_residual >= 10 && post_residual < 20 {
        score += 25.0; // barely usable, still wasteful
    } else if post_residual == 0 {
        score -= 40.0; // perfect fit, strongly reward
    }

    // Reward bins whose post_residual can still host the lookahead item (k=2 lookahead).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // The gap blocks the next item: dead space for the immediate future.
        score += 18.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is truly terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing bins
    // (penalize the new-bin candidate more as open_bins_count grows).
    if bin_residual == bin_capacity {
        score += 15.0 + 2.0 * open_bins_count as f64;
    } else {
        score -= 1.5 * open_bins_count.min(20) as f64;
    }

    // Prefer bins tighter than the mean residual (best-fit flavor).
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Early in the stream, be more willing to open fresh bins; late, consolidate.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score -= 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Perfect fit bonus: leaving zero residual is ideal.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Two-step lookahead: reward residuals that exactly fit the next item
    // (this bin stays perfectly usable), penalize otherwise.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual >= next_item_size {
            let gap = post - nxt;
            if gap == 0.0 {
                score -= 30.0; // residual exactly matches next item
            } else {
                // small positive gap is okay, large gap wastes space
                score += (gap / cap) * 15.0;
            }
        } else {
            // residual too small for next item: dead-space penalty,
            // worse when the leftover is tiny (unusable sliver).
            let sliver = post / cap;
            score += 12.0 + sliver * 20.0;
        }
    }

    // Compare post_residual against mean residual: leaving more space than
    // average suggests this bin is relatively "roomy" — mildly deprioritize
    // using roomy bins when other tighter bins could also fit.
    score += (post - mean_residual) * 0.05;

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly prefer it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when the item is large relative to
    // capacity or current open bins fit poorly. Base cost of opening a bin.
    if bin_residual == bin_capacity {
        score = cap * 0.75;
        if item_size as f64 / cap > 0.7 {
            score -= 20.0; // big items: fresh bin is reasonable
        }
        if fitting_bins_count == 0 {
            score -= 30.0; // no open bin fits: must open
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let capacity = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: scale score by fill fraction of this placement.
    let fill = item_size as f64 / bin_residual as f64;
    score -= 40.0 * fill * fill;

    // Penalize dead space: residuals too small for the minimum item size.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual > 0 && post_residual < 20 {
        score += 25.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 18.0 * (next_item_size as f64 / 100.0);
        } else {
            // Leaving a residual that even the next item cannot use is wasteful.
            score += 12.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 50.0;
    }

    // Mild preference for fuller bins among many open bins (reduce fragmentation).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (open_bins_count as f64).ln() * 3.0 * (1.0 - progress);

    // Prefer bins whose residual deviates from the mean in a compacting direction
    // (below-average residual = already compacted, keep using it).
    score += (post_residual as f64 - mean_residual) * 0.15;

    // New-bin candidate logic: opening a new bin should only win when the item
    // is large relative to every residual (poor fits elsewhere). Compare against
    // the effective cost of wasting space in an existing bin.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin: it is attractive when the item is big and
        // would leave a fragmented residual in existing bins.
        let big_item_bonus = 70.0 * (item_size as f64 / capacity);
        // Late in the stream, consolidation matters more; early on, spreading is fine.
        let time_penalty = 45.0 * progress;
        // If many bins already fit the item, a new bin is rarely needed.
        let crowd_penalty = 8.0 * (fitting_bins_count as f64).min(6.0);
        score = score - big_item_bonus + time_penalty + crowd_penalty;
        // A new bin's post_residual is large; discourage unless item is huge.
        if item_size < 50 {
            score += 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    // Base: waste after placement
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early on, prefer tight fills (small post_residual); later, tolerate residual less
    let phase = progress * std::f64::consts::PI;
    let tightness = 1.0 + 0.5 * (1.0 - (phase).cos()); // smooth ramp 1.0 -> 2.0
    score *= tightness;

    // Cubic penalty on normalized residual, modulated by progress
    let cube = norm_pr * norm_pr * norm_pr;
    score += 20.0 * cube * (0.5 + progress);

    // Interaction: item size vs post residual — reward large items filling bins well
    score -= 15.0 * norm_item * (1.0 - norm_pr) * (1.0 - norm_pr);

    // Dead-space avoidance: residual just below smallest plausible item is bad
    let small = 10.0f64.min(cap * 0.1);
    if norm_pr > 0.0 && pr < small {
        score += 12.0 * (1.0 - pr / small);
    }

    // Lookahead coupling: if next item fits the post residual, reward strongly
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let fit_quality = (next_item_size as f64 / pr.max(1.0)).min(1.0);
        score -= 18.0 * fit_quality * (1.0 - progress * 0.5);
    } else if next_item_size > 0 {
        // next item cannot use this residual: penalize proportionally to its size
        score += 4.0 * (next_item_size as f64 / cap) * norm_pr;
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: penalize mildly early, more when many bins open
    if bin_residual == bin_capacity {
        score += 8.0 + 2.0 * open_bins_count as f64 * (1.0 - progress);
        // but if current bins would leave big waste, opening is fine
        if mean_residual < norm_item * cap * 0.5 {
            score -= 12.0;
        }
    }

    // Mean residual coupling: prefer bins near the mean (balanced packing)
    score += 0.5 * (pr - mean_residual).abs() * (0.3 + progress);

    // Smooth sigmoid saturation of item fill ratio
    let fill = 1.0 - norm_pr;
    let sig = 1.0 / (1.0 + (-8.0 * (fill - 0.85)).exp());
    score -= 10.0 * sig;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover: bins whose residual falls into small
    // "dead zone" classes are penalized (wasted capacity), while residuals
    // that match plausible future item sizes are rewarded.
    let cap = bin_capacity as f64;
    let frac = post_residual as f64 / cap; // capacity fraction left over

    // Integer-division threshold classes on post_residual (capacity=100).
    // Class boundaries at multiples of 10: residual < 10 is nearly dead space.
    let dead_class = post_residual / 10; // 0..10
    if dead_class == 0 {
        score += 40.0; // tiny leftover: almost unusable
    } else if dead_class <= 2 {
        score += 12.0; // small leftover
    } else if dead_class >= 7 {
        score -= 6.0; // large leftover: flexible
    }

    // Modulo arithmetic: leftovers that are multiples of 10 align with the
    // coarse item grid (items in 10..80), making them re-usable.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    }

    // Lookahead coupling: does post_residual exactly fit the next item?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0; // perfect two-item fill
        } else if next_item_size <= post_residual {
            score -= 10.0; // next item still fits here
            // harmonic bonus when next item leaves another multiple-of-10
            if (post_residual - next_item_size) % 10 == 0 {
                score -= 5.0;
            }
        } else {
            // next item cannot use this bin's leftover: mild penalty scaled
            // by how far off it is (mod-10 distance)
            let gap = next_item_size - post_residual;
            score += (gap % 10) as f64 * 0.5;
        }
    } else {
        // last item: prefer tightest fill overall
        score -= 5.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate (pristine empty bin): only attractive when the item
    // is huge relative to capacity or the stream is early and mean residual
    // across open bins is already low (fragmented state).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = mean_residual / cap;
        // reward opening fresh bin when existing bins are fragmented and
        // item is large; otherwise penalize so we reuse open bins.
        let fresh_bonus = 35.0 * (1.0 - fragmentation) * (0.5 + 0.5 * (item_size as f64 / cap)) - 20.0 * progress;
        score += 20.0 - fresh_bonus;
        // a fresh bin gives perfect mod-10 headroom
        if item_size % 10 == 0 {
            score -= 4.0;
        }
    }

    // Mild pressure against hoarding many open bins with big mean residual.
    if open_bins_count > 4 && mean_residual > 0.5 * cap {
        score += 3.0;
    }

    // Small tie-breaker favoring tighter fits within the same class.
    score += frac * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Reward tight fits strongly.
    score -= (item_size as f64 / bin_capacity as f64) * 40.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Dead space relative to bin capacity.
    score += (post_residual as f64 / bin_capacity as f64) * 25.0;

    // Open bins pressure: fewer open bins is better when residuals are useful.
    score += open_bins_count as f64 * 0.5;

    // Last chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    }
    // If next item cannot fit anywhere else, keep space for it.
    if next_item_size > 0 && post_residual < next_item_size && next_item_size <= bin_residual {
        score += 10.0;
    }

    // New-bin candidate: prefer it only when open bins are crowded.
    if bin_residual == bin_capacity {
        score += 15.0 + open_bins_count as f64 * 1.5;
        if mean_residual < item_size as f64 * 0.5 {
            score -= 25.0;
        }
    }

    // Stream progression: as stream advances, be less tolerant of new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 8.0;

    // Mean residual coupling: prefer bins whose residual is near the mean (avoid outliers).
    score += (bin_residual as f64 - mean_residual).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect two-step packing: post_residual exactly fits next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 100.0;
    } else if next_item_size > 0 {
        // Proximity of post_residual to next_item_size: tighter match is better.
        let gap = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        score -= 30.0 / (1.0 + gap * 0.1);
        // Penalize leaving dead space that neither next item nor typical items can use.
        if post_residual < next_item_size && post_residual < 10 {
            score += 20.0;
        }
    }

    // Penalize large post_residual relative to mean residual (wasting big space on small item).
    if post_residual as f64 > mean_residual {
        score += 0.5 * (post_residual as f64 - mean_residual);
    } else {
        score -= 0.3 * (mean_residual - post_residual as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New empty bin candidate: penalize unless nothing decent is open.
    if bin_residual == bin_capacity {
        score += 40.0;
        // But if next item is huge and current item is small, fresh bin may be good.
        if next_item_size >= 50 && item_size <= 30 {
            score -= 25.0;
        }
    }

    // Late in stream, prefer compacting into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post_residual) more aggressively.
    score *= 1.0 + 0.01 * (post_residual as f64 / bin_capacity as f64);

    // Last chance: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Lookahead: penalize if placing here leaves no room for the next item
    // while another placement could accommodate it.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 8.0;
        } else if post_residual == next_item_size {
            score -= 10.0; // perfect two-item chain
        }
        // Favor bins whose leftover pairs well with the next item size.
        score -= 5.0 * (1.0 - ((post_residual as i64 - next_item_size as i64).abs() as f64) / bin_capacity as f64);
    }

    // Penalize bins far below mean residual (fragmented outliers) mildly.
    score += 0.15 * (mean_residual - bin_residual as f64).abs();

    // Early in stream: prefer keeping bins open flexible; late: prefer filling.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * (bin_capacity - post_residual) as f64 / bin_capacity as f64;

    // Many open bins: discourage opening new bins implicitly by favoring reuse.
    score -= 0.5 * open_bins_count as f64 * (1.0 - progress);

    // Discourage using a nearly full bin for a small item (waste of tight space).
    if item_size < 20 && bin_residual <= 30 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, with non-linear polynomial coupling to stream progress
    let mut score = pr * (1.0 + 0.8 * progress * norm_pr * norm_pr);

    // Penalize small dead space quadratically (wasted capacity)
    let dead = norm_pr;
    score += 40.0 * (1.0 - dead) * (1.0 - dead) * dead * (1.0 + 0.5 * progress);

    // Reward tight fits: post residual near zero
    score -= 25.0 * (-pr / (0.15 * cap)).exp();

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 30.0 + 20.0 * progress;
    }

    // Lookahead coupling: if next item fits in post residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 12.0 * (1.0 - (next_item_size as f64 / cap)) * (1.0 + progress);
    } else if next_item_size > 0 {
        score += 6.0 * (next_item_size as f64 / cap);
    }

    // Mild penalty for proliferating open bins early in the stream
    score += (open_bins_count as f64).ln() * (1.0 - progress) * 4.0;

    // Deviation from mean residual: prefer bins whose residual is below mean (more filled)
    score += 0.3 * (pr - mean_residual) * (1.0 + 0.5 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that fall into
    // "highly reusable" classes (small, or exact multiples of common item sizes).
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Class A: perfect fit — zero residual is ideal.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Class B: tiny dead space (1..=5) — nearly perfect, strong reward.
    if post_residual >= 1 && post_residual <= 5 {
        score -= 25.0;
    }

    // Class C: residual divisible by common small item sizes (10, 20, 25, 50)
    // is more likely to be filled by future items.
    if post_residual > 0 && (post_residual % 10 == 0 || post_residual % 25 == 0) {
        score -= 8.0;
    }

    // Class D: integer-division thresholds on post_residual.
    let pr_class = post_residual / 10; // harmonic decade class
    score += (pr_class as f64) * 1.5; // larger decade => mild penalty

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly reward this placement (chained perfect fit).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size < post_residual {
            let nxt_res = post_residual - next_item_size;
            if nxt_res <= 5 {
                score -= 18.0;
            } else if nxt_res % 10 == 0 {
                score -= 6.0;
            }
        } else {
            // next item cannot use this bin's leftover: penalize large leftovers
            score += pr * 0.05;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless residual is huge/wasteful).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: a fresh bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Prefer opening a new bin only when no open bin fits well:
        // penalize new bins mildly so tight fits in open bins win,
        // but if all open bins would leave big waste, new bin looks better
        // because their scores carry the waste penalty.
        score += 12.0;
        // Early in the stream, opening bins is cheaper.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
        // If many bins are open with high mean residual, discourage new bins.
        score += (open_bins_count as f64).sqrt() * 0.8;
        score += (mean_residual / cap) * 5.0;
    } else {
        // Waste-aware penalty: leftover relative to capacity, superlinear for
        // mid-range dead zones (11..49) which are hardest to fill.
        if post_residual >= 11 && post_residual <= 49 {
            score += 6.0;
        }
        // Slight preference for fuller bins (best-fit-like sharpening).
        score -= (1.0 - pr / cap) * 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals below the minimum item size are pure waste.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item.max(1) {
        score += 1000.0;
    }
    // Small unusable gaps (below typical smallest item) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Reward tight fits: bonus proportional to fill ratio of the bin.
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 30.0 * fill * fill;

    // Perfect fit is extremely desirable.
    if post_residual == 0 {
        score -= 200.0;
    }

    // Lookahead: if next item fits exactly in post_residual, reward this placement.
    if next_item_size > 0 && post_residual > 0 && next_item_size == post_residual {
        score -= 80.0;
    }
    // Penalize leaving a gap that the next item cannot use.
    if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual {
        score += 25.0;
    }

    // Open-bin pressure: encourage filling existing bins rather than opening new ones.
    score += open_bins_count as f64 * 2.0;

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 120.0;
    }

    // New-bin candidate: make empty bins less attractive unless open bins are very full.
    if bin_residual == bin_capacity {
        score += 40.0 + mean_residual * 0.5;
    }

    // Stream progression: early on, be more conservative (favor new bins less).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-exact fit (minimize wasted space non-linearly).
    let fit_ratio = item_size as f64 / bin_residual as f64;
    if fit_ratio > 0.9 {
        score -= 25.0 * (fit_ratio - 0.9);
    }

    // 2-step lookahead: if next item exactly fills post_residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 40.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // next item fits here later: mild reward proportional to tightness
        let t = next_item_size as f64 / post_residual as f64;
        score -= 10.0 * t;
    } else if next_item_size > post_residual {
        // next item cannot use leftover: penalize large dead space
        score += 0.15 * (post_residual as f64 - mean_residual).max(0.0);
    }

    // Penalize bins far below mean residual (hoarding large residuals is bad),
    // reward bins near mean residual for balanced packing.
    score += 0.05 * (post_residual as f64 - mean_residual).abs();

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate: penalize unless current item is huge and no open bin fits well.
    if bin_residual == bin_capacity {
        let tight_exists = fitting_bins_count > 0 && (bin_capacity - item_size) as f64 <= mean_residual;
        if tight_exists && item_size < 70 {
            score += 60.0; // prefer existing bins
        } else {
            score += 5.0; // slight preference to reuse open bins generally
        }
    }

    // Late in stream: be more conservative, favor closing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fit_ratio = item_size as f64 / bin_residual as f64;

    // Reward tight fits: subtract more as fit_ratio approaches 1.
    score -= 20.0 * fit_ratio * fit_ratio;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 15.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Post-residual too small for next item: penalize creating dead space,
            // scaled by how dead it is relative to capacity.
            let deadness = post_residual as f64 / bin_capacity as f64;
            if deadness < (next_item_size as f64 / bin_capacity as f64) {
                score += 12.0 * deadness;
            }
        }
    } else {
        // Last item: just minimize waste.
        score -= 30.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Penalize spreading across many open bins slightly; encourage consolidation
    // early, allow more bins later in the stream.
    if bin_residual != bin_capacity {
        score += 2.0 * open_bins_count as f64 * (1.0 - progress);
    }

    // Coupling with global mean residual: prefer bins whose residual is below
    // mean (they are the "fuller" bins) to keep a pool of large residuals open.
    let diff = mean_residual - bin_residual as f64;
    score += 0.15 * diff;

    // New-bin candidate handling: opening a new bin is attractive when existing
    // fits are loose or the item is large relative to typical residuals.
    if bin_residual == bin_capacity {
        let mean_waste = mean_residual.max(0.0);
        // Prefer new bin if item would leave a big awkward gap elsewhere.
        let poor_fit_pressure = (1.0 - fit_ratio) * 30.0;
        let consolidation_penalty = open_bins_count as f64 * 1.5 * (1.0 - progress);
        score += poor_fit_pressure + consolidation_penalty - 0.1 * mean_waste;
        // Slight bias against opening new bins for small items.
        score += 0.3 * (bin_capacity - item_size) as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let fit_norm = pr / cap;
    let base = pr as f64;
    let poly = fit_norm * (1.0 - fit_norm) * 4.0;
    let mut score = base * (1.0 + 0.5 * (progress - 0.5) * (progress - 0.5));
    score -= 30.0 * poly * (item_size as f64 / cap);
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - progress);
    }
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64) as f64;
        if gap >= 0.0 {
            score -= 10.0 * (gap / cap);
        } else {
            score += 5.0 * (-gap / cap);
        }
    }
    score += 0.1 * (mean_residual - pr).abs();
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how "usable" the leftover space is.
    // Class 0: post_residual divisible by 10 -> clean slot, likely reusable.
    // Class 1: odd residuals -> awkward.
    // Class 2: divisible by 5 only -> medium.
    let pr = post_residual;
    let harmonic_class = if pr == 0 { 3 } else if pr % 10 == 0 { 2 } else if pr % 5 == 0 { 1 } else { 0 };
    score -= harmonic_class as f64 * 4.0;

    // Integer-division threshold: chunk the residual into "slots" of size 10.
    // Reward residuals that can still hold a mid-size item (>=10..=80 range).
    let slots = pr / 10;
    score -= slots as f64 * 1.5;

    // Penalize dead space: residual too small for the minimum item (1) is fine,
    // but residual in the "dead zone" (1..10) wastes capacity.
    if pr > 0 && pr < 10 {
        score += 12.0;
    }

    // Coupling with lookahead item: if the next item fits the post residual,
    // strongly reward (chaining placement).
    if next_item_size > 0 && next_item_size <= pr {
        score -= 15.0;
        // Extra reward if next item exactly fills the bin (perfect packing).
        if next_item_size == pr {
            score -= 20.0;
        }
        // Harmonic coupling: next item size modulo classes vs residual modulo.
        if next_item_size % 10 == pr % 10 && pr >= next_item_size {
            score -= 3.0;
        }
    } else if next_item_size > pr && next_item_size > 0 {
        // Next item won't fit here anyway; mildly penalize leaving large gaps
        // that fragment future capacity relative to the mean residual.
        let gap = (pr as f64 - mean_residual).abs();
        score += gap * 0.3;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless the item is
    // large relative to capacity (big items deserve fresh bins) or all open bins
    // are nearly full.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let fill_frac = item_size as f64 / cap;
        // Fresh bin: score = wasted capacity if item placed alone, minus bonuses.
        score = (cap - item_size as f64) * 0.9;
        // Prefer new bin for very large items (harmonic top class: > 3/4 capacity).
        if item_size * 4 > bin_capacity * 3 {
            score -= 18.0;
        }
        // If mean residual across open bins can't comfortably fit the item's
        // harmonic partner (item/2), opening fresh is attractive.
        if mean_residual < item_size as f64 / 2.0 {
            score -= 10.0;
        }
        // Late in the stream, avoid proliferating bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 8.0;
        // If few fitting bins exist and open bins exist, discourage new bin mildly.
        if open_bins_count > 0 && fitting_bins_count > 0 {
            score += 6.0;
        }
        let _ = fill_frac;
    }

    // Perfect fit: absolute reward.
    if pr == 0 {
        score -= 40.0;
    }

    // Small tie-breaker favoring tighter bins (smaller residual before placement)
    // via modulo threshold on bin_residual: bins whose residual is in the top
    // harmonic quartile are less precious.
    if bin_residual * 4 > bin_capacity * 3 {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold anything useful
    // (below the minimum plausible item size) are pure waste.
    if post_residual > 0 {
        if post_residual <= 10 {
            score += 40.0; // tiny unusable gap
        } else if post_residual < item_size {
            score += 12.0; // awkward gap smaller than current item class
        } else {
            score -= 8.0; // gap remains reusable
        }
    } else {
        score -= 25.0; // perfect fill
    }

    // Reward tight fits (low waste fraction).
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fill;

    // Pressure from number of open bins: discourage proliferation,
    // but only mildly so tight fits still win.
    score += (open_bins_count as f64).sqrt() * 2.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Lookahead: bonus if the next item fits the resulting residual exactly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 22.0;
        } else if post_residual >= next_item_size {
            score -= 5.0;
        } else {
            score += 6.0; // next item won't fit here
        }
    }

    // Mean residual coupling: prefer bins whose residual deviates from the mean
    // toward a better fit (keep extreme residuals for future large items).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // New-bin candidate handling: an empty bin should only win when no open bin
    // offers a decent fit (tightness bonus makes good fits beat the empty bin).
    if bin_residual == bin_capacity {
        score += 18.0 + 3.0 * (open_bins_count as f64);
        // Late in the stream, opening fresh bins is less attractive.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }

    // Near-match bonus: post_residual within a small window of next_item_size.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if gap <= 10.0 {
            score -= (10.0 - gap) * 2.0;
        }
    }

    // Penalize dead space that cannot fit the next item (wasted residual).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 1.5;
    }

    // Penalize residuals far above the mean residual (fragmenting the stream).
    score += (post_residual as f64 - mean_residual).abs() * 0.3;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Prefer filling bins tightly as the stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (bin_capacity - post_residual) as f64 * 0.1 * (0.5 + progress);

    // Mildly discourage opening new bins when many bins are already open.
    if bin_residual == bin_capacity {
        score += open_bins_count as f64 * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post-residual is good, amplify non-linearly.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tight * tight;

    // Lookahead: if the next item fits exactly into the post-residual, big bonus.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 8.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > post_residual && next_item_size > 0 {
        // Next item won't fit here after placement; mild penalty if it leaves dead space.
        if post_residual < 10 {
            score -= 3.0; // tiny dead space is fine, even good
        } else {
            score += 0.02 * post_residual as f64;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // Many open bins: prefer filling existing bins, penalize spreading.
    score += 0.15 * open_bins_count as f64 * (1.0 - tight);

    // Mean residual coupling: if open bins are already slack-heavy, avoid adding more slack.
    if mean_residual > 30.0 && post_residual as f64 > mean_residual {
        score += 0.05 * (post_residual as f64 - mean_residual);
    }

    // New-bin candidate handling: penalize opening a new bin, but less when
    // the item is large (poor fits elsewhere) or few bins fit the item.
    if bin_residual == bin_capacity {
        let mut new_bin_penalty = 15.0;
        if item_size > 60 {
            new_bin_penalty -= 6.0;
        }
        if fitting_bins_count <= 2 {
            new_bin_penalty -= 5.0;
        }
        // Early in stream, opening bins is cheaper; late, consolidate.
        let progress = step_index as f64 / total_items.max(1) as f64;
        new_bin_penalty += 10.0 * progress;
        score += new_bin_penalty;
    }

    // Small residual fragmentation penalty: residuals of 1..9 are near-dead space.
    if post_residual >= 1 && post_residual <= 9 {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let fit = item_size as f64 / cap;

    // Base: prefer tight fits (small post_residual), with non-linear emphasis.
    let mut score = pr + (pr / cap).powi(3) * 40.0;

    // Smooth progress coupling: later in stream, tighten more aggressively.
    score += (pr / cap).powi(2) * (20.0 + 60.0 * progress);

    // Penalize leaving dead space that no realistic item can use.
    if pr > 0.0 && pr < 10.0 {
        score += (10.0 - pr) * 3.0;
    }

    // Lookahead: reward residual that can host the next item, penalize near-misses.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            score -= 8.0 * (1.0 - ((pr - nx) / cap)).min(1.0);
        } else {
            score += (nx - pr) * 0.5;
        }
    }

    // Last-chance bin: strong reward to use it instead of opening a new bin.
    if fitting_bins_count <= 1 && bin_residual >= item_size {
        score -= 25.0 * (1.0 + fit);
    }

    // New-bin candidate: make it attractive only when existing bins fit poorly.
    if bin_residual == bin_capacity {
        let scarcity = 1.0 / (fitting_bins_count as f64 + 1.0);
        score += 10.0 + 30.0 * (1.0 - scarcity) - 15.0 * progress * scarcity;
        if next_item_size > 0 && (next_item_size as f64) <= cap * 0.5 {
            score -= 5.0; // fresh bin is useful for upcoming items
        }
    }

    // Mild preference for consolidating among many open bins.
    score -= (open_bins_count as f64).ln() * (pr / cap) * 5.0;

    // Deviation from mean residual: prefer bins near mean to balance load.
    score += ((pr - mean_residual) / cap).abs() * 6.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the residual after placement (dead-space classes).
    let class = match post_residual {
        0 => 0.0,          // perfect fit
        1..=9 => 1.0,      // near-dead space (typical min item is small)
        10..=19 => 2.0,    // awkward mid gap
        20..=39 => 3.0,
        40..=69 => 4.0,
        _ => 5.0,          // large leftover, still reusable
    };

    // Reward exact and near-exact fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 9 {
        score -= 25.0;
    } else if post_residual <= 19 {
        score -= 10.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size < post_residual {
            let slack = post_residual - next_item_size;
            if slack <= 9 {
                score -= 20.0;
            } else {
                score -= (slack as f64).sqrt() * 2.0;
            }
        } else {
            // Next item won't fit here: penalize small unusable leftovers more.
            if post_residual < 10 {
                score += 8.0;
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: strongly discourage unless current fits are all poor
    // (large post_residual) or stream is early with few bins open.
    if bin_residual == bin_capacity {
        score += 40.0;
        if post_residual as f64 - item_size as f64 >= 0.0 { /* no-op, keep base */ }
        // Allow opening a fresh bin when the best existing fit would waste a lot.
        let waste_elsewhere = mean_residual;
        if waste_elsewhere > 60.0 && open_bins_count > 0 {
            score -= 30.0;
        }
        if step_index == 0 {
            score -= 100.0; // first item must open a bin
        }
    }

    // Mild pressure to consolidate into fewer bins when many are open.
    score += (open_bins_count as f64).ln().max(0.0) * (post_residual as f64 / bin_capacity as f64) * 5.0;

    // Coupling with mean residual: prefer bins tighter than average.
    score += (mean_residual - post_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps hard.
    // Gap is "dead" if smaller than the minimum plausible item (assume ~10% of capacity)
    // and not exactly zero (perfect fit).
    let min_item = (bin_capacity as f64 * 0.1).max(1.0);
    if post_residual > 0 && (post_residual as f64) < min_item {
        score += 40.0 + 0.5 * (min_item - post_residual as f64);
    }
    // Reward perfect fits strongly.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Tight fits (small post_residual relative to item) are favored.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * tightness;

    // Penalty if this bin cannot also host the next item (lookahead waste).
    if next_item_size > 0 {
        if post_residual < next_item_size && post_residual > 0 {
            score += 8.0;
        } else if post_residual >= next_item_size {
            score -= 4.0;
        }
    }

    // Open bins pressure: with many open bins, discourage opening new ones
    // (new bin candidate has bin_residual == bin_capacity).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 30.0 + 20.0 * progress + 3.0 * open_bins_count as f64;
        // But if this is the only fitting option situation, new bin is fine.
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    }

    // Last-chance bonus: if this is the only open bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Mild preference for bins below mean residual (consolidate emptier bins).
    if (bin_residual as f64) > mean_residual {
        score += 3.0;
    } else {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: strongly favor bins whose residual becomes tiny.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 300.0;
    } else if post_residual <= 10 {
        score -= 120.0;
    }

    // 2-step lookahead: reward if next item exactly/very tightly fits post_residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0; // chain perfect fit
        } else if post_residual >= next_item_size {
            let slack_after_next = post_residual - next_item_size;
            if slack_after_next <= 10 {
                score -= 150.0 - slack_after_next as f64 * 10.0;
            } else {
                // penalize leaving a mid-sized gap that no item likely fills
                score += slack_after_next as f64 * 0.3;
            }
        } else {
            // next item cannot fit: post_residual is dead space unless small
            if post_residual >= 10 {
                score += 60.0;
            }
        }
    } else {
        // last item: pure fit tightness
        score += post_residual as f64 * 2.0;
    }

    // Relative to mean residual: placing in a fuller-than-average bin is good
    // (keeps many open bins compact, frees emptier ones).
    score += (mean_residual - post_residual as f64) * 0.5;

    // Last-chance bonus: if this is the only bin that fits, use it.
    if fitting_bins_count == 1 {
        score -= 200.0;
    }

    // New-bin candidate handling: penalize opening a fresh bin unless no
    // open bin offers a decent fit.
    if bin_residual == bin_capacity {
        let decent_fit_exists = mean_residual >= item_size as f64
            || (next_item_size > 0 && post_residual >= next_item_size);
        if decent_fit_exists {
            score += 250.0; // prefer an existing bin
        } else {
            score += 20.0; // opening new bin is acceptable
        }
    }

    // Early stream: be slightly conservative about wasting space.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.15 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect or near-perfect fills strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 50.0;
    }

    // Lookahead: reward bins whose leftover can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0 + (post_residual - next_item_size) as f64 * 0.1;
    } else if next_item_size > 0 {
        // Penalize creating dead space the next item cannot use.
        score += post_residual as f64 * 0.05;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize unless the item is large relative to capacity
    // (large items pack better into fresh bins) or few bins fit the item.
    if bin_residual == bin_capacity {
        let mut new_bin_score = (bin_capacity - item_size) as f64 + 40.0;
        if item_size >= 60 {
            new_bin_score -= 30.0;
        }
        if fitting_bins_count <= 1 {
            new_bin_score += 100.0; // never open when an existing bin is last chance
        }
        // Early in the stream, opening bins is cheaper (more future items to fill them).
        let progress = step_index as f64 / total_items.max(1) as f64;
        new_bin_score += progress * 20.0;
        score = score.max(new_bin_score);
    }

    // Slight preference for bins tighter than average (best-fit flavor).
    score += (bin_residual as f64 - mean_residual) * 0.05;

    // Mild penalty for wasting space in bins that are nearly full anyway.
    if bin_residual < 20 && post_residual > 0 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let base = pr;

    // Polynomial coupling of post_residual with stream progress:
    // early on, tolerate loose fits; later, punish wasted residual strongly.
    let progress_weight = 0.4 + 1.6 * progress * progress;
    let mut score = base * (1.0 + progress_weight * (pr / cap));

    // Non-linear penalty on small-but-nonzero residual (dead space), smoothed.
    let dead = (pr / cap - 0.15).max(0.0);
    score += 30.0 * dead * dead * (1.0 + progress);

    // Perfect-fit reward: strongly subtract when post_residual is tiny.
    let tightness = 1.0 - (pr / cap).min(1.0);
    score -= 25.0 * tightness * tightness * tightness;

    // Last-chance bin: reward heavily to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0 + 15.0 * progress;
    }

    // Lookahead: if next item exactly fills this bin's post-residual, big reward.
    if next_item_size > 0 && (post_residual as u32) == next_item_size {
        score -= 35.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // partial lookahead reward, scaled by how well next item would fit
        let fit_frac = next_item_size as f64 / post_residual as f64;
        score -= 10.0 * fit_frac * fit_frac;
    }

    // Prefer bins below mean residual (more packed bins get priority).
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Mild penalty for opening new bins when many are open.
    if bin_residual == bin_capacity {
        score += 5.0 + 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover lies in "usable"
    // classes (multiples of 10, or >= 20) are more valuable to preserve.
    let pr = post_residual;
    let class_bonus = if pr == 0 {
        -60.0 // perfect fit: strongly reward
    } else if pr % 10 == 0 {
        -25.0 // residual on the canonical grid, likely reusable
    } else if pr >= 20 {
        -8.0 // still moderately usable
    } else {
        15.0 // dead space class (1..=9)
    };
    score += class_bonus;

    // Integer-division threshold: residual chunk size relative to capacity.
    let quarter = bin_capacity / 4;
    if pr >= 3 * quarter {
        score -= 12.0;
    } else if pr < quarter && pr > 0 {
        score += 10.0;
    }

    // Lookahead coupling: does next item fit in the post-residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 20.0; // chain two items: excellent
            // harmonic match: next item and post_residual share a class
            if pr % next_item_size == 0 || next_item_size % 10 == 0 && pr % 10 == 0 {
                score -= 10.0;
            }
        } else if next_item_size <= bin_residual {
            score += 5.0; // next item would have fit before this placement
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new one
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless current bins are crowded.
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64) * (mean_residual / bin_capacity as f64);
        score += 45.0 - 10.0 * pressure;
        // If next item is large, a fresh bin is more attractive
        if next_item_size > bin_capacity / 2 {
            score -= 15.0;
        }
    }

    // Stream progression: late in the stream, prefer tightening fills.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (bin_residual - post_residual) as f64 / item_size.max(1) as f64;

    // Deviation from mean residual: prefer bins tighter than average.
    score += 0.05 * ((post_residual as f64) - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harder.
    let dead_threshold = 10.0;
    if post_residual > 0 && post_residual < 10 {
        score += (dead_threshold - post_residual as f64) * 6.0;
    }
    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Tight fit reward: item consumes most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 10.0 * fill_ratio;

    // Open bins pressure: discourage scattering across many bins.
    score += open_bins_count as f64 * 1.5;

    // Last chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits the post residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0;
    } else if next_item_size > 0 && next_item_size > post_residual && post_residual < next_item_size {
        score += 4.0 * (next_item_size - post_residual) as f64;
    }

    // Mild progression term: early in stream, slightly prefer consolidating.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 3.0;

    // Deviation from mean residual: prefer bins whose residual is near mean.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // New-bin candidate: keep it neutral-to-slightly-costly so it only wins
    // when no open bin offers a good fit.
    if bin_residual == bin_capacity {
        score += 8.0 + open_bins_count as f64 * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match between post_residual and next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        if post == nxt {
            score -= 60.0; // perfect two-item chain fill
        } else if post > nxt {
            let gap = post - nxt;
            // penalize leftover after imagined next placement
            score += gap * 0.8;
            // bonus if the gap is small (near-perfect chain)
            if gap <= 10.0 {
                score -= 25.0;
            }
        } else {
            // next item cannot follow into this bin's remainder
            score += (nxt - post) * 0.35;
        }
    }

    // Penalize unusable dead space relative to smallest possible item (1..100 unknown, use 10 floor)
    let dead = post_residual as f64;
    if dead > 0.0 && dead < 10.0 {
        score += 40.0; // tiny unusable sliver
    }

    // Compare residual against mean residual of open bins
    if post_residual as f64 > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.25;
    } else {
        score -= (mean_residual - post_residual as f64) * 0.15;
    }

    // Last-chance bin: strongly prefer filling the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless nothing else fits well
    if bin_residual == bin_capacity {
        let mut penalty = 55.0;
        if next_item_size > 0 && (bin_capacity as u32 - next_item_size) < item_size {
            // current item would leave room exactly hostile for next item anyway
            penalty -= 10.0;
        }
        if fitting_bins_count == 0 {
            penalty = 0.0; // forced open
        }
        score += penalty;
    }

    // Stream progression: early on, be slightly conservative (keep bins flexible)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * post_residual as f64 * 0.1;

    // Prefer denser packing when many bins open
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual) nonlinearly.
    let cap = bin_capacity as f64;
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 8.0 * tightness * tightness;

    // Penalize dead space that can never host small items (residual < 10).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Lookahead: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else {
            score += 2.0;
        }
        // Perfect chain: next item exactly fills the bin.
        if post_residual == next_item_size {
            score -= 10.0;
        }
    }

    // Penalize spreading across too many open bins when residuals are large.
    let waste = mean_residual - (post_residual as f64);
    if waste > 0.0 {
        score += 0.15 * waste;
    }

    // New-bin candidate handling: empty bin should only win when fits are poor
    // or many bins are open with fragmented space.
    if bin_residual == bin_capacity {
        score += 12.0;
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
        if open_bins_count > 2 && mean_residual > 0.6 * cap {
            score -= 5.0;
        }
    }

    // Time horizon: early in the stream, be more selective (avoid premature opens);
    // later, consolidate.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 4.0 * progress * tightness;
    score += 2.0 * (1.0 - progress) * (post_residual as f64 / cap);

    // Mild preference to fill bins with larger residuals less when item is large.
    if item_size as f64 > 0.7 * cap {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let r = bin_residual as f64;
    let it = item_size as f64;
    let prog = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Quadratic penalty on post_residual: small residuals are fine, large waste is bad
    let prn = pr / cap;
    score += 40.0 * prn * prn;

    // Smooth coupling: reward tight fits more as stream progresses
    let tightness = it / r.max(1.0);
    score -= 25.0 * tightness * (0.3 + 0.7 * prog) * (1.0 - prn);

    // Cubic dead-space term: penalize residuals that are hard to fill later
    let dead = prn * prn * prn;
    score += 60.0 * dead * (0.5 + 0.5 * prog);

    // Exact fit bonus (smooth via product term)
    if post_residual == 0 {
        score -= 30.0 * (1.0 + prog);
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Next-item lookahead: reward leaving a residual that fits the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            let slack = (pr - nx) / cap;
            score -= 15.0 * (1.0 - slack * slack);
        } else {
            let gap = (nx - pr) / cap;
            score += 12.0 * gap * gap;
        }
    }

    // Mean residual context: penalize bins far from the fleet mean (smooth)
    let dev = (pr - mean_residual).abs() / cap;
    score += 8.0 * dev * dev;

    // New-bin candidate: mildly discourage opening bins when good fits exist,
    // more so early in the stream
    if bin_residual == bin_capacity {
        score += 10.0 + 20.0 * (1.0 - prog) + 2.0 * open_bins_count as f64;
        if prn < 0.15 { score -= 5.0; }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how "usable" the leftover space is.
    // Class 0: residual fits next item perfectly or well; class grows as space fragments.
    if next_item_size > 0 {
        let fits_next = (next_item_size <= post_residual) as i32;
        // Exact-fit lookahead reward: next item consumes post_residual completely.
        if fits_next == 1 {
            let gap = (post_residual - next_item_size) as f64;
            score -= 30.0 + (bin_capacity as f64 - gap) * 0.3;
        } else {
            // Next item cannot use this bin: penalize proportionally to wasted potential.
            score += 8.0 + (next_item_size as f64 - post_residual as f64) * 0.15;
        }
    } else {
        // Last item: strongly reward near-exact fill.
        score -= (bin_capacity as f64 - post_residual as f64) * 0.5;
    }

    // Harmonic residue classes on post_residual: small dead zones (1..=9) are useless.
    let dead = post_residual % 10;
    if post_residual > 0 && post_residual < 10 {
        score += 20.0; // tiny unusable sliver
    } else if dead == 0 && post_residual > 0 {
        score -= 6.0; // clean multiple of 10 keeps modular alignment
    }

    // Integer-division threshold: residual in [10, 20) can host only the smallest items.
    if post_residual >= 10 && post_residual < 20 {
        score += 5.0;
    }

    // Prefer tight fits: reward small post_residual relative to item size.
    score -= (item_size as f64 / bin_capacity as f64) * 12.0;

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when open bins are badly fragmented
    // (mean residual large but nothing fits well) or stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = (mean_residual - post_residual as f64).max(0.0);
        score = 60.0 + fragmentation * 0.5 - (1.0 - progress) * 10.0;
        if fitting_bins_count == 0 {
            score -= 40.0; // nothing fits anywhere: new bin is mandatory anyway
        }
    }

    // Mild pressure to consolidate when many bins are open.
    score += open_bins_count as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold any
    // plausible future item (<= 10, or <= next item) are pure waste.
    let min_item = 1u32;
    if post_residual < min_item {
        score -= 1000.0; // perfect fit, no dead space at all
    } else if post_residual <= 10 {
        score += 60.0; // unusable sliver -> strong penalty
    } else if post_residual < item_size.min(next_item_size.max(1)) && post_residual < 20 {
        score += 25.0; // gap too small for likely successors
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * tightness;

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Pressure from number of open bins: consolidate when many bins are open.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (open_bins_count as f64) * (1.5 + 3.0 * progress);

    // Prefer bins with below-average residual (keep large residuals for large items).
    let avg = mean_residual.max(0.0);
    if (bin_residual as f64) > avg + 1.0 {
        score += 2.0 * (bin_residual as f64 - avg);
    } else {
        score -= 1.0 * (avg - bin_residual as f64);
    }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 120.0;
    } else if next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size <= 10 {
        score -= 40.0;
    }

    // New-bin candidate: baseline cost of opening a fresh bin, modulated by
    // how bad the alternatives look (many open bins with large residuals).
    if bin_residual == bin_capacity {
        score = 100.0 + (open_bins_count as f64) * 0.5 - 0.3 * avg;
        if fitting_bins_count == 1 {
            score += 200.0; // never open a new bin when only one bin fits
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    } else if next_item_size > 0 && post_residual > next_item_size {
        // Next item still fits after this placement: mild reward proportional to slack.
        score -= 15.0 * (post_residual as f64 - next_item_size as f64) / bin_capacity as f64;
    } else if next_item_size > 0 {
        // Next item cannot fit: penalize dead space created, stronger when large.
        score += 20.0 * (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
    }

    // Compare post_residual against mean residual across open bins.
    if (post_residual as f64) < mean_residual {
        score -= 8.0;
    } else {
        score += 4.0 * ((post_residual as f64 - mean_residual) / bin_capacity as f64);
    }

    // Last-chance bin: strong bonus to use it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Penalize leaving very small unusable gaps (classic dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Perfect closure reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Early in stream: slightly discourage hoarding too many open bins.
    if step_index < total_items / 10 {
        score += open_bins_count as f64 * 0.5;
    }

    // New-bin candidate: only attractive when existing bins would create bad fits.
    if bin_residual == bin_capacity {
        score += 10.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 12.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual dominates).
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 8.0 * fit_ratio * fit_ratio * (bin_capacity as f64);

    // Penalize leaving dead space that no plausible future item can use.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual > 0 && post_residual < 10 {
        score -= 6.0; // tiny leftover is fine (near-perfect packing)
    } else if post_residual >= 10 && post_residual < 50 {
        // medium leftovers are useful; mild bonus scaled by remaining stream
        score -= 4.0 * (1.0 - progress) * (post_residual as f64 / 50.0);
    } else {
        score += 3.0; // large leftover wastes capacity
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of opening a bin, softened late in the stream.
        score += 20.0 - 8.0 * progress;
        // If many bins already fit the item, discourage opening a new one.
        if fitting_bins_count > 0 {
            score += 12.0 * (fitting_bins_count as f64).min(5.0);
        }
    } else {
        // Reward using existing bins, more so when bins are scarce relative to stream.
        score -= 2.0;
    }

    // Lookahead coupling: if the next item fits into this bin's post-residual,
    // reward the placement (chain packing); otherwise penalize slightly.
    if next_item_size > 0 {
        if (post_residual as i64) >= (next_item_size as i64) {
            score -= 5.0 * (next_item_size as f64 / bin_capacity as f64);
        } else {
            score += 2.0 * (1.0 - progress);
        }
    }

    // Global state: prefer filling bins when mean residual is low (consolidation),
    // prefer spreading when mean residual is high (avoid fragmenting many bins).
    if !is_new_bin {
        score -= (bin_residual as f64 - mean_residual) * 0.05;
        score += open_bins_count as f64 * 0.05;
    }

    // Small tie-breaker: prefer bins with less residual overall.
    score += bin_residual as f64 * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
