    // Lookahead: reward leaving space for next item (smooth interaction)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let match_term = 1.0 - ((pr - nx).abs() / cap);
        score -= match_term * match_term * 15.0;
    }

    // Mean residual coupling: prefer bins deviating smoothly from mean
    let dev = (pr - mean_residual) / cap;
    score += dev * dev * 10.0;

    // Slight preference to fill emptier bins early (balance load)
    score += (open_bins_count as f64).ln().max(0.0) * (1.0 - progress) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: overwhelming reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of the residual: discretize post_residual into capacity
    // fractions (20-wide bands). Larger band index = more wasted space.
    let band = post_residual / 20; // 0..=5
    score += band as f64 * 3.0;

    // Non-linear penalty inside the awkward 1..19 band (hard-to-fill sliver),
    // but only when no lookahead item can use it.
    if post_residual > 0 && post_residual < 20 {
        score += 2.0;
    }

    // Lookahead chaining: if the next item fits into the post_residual,
    // reward this bin proportionally to how well it chains (k=2 lookahead).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // tighter chain (next item nearly fills residual) gets bigger bonus
            let chain_tightness = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 5.0 + 10.0 * chain_tightness;
        } else {
            // next item won't fit here: mild penalty
            score += 2.0;
        }
    }

    // Last-chance bin: if this is the ONLY open bin that fits the item,
    // strongly prefer it over opening a new bin (unless it's the new-bin candidate itself).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate handling: penalize a fresh empty bin unless the item
    // is large (opening a bin for a big item wastes little).
    if bin_residual == bin_capacity {
        score += 10.0 - item_size as f64 * 0.15;
        // early in the stream, new bins are cheaper
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 4.0 * (1.0 - progress);
    }

    // Global context: slightly prefer bins whose residual deviates below the
    // mean (concentrate waste), and mildly discourage bin proliferation.
    if (post_residual as f64) < mean_residual {
        score -= 1.0;
    } else {
        score += 1.0;
    }
    score += open_bins_count as f64 * 0.05;

    // Modulo harmonic nudge: residuals that are multiples of 10 align with
    // typical item granularities; reward them slightly.
    if post_residual % 10 == 0 {
        score -= 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are small but nonzero are
    // nearly unusable (items are >= 1, but tiny gaps waste capacity).
    if post_residual > 0 && post_residual <= 10 {
        score += 40.0 + (10 - post_residual) as f64 * 3.0;
    }

    // Reward tight fits (exact or near-exact fills).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage opening another;
    // make the new-bin candidate less attractive as open_bins_count grows.
    if bin_residual == bin_capacity {
        score += 10.0 + open_bins_count as f64 * 2.0;
        // But if the item fits poorly everywhere, a fresh bin may be better.
        if post_residual == bin_capacity - item_size && item_size >= 50 {
            score -= 20.0;
        }
    }

    // Lookahead: if the next item can exactly fill this bin's post-residual,
    // reward placing the current item here.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 45.0;
    } else if next_item_size > post_residual && next_item_size <= bin_residual {
        score += 8.0;
    }

    // Stream progression: early on, be more conservative with new bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += (1.0 - progress) * 15.0;
    }

    // Prefer bins whose residual is already below the mean (consolidate waste).
    score += ((bin_residual as f64 - mean_residual) * 0.3).max(-10.0).min(10.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: reward exact match between post_residual and next item size
    let post = post_residual as f64;
    let nxt = next_item_size as f64;
    if next_item_size > 0 {
        let match_gap = (post - nxt).abs();
        // perfect lookahead match: strong reward
        if match_gap <= 1.0 {
            score -= 60.0;
        } else {
            // penalize residuals that don't serve the next item
            score += match_gap * 0.6;
            // if next item fits exactly into current residual, big reward
            if next_item_size <= post_residual {
                score -= 25.0 * (1.0 - match_gap / bin_capacity as f64);
            }
        }
        // next item too big for residual: this bin leaves dead space
        if next_item_size > post_residual {
            score += (next_item_size - post_residual) as f64 * 0.8;
        }
    } else {
        // last item: minimize waste directly
        score += post * 0.5;
    }

    // prefer tight fits relative to mean residual
    if post < mean_residual {
        score -= (mean_residual - post) * 0.3;
    } else {
        score += (post - mean_residual) * 0.4;
    }

    // last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // new-bin candidate: penalize opening a bin unless item is large relative to capacity
    if bin_residual == bin_capacity {
        let fill_frac = item_size as f64 / bin_capacity as f64;
        score = 100.0 - 70.0 * fill_frac;
        if fitting_bins_count == 0 {
            score -= 200.0; // must open new bin
        }
        // open new bin if item is big and would leave tiny waste elsewhere
        if fill_frac > 0.7 {
            score -= 30.0;
        }
    }

    // reward filling bins tighter as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (bin_capacity - post_residual) as f64 * 0.2 * (1.0 + progress);

    // slight preference for bins with fewer alternatives when residual is small
    if post_residual <= 10 {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic bonus for small post-residual.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tight * tight;

    // Perfect fit: huge reward.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Penalize dead space that no plausible item can use (min item size 1..10).
    let min_item = 10u32.min(item_size.max(1));
    if post_residual > 0 && post_residual < min_item {
        score += 30.0;
    }

    // Lookahead: reward if next item fits the post-residual exactly or well.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here: mild penalty for wasting residual.
            score += 8.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Many fitting bins: mildly prefer bins with least residual (already covered),
    // but penalize spreading across too many open bins.
    if fitting_bins_count > 3 {
        score += 2.0 * (fitting_bins_count as f64 - 3.0);
    }

    // Time horizon: late in the stream, consolidation matters more.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 12.0 * progress * tight;

    // Global residual state: if mean residual is high, prefer packing into existing bins.
    if bin_residual < bin_capacity {
        score -= 6.0 * (mean_residual / bin_capacity as f64);
    }

    // New-bin candidate handling: penalize opening a new bin unless the item fits
    // poorly everywhere (post_residual on empty bin = capacity - item_size).
    if bin_residual == bin_capacity {
        let waste = post_residual as f64;
        // Base cost of opening a new bin.
        score += 35.0;
        // If this item would leave a large unusable gap in any existing bin,
        // opening fresh is better: discount the penalty.
        if fitting_bins_count == 0 || (post_residual <= 10 && next_item_size > post_residual) {
            score -= 50.0;
        }
        // Very large items near capacity fit best in a fresh bin.
        if item_size >= 80 {
            score -= 20.0;
        }
        // Lookahead synergy: fresh bin can host next item too.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 10.0;
        }
        let _ = waste;
    }

    // Mild penalty per open bin to discourage bin proliferation.
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;
    let fill = 1.0 - pr_norm;

    // Base: penalize leftover space, with a convex (quadratic) blow-up on tiny residuals
    let mut score = pr * (1.0 + 0.9 * pr_norm * pr_norm);

    // Smooth non-linear coupling of post_residual with stream progress:
    // late in the stream, waste matters more (bins are nearly committed)
    let progress_coupling = pr * (progress * progress * (3.0 - 2.0 * progress)); // smoothstep
    score += 1.7 * progress_coupling;

    // Reward tight fits: subtract a smooth function of fill ratio, amplified by progress
    let tightness = fill * fill * fill;
    score -= 12.0 * tightness * (0.5 + progress);

    // Dead-space danger: residual too small for typical future items
    let dead_zone = ((pr - 25.0) / 25.0).powi(2).min(1.0);
    score += 8.0 * dead_zone * pr_norm * (1.0 - progress);

    // Lookahead: reward if next item fits the post-residual exactly-ish
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score -= 10.0 * (-gap / 20.0) * (1.0 - 0.5 * progress);
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 * (1.0 + progress);
    }

    // Mild preference for bins below mean residual (balance spread) — smooth coupling
    let dev = (pr - mean_residual) / cap;
    score += 4.0 * dev * dev * (1.0 - progress);

    // New-bin candidate: penalize mildly so it only wins when fits are truly bad
    if bin_residual == bin_capacity {
        score += 15.0 + 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residuals divisible by common
    // item sizes (10, 20, 25, 50) are more reusable -> reward them.
    let pr = post_residual;
    if pr == 0 {
        score -= 1000.0; // perfect fit
    } else {
        if pr % 10 == 0 { score -= 6.0; }
        if pr % 20 == 0 { score -= 4.0; }
        if pr % 25 == 0 { score -= 4.0; }
        if pr % 50 == 0 { score -= 6.0; }

        // Dead-space penalty: residual too small for the smallest plausible item
        if pr < 10 {
            score += 40.0;
        } else if pr < 20 {
            score += 12.0;
        }

        // Harmonic bucket: how well does pr align with typical item classes?
        let bucket = pr / 10; // 0..10
        match bucket {
            0 => score += 30.0,          // unusable sliver
            1 | 2 => score += 8.0,       // only fits tiny items
            3 | 4 => score += 2.0,
            5 => score -= 3.0,           // half-capacity: very reusable
            6 | 7 => score -= 1.0,
            _ => score -= 2.0,           // large residual stays flexible
        }

        // Lookahead: if next item fits exactly in post_residual, big reward.
        if next_item_size > 0 {
            if next_item_size == pr {
                score -= 60.0;
            } else if next_item_size <= pr {
                score -= (pr - next_item_size) as f64 * 0.5;
                // harmonic match: next item leaves another divisible residual
                if (pr - next_item_size) % 10 == 0 { score -= 5.0; }
            } else {
                // next item cannot use this residual at all -> mild penalty
                score += 3.0;
            }
        }

        // Last chance bin: strongly prefer using it before opening a new bin.
        if fitting_bins_count == 1 && bin_residual < bin_capacity {
            score -= 25.0;
        }

        // New-bin candidate should only win when residuals are fragmented:
        // penalize the fresh bin when open bins are mostly empty.
        if bin_residual == bin_capacity {
            let progress = step_index as f64 / (total_items.max(1) as f64);
            score += 15.0 + mean_residual * 0.3 + open_bins_count as f64 * 2.0 - progress * 10.0;
            if pr == bin_capacity { /* unreachable, keep symmetric */ }
            // make fresh bin attractive only if mean residual is small/dead
            if mean_residual < 15.0 { score -= 30.0; }
        }
    }

    // Slight preference for tighter bins overall.
    score += (bin_residual as f64 - post_residual as f64) * 0.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

