    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Open-bin pressure: many open bins -> prefer filling existing bins,
    // discourage opening new ones.
    let pressure = open_bins_count as f64 * 1.5;
    if bin_residual == bin_capacity {
        // new-bin candidate: penalize more when many bins are already open
        score += pressure;
        // but if mean residual is large and item fits poorly everywhere,
        // a fresh bin may still win; keep base competitive
        score += post_residual as f64 * 0.1;
    } else {
        // existing bin: reward using it under pressure
        score -= pressure * 0.3;
    }

    // Tightness coupling: prefer bins whose residual is close to item size
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += tightness * 0.05;

    // Late in the stream, consolidate harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 4.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
