    }
    // Odd residuals are dead-space prone
    if post_residual % 2 == 1 && post_residual > 15 {
        score += 4.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.5;
        } else {
            // next item won't fit here; penalize leaving medium dead space
            if post_residual >= next_item_size - 10 && post_residual < next_item_size {
                score += 6.0;
            }
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // among many fitting bins, prefer tighter ones (already via post_residual)
        score += (fitting_bins_count as f64).ln() * 2.0;
    }

    // New-bin candidate handling: empty bin has residual == capacity.
    // Only attractive when current item is large or no good fits exist.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Penalize opening new bins early / when open bins are spacious
        score += 20.0 + mean_residual * 0.15;
        // But if item is huge relative to capacity, opening is fine
        score -= (item_size as f64 / bin_capacity as f64) * 15.0;
        // Late in stream, prefer consolidating into open bins
        score += progress * 5.0;
        // If few bins fit the item, opening a new one is reasonable
        if fitting_bins_count <= 1 {
            score -= 18.0;
        }
    }

    // Mean-residual coupling: if this bin is much tighter than average, prefer it
    let dev = mean_residual - bin_residual as f64;
    score += dev * 0.3; // tighter bin (bin_residual < mean) -> dev > 0 -> wait, invert
    // Correct sign: tighter bin (small residual) should be favored -> subtract
    score -= dev * 0.6;

    // Integer division threshold: residuals in (50, 75] can host mid items
    if post_residual / 25 == 2 {
        score += 3.0;
    } else if post_residual / 25 == 1 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A residual is "dead" if it is too small to fit any plausible item (min size ~1,
    // but practically gaps < 20 are rarely reusable). Penalize non-linearly.
    let dead_threshold = 20.0f64;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        let depth = dead_threshold - post_residual as f64;
        score += 3.0 * depth + 15.0 * (depth / dead_threshold).powi(2);
    }
    // Perfect fit reward
    if post_residual == 0 {
        score -= 50.0;
    }

    // Reward leaving a gap that exactly fits the lookahead item (k=2 lookahead synergy)
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }
    // Penalize if post_residual can't fit the next item but bin_residual could
    if next_item_size > 0 && post_residual < next_item_size && bin_residual >= next_item_size {
        score += 5.0;
    }

    // Open bins pressure: with many open bins, prefer filling existing ones over
    // opening new ones; the new-bin candidate (bin_residual == bin_capacity) gets
    // a large penalty scaled by open_bins_count.
    if bin_residual == bin_capacity {
        score += 40.0 + 8.0 * open_bins_count as f64;
    } else {
        score -= 2.0 * open_bins_count as f64;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Mean residual coupling: prefer bins whose residual is below mean (tighter bins)
    score += 0.5 * ((bin_residual as f64) - mean_residual);

    // Early in the stream, be more tolerant of opening bins (exploration);
    // late in the stream, pack tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual to next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post_residual as f64 - nxt).abs();
        // Perfect chain: next item fills this bin exactly afterwards
        if post_residual as u32 == next_item_size {
            score -= 40.0;
        }
        // Penalize mismatch proportional to how badly the chain breaks
        score += 0.35 * diff;
        // Reward when next item fits tightly (post_residual >= next_item_size)
        if post_residual as u32 >= next_item_size {
            score -= 6.0;
        } else if post_residual > 0 {
            // dead space that the next item cannot use
            score += 8.0;
        }
    } else {
        // Last item: strongly prefer minimal final residual
        score += 0.5 * post_residual as f64;
    }

    // Prefer bins tighter than the mean residual (good fills)
    score -= 0.25 * (mean_residual - post_residual as f64);

    // Penalize opening a new bin when existing bins fit, unless residual is very tight
    if bin_residual == bin_capacity && fitting_bins_count > 0 && post_residual > 20 {
        score += 15.0;
    }

    // Last-chance bin bonus: if this is the only fitting bin, avoid wasting it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 5.0;
    }

    // Early in stream: slightly favor consolidation into few bins
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score += 3.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: prefer bins whose residual is barely larger than item.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 18.0 * fit_ratio * fit_ratio;

    // Penalize small dead space that no future item can plausibly use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // If next item would exactly fill the bin, reward strongly.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    }
    // If next item cannot fit but post-residual is large, mild penalty (bin may strand space).
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 4.0;
    }

    // Last-chance bonus: only one fitting bin; strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Many open bins: discourage spreading; prefer filling existing bins.
    let pressure = open_bins_count as f64 / (1.0 + step_index as f64);
    score += 6.0 * pressure;

    // Mean-residual coupling: if this bin is above mean residual, it is a good target.
    if (bin_residual as f64) > mean_residual {
        score -= 3.0;
    } else {
        score += 2.0;
    }

    // Time horizon: late in stream, be conservative and fill existing bins tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * fit_ratio;

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let poor_alternatives = fitting_bins_count == 0
            || (item_size as f64 / bin_capacity as f64) < 0.5 && fitting_bins_count <= 1;
        if poor_alternatives {
            score -= 8.0;
        } else {
            score += 15.0;
        }
    }

    // Slight preference for bins that end exactly empty.
    if post_residual == 0 {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_post = post / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let base = post * (1.0 + 0.8 * progress * norm_post);

    // Smooth interaction: tight fits favored more as stream progresses
    let tightness = 1.0 - norm_post * norm_post;
    let coupling = -40.0 * tightness * (0.5 + progress);

    // Last-chance bonus (smoothly scaled)
    let last_chance = if fitting_bins_count == 1 { -30.0 * (1.0 - progress) } else { 0.0 };

    // Penalize new bins slightly less early, more late
    let new_bin_penalty = if bin_residual == bin_capacity {
        10.0 + 25.0 * progress
    } else {
        0.0
    };

    // Lookahead: reward leaving space for next item
    let look = if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt { -8.0 * (1.0 - (nxt / cap)) } else { 6.0 }
    } else {
        0.0
    };

    base + coupling + last_chance + new_bin_penalty + look
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the item: quarter-capacity buckets (cap 100 -> classes of 25)
    let item_class = item_size / 25;
    let next_class = if next_item_size == 0 { 0 } else { next_item_size / 25 };

    // Post-residual harmonic class: how the leftover space quantizes
    let post_class = post_residual / 10;

    // Reward tight fits: post_residual near 0 or in a "complementary" class
    if post_residual == 0 {
        score -= 40.0; // perfect closure
    } else if post_residual <= 10 {
        score -= 20.0;
    } else {
        // Penalize dead space that no small item (>=1) can pair into usefully:
        // leftover in (10..25) is awkward; leftover >= 50 keeps future options open
        if post_residual < 25 {
            score += 10.0;
        } else if post_residual >= 50 {
            score -= 6.0;
        }
    }

    // Modulo coupling: does post_residual pair with next_item_size's class?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item fits here afterwards -> strong reward, scaled by tightness
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 + (10.0 - slack.min(10.0));
        } else {
            // next item cannot use the leftover: penalize by class mismatch
            let class_gap = if next_class > item_class { next_class - item_class } else { item_class - next_class };
            score += 3.0 * class_gap as f64;
        }
    }

    // Integer-division threshold on residual: bins with residual in harmonic
    // "sweet spots" (multiples of 25) absorb items cleanly
    if bin_residual % 25 == 0 && bin_residual != bin_capacity {
        score -= 4.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (unless fit is terrible)
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate (empty bin): make it unattractive unless everything else is bad.
    // Empty bin has post_residual = capacity - item_size; base score already large,
    // add a bias that decays as stream progresses (early on, more bins is fine).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 18.0 - 10.0 * progress;
        // If mean residual across open bins is tiny, opening fresh is reasonable
        if mean_residual < item_size as f64 {
            score -= 14.0;
        }
    } else {
        // Slight preference for filling bins below mean residual (pack tighter bins first)
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        }
    }

    // Mild pressure to consolidate when many bins are open
    score -= 0.5 * (open_bins_count.min(20) as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum item size (1..=100 range,
    // but small gaps < ~15 are practically unusable) are heavily penalized.
    if post_residual > 0 && post_residual < 15 {
        score += 60.0 * (1.0 - post_residual as f64 / 15.0);
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Reward exact fit of the lookahead item into the resulting gap.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap_util = next_item_size as f64 / post_residual as f64;
        score -= 25.0 * gap_util;
    } else if next_item_size > 0 && post_residual > 0 {
        // Gap too small for the next item: mild penalty proportional to wasted potential.
        score += 10.0 * (1.0 - post_residual as f64 / next_item_size as f64);
    }

    // Last-chance pressure: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading; few bins -> mild reward
    // to keep bins tight.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 2.0 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // New-bin candidate handling: an empty bin has a high base score so it is only
    // chosen when all existing fits would create severe dead space or mean residual
    // across open bins is already fragmented.
    if bin_residual == bin_capacity {
        score = 80.0 + 3.0 * open_bins_count as f64;
        if fitting_bins_count == 0 {
            score = 0.0; // no alternative: new bin is mandatory
        }
        // If every existing fit would leave a tiny dead gap, opening fresh is better.
        if fitting_bins_count == 1 && next_item_size > 0 && bin_residual > 0 {
            score -= 20.0;
        }
        if mean_residual < 10.0 && open_bins_count > 0 {
            score -= 25.0;
        }
    }

    // Mild alignment with mean residual: prefer bins whose residual is near the mean
    // (balanced packing) slightly over outliers.
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual equals next item size -> ideal chain fill
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near match: next item fits with small slack left
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = post_residual - next_item_size;
        score -= 25.0 * (1.0 - slack as f64 / bin_capacity as f64);
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item cannot follow: penalize proportionally to wasted potential
        let wasted = (next_item_size - post_residual) as f64;
        score += 0.35 * wasted;
    }

    // Penalize dead space relative to mean residual of open bins
    if post_residual as f64 > mean_residual {
        score += 0.5 * (post_residual as f64 - mean_residual);
    } else {
        score -= 0.25 * (mean_residual - post_residual as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize unless current bin leaves unusably small residual
    if bin_residual == bin_capacity {
        let unusable = post_residual > 0 && post_residual < 10;
        if unusable {
            score -= 30.0; // current placement would strand tiny residual
        } else {
            score += 15.0; // prefer existing bins generally
        }
    }

    // Tight fits (small post residual) are good
    score -= 0.4 * (bin_capacity as f64 - post_residual as f64).max(0.0) * 0.0;
    score += (post_residual as f64).powi(2) / (bin_capacity as f64);

    // Late in stream, prefer filling existing bins more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong best-fit core: reward tight fits nonlinearly.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Perfect-fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Penalize small unusable residuals (dead space below min item size 1..=5).
    if post_residual > 0 && post_residual < 6 {
        score += 8.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual > next_item_size {
            // next item fits too: mild reward, scaled by leftover quality
            let after_next = post_residual - next_item_size;
            score -= 6.0 * (1.0 - after_next as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here: penalize wasting a large gap
            score += 0.05 * (next_item_size - post_residual) as f64;
        }
    } else {
        // Last item: prefer filling bins completely, avoid opening new bins.
        score += 15.0;
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 10.0;
    } else if fitting_bins_count > 1 {
        // among many candidates, tighten discrimination by fit
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // New-bin candidate handling: make empty bins attractive only when
    // global residuals are low or item is large relative to mean residual.
    if bin_residual == bin_capacity {
        let pressure = item_size as f64 / mean_residual.max(1.0);
        let progress = step_index as f64 / total_items.max(1) as f64;
        // open new bin when item barely fits nowhere well and stream is late
        score = 40.0 + 30.0 * pressure - 20.0 * progress;
        if fitting_bins_count == 0 {
            score -= 50.0; // no alternative: must open
        }
    } else {
        // Existing bin: slight bonus when its residual is below mean (already tight)
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        }
    }

    // Mild open-bin economy: discourage spreading across many bins early.
    score += 0.3 * open_bins_count as f64 * (1.0 - step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post_residual as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let pr = post_residual as f64;
    let pr_norm = pr / bin_capacity as f64;
    let coupling = pr_norm * pr_norm * (1.0 - progress) - pr_norm * progress;
    score += 30.0 * coupling;

    // Penalize large post_residual late in the stream
    score += 12.0 * pr_norm * pr_norm * progress;

    // Reward tight fits (small post_residual) especially early
    score -= 8.0 * (1.0 - pr_norm) * (1.0 - progress);

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Lookahead: reward if next item fits the post residual
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
    } else if next_item_size > 0 {
        score += 4.0 * (next_item_size as f64 - pr) / bin_capacity as f64;
    }

    // Prefer bins below mean residual (keeps fuller bins for large items)
    score += 3.0 * ((pr - mean_residual) / bin_capacity as f64);

    // Mild penalty for many open bins to discourage sprawl
    score += 0.5 * open_bins_count as f64 * pr_norm;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit: perfect packing, strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: residuals that are multiples of common
    // item sizes are more likely to be filled by future items.
    let pr = post_residual;
    if pr > 0 {
        let mut useful = false;
        for &m in &[100u32, 80, 70, 60, 50, 40, 30, 25, 20, 15, 12, 10] {
            if m <= pr && pr % m == 0 {
                useful = true;
                break;
            }
        }
        if useful {
            score -= 8.0; // divisible residual: likely fillable later
        } else {
            score += 10.0; // awkward residual: dead space risk
        }
        // Very small residuals are nearly dead space.
        if pr < 10 {
            score += 25.0 * (10 - pr) as f64;
        }
    }

    // Next-item lookahead: if the next item fits exactly into post_residual,
    // this bin chains perfectly; reward it. If the next item cannot fit but
    // could have fit a larger residual, mild penalty.
    if next_item_size > 0 && pr > 0 {
        if next_item_size == pr {
            score -= 500.0;
        } else if next_item_size <= pr {
            // next item fits: residual class compatibility
            if pr % next_item_size == 0 {
                score -= 30.0;
            } else {
                score -= 5.0;
            }
        } else {
            // next item won't fit here; penalize bins left with big leftovers
            score += 6.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new
    // bin unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate: an empty bin has full residual; prefer it only when
    // no existing bin offers a decent fit. Penalize opening new bins mildly,
    // more so as many bins are already open.
    if bin_residual == bin_capacity {
        score += 40.0 + 2.0 * open_bins_count as f64;
        // but if the item is large, a fresh bin is fine
        if item_size >= bin_capacity / 2 {
            score -= 20.0;
        }
    }

    // Fractional capacity thresholds: item filling >= half the bin is good.
    if item_size * 2 >= bin_capacity {
        score -= 5.0;
    }

    // Progression: late in the stream, consolidate aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 3.0;

    // Prefer bins whose residual deviates favorably from the mean (tighter bins).
    score += (mean_residual - bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small non-zero post_residual is the worst outcome.
    if post_residual > 0 {
        if post_residual < 10 {
            // Unusable gap: severe penalty scaled by how tiny the gap is.
            score += (10 - post_residual) as f64 * 6.0;
        } else if post_residual < 20 {
            score += (20 - post_residual) as f64 * 2.0;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 60.0;
    }

    // Reward filling bins tightly relative to their residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 25.0;

    // Open-bin pressure: discourage spreading across many bins unless fit is great.
    score += (open_bins_count as f64) * 1.5;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive if residual is large and mean residual of
    // open bins is small (open bins are nearly full) or no open bin fits well.
    if bin_residual == bin_capacity {
        let mean_gap = bin_capacity as f64 - mean_residual; // how full open bins are on average
        let pressure = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        // New bin gets bad score when open bins are roomy; good when they're nearly full.
        score += 30.0 + pressure * 90.0;
        // Lookahead: if next item is large, opening a fresh bin early is safer.
        if next_item_size > 0 && (next_item_size as f64) > mean_residual {
            score -= 35.0;
        }
        let _ = mean_gap;
    }

    // Lookahead synergy: if the post_residual can host the next item, reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    }
    // If post_residual is nonzero but cannot host the next item, penalize slightly.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0;
    }

    // Late in stream: prefer closing out bins, avoid creating new dead space.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 5.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual can host next_item_size
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Perfect chain: post residual exactly matches next item -> strong reward
            let exact = if post_residual == next_item_size { 12.0 } else { 0.0 };
            let near = if post_residual - next_item_size <= 10 { 6.0 } else { 0.0 };
            score -= exact + near;
        } else {
            // Post residual cannot host next item: penalize proportionally to wasted lookahead
            let waste = (next_item_size - post_residual) as f64;
            score += waste * 0.15;
        }
    }

    // Penalize dead space relative to mean residual (fragmentation pressure)
    let frag = (post_residual as f64 - mean_residual).abs();
    score += frag * 0.05;

    // Reward tight fits: small post_residual is good, extra bonus if very tight
    if post_residual <= 5 {
        score -= 8.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Early in stream: prefer keeping residuals flexible (larger post residual is fine)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 2.0;

    // Many open bins: discourage spreading items, favor filling existing bins
    if open_bins_count > 4 {
        score -= 2.0;
    }

    // New-bin candidate: only attractive when item is large relative to capacity
    if bin_residual == bin_capacity {
        let big_item = item_size as f64 / bin_capacity as f64;
        score += 25.0 - big_item * 30.0;
        // If no open bin fits comfortably, opening a new bin is acceptable
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: minimize wasted space after placement.
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits (post_residual very small).
    if post_residual <= 2 {
        score -= 40.0;
    } else if post_residual <= 8 {
        score -= 20.0 * (1.0 - post_residual as f64 / 8.0);
    }

    // Lookahead: if the next item fits into the post residual, this placement
    // chains nicely — reward proportionally to the leftover usefulness.
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_fit = (post_residual - next_item_size) as f64;
        score -= 12.0 * (1.0 - chain_fit / bin_capacity as f64);
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Post residual is dead space for the next item; penalize slightly
        // more when the leftover is in the awkward small range.
        if post_residual > 0 && post_residual < 10 {
            score += 6.0;
        }
    }

    // Penalize opening a new bin when existing bins could fit, but less so
    // early in the stream (plenty of future items to fill it) or when the
    // existing fit is very poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let pressure = (fitting_bins_count as f64).max(1.0);
        let fill_factor = (open_bins_count as f64).max(1.0);
        let new_bin_penalty = 18.0
            + 10.0 * progress                       // later: prefer closing out open bins
            + 4.0 * fill_factor / (fill_factor + 4.0); // many open bins: reuse them
        score += new_bin_penalty / pressure.sqrt();
    } else {
        // Reward using the last-chance bin (avoids opening a bin for one item).
        if fitting_bins_count == 1 {
            score -= 15.0;
        } else if fitting_bins_count > 1 {
            // Among multiple candidates, mildly prefer emptier bins to consolidate.
            score += 3.0 * (bin_residual as f64 / bin_capacity as f64);
        }
    }

    // Global state coupling: if mean residual across open bins is large,
    // prefer placements that reduce dispersion (place into large-residual bins).
    let deviation = (bin_residual as f64 - mean_residual).abs();
    score += 2.0 * deviation / bin_capacity as f64;

    // Time horizon: late in the stream, tighten up aggressively — dead space
    // matters more because fewer items remain to fill it.
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_post = pr / cap;

    // Base: prefer filling bins tightly (low post residual)
    let mut score = pr as f64;

    // Non-linear polynomial coupling of post residual with stream progress.
    // Early stream: mild tightening pressure; late stream: strong pressure to
    // squeeze items into existing bins (avoid opening new bins near the end).
    let squeeze = norm_post * norm_post * (0.5 + 2.0 * progress);
    score += 60.0 * squeeze;

    // Cubic term: heavily penalize large dead space as the stream matures.
    score += 40.0 * norm_post.powi(3) * (0.3 + 1.7 * progress);

    // Reward perfect-ish fits (post residual small relative to capacity)
    let fit_bonus = (1.0 - norm_post).powi(2);
    score -= 25.0 * fit_bonus * (0.4 + 0.6 * progress);

    // Last-chance bin: strong incentive to use it rather than open a new bin.
    if fitting_bins_count == 1 {
        score -= 45.0 + 30.0 * progress;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward;
    // if post residual is too small for the next item and nonzero, penalize
    // creating unusable slivers.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr as u32 >= next_item_size {
            let gap = (pr as u32 - next_item_size) as f64 / cap;
            score -= 12.0 * (1.0 - gap) * (1.0 - gap);
        } else if pr > 0 {
            score += 18.0 * (1.0 - norm_post) * (0.5 + progress);
        }
    }

    // New-bin candidate handling: empty bin (residual == capacity).
    if bin_residual == bin_capacity {
        // Opening a new bin is attractive early (many items remain) but
        // increasingly costly as the stream progresses.
        score = cap - 30.0 * (1.0 - progress) + 55.0 * progress;
        // Discourage opening a new bin when several bins already fit the item.
        if fitting_bins_count > 1 {
            score += 25.0;
        }
        // If only one bin fits, opening new is less bad.
        if fitting_bins_count == 1 {
            score -= 20.0;
        }
    }

    // Mild penalty proportional to open bins count to consolidate bins,
    // modulated by progress.
    score += open_bins_count as f64 * (1.5 * progress);

    // Deviation from mean residual: prefer bins whose post residual lands
    // near the mean (keeps future flexibility), smooth quadratic coupling.
    let dev = (pr - mean_residual) / cap;
    score += 8.0 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: modulo-10 classes define
    // "usable" residual bands. Residuals divisible by 10 are prime targets
    // for future items (sizes 1..100 commonly land on decade boundaries).
    let pr = post_residual as i64;
    let cls = pr % 10;

    // Reward residuals that are harmonic multiples of 10 (perfect decade fit).
    if cls == 0 && pr > 0 {
        score -= 12.0;
    } else if cls == 5 {
        score -= 4.0; // half-decade residuals are decent
    } else {
        // Penalize awkward odd residuals proportional to distance from decade.
        score += (5 - cls.abs()) as f64 * 0.6;
    }

    // Tight fits are always excellent: reward small post residual strongly.
    if post_residual <= 2 {
        score -= 20.0;
    } else if post_residual <= 10 {
        score -= 10.0;
    }

    // Integer-division threshold: does the residual still hold a "medium" item (>= 30)?
    let holds_medium = post_residual / 30;
    if holds_medium == 0 && post_residual > 0 {
        // Dead space: residual too small for mid-size items.
        score += 8.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // this is a golden pairing.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size < post_residual {
            let nxt_res = post_residual - next_item_size;
            // Harmonic check on the double-post residual.
            if nxt_res % 10 == 0 {
                score -= 15.0;
            }
            score += nxt_res as f64 * 0.15;
        } else {
            // Next item cannot follow here: slight penalty, worse if this bin
            // was the only fitting one (we would strand it).
            score += 3.0;
            if fitting_bins_count == 1 {
                score += 5.0;
            }
        }
    }

    // Last-chance bin: strongly favor using the only bin that can fit the item
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate logic: opening a fresh bin is attractive when existing
    // residuals are all small (poor fits) or the item is large relative to
    // available fits.
    if bin_residual == bin_capacity {
        // Base hesitation: prefer filling existing bins mildly.
        score += 6.0;
        // But if this item is huge and mean residual is tiny, a new bin is right.
        if (item_size as f64) > mean_residual + 25.0 {
            score -= 14.0;
        }
        // Early in the stream, having few bins favors consolidation instead.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if progress < 0.2 && open_bins_count < 4 {
            score += 10.0;
        }
        // Late stream: many open bins with large mean residual -> consolidate.
        if open_bins_count > 6 && mean_residual > 40.0 {
            score += 12.0;
        }
    }

    // Mild pressure to prefer bins with residual close to the item (best fit).
    score += (bin_residual as f64 - item_size as f64) * 0.05;

    // Mean-residual harmonic coupling: bins far below the mean residual are
    // already "worn"; prefer them slightly to balance load.
    let dev = mean_residual - bin_residual as f64;
    score += dev * 0.08;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small gaps (<10) are unusable waste.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // heavy penalty for creating a dead gap
    }
    if post_residual == 0 {
        score -= 15.0; // perfect fit is highly rewarded
    }

    // Reward tight fits: fraction of bin consumed by this placement.
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 10.0 * tightness * tightness;

    // Pressure from open bin count: discourage spreading across many bins,
    // but allow opening when this is the last fitting bin.
    score += 0.8 * open_bins_count as f64;
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0; // last chance: strongly favor using this bin
    }

    // Lookahead: if next item could use the post residual, reward leaving it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else if post_residual > 0 {
            score += 5.0; // residual too small for next item: dead space risk
        }
    }

    // Mean residual coupling: prefer bins whose residual deviates favorably
    // (place into bins with below-average residual to consolidate space).
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // New-bin candidate handling: only attractive when open bins are crowded.
    if bin_residual == bin_capacity {
        let crowd = open_bins_count as f64 / (1.0 + mean_residual / 20.0);
        score += 12.0 - 3.0 * crowd;
        if fitting_bins_count == 0 {
            score -= 30.0; // no open bin fits: must open new bin
        }
    }

    // Slight stream-progression bias: as stream ends, prefer consolidating.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 2.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: strongly favor bins where the item fills them exactly.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: if the next item fits exactly into the
    // post-residual, this placement sets up a perfect follow-up.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 600.0;
    }
    // If the next item can still fit after this placement, mild reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 50.0;
    }
    // If this placement leaves a residual too small for the next item
    // (dead space for the lookahead), penalize proportionally.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 0.5 * (next_item_size - post_residual) as f64;
    }

    // Relative-to-mean coupling: prefer bins tighter than the average residual
    // (best-fit style), penalize bins that would become outliers of waste.
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: if this is the only bin that fits the item, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 300.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless the item
    // is large and no good fit exists. Empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / bin_capacity as f64;
        // Big items are fine in a fresh bin; small items should reuse open bins.
        score += 400.0 * (1.0 - tightness);
        // As the stream fills up, be more willing to open new bins.
        score -= 100.0 * (step_index as f64 / total_items.max(1) as f64);
    }

    // Slight preference to keep few bins open (consolidation pressure).
    score += 0.1 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: quadratic penalty on wasted space.
    score += 0.35 * (post_residual as f64).powi(2) / bin_capacity as f64;

    // Reward near-perfect fills.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0 + 0.25 * item_size as f64;
    }

    // Lookahead: bonus if the next item fits in the post residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 18.0;
        } else {
            // Penalize leaving residuals just below next item size (dead space).
            let gap = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
            if post_residual < next_item_size {
                score += 0.15 * gap;
            }
        }
    }

    // Global state coupling: when bins are sparse on average, conserve residual space.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.2 * mean_residual * (1.0 - progress);

    // Many open bins: mild penalty to avoid spreading items too thin.
    score += 0.6 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: open a fresh bin only when current fits are poor
    // and mean residual across open bins is low.
    if bin_residual == bin_capacity {
        let poor_fits = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let waste = (post_residual as f64 / bin_capacity as f64);
        let threshold = 0.35 + 0.4 * progress;
        if mean_residual < 30.0 || poor_fits > 0.0 {
            score -= 30.0 + 20.0 * (1.0 - waste);
        } else {
            score += 25.0 * threshold;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress in (0,1]
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Smooth non-linear coupling: tight fits are rewarded more strongly as the stream progresses.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 8.0 * tightness * tightness * (0.5 + progress);

    // Penalize residuals that are too small to be useful later (dead space), smoothly.
    let dead = (10.0 - post_residual as f64).max(0.0);
    score += 0.6 * dead * dead / 100.0;

    // Lookahead coupling: if the next item fits exactly in the post residual, reward heavily.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 4.0 * (-gap / 12.0).exp() * (1.0 + progress);
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 6.0;
    }

    // New-bin candidate: penalize opening a bin unless few bins fit or the fit elsewhere is bad.
    if bin_residual == bin_capacity {
        let scarcity = 1.0 / fitting_bins_count.max(1) as f64;
        let crowding = (open_bins_count as f64 / 8.0).tanh();
        score += 14.0 - 10.0 * scarcity - 4.0 * crowding * progress;
        // If next item could pair with a fresh full bin, soften the penalty.
        if next_item_size > 0 && next_item_size <= 20 {
            score -= 5.0;
        }
    }

    // Mild preference for bins whose residual is close to the mean (balanced packing), smoothly.
    score += 0.05 * ((bin_residual as f64 - mean_residual) / bin_capacity as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: exact-fit classes are golden.
    let cap = bin_capacity as f64;
    let pr = post_residual;
    let prf = pr as f64;

    // Exact fit => huge reward.
    if pr == 0 {
        score -= 1000.0;
    }

    // Harmonic class buckets on post_residual (mod arithmetic on capacity fractions).
    // Classes: 0, (0,10], (10,25], (25,50], (50, cap/2..cap)
    if pr > 0 && pr <= 10 {
        score -= 60.0; // near-perfect: dead space is minimal
    } else if pr > 10 && pr <= 25 {
        score -= 20.0;
    } else if pr > 25 && pr <= 50 {
        score -= 5.0;
    } else {
        score += 5.0; // large residual: bin still very "open", less urgent to fill
    }

    // Integer-division threshold: post_residual divisible by common item sizes
    // (10..80 harmonic divisors) means a future item can exactly fill it.
    for d in [10u32, 20, 25, 40, 50] {
        if pr > 0 && pr % d == 0 {
            score -= 15.0;
            break;
        }
    }

    // Lookahead coupling: if next item exactly fits post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 300.0;
        } else if next_item_size < pr {
            let slack = (pr - next_item_size) as f64;
            // reward if next item leaves a good harmonic class again
            if slack <= 10.0 {
                score -= 80.0;
            } else {
                score -= (50.0 / (1.0 + slack / 20.0)) - 20.0;
            }
        } else {
            // next item does NOT fit here: penalize mildly if this bin was the
            // only option, else it's fine.
            score += 10.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate handling: neutral-ish baseline so it only wins when
    // all open bins are bad fits; penalize opening bins early in the stream.
    if bin_residual == bin_capacity {
        score += 40.0;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 30.0 * (1.0 - progress);
        // If mean residual across open bins is large, discourage new bin.
        score += (mean_residual / cap) * 50.0;
    }

    // Prefer filling bins with small residuals relative to fleet mean.
    score -= (mean_residual - prf) * 0.3;

    // Mild congestion control: many open bins => consolidate.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead space avoidance: residuals too small to hold the smallest
    // plausible item are pure waste; penalize them heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 12.0;
    }

    // Reward near-perfect fills.
    if post_residual == 0 {
        score -= 100.0;
    }

    // If the leftover can still host the lookahead item, reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && next_item_size <= bin_residual && post_residual < next_item_size {
        // We destroy the bin's ability to host the next item.
        score += 10.0;
    }

    // Open-bin pressure: many open bins -> prefer filling existing ones
    // (avoid fragmentation); few open bins -> opening is cheaper.
    let pressure = (open_bins_count as f64).ln().max(0.0) * 6.0;
    score -= pressure;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when it enables a good long-term fit
    // (large item) or when open bins are very fragmented.
    if bin_residual == bin_capacity {
        score += 20.0 + pressure;
        if item_size > 70 {
            score -= 30.0;
        }
        if mean_residual > 30.0 {
            score += 10.0;
        }
    }

    // Slight preference for tight fits relative to bin residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 10.0;

    // Late in the stream, waste matters more (no future to amortize it).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: next item exactly fills the post-residual -> strong reward
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 40.0;
    }

    // Next item fits into post-residual -> moderate reward scaled by tightness
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 15.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item won't fit here: penalize leaving a residual smaller than next item (dead space)
        if post_residual < next_item_size {
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    }

    // Compare post-residual against mean residual across open bins
    let mean_res = if mean_residual.is_finite() { mean_residual } else { bin_capacity as f64 };
    let dev = post_residual as f64 - mean_res;
    score += 0.3 * dev;

    // Reward tight fits (small post-residual) non-linearly
    let tightness = 1.0 - post_residual as f64 / bin_capacity as f64;
    score -= 10.0 * tightness * tightness;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Prefer keeping many small open bins consolidated early in the stream
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if open_bins_count > 1 {
        score -= 2.0 * (1.0 - progress);
    }

    // New-bin candidate: only attractive when no open bin gives a decent fit
    if bin_residual == bin_capacity {
        let poor_fit = post_residual as f64 > 0.7 * bin_capacity as f64
            || (next_item_size > 0 && post_residual < next_item_size as f64 && fitting_bins_count <= 1);
        if poor_fit {
            score -= 20.0;
        } else {
            score += 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic bonus for small post-residual.
    score -= (bin_capacity as f64 - post_residual as f64).powi(2) / (bin_capacity as f64 * bin_capacity as f64) * 20.0;

    // Penalize dead space that no typical item could fill later.
    if post_residual > 0 && post_residual < 10 {
        score -= 15.0; // near-perfect fit
    } else if post_residual >= 10 && post_residual < 20 {
        score += 2.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0 + (post_residual - next_item_size) as f64 * 0.1;
        } else {
            score += 5.0;
        }
        // Perfect pairing: item + next item exactly fills bin.
        if item_size + next_item_size == bin_residual {
            score -= 30.0;
        }
    }

    // New-bin candidate handling: only attractive when existing bins fit poorly.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let late = step_index as f64 / (total_items.max(1) as f64);
        score = bin_capacity as f64
            - pressure * 40.0
            - late * 5.0
            + if fitting_bins_count == 1 { 35.0 } else { 0.0 };
    }

    // Global state: many open bins with high mean residual -> prefer reusing fuller bins.
    if open_bins_count > 2 && mean_residual > 30.0 {
        score += (mean_residual - 30.0) * 0.15;
    }

    // Mild time-horizon modulation: early stream, be more conservative with big residuals.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * post_residual as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Normalized stream progress
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Normalized post-residual and fill ratio
    let pr = post_residual as f64 / cap;
    let fill = 1.0 - pr;

    // Smooth polynomial coupling: reward high fill more strongly as stream progresses
    let progress_boost = t * (1.0 - pr).powi(3) * 40.0;
    score -= progress_boost;

    // Penalize tiny dead space quadratically (unusable gaps), smooth in pr
    let dead_penalty = (pr * pr) * (1.0 - pr) * 20.0;
    score += dead_penalty;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * fill;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward
    if next_item_size > 0 && (next_item_size as f64) == post_residual as f64 {
        score -= 25.0;
    } else if next_item_size as f64 > post_residual as f64 {
        // next item cannot use leftover space: penalize leftover mildly
        score += pr * 10.0 * (1.0 - t);
    }

    // Mild penalty for spreading across many open bins late in the stream
    score += (open_bins_count as f64).ln().max(0.0) * t * 2.0;

    // Mean-residual coupling: prefer bins with residual below mean (tighter bins first)
    let res = bin_residual as f64;
    score += (res - mean_residual) * 0.05 * (0.5 + t);

    // New-bin candidate: only attractive when no good fit exists (large post-residual waste elsewhere)
    if bin_residual == bin_capacity {
        score += 30.0 - 25.0 * (1.0 - pr) - (fitting_bins_count as f64) * 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: classify post_residual into
    // residue classes modulo 10 and integer-division thresholds.
    let cls = post_residual / 10;          // coarse class 0..=10
    let rem = post_residual % 10;          // fine residue within class

    // Reward tight fits: lower class (smaller leftover) is already favored
    // by the base term; add a non-linear bonus for very tight classes.
    score -= (10 - cls as f64) * 3.0;

    // Dead-space penalty: leftover that no plausible item (>=1) can use well.
    // Residues in 1..10 are awkward; penalize small nonzero remainders.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    if rem >= 1 && rem <= 3 && cls >= 1 {
        score += rem as f64 * 1.5;
    }

    // Perfect fill reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Harmonic coupling with next item: if the next item fits exactly in
    // post_residual, strongly favor this bin (chained perfect fit).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size < post_residual {
            let nxt_post = post_residual - next_item_size;
            // Reward leaving a residue class that is a "good" harmonic slot
            // (multiples of 10 or exact halves/quarters of capacity).
            if nxt_post % 10 == 0 || nxt_post * 2 == bin_capacity || nxt_post * 4 == bin_capacity {
                score -= 20.0;
            } else if nxt_post < 10 {
                score += 10.0;
            }
        } else {
            // Next item cannot follow here; slight penalty unless bin is nearly full anyway.
            score += 4.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new
    // bin unless the fit is terrible (large post_residual).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + (bin_capacity - post_residual) as f64 * 0.2;
    }

    // New-bin candidate: opening a fresh bin is only attractive when the item
    // is large relative to capacity or no open bin fits well.
    if bin_residual == bin_capacity {
        let fill_frac = item_size as f64 / bin_capacity as f64;
        let pressure = mean_residual / bin_capacity as f64;
        // Penalize new bins when existing bins have plenty of room and item is small.
        score += 30.0 + (1.0 - fill_frac) * 40.0 - pressure * 25.0;
        // Early in the stream, a new bin is cheap; later, prefer consolidation.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 20.0;
        // Large items start fresh bins happily (big items pair poorly).
        if item_size >= 50 {
            score -= 25.0;
        }
    }

    // Mild preference for bins deviating below the mean residual (use lumpy
    // bins first, keep smooth bins flexible).
    if (bin_residual as f64) > mean_residual {
        score += (bin_residual as f64 - mean_residual) * 0.3;
    } else {
        score -= (mean_residual - bin_residual as f64) * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the minimum item (1..=9)
    // are wasted forever; penalize them harshly with a non-linear surge.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64) / 10.0;
    }
    // Residuals in 10..=20 are only usable by small items; mild penalty grows
    // as the stream progresses and small-item demand may have passed.
    if post_residual >= 10 && post_residual < 20 {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 4.0 + 8.0 * progress;
    }

    // Reward near-perfect fills (tight packing) with a strong bonus.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual, reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // next item fits but leaves a gap; scale bonus by tightness of that fit
        let slack = (post_residual - next_item_size) as f64;
        if slack < 10.0 {
            score -= 10.0 - slack;
        }
    }

    // Last-chance pressure: if this is the only bin that fits, prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, favor filling
    // existing bins; the new-bin candidate (residual == capacity) gets pushed up.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        score += 25.0 + 10.0 * pressure;
    } else {
        score -= 2.0 * pressure;
    }

    // Coupling with mean residual: bins far below the mean residual are poor
    // targets for medium items; nudge score toward mean-consistent choices.
    score += 0.15 * (mean_residual - bin_residual as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is perfect: heavily reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: if the next item fits exactly into the post-residual,
    // this placement is a chain of perfect fits -> strong reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            // Next item fits, but leaves a third-generation residual.
            let third = post_residual - next_item_size;
            score -= 120.0 - (third as f64).min(120.0);
        } else {
            // Next item does NOT fit in the leftover: penalize dead space,
            // worse when the leftover is small (unusable).
            let waste = post_residual as f64;
            let unusable = if waste < 10.0 { 60.0 } else if waste < next_item_size as f64 { 30.0 } else { 0.0 };
            score += unusable + 0.25 * waste;
        }
    }

    // Relative to mean residual: bins with residual far above the mean are
    // "fresher" bins; filling them early wastes their capacity. Prefer bins
    // whose residual is below/at the mean (they are already committed).
    let dev = bin_residual as f64 - mean_residual;
    score += 0.35 * dev.max(0.0) - 0.15 * (-dev).max(0.0);

    // Last-chance bonus: if this is the only bin that fits, avoid opening a
    // new bin unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 80.0;
    }

    // New-bin candidate: only attractive when no open bin fits well or the
    // item is large and would leave a bad residual in existing bins.
    if bin_residual == bin_capacity {
        let big_item = item_size as f64 / bin_capacity as f64;
        let poor_options = if fitting_bins_count == 0 { 200.0 } else { 0.0 };
        score -= poor_options + 40.0 * big_item;
        // Late in the stream, opening fresh bins is less useful.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 50.0 * progress;
    }

    // Slight preference for tighter fits generally.
    score += 0.1 * (bin_residual - item_size) as f64 * 0.0; // no-op guard
    score += 0.05 * item_size as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual), with non-linear shaping.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * tightness * tightness;

    // Penalize dead space that cannot fit a typical next item.
    if next_item_size > 0 {
        let usable = if post_residual >= next_item_size { 1.0 } else { (post_residual as f64) / (next_item_size as f64) };
        score -= 12.0 * usable;
        // Reward bins whose post-residual exactly accommodates the next item.
        if post_residual == next_item_size {
            score -= 8.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Many open bins: discourage spreading; favor filling existing bins.
    let open_pressure = open_bins_count as f64 / (1.0 + mean_residual.max(1.0));
    score += 2.0 * open_pressure;

    // Early in the stream: be more willing to open bins / keep flexibility.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses unless
        // existing fits are poor (high post residual).
        score += 10.0 + 40.0 * progress;
        if post_residual as f64 > mean_residual + item_size as f64 {
            score -= 5.0;
        }
    } else {
        // Late in stream: reward using existing bins more aggressively.
        score -= 5.0 * progress;
    }

    // Coupling with mean residual: prefer bins below mean residual
    // (i.e., fuller than average) to consolidate.
    let dev = mean_residual - bin_residual as f64;
    score += 0.15 * dev;

    // Small penalty for very large leftover fragments (unusable slivers).
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    // Normalized stream progress
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    // Normalized post-residual
    let npr = pr / cap;
    // Smooth non-linear coupling: post_residual penalized more as stream progresses
    score += npr * npr * cap * (0.5 + 0.5 * progress);
    // Reward tight fits (small post-residual) with smooth decay
    score -= cap * (1.0 - npr) * (1.0 - npr) * 0.25;
    // Penalize dead space that cannot fit a typical next item (smooth interaction)
    if next_item_size > 0 {
        let nsize = next_item_size as f64;
        let waste = (nsize - pr).max(0.0) / cap;
        score += waste * waste * cap * 0.8;
        // Reward leaving space exactly usable by next item (smooth kernel)
        let fit_gap = (pr - nsize).abs() / cap;
        score -= cap * (-fit_gap * 6.0).exp() * 0.5;
    }
    // Last-chance bonus: strongly favor using the only fitting bin (smooth weight via progress)
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= cap * (0.6 + 0.4 * progress);
    }
    // Slightly discourage spreading across many open bins when residuals are large
    let mr = mean_residual / cap;
    score += (open_bins_count as f64).ln().max(0.0) * mr * mr * cap * 0.1;
    // New-bin candidate: prefer opening a new bin only late in stream or for large items
    let is_new_bin = (bin_residual as f64 - cap).abs() < 1e-6;
    if is_new_bin {
        score += cap * (1.0 - progress) * 0.3;
        score -= item_size as f64 * 0.1;
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: items of size dividing capacity cleanly
    // (10,20,25,50) leave residuals in "friendly" classes. Penalize residuals that
    // are not expressible as sums of common item sizes.
    let friendly = [0u32, 10, 20, 25, 30, 40, 50, 60, 70, 75, 80];
    let mut friendly_bonus = 0.0f64;
    for &f in friendly.iter() {
        if post_residual == f {
            friendly_bonus = 12.0;
        }
    }
    score -= friendly_bonus;

    // Modulo-10 class of post_residual: multiples of 10 pair well with the
    // typical granularity of item sizes.
    if post_residual % 10 == 0 {
        score -= 6.0;
    } else if post_residual % 5 == 0 {
        score -= 3.0;
    } else {
        score += 4.0; // awkward remainder class
    }

    // Integer-division threshold: tiny dead space (< 10) is nearly worthless.
    if post_residual < 10 {
        score -= 15.0; // perfect fill, great outcome
    } else if post_residual < 20 {
        score += 8.0;  // dead space that almost nothing fits
    }

    // Lookahead coupling: does next_item_size fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // chain placement possible: reward proportional to how snugly it fits
            let snug = (post_residual - next_item_size) as f64;
            score -= 10.0 + snug * 0.1;
        } else {
            // next item won't fit here; penalize large wasted residuals less
            // if they belong to a friendly class (reusable later)
            score += 2.0;
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only open a new bin when existing residuals
    // are poor (large, awkward classes) or the item is huge.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        // baseline: opening a bin is moderately costly
        score = 55.0;
        if item_size >= 60 {
            score += 10.0; // huge items deserve fresh bins less often
        }
        if mean_residual >= item_size as f64 + 15.0 {
            score += 15.0; // open bins still have room; discourage new bin
        }
        if pressure < 0.15 {
            score -= 10.0; // existing bins nearly full -> new bin is fine
        }
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 5.0; // new bin can chain current + next item
        }
    }

    // Progression: later in stream, consolidate more aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 3.0 * (post_residual as f64 / bin_capacity as f64);

    // Prefer tighter bins overall when many bins are open.
    score += (open_bins_count as f64).sqrt() * (post_residual as f64 / bin_capacity as f64) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    // A residual that can never fit even the smallest future item (size 1..100
    // unknown, assume tiny items rare) is wasted space; the smaller the gap
    // relative to typical item sizes, the worse.
    if post_residual > 0 {
        let pr = post_residual as f64;
        // Non-linear penalty: gaps below ~20 are near-waste for typical items.
        if post_residual < 20 {
            score += (20.0 - pr) * 6.0; // strong penalty for tiny dead space
        } else if post_residual < 35 {
            score += (35.0 - pr) * 2.5; // moderate penalty for small gaps
        }
        // Reward gaps that can still fit the lookahead item exactly well.
        if next_item_size > 0 && post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            score -= (next_item_size as f64) * 0.8; // lookahead fits: big bonus
            if slack < 10 {
                score -= 8.0; // near-perfect fit for next item
            }
        } else if next_item_size > 0 && post_residual < next_item_size {
            // Post residual cannot accommodate lookahead: mild penalty scaled
            // by how close it is (a near miss wastes potential).
            score += (next_item_size as f64 - pr) * 0.6;
        }
    } else {
        // Perfect fill: best possible outcome.
        score -= 50.0;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + (item_size as f64) * 0.2;
    }

    // Open-bin pressure: with many open bins, discourage spreading; with few,
    // allow opening new bins for good fits.
    let ob = open_bins_count as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize when many bins already open, reward
        // when the current item is large and few bins exist.
        score += ob * 4.0;
        if item_size >= 50 {
            score -= 10.0;
        }
        // If the new bin would leave a bad residual, add extra penalty.
        if post_residual < 20 {
            score += 12.0;
        }
    } else {
        // Existing bin: slight reward for consolidating when bins are many.
        score -= (ob - 1.0).max(0.0) * 0.5;
    }

    // Mean-residual coupling: prefer bins with residual below mean (tighter
    // bins get filled first), keeping large residuals for future big items.
    let mr = mean_residual;
    if bin_residual != bin_capacity {
        let br = bin_residual as f64;
        if br < mr {
            score -= (mr - br) * 0.4;
        } else {
            score += (br - mr) * 0.3;
        }
    }

    // Stream progression: late in the stream, be more conservative about
    // opening new bins (less future to amortize them).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += progress * 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward: post_residual exactly matches next item (perfect 2-step chain).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }
    // Soft reward: next item still fits after placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
        // Extra reward when post_residual is close to next item size (tight chain).
        let gap = (post_residual - next_item_size) as f64;
        score -= 12.0 / (1.0 + gap / 10.0);
    }
    // Penalize dead space: small post_residual that cannot fit next item.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 10.0;
    }
    // Penalize leaving unusable tiny residuals (< 10, min plausible item size).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Compare against mean residual: prefer bins with less residual (tighter bins).
    score += (mean_residual - bin_residual as f64).max(-50.0).min(50.0) * 0.3;

    // Last chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when current fit is poor or stream is early.
    if bin_residual == bin_capacity {
        let poor_fit = if next_item_size > 0 { (post_residual as f64 - next_item_size as f64).abs() } else { 0.0 };
        let pressure = if fitting_bins_count <= 1 { 20.0 } else { 0.0 };
        score += 30.0 - pressure - (poor_fit / 10.0).min(20.0);
        // Early in stream, opening bins is cheaper.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 10.0 * (1.0 - progress);
    }

    // Mild preference to fill large items into already-open bins.
    score += (item_size as f64 / 100.0) * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: scale post_residual down when the fill fraction is high.
    let fill = item_size as f64 / bin_residual as f64;
    score -= 25.0 * fill * fill;

    // Penalize small dead space that nothing can use (dead zone under 10 units
    // is useless given min item size, but sizes go down to 1, so weight gently).
    if post_residual < 4 {
        score -= 15.0; // near-perfect closure bonus
    } else if post_residual <= 10 {
        score += 6.0; // awkward tiny gap
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Lookahead: if the next item can use this bin's post_residual, reward it.
    if next_item_size > 0 {
        let nr = next_item_size as f64;
        if (post_residual as f64) >= nr {
            score -= 12.0 * (nr / 100.0);
        } else if (post_residual as f64) > 0.0 {
            score += 4.0; // next item cannot follow here; dead-ish space
        }
    }

    // New-bin candidate handling: neutral baseline; only attractive when open
    // bins are fragmented (low mean residual relative to capacity).
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / bin_capacity as f64;
        // Opening a new bin is penalized unless existing bins are very tight.
        score += 30.0 - 25.0 * (1.0 - fragmentation);
        // Late in the stream, prefer closing out existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
        // Many open bins already: discourage spreading.
        score += 0.8 * open_bins_count as f64;
    }

    // Mild preference for bins tighter than average (best-fit flavor).
    score += 0.15 * (bin_residual as f64 - mean_residual).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let post_norm = post / cap;

    // Base: penalize post residual, with quadratic dead-space growth
    let mut score = post + 90.0 * post_norm * post_norm;

    // Reward tight fits (small post_residual) more strongly as stream progresses
    let tightness = 1.0 - post_norm;
    score -= 40.0 * progress * tightness * tightness;

    // Cubic coupling: mid-range residuals are least desirable later in the stream
    let mid = post_norm * (1.0 - post_norm);
    score += 60.0 * progress * mid;

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 + 30.0 * progress;
    }

    // Lookahead: if the next item fits the post residual exactly-ish, reward
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        let slack = post - next_item_size as f64;
        score -= 20.0 * (1.0 - slack / cap) * (0.5 + progress);
    } else if next_item_size > 0 && post_residual > 0 {
        // dead space unusable by next item
        score += 10.0 * progress;
    }

    // Prefer bins below mean residual slightly (fill emptier bins first)
    score += 0.15 * (post - mean_residual);

    // Mildly penalize opening new bins when many bins are open and stream is late
    if bin_residual == bin_capacity {
        score += 8.0 + 15.0 * progress * (open_bins_count as f64).ln().max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: classify leftover space by
    // integer division into capacity "octaves" (fractions of C).
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let octave = (pr / cap * 8.0).floor() as i32; // 0..8 harmonic class

    // Reward residuals that sit in "usable" harmonic classes.
    // Class 0 (near-full bin) is excellent -> strong reward.
    // Class 7 (near-empty bin, item was tiny) is wasteful -> penalize.
    match octave {
        0 => score -= 30.0,
        1 => score -= 18.0,
        2 => score -= 8.0,
        3 => score -= 2.0,
        4 => score += 0.0,
        5 => score += 4.0,
        6 => score += 8.0,
        _ => score += 14.0,
    }

    // Exact-fit modulo bonus: post_residual divisible by common item
    // granularities (10, 20, 25, 50) means future items can tile it perfectly.
    let pr_u = post_residual;
    if pr_u > 0 {
        if pr_u % 10 == 0 { score -= 6.0; }
        if pr_u % 20 == 0 { score -= 4.0; }
        if pr_u % 25 == 0 { score -= 3.0; }
        if pr_u % 50 == 0 { score -= 5.0; }
    }

    // Coupling with next item: if next item fits exactly into post_residual,
    // this is a perfect chaining placement -> big reward.
    if next_item_size > 0 && next_item_size == pr_u {
        score -= 40.0;
    } else if next_item_size > 0 && next_item_size <= pr_u {
        // Next item fits: reward proportionally to how well it uses the leftover.
        let fill = next_item_size as f64 / pr;
        score -= 12.0 * fill;
        // Harmonic class of the chained residual.
        let chained = (pr - next_item_size as f64) / cap * 8.0;
        if chained < 1.0 { score -= 8.0; }
    } else if next_item_size > 0 {
        // Next item cannot use this residual: dead-space penalty scaled
        // by how small the residual is relative to the next item.
        score += 6.0 * (next_item_size as f64 - pr) / cap;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin gets a baseline score so it
    // only wins when existing bins have genuinely bad fits.
    if bin_residual == bin_capacity {
        score = 55.0 + (open_bins_count as f64).sqrt() * 3.0;
        // Early in the stream, opening bins is cheaper (fewer bins to manage).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 15.0 * (1.0 - progress);
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // big next item pairs well with fresh capacity
        }
        return score;
    }

    // Prefer tighter bins generally: reward small bin_residual (best-fit bias).
    score += (bin_residual as f64) * 0.15;

    // Slight preference for consolidating when many bins are open.
    score -= (open_bins_count as f64).ln().max(0.0) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A gap is "dead" if it is smaller than the smallest plausible item (1..100 unknown,
    // so use a conservative small-item threshold ~10) — waste that can never be filled.
    if post_residual > 0 {
        let dead_threshold = 10.0f64;
        if (post_residual as f64) < dead_threshold {
            score += 200.0 + (dead_threshold - post_residual as f64) * 50.0;
        }
        // Non-linear penalty on moderate gaps: quadratic growth punishes
        // mid-range waste that fragments residual capacity.
        score += (post_residual as f64).powi(2) * 0.02;
    } else {
        // Perfect fit: strong reward.
        score -= 150.0;
    }

    // Exact-fit lookahead: if the next item exactly fills the new residual,
    // strongly favor this placement.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 120.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // Next item fits: mild reward proportional to how well it uses the gap.
        score -= (next_item_size as f64) * 0.5;
    } else if next_item_size > post_residual && post_residual > 0 {
        // Next item cannot use this residual: penalize leaving a stranded gap.
        score += (post_residual as f64) * 0.8;
    }

    // Open-bin pressure: discourage spreading across many bins when few fit.
    if fitting_bins_count <= 1 {
        // Last-chance bin: heavily reward using it instead of opening a new bin,
        // unless post_residual would be tiny dead space (already penalized above).
        score -= 100.0;
    } else {
        // Mild penalty scaling with number of alternatives — prefer tightest fits.
        score += (fitting_bins_count as f64 - 1.0) * 5.0;
    }

    // Pressure against opening new bins when many bins are already open.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize so it is only chosen when all open bins
        // have terrible scores (dead-space penalties dominate).
        score += 80.0 + (open_bins_count as f64) * 3.0;
        // But if open bins are nearly full on average, a new bin is reasonable.
        score -= (mean_residual / bin_capacity as f64) * 40.0;
    } else {
        // Using an existing bin relieves open-bin pressure slightly.
        score -= (open_bins_count as f64) * 1.5;
    }

    // Early-stream bonus for consolidating items; late stream, be more tolerant
    // of opening bins since residual structure is already fixed.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if progress < 0.5 {
        score += post_residual as f64 * 0.3; // stricter early on
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect 2-step lookahead match: post_residual == next_item_size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Penalize post_residual slightly below next_item_size (dead space blocks lookahead item)
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0 * (1.0 - post_residual as f64 / next_item_size as f64);
    }

    // Reward tight fits generally
    score -= 30.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Penalize large waste relative to mean residual of open bins
    if post_residual as f64 > mean_residual {
        score += 0.5 * (post_residual as f64 - mean_residual);
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when current fit is very poor
    if bin_residual == bin_capacity {
        let fit_quality = item_size as f64 / bin_residual as f64;
        if fit_quality < 0.5 {
            score -= 20.0;
        } else {
            score += 40.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: prefer bins where the item fills a large fraction of residual.
    if bin_residual > 0 {
        let fill_ratio = item_size as f64 / bin_residual as f64;
        score -= 40.0 * fill_ratio * fill_ratio;
    }

    // Penalize small post-residuals that are too small for typical future items
    // (dead space), but reward exact or near-exact closure.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score += 25.0; // unusable sliver
    } else if post_residual <= 30 {
        score += 8.0; // low utility leftover
    }

    // Lookahead coupling: if the next item fits the post-residual well, reward this placement.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let next_fit = next_item_size as f64 / post_residual as f64;
            score -= 30.0 * next_fit;
        } else {
            // Next item won't fit here; penalize leaving a mid-size gap that nothing can use.
            score += 6.0;
        }
        // If next item exactly fills the post-residual, strong reward (chain completion).
        if next_item_size == post_residual {
            score -= 45.0;
        }
    } else {
        // Last item in stream: strongly prefer closing bins completely.
        score -= 2.0 * post_residual as f64;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // Crowding pressure: with many open bins, prefer consolidating into existing ones
    // (penalize new-bin candidate less when few bins are open).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let open_f = open_bins_count as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses and bins accumulate.
        score += 20.0 + 30.0 * progress + 2.0 * open_f;
    } else {
        // Existing bin: mild reward scaled by how much the fleet is fragmented.
        score -= 3.0 * open_f.min(10.0) * 0.1;
    }

    // Global residual alignment: prefer bins whose residual is close to the mean
    // (balances residual distribution), penalize outliers.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Time-horizon modulation: early in the stream, be more open to new bins
    // (long horizon amortizes); late, consolidate aggressively.
    if progress > 0.7 && bin_residual != bin_capacity {
        score -= 10.0 * (progress - 0.7);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Reward tight fits: strongly discount small post-residuals (non-linear).
    let fill_frac = 1.0 - pr / cap;
    score -= 30.0 * fill_frac * fill_frac;

    // Penalize residuals that are small but not zero (dead space) — smooth quadratic bowl
    let dead = pr / cap;
    score += 12.0 * dead * (1.0 - dead) * (1.0 - dead);

    // Lookahead coupling: if next item fits perfectly in post_residual, big reward
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let fit_gap = (pr - nx) / cap;
            score -= 20.0 * (1.0 - fit_gap) * (1.0 - fit_gap);
        } else {
            score += 6.0 * (nx - pr) / cap;
        }
    }

    // Stream progress: later in the stream, prefer using existing bins more aggressively
    score -= 10.0 * progress * fill_frac;

    // Scarcity: if this is the only fitting bin, favor it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless existing residuals are all poor.
    // Poor = mean residual far from any plausible useful size; smooth coupling with progress.
    if bin_residual == bin_capacity {
        let waste = mean_residual / cap;
        score += 25.0 - 20.0 * waste * progress;
        if next_item_size > 0 && next_item_size >= item_size {
            score += 8.0; // chaining large items benefits from fresh bins
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of the post residual (mod-10 classes, capacity fractions) ---
    let pr = post_residual;
    let cap_frac = post_residual as f64 / bin_capacity as f64;

    // Perfect fits and near-perfect fits are heavily rewarded.
    if pr == 0 {
        score -= 1000.0;
    } else if pr <= 5 {
        score -= 200.0;
    }

    // Dead-space class: residuals that are hard to fill (small odd remainders).
    // Classify by post_residual mod 10: residuals in [1,9] mod 10 that are tiny are bad.
    let class = pr % 10;
    match class {
        0 => score -= 40.0,                 // decade-aligned residual: very reusable
        1..=4 => score += 15.0,             // awkward sliver
        5 => score -= 10.0,                 // half-decade, moderately reusable
        _ => score += 8.0,                  // 6..9: awkward
    }

    // Integer-division thresholds: how many "typical" items (size ~25) fit in the residual?
    let fits25 = pr / 25;
    score -= 25.0 * fits25 as f64;
    // Bonus if the NEXT item exactly fits the post residual (harmonic coupling k=2).
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 300.0;
        } else if next_item_size <= pr {
            score -= 20.0 + (pr - next_item_size) as f64 * 0.5;
        } else {
            // next item won't fit here: penalize proportionally to wasted potential
            score += (next_item_size - pr) as f64 * 0.3;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate handling: empty bin gets a large opening penalty so we only
    // open when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 250.0;
        // But if the item is huge and leaves an awkward residual, opening fresh is fine.
        if item_size >= bin_capacity * 3 / 4 {
            score -= 120.0;
        }
        // Early in the stream, opening bins is cheaper (build a diverse pool).
        if total_items > 0 && (step_index as f64) / (total_items as f64) < 0.2 {
            score -= 60.0;
        }
    }

    // Coupling with mean residual: prefer bins that are already below-average full
    // (keeps the portfolio balanced) — slight reward for tight bins.
    score -= (mean_residual - cap_frac * 50.0) * 0.05;

    // Mild pressure to close bins as the stream progresses.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 10.0 * (bin_residual as f64 / bin_capacity as f64);

    // Small tie-breaker: tighter bins (smaller residual before placement) preferred.
    score += (bin_capacity - bin_residual) as f64 * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 25.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 80.0;
    }

    // Reward tight fits relative to bin capacity.
    let tightness = (bin_residual - post_residual) as f64 / bin_capacity as f64;
    score -= 30.0 * tightness;

    // Open-bin pressure: with many open bins, discourage opening new ones
    // (a new-bin candidate has bin_residual == bin_capacity).
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
        score += 15.0 + 8.0 * pressure;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Lookahead coupling: if next item fits into the post_residual, reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 8.0;
    }

    // Early stream: keep bins flexible; late stream: pack tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 5.0 * (post_residual as f64 / bin_capacity as f64);

    // Slight penalty for deviating from mean residual (keep bins balanced).
    score += 0.1 * (post_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 1.17;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: subtract proportionally to how well the item fills the bin.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 40.0 * fill_ratio;

    // Lookahead: if the next item fits into the post-residual, this bin stays useful.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Excellent chaining: residual is reusable, heavily reward.
            let chain_fit = next_item_size as f64 / post_residual.max(1) as f64;
            score -= 25.0 * chain_fit;
        } else {
            // Residual becomes dead space unless it's tiny; penalize mid-size dead gaps.
            let dead = post_residual as f64;
            if dead > 0.0 && dead < next_item_size as f64 {
                // Waste grows if dead space is large but unusable.
                score += 0.3 * dead;
            }
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded or fits are bad.
    if bin_residual == bin_capacity {
        // Base aversion to opening new bins.
        score += 55.0;
        // More attractive when mean residual across open bins is small (bins nearly full).
        score -= (mean_residual / bin_capacity as f64) * 40.0;
        // More attractive when many bins are open (spread load to keep flexibility).
        score -= 2.0 * open_bins_count as f64;
        // If no open bin fits, this is the only option anyway (fitting_bins_count reflects that).
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // Late in stream, prefer closing out bins tightly rather than opening new ones.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    // Slight preference for bins whose residual deviates from mean (consolidate waste).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score -= 0.05 * dev;

    // Small penalty for very large leftover gaps that likely become waste.
    if post_residual > 0 && post_residual < 10 {
        score -= 5.0; // nearly perfect fit
    } else if post_residual >= 10 && post_residual < 20 {
        score += 3.0; // awkward small gap
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let progress_sq = progress * progress;

    // Normalized post-residual
    let pr = post_residual as f64 / bin_capacity as f64;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early in the stream, prefer tight fits more aggressively; late, tolerate slack.
    score += 12.0 * pr * pr * (1.0 - progress) - 6.0 * pr * progress_sq;

    // Dead-space penalty: residual that is too small to fit typical items
    // (smoothly penalize residuals below ~ mean item size proxy)
    let dead = if post_residual > 0 && post_residual < 10 {
        (10.0 - post_residual as f64) / 10.0
    } else {
        0.0
    };
    score += 8.0 * dead * (1.0 - 0.5 * progress);

    // Lookahead: reward if next item fits exactly into post_residual (smooth coupling)
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        let fits_next = if next_item_size as u32 <= post_residual { 1.0 } else { 0.0 };
        score -= 6.0 * fits_next * (1.0 - gap / bin_capacity as f64) * (0.5 + 0.5 * progress);
    }

    // Last-chance bin: strongly favor using it (avoid opening a new bin)
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are poor fits
    if bin_residual == bin_capacity {
        let spread = (mean_residual - bin_residual as f64).abs();
        score += 15.0 - 3.0 * (fitting_bins_count as f64).ln().max(0.0) - 0.02 * spread * progress;
    }

    // Mild bonus for filling a bin closer to capacity (smooth quadratic reward)
    score -= 4.0 * (1.0 - pr) * (1.0 - pr) * (1.0 - progress);

    // Encourage consolidation when many bins are open
    score += 0.05 * open_bins_count as f64 * pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Base: prefer minimizing leftover space (tight fits).
    let mut score = post_residual as f64;

    // Exact fit is ideal: strong reward.
    if post_residual == 0 {
        score -= 100.0;
    } else {
        // Harmonic class of post_residual modulo 10: residues 1..9 are
        // "dead space" classes since typical items are multiples of 10.
        let residue = post_residual % 10;
        if residue != 0 {
            // Penalize unusable fractional residue proportional to how
            // small the residue is (harder to fill).
            score += (10 - residue) as f64 * 0.5;
        } else {
            // Residue is a multiple of 10: still fillable, mild reward.
            score -= 2.0;
        }
    }

    // Lookahead: if the next item cannot fit into post_residual, this bin
    // will be dead afterwards. Penalize proportionally to the gap.
    if next_item_size > 0 && next_item_size > post_residual {
        let gap = (next_item_size - post_residual) as f64;
        score += gap * 0.6;
    } else if next_item_size > 0 {
        // Next item still fits here: reward keeping a viable bin alive.
        score -= 3.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate (bin_residual == bin_capacity): only attractive if
    // current bins are heavily fragmented. Compare mean residual.
    if bin_residual == bin_capacity {
        // Base cost of opening a bin; offset by fragmentation of open bins.
        score += 20.0;
        score -= mean_residual * 0.35;
        // Late in the stream, opening bins is cheaper than scattering.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 5.0;
    }

    // Mild penalty for spreading across too many open bins.
    score += open_bins_count as f64 * 0.1;

    // Slight normalization by capacity fraction of item size.
    score += (item_size as f64 / bin_capacity as f64) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (below min item size 1..~20)
    // are heavily penalized since they can never be filled.
    if post_residual > 0 && post_residual < 20 {
        score += 40.0 * (1.0 - post_residual as f64 / 20.0);
    }
    // Perfect fit is strongly rewarded.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Reward leaving room that can still accommodate the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 8.0;
    }

    // Open-bin pressure: when many bins are open, prefer tightening them
    // rather than spreading; when few bins, allow spreading.
    let pressure = (open_bins_count as f64 / (mean_residual.max(1.0))).min(3.0);
    score += pressure * 2.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when current bin fit is terrible.
    if bin_residual == bin_capacity {
        let tightness = (post_residual as f64 / bin_capacity as f64).max(0.0);
        if tightness > 0.7 {
            score -= 12.0; // item is small; fresh bin keeps large residual
        } else {
            score += 25.0; // discourage opening new bins for good fits
        }
    }

    // Mild progression scaling: later in stream, be greedier about tight fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual to next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            // Perfect chain: this bin becomes exactly filled by the next item
            score -= 60.0;
        } else if post_residual > next_item_size {
            // Next item still fits after this placement: mild reward proportional to tightness
            let slack = (post_residual - next_item_size) as f64;
            score -= 30.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item cannot use this bin's leftover: penalize dead space
            let dead = (next_item_size - post_residual) as f64;
            score += 0.5 * dead;
        }
    } else {
        // Last item: just minimize leftover
        score += 0.1 * post_residual as f64;
    }

    // Prefer tight fits overall
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 20.0 * tightness * tightness;

    // Relative to mean residual: filling a bin below-average residual is good
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate: make it unattractive unless all open bins are nearly full
    if bin_residual == bin_capacity {
        score += 40.0 + 0.4 * mean_residual;
    }

    // Late in the stream: consolidate, discourage spreading across many bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.05 * (open_bins_count as f64) * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) nonlinearly.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= 30.0 * (1.0 - fit_ratio).powi(3);

    // Penalize dead space that can never fit a typical item again.
    if post_residual < 10 {
        score -= 8.0; // perfect closure bonus
    } else if post_residual < item_size.min(80) {
        score += 6.0; // likely unusable sliver
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big bonus.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            score -= 5.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            score += 3.0; // next item won't reuse this bin's leftover
        }
    }

    // Global state coupling: many open bins with slack -> prefer consolidation.
    let slack_pressure = mean_residual / bin_capacity as f64;
    score += slack_pressure * 4.0 * (open_bins_count as f64).ln().max(1.0);

    // Time horizon: early on, be more willing to open new bins (spread items);
    // later, consolidate aggressively.
    let t = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses.
        score += 10.0 * (1.0 - t) - 4.0 * t;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 3.0; // big next item may justify fresh bin
        }
    } else {
        score -= 2.0 * t; // late stream: favor existing bins
    }

    // Mild preference for bins with residual close to item size (best-fit flavor).
    score += 0.15 * ((bin_residual as f64 - item_size as f64).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post_residual, with non-linear emphasis
    let mut score = norm_pr * (1.0 + 2.0 * norm_pr * norm_pr);

    // Smooth stream-progress coupling: later in stream, penalize waste more strongly
    score *= 1.0 + 1.5 * progress * norm_pr;

    // Polynomial interaction between post_residual and mean residual
    let mr = mean_residual / cap;
    score += 0.8 * (norm_pr - mr) * (norm_pr - mr);
    score -= 0.4 * norm_pr * (1.0 - norm_pr);

    // Perfect-fit reward (smooth, via polynomial)
    score -= 2.5 * (1.0 - norm_pr) * (1.0 - norm_pr) * (1.0 - norm_pr);

    // Lookahead: reward leaving space the next item can use
    let nxt = next_item_size as f64;
    if nxt > 0.0 {
        let usable = (pr - nxt).max(0.0) / cap;
        score -= 0.6 * usable * (1.0 - usable);
        if pr >= nxt {
            score -= 0.5;
        }
    }

    // Last-chance bin bonus: strongly favor using a nearly-exclusive fitting bin
    if fitting_bins_count == 1 {
        score -= 1.2;
    }

    // Mild penalty for spreading across many bins when residuals are large
    score += 0.05 * (open_bins_count as f64).ln().max(0.0) * norm_pr;

    // New-bin candidate: make empty bins moderately attractive only when item is large
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / cap;
        score += 3.0 - 4.0 * fill_ratio * fill_ratio;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: residuals divisible by common
    // item-size classes (10, 20, 25, 50) are more reusable.
    let pr = post_residual;
    if pr == 0 {
        score -= 30.0; // perfect fit is ideal
    } else {
        // Dead-space penalty grows for small, "odd" leftovers.
        if pr < 10 {
            score += 45.0; // unusable dead space
        } else if pr % 10 == 0 {
            score -= 12.0; // aligns with decade class items
        }
        if pr % 25 == 0 {
            score -= 8.0;
        }
        if pr % 50 == 0 {
            score -= 10.0;
        }
        // Integer-division thresholds: big leftovers are flexible.
        if pr / 25 >= 2 {
            score -= 6.0;
        }
        if pr < 20 {
            score += 18.0;
        }
    }

    // Lookahead coupling: can the next item fit into the post-residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 15.0; // chains nicely
            // Harmonic bonus: next item exactly matches a divisor class of pr
            if pr % next_item_size == 0 {
                score -= 10.0;
            }
        } else {
            score += 8.0; // next item won't fit here
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate handling: only open a fresh bin when existing
    // residuals are poor (tight / fragmented).
    if bin_residual == bin_capacity {
        let pressure = (mean_residual / bin_capacity as f64).min(1.0);
        if pressure < 0.35 {
            score -= 25.0; // open bins are nearly full -> new bin is fine
        } else {
            score += 35.0; // prefer packing into existing bins
        }
        // Early stream: allow spreading slightly.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 10.0;
    }

    // Mild preference to balance across many open bins.
    score += open_bins_count as f64 * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    // A residual that cannot fit even the smallest plausible item (<= ~15)
    // is "dead space" — amplify its cost non-linearly.
    if post_residual > 0 {
        if post_residual < 15 {
            score += (15 - post_residual) as f64 * 8.0;
        } else if post_residual < 25 {
            score += (25 - post_residual) as f64 * 2.0;
        }
    }

    // Reward tight fits strongly (small post_residual relative to item size).
    let fit_ratio = post_residual as f64 / (bin_residual as f64 + 1.0);
    score -= (1.0 - fit_ratio) * 10.0;

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 50.0;
    }

    // If lookahead item can exactly use the post-residual, reward heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap < 10 {
            score -= 30.0;
        } else {
            score -= 10.0;
        }
    }
    // If post-residual is dead space AND lookahead cannot use it, penalize more.
    else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < 15 {
        score += 20.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones.
    let progress = step_index as f64 / (total_items as f64 + 1.0);
    let pressure = open_bins_count as f64 * (0.5 + progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure; also account for mean
        // residual across open bins — if open bins are roomy, new bin is worse.
        score = bin_capacity as f64 * 0.6 + pressure * 3.0 + mean_residual * 0.3;
    } else {
        // Mild penalty for leaving large residuals when many bins are open.
        score += mean_residual.max(0.0) * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base preference: tighter fit wins (penalize waste).
    score += (bin_residual as f64 - item_size as f64) * 0.001;

    // Lookahead: reward near-exact match between post_residual and next item.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= (bin_capacity as f64 / (1.0 + gap)) * 0.05;
        // Perfect lookahead match: next item exactly fills the bin.
        if post_residual == next_item_size {
            score -= 40.0;
        }
        // Next item fits in residual: mildly reward keeping that option.
        if post_residual >= next_item_size {
            score -= 5.0;
        } else {
            // Dead space created relative to next item: penalize.
            score += (next_item_size - post_residual) as f64 * 0.08;
        }
    }

    // Relative to mean residual: bins with unusual residual are interesting targets.
    let dev = post_residual as f64 - mean_residual;
    if dev < 0.0 {
        score += dev * 0.02; // below-mean residual slightly favored (tighter)
    } else {
        score += dev * 0.01;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are crowded.
    if bin_residual == bin_capacity {
        let crowded = open_bins_count as f64 * (mean_residual / bin_capacity as f64);
        score += 25.0 - 10.0 * crowded;
        // Late in the stream, opening new bins is more acceptable.
        score -= (step_index as f64 / total_items.max(1) as f64) * 10.0;
    }

    // Prefer filling bins that are already mostly full.
    let fill_ratio = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= fill_ratio * fill_ratio * 8.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Penalize creating small unusable gaps (dead space threshold ~10).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // worst: leaves a gap nothing can fill
    } else if post_residual < 20 {
        score += 12.0;
    }

    // Perfect closure bonus: item exactly fills the bin.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance bin: if this is the ONLY bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 + 0.5 * (bin_residual as f64 - item_size as f64);
    }

    // New-bin candidate logic: opening a new bin is attractive only when the item
    // fits poorly everywhere else or when residuals across bins are already large.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin (prefer existing bins).
        let mut new_bin_penalty = 18.0;
        // If the item leaves a bad gap in this bin's alternative, opening a new bin
        // becomes more attractive: compare to mean residual spread.
        let fit_quality = 1.0 - (post_residual as f64) / (bin_capacity as f64);
        new_bin_penalty -= 30.0 * (1.0 - fit_quality);
        // When mean residual of open bins is small (bins are full), new bin is fine.
        if mean_residual < 15.0 {
            new_bin_penalty -= 20.0;
        }
        // Late in the stream, avoid proliferating bins unnecessarily.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        new_bin_penalty += 10.0 * progress;
        // Many open bins already: discourage more.
        new_bin_penalty += 1.5 * open_bins_count as f64;
        score += new_bin_penalty;
    }

    // Lookahead coupling: if the next item could use the post_residual exactly,
    // reward leaving that gap; if next item cannot fit in post_residual, penalize.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item fits in the leftover space: good chaining.
            let chain_fit = 1.0 - ((post_residual - next_item_size) as f64) / (bin_capacity as f64);
            score -= 15.0 * chain_fit;
        } else if next_item_size > post_residual && next_item_size <= bin_residual {
            // Next item would fit now but not after this placement: mild penalty.
            score += 8.0;
        }
        // Perfect two-item chain: this item + next item exactly fill the bin.
        if item_size + next_item_size == bin_residual {
            score -= 45.0;
        }
    }

    // Global residual alignment: prefer bins whose residual is close to the mean
    // (keeps residual distribution balanced, easier future packing).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Slight preference for filling fuller bins first (best-fit bias).
    score -= 0.05 * (bin_capacity as f64 - bin_residual as f64);

    // Early stream: be a bit more willing to spread out; late stream: consolidate.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / cap;

    // Base: reward tight fills (low post_residual), with non-linear sharpening.
    let mut score = pr * (1.0 + 0.5 * (pr / cap).powi(2));

    // Smooth progress coupling: early on tolerate slack; late, push hard toward tight fits.
    score += pr * progress * (1.0 - (pr / cap)) * 1.2;

    // Penalize post-residuals that cannot fit the next item (dead space), smoothly.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let deficit = ((nx - pr) / cap).max(0.0);
        score += deficit.powi(2) * 30.0 * (1.0 - progress * 0.5);
        // Reward when next item exactly fits remaining space.
        let gap = (nx - pr).abs() as f64;
        score -= (1.0 - gap / cap) * 8.0;
    }

    // Last-chance bonus: if only this bin fits, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    }

    // Mild penalty for wasting a large fraction of the bin.
    score += (1.0 - fit_ratio).powi(3) * 5.0;

    // Prefer bins with residual below mean (consolidating slack) via smooth coupling.
    score += ((pr - mean_residual) / cap) * 6.0 * (1.0 - progress);

    // New-bin candidate: keep it slightly unattractive unless open bins are poor fits.
    if bin_residual == bin_capacity {
        score = cap * (1.0 + 0.3 * (1.0 - progress)) - 10.0 * (1.0 - fit_ratio);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: mod 10 buckets capture
    // which "denominators" of future items can still tile this bin.
    let class = post_residual % 10;
    match class {
        0 => score -= 18.0,           // perfectly divisible residue, highly reusable
        5 => score -= 10.0,           // half-step residue, decent reuse
        2 | 8 => score -= 6.0,
        4 | 6 => score -= 4.0,
        3 | 7 => score += 2.0,
        1 | 9 => score += 5.0,        // prime-ish residues, likely dead space
        _ => {}
    }

    // Integer-division thresholds: how many "average" items still fit.
    let avg_item = if next_item_size > 0 { next_item_size } else { 45 };
    let fits_count = post_residual / avg_item.max(1);
    score -= fits_count as f64 * 4.0;

    // Lookahead coupling: if next item fits exactly in post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= 8.0;
            // harmonic match: next item divides the post residual
            if post_residual % next_item_size == 0 {
                score -= 10.0;
            }
        } else {
            // next item cannot use this bin's leftover: penalize small leftovers
            if post_residual < 10 {
                score += 12.0;
            }
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: make empty bins mildly unattractive unless
    // the current bin would be left with unusable dead space.
    if bin_residual == bin_capacity {
        let tight = post_residual > 0 && post_residual < 10;
        if !tight {
            score += 15.0;
        } else {
            score -= 5.0;
        }
    }

    // Penalize bins far from the mean residual (fragmentation signal).
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.08;

    // Early in the stream, encourage consolidation into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * (open_bins_count.min(20) as f64) * 0.5;

    // Small bonus for filling bins nearly completely.
    if post_residual <= 5 {
        score -= 14.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for a perfect fit: post_residual exactly matches next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Reward if next item fits into the post-residual (2-step lookahead match).
    if next_item_size > 0 && post_residual >= next_item_size {
        let tightness = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
        score -= 25.0 * tightness;
    } else if next_item_size > 0 {
        // Next item won't fit here after placement: penalize dead space growth.
        score += 8.0;
    }

    // Penalize post_residual that is too small to ever be useful (dead space).
    if post_residual < 10 {
        score += 20.0;
    } else if post_residual < 25 {
        score += (25 - post_residual) as f64 * 0.5;
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Prefer bins with residuals tighter than the mean (good packing pressure).
    score -= 0.3 * (mean_residual - bin_residual as f64);

    // Mildly discourage leaving large residuals relative to capacity early on.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (post_residual as f64 / bin_capacity as f64) * (10.0 * (1.0 - progress));

    // New-bin candidate handling: prefer existing bins unless this is a very
    // large item that would leave a poor fit elsewhere, or stream is early.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 15.0;
        // But if no bin fits (fitting_bins_count counts open fitting bins and
        // this call is the new-bin candidate), opening is necessary: reduce cost.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // With lookahead: a fresh bin can host the next item too.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 12.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress in the stream (0..1)
    let progress = step_index as f64 / (total_items.max(1) as f64);

    // Is this the brand-new empty bin candidate?
    let is_new_bin = bin_residual == bin_capacity;

    // Perfect fit bonus: strongly reward filling a bin exactly.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Dead-space penalty: residual that no plausible future item can use.
    // Items can be as small as 1, but very small residuals are wasted if
    // they can't hold the lookahead item or typical sizes.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (10 - post_residual) as f64 / 10.0;
    }

    // Lookahead coupling: reward leaving room for the next item,
    // penalize residuals that are just barely too small for it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Room for the next item: gentle reward, scaled by how well it fits.
            score -= 8.0 * (next_item_size as f64 / 100.0);
        } else if post_residual > 0 {
            // Near-miss dead space for the lookahead item: penalize.
            let miss = (next_item_size - post_residual) as f64;
            score += 6.0 * (miss / 100.0).min(1.0);
        }
    }

    // Fit tightness: reward placing into the tightest feasible bin
    // (small bin_residual means item fills most of the bin).
    let tightness = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness;

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a bin is expensive; only make it
    // attractive when the item fits poorly everywhere else. Base cost:
    if is_new_bin {
        score += 15.0;
        // As the stream progresses and open bins accumulate, discourage
        // proliferation of bins with small residuals.
        score += 0.5 * open_bins_count as f64 * (0.3 + 0.7 * progress);
        // If many bins can already fit the item, a new bin is wasteful.
        if fitting_bins_count > 1 {
            score += 30.0 * (fitting_bins_count as f64).min(5.0);
        }
        // Late in the stream, prefer consolidating into existing bins.
        score += 20.0 * progress;
    }

    // Global residual context: if mean residual is high, we have slack
    // elsewhere; mildly prefer bins whose post-residual stays near the mean
    // (balanced packing), penalize extreme outliers.
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += 0.05 * deviation;

    // Mild preference for using older/more-filled bins early (first-fit flavor)
    // and for exactness late: shrink score toward tight fits as stream advances.
    score -= 10.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let base = pr * pr / cap;
    let progress_coupling = base * (0.5 + progress * (1.0 - progress) * 2.0);

    // Reward tight fits more strongly as the stream progresses
    let tight_fit_reward = -((cap - pr) / cap).powi(3) * (1.0 + progress) * 8.0;

    // Penalize dead space that cannot fit the next item
    let dead_space_penalty = if next_item_size > 0 && pr > 0.0 && pr < next_item_size as f64 {
        (next_item_size as f64 - pr) * (1.0 + progress)
    } else {
        0.0
    };

    // Bonus when this bin is the only fitting option
    let last_chance_bonus = if fitting_bins_count == 1 { -6.0 } else { 0.0 };

    // Mild penalty for spreading across many open bins
    let spread_penalty = (open_bins_count as f64).ln().max(0.0) * (1.0 - norm_pr) * 0.5;

    // Coupling with mean residual: prefer bins below mean residual (tighter bins)
    let mean_coupling = (mean_residual - pr) * 0.3;

    score = progress_coupling + tight_fit_reward + dead_space_penalty + last_chance_bonus + spread_penalty + mean_coupling;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual modulo capacity fractions
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;
    let cls = post_residual % quarter;

    // Reward post-residuals that land in "usable" harmonic classes
    // (multiples of quarter are ideal; small leftovers near zero are good too)
    let cls_dist = (cls as f64).min((quarter - cls) as f64);
    score += cls_dist * 0.5; // penalize awkward leftover classes

    // Exact harmonic class hits get strong bonuses
    if post_residual % eighth == 0 {
        score -= 8.0;
    }
    if post_residual % quarter == 0 {
        score -= 6.0;
    }

    // Penalize tiny dead space that is too small for the smallest plausible item
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead coupling: reward leaving room for the next item exactly
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 12.0;
        } else if post_residual > next_item_size {
            let slack = post_residual - next_item_size;
            if slack % quarter == 0 {
                score -= 5.0;
            }
            score += slack as f64 * 0.05;
        } else {
            // next item cannot fit here; mildly penalize
            score += 3.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when current fit is poor
    if bin_residual == bin_capacity {
        let tight = (post_residual as f64) <= 8.0;
        if tight {
            score -= 10.0; // item nearly fills a fresh bin: good
        } else {
            score += (post_residual as f64) * 0.3 + open_bins_count as f64 * 0.1;
        }
    }

    // Progress-based mild pressure to consolidate as stream ends
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 2.0;

    // Prefer bins already tighter than the mean (consolidation)
    score += ((mean_residual - post_residual as f64) * 0.1).max(-3.0).min(3.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny leftover gaps are almost unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // dead space penalty
    } else if post_residual == 0 {
        score -= 40.0; // perfect fit reward
    } else if post_residual <= 20 {
        score += 15.0; // semi-dead zone
    }

    // Reward tight fits (small post_residual relative to item).
    score -= (item_size as f64) * 0.5;

    // Last chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: prefer consolidating when many bins are open.
    score += (open_bins_count as f64) * 1.5;

    // Prefer bins with residual below mean (fill the emptiest-ish bins first),
    // keeping large residual bins for big future items.
    if bin_residual != bin_capacity {
        score += (mean_residual - bin_residual as f64) * 0.4;
    }

    // Lookahead: if next item fits exactly in post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 10 {
        score -= 25.0;
    }
    // If next item would NOT fit in post_residual and post_residual is small, slight penalty.
    if next_item_size > post_residual && post_residual > 0 && post_residual < 15 {
        score += 20.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    // (handled implicitly by dead-space penalties), but add mild base penalty.
    if bin_residual == bin_capacity {
        score += 30.0;
        // Late in stream, new bins are cheaper than scattering.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward
    if post_residual == 0 {
        score -= 500.0;
    }

    // 2-step lookahead: reward if next item fits exactly in post_residual
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual as u32 - next_item_size) as f64;
        score -= 40.0 * (1.0 - slack / bin_capacity as f64);
        if slack == 0.0 {
            score -= 150.0; // exact 2-item chain completion
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // dead space relative to next item: penalize small unusable gaps
        let gap = post_residual as f64;
        score += 25.0 * (1.0 - gap / bin_capacity as f64);
    }

    // Compare post_residual against mean residual: avoid bins that end far below average usable space
    score += 0.5 * (mean_residual - post_residual as f64);

    // Last chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: neutral-ish baseline, slightly penalized so we prefer reuse,
    // but attractive when post_residual after placement is large (fresh bin)
    if bin_residual == bin_capacity {
        score += 30.0;
        score -= 0.3 * post_residual as f64;
        // late in stream, opening fresh bins for good future packing is fine
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * progress;
    }

    // Tightness reward: the fuller the bin becomes, the better
    score -= 0.4 * item_size as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize large post_residual non-linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 6.0 * tightness * tightness * item_size as f64;

    // Dead space penalty: residuals too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: bonus if the next item fits the post-residual well.
    if next_item_size > 0 && next_item_size as f64 <= post_residual as f64 {
        let slack = post_residual as f64 - next_item_size as f64;
        score -= 8.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item won't fit here: mild penalty proportional to mismatch.
        score += 3.0 * (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Prefer bins with residuals below the mean (consolidate small leftovers).
    let dev = bin_residual as f64 - mean_residual;
    score += 0.15 * dev;

    // Time horizon: early in the stream, be more selective (penalize waste);
    // later, favor closing out open bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);
    score -= 4.0 * progress * (open_bins_count as f64).ln().max(0.0);

    // New-bin candidate: only attractive when current item is large and fits poorly.
    if bin_residual == bin_capacity {
        let large_item_bonus = (item_size as f64 / bin_capacity as f64).powi(2);
        score += 20.0 - 18.0 * large_item_bonus;
        if next_item_size > 0 && next_item_size <= item_size {
            score -= 6.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual

    // Base: penalize wasted space, non-linearly (quadratic in normalized residual)
    let mut score = 100.0 * x + 60.0 * x * x;

    // Smooth polynomial coupling of post_residual with stream progress:
    // early in stream, prefer filling bins tightly (low post residual);
    // late in stream, waste matters relatively more.
    let progress_coupling = (1.0 + 3.0 * t * t) * x * x * cap + (2.0 * t - 0.5) * x;
    score += progress_coupling;

    // Reward tight fits: item fills most of the bin
    let fill = item_size as f64 / cap;
    score -= 30.0 * fill * fill * (1.0 + t);

    // Last-chance bin: strongly favor it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 45.0;
    }

    // Lookahead: if next item fits exactly in the post residual, reward this bin
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64 / cap;
        score -= 25.0 * (1.0 - gap) * (1.0 + 2.0 * t);
    } else if next_item_size > post_residual {
        // dead space for the next item
        score += 8.0 * ((next_item_size - post_residual) as f64 / cap);
    }

    // Prefer bins below mean residual slightly (balance load)
    score += 0.3 * (pr - mean_residual);

    // New-bin candidate: neutralize base waste penalty, add a mild opening cost
    if bin_residual == bin_capacity {
        score = 55.0 + 20.0 * t;
        if fitting_bins_count == 0 {
            score = -100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls on
    // "usable" residue classes (multiples of common item sizes) are better.
    let post = post_residual;
    if post > 0 {
        let class_bonus: f64 = match post % 10 {
            0 => -6.0,               // perfectly reusable leftover
            1 | 2 | 3 | 4 => -2.0,   // small but partially reusable
            5 | 6 | 7 => 1.5,        // awkward mid-range gap
            _ => 3.0,                // 8/9: nearly dead space
        };
        score += class_bonus;

        // Dead-space penalty: leftover too small for the minimum item (1..100
        // interface, but keep a floor of 10 from the classic regime).
        let min_item = 10u32.min(bin_capacity);
        if post > 0 && post < min_item {
            score += 25.0;
        }
    } else {
        score -= 10.0; // perfect closure
    }

    // Fractional fill coupling: reward high fill ratio quadratically.
    let fill = (bin_capacity - post_residual) as f64 / cap;
    score -= 12.0 * fill * fill;

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // strongly favor this bin; if it nearly fits, mild penalty.
    if next_item_size > 0 {
        if next_item_size == post {
            score -= 15.0;
        } else if next_item_size > post {
            score += 2.0 * (next_item_size - post) as f64 / cap;
        } else {
            score += 0.5 * (post - next_item_size) as f64 / cap;
        }
    }

    // Last-chance logic: if this is the only fitting bin, avoid opening a new
    // bin unless the fit is terrible.
    if fitting_bins_count == 1 && post > 0 {
        score -= 8.0;
    }

    // New-bin candidate: penalize slightly so we only open new bins when the
    // best open bin is genuinely bad; scale with stream progression.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 5.0 + 4.0 * (1.0 - progress);
        // Opening a fresh bin is attractive when open bins are fragmented.
        if mean_residual / cap > 0.6 && open_bins_count > 1 {
            score -= 6.0;
        }
    }

    // Mean-residual drift: prefer bins below the mean (concentrate waste).
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    } else {
        score += 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small for any future item
    // (items >= 1, but small slivers < ~12 are effectively unusable) are heavily penalized.
    if post_residual > 0 && post_residual < 12 {
        score += 60.0 - 5.0 * post_residual as f64;
    }
    // Perfect fit: eliminate the baseline residual entirely.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward tight fits proportionally (fill ratio of the consumed space).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * tightness;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly into the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size <= post_residual {
            score -= 10.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            // this bin's leftover can't host next item; mild penalty if gap is tiny
            if post_residual < 12 {
                score += 15.0;
            }
        }
    }

    // Open-bin pressure: with many open bins, discourage spreading; prefer compacting.
    score += 0.8 * open_bins_count as f64;

    // Mean-residual coupling: if this bin is below-average full (high residual),
    // slightly prefer it to consolidate slack into few bins.
    score -= 0.3 * (bin_residual as f64 - mean_residual);

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 0.0 } else { 45.0 + 2.0 * open_bins_count as f64 };
        score += pressure;
        // Early in stream, a fresh bin is cheap insurance.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize wasted capacity relative to bin size (dead space pressure).
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 20.0 * fill_ratio;

    // Aggressive 2-step lookahead: reward if the next item fits into post_residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        // Exact match gets the strongest reward.
        let slack = (post_residual - next_item_size) as f64;
        score -= 15.0 + 10.0 * (1.0 - slack / bin_capacity as f64);
        // Extra reward when the pair nearly fills the bin completely.
        if post_residual == next_item_size {
            score -= 25.0;
        }
    } else if next_item_size > 0 {
        // Next item won't fit here: penalize leaving residual close to but below next size.
        let gap = (next_item_size - post_residual) as f64;
        score += 8.0 * (1.0 - gap / bin_capacity as f64);
    }

    // Contextualize residual against the mean residual of open bins.
    // Placing into a bin with below-average residual (tight bin) is preferred.
    score += 0.5 * ((bin_residual as f64 - mean_residual) / bin_capacity as f64);

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: only attractive when item is large or no good fit exists.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 / bin_capacity as f64;
        // Reward opening a new bin for large items; penalize for small ones.
        score += 30.0 * (1.0 - large_item);
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 18.0; // fresh bin can host the pair
        }
        // Early in the stream, opening bins is cheaper.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Slight preference for bins that keep residual in "usable" ranges (>= 10).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // unusable sliver penalty
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near 0 is best.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize small-but-nonzero dead space (unusable slivers).
    if post_residual > 0 && post_residual < 10 {
        score += 18.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, reward heavily.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            // next item fits but leaves more fragmentation; mild reward scaled by fit quality
            let nl = 1.0 - ((post_residual - next_item_size) as f64 / bin_capacity as f64);
            score -= 6.0 * nl;
        } else {
            // next item cannot fit here; penalize leaving medium dead space
            score += 4.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // New-bin candidate handling: empty bin gets a base cost so it only wins
    // when open bins fit poorly.
    if bin_residual == bin_capacity {
        score += 30.0;
        // opening new bins is cheaper early in the stream
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
        // and when many bins are already open (avoid bin explosion)
        score += 1.5 * open_bins_count as f64;
    } else {
        // reward using existing bins, more so when mean residual is high (bins are roomy)
        score -= 0.05 * mean_residual;
    }

    // Prefer filling bins that are already partially used (reduce bin count).
    let used = (bin_capacity - bin_residual) as f64;
    score -= 0.08 * used;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let is_new_bin = (bin_residual as u32 == bin_capacity);

    // Base: prefer small post-residual, with smooth polynomial shaping.
    let x = pr / cap; // normalized post-residual in [0,1]
    let mut score = 2.0 * x * x + 0.5 * x * x * x;

    // Smooth coupling of residual quality with stream progress:
    // early on, waste matters less; late, dead space is heavily penalized.
    score += (0.4 + 1.2 * progress) * x * x * (1.0 - x * (1.0 - x));

    // Reward filling the bin well (item size relative to capacity), smoothly.
    let fill = it / cap;
    score -= 0.8 * fill * fill;

    // New-bin candidate: penalize smoothly, scaled by how much of the bin
    // the item alone would occupy and remaining stream length.
    if is_new_bin {
        let remaining = (total_items - step_index) as f64 / total_items.max(1) as f64;
        score += 1.5 + 1.5 * remaining * (1.0 - fill * fill);
    }

    // Last-chance bin: strongly reward using it to avoid opening a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 1.2;
    }

    // Lookahead: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fits_next = if pr >= nxt { 1.0 } else { 0.0 };
        let tightness = 1.0 - ((pr - nxt) / cap).abs();
        score -= 0.6 * fits_next * tightness * tightness;
    }

    // Mild dispersion penalty: bins far from mean residual get smoothed penalty.
    let dev = (pr - mean_residual) / cap;
    score += 0.15 * dev * dev;

    // Slight preference for compacting among many open bins.
    score += 0.02 * (open_bins_count as f64).ln().max(0.0) * x;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify dead space by capacity fractions
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // fraction of capacity left

    // Perfect / near-perfect fits get strong reward
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 300.0;
    } else if post_residual <= 10 {
        score -= 150.0;
    }

    // Harmonic class buckets via integer division thresholds on post_residual
    let class = post_residual / 25; // 0,1,2,3 for 100-capacity
    score -= match class {
        0 => 60.0,           // 0..24: nearly full bin, very good
        1 => 20.0,           // 25..49: decent leftover
        2 => -10.0,          // 50..74: moderate leftover, slightly favored
        _ => 0.0,            // 75..99: large leftover, neutral
    };

    // Modulo arithmetic: residuals divisible by common small item sizes are reusable
    for m in [10u32, 20, 25, 50] {
        if post_residual >= m && post_residual % m == 0 {
            score -= 25.0;
        }
    }

    // Penalize residuals that can't fit typical small items (dead space)
    if post_residual > 0 && post_residual < 10 {
        score += 80.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 200.0;
        } else if next_item_size < post_residual {
            let nfit = post_residual - next_item_size;
            score -= 40.0 * (1.0 - nfit as f64 / cap);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: make it mildly unattractive unless residual logic favors it
    if bin_residual == bin_capacity {
        score += 30.0 + 10.0 * frac;
        // late in stream, prefer reusing open bins even more
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 40.0 * progress;
    }

    // Prefer bins below mean residual (keeps residuals balanced)
    score += 0.3 * (pr - mean_residual);

    // Slight penalty for many open bins to encourage consolidation
    score += 2.0 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10.0 - post_residual as f64);
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 25.0;
    } else {
        // Larger leftovers are fine if still reusable; mild reward proportional to size.
        score -= 0.15 * post_residual as f64;
    }

    // Reward tight fits relative to item size (packing efficiency).
    score -= 0.3 * (item_size as f64 / bin_capacity as f64) * 100.0;

    // Open bins pressure: discourage spreading across many bins.
    score += 1.5 * open_bins_count as f64;

    // Deviation from mean residual: prefer bins tighter than average.
    score += 0.5 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    // or the item is large relative to typical residuals.
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64) * 2.0 + 0.4 * mean_residual;
        let big_item = item_size as f64 > 0.7 * bin_capacity as f64;
        if big_item || fitting_bins_count == 0 {
            score -= 15.0;
        } else {
            score += pressure;
        }
        // Prefer deferring new bins late in the stream.
        score += 10.0 * (step_index as f64 / total_items.max(1) as f64);
    }

    // Lookahead: if next item could use this bin's post residual, reward it.
    if next_item_size > 0 {
        if (post_residual as i64 - next_item_size as i64) == 0 {
            score -= 18.0;
        } else if post_residual >= next_item_size {
            score -= 4.0;
        } else {
            // Dead space for the known next item.
            score += 0.4 * (next_item_size as f64 - post_residual as f64).min(20.0);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress of the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Primary objective: minimize post_residual (tightest fit wins).
    // Non-linearly reward very tight fits (post_residual small).
    if post_residual <= 5 {
        score -= 40.0 + (5 - post_residual) as f64 * 8.0; // near-perfect fill
    } else if post_residual <= 15 {
        score -= 15.0 + (15 - post_residual) as f64 * 1.5;
    }

    // 2-step lookahead: if the next item fits exactly into post_residual,
    // this placement is doubly desirable.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect two-item chain
        } else if next_item_size <= post_residual {
            // next item fits: leftover after two placements drives score
            let two_step_left = post_residual - next_item_size;
            score -= 25.0 - two_step_left as f64 * 0.8;
            if two_step_left <= 5 {
                score -= 20.0; // two items nearly fill the bin
            }
        } else {
            // next item will NOT fit here: penalize leaving a residual
            // that is just barely too small (dead space trap).
            let gap = next_item_size - post_residual;
            if gap <= 10 {
                score += 25.0 + (10 - gap) as f64 * 2.5; // unusable sliver
            } else {
                score += gap as f64 * 0.3; // mild penalty for large leftovers
            }
        }
    }

    // Relative to mean residual: bins already looser than average are
    // better candidates to consume big items into.
    let residual_gap = post_residual as f64 - mean_residual;
    score += residual_gap * 0.4;

    // Last-chance bin: if this is the ONLY bin that fits, strongly prefer
    // using it over opening a new bin (unless post_residual is huge).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 + progress * 20.0;
    }

    // New-bin candidate handling: an empty bin should only win when no
    // open bin offers a decent fit. Penalize the fresh bin moderately,
    // but less when the stream is early (few open bins to fragment).
    if bin_residual == bin_capacity {
        let base_penalty = 45.0;
        let early_bonus = (1.0 - progress) * 25.0;
        let crowding = (open_bins_count as f64).sqrt() * 3.0;
        score += base_penalty + crowding - early_bonus;
        // If the next item is large, a fresh bin is more attractive.
        if next_item_size >= 60 {
            score -= 15.0;
        }
    }

    // Slight preference to spread load when many bins are open and this
    // bin's residual is far above the mean (avoid one bloated bin).
    if open_bins_count > 3 && post_residual as f64 > mean_residual * 1.8 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize small post-residual quadratically.
    score -= 2.0 * ((bin_capacity as f64 - post_residual as f64) / bin_capacity as f64).powi(3) * 20.0;

    // Penalize dead space that no future item (min size 1) can use well.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead coupling: if next item fits in post-residual, reward this placement.
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 8.0;
    } else if next_item_size > 0 {
        // Next item won't fit after this placement; mild penalty scaled by how close.
        let gap = next_item_size as f64 - post_residual as f64;
        score += gap * 0.1;
    }

    // Prefer filling bins with low residual relative to mean (consolidate waste).
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // Time horizon: late in stream, favor using existing bins over opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses and many bins open.
        score += 10.0 + 40.0 * progress + (open_bins_count as f64).sqrt() * 2.0;
        // But early on, or when item is huge relative to mean residual, opening is fine.
        if progress < 0.1 {
            score -= 15.0;
        }
        if (item_size as f64) > mean_residual + 1.0 {
            score -= 20.0;
        }
    }

    // Slight preference for bins whose residual is close to item size (perfect split).
    let diff = (bin_residual as i64 - item_size as i64).abs() as f64;
    score += diff * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post_residual as f64;

    // Non-linear tightness reward: quadratic decay of residual, modulated by stream progress.
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let tight = (pr / cap).powi(2);
    score -= 6.0 * tight * (0.5 + progress);

    // Perfect-fit emphasis: cubic term for very small residuals.
    let small = ((cap - pr) / cap).powi(3);
    score -= 8.0 * small * item_size as f64 / cap;

    // Lookahead coupling: penalize leaving residual that neither fits next item well nor stays useful.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            // residual can host next item: mild reward scaled by how snugly it fits
            let snug = 1.0 - ((pr - nx) / cap);
            score -= 2.5 * snug * (pr / cap);
        } else {
            // residual too small for next item: dead-space penalty grows with progress
            score += 3.0 * (pr / cap) * (0.3 + progress);
        }
    }

    // Last-chance bonus: strongly favor the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0 + 5.0 * progress;
    }

    // New-bin candidate: keep it neutral-to-slightly-high early, penalize late when
    // consolidation is valuable; also penalize opening bins when mean residual is large.
    if bin_residual == bin_capacity {
        let open_pressure = (open_bins_count as f64 / (total_items.max(1) as f64)).sqrt();
        score += 4.0 + 6.0 * progress + 3.0 * open_pressure + 0.05 * mean_residual;
        // but allow new bin if item is huge and no open bin is snug
        if item_size as f64 > 0.7 * cap && fitting_bins_count == 0 {
            score -= 8.0;
        }
    }

    // Mild preference for bins with residuals near the mean (balance preservation).
    score += 0.02 * (pr - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: bonus proportional to how well item fills the bin.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 40.0 * fill_ratio * fill_ratio;

    // Penalize dead space: small post_residual is good, but zero-ish is best.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 25.0;
    } else if post_residual < 20 {
        score -= 8.0;
    } else {
        // Dead space that likely cannot host future items (items >= 10).
        score += (post_residual as f64) * 0.15;
    }

    // Harmonic class: does the lookahead item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Great: next item can join this bin.
            let pair_fill = (item_size + next_item_size) as f64 / bin_capacity as f64;
            score -= 30.0 * pair_fill;
            if (item_size + next_item_size) == bin_residual {
                score -= 45.0; // perfect pair
            }
        } else {
            // Next item won't fit here; penalize slightly more if we leave a large gap.
            let gap_class = post_residual / 10; // integer division harmonic class
            score += gap_class as f64 * 4.0;
        }
    } else {
        // Last item: strongly prefer perfect closure.
        score -= 70.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when the
    // item fits poorly everywhere else.
    if bin_residual == bin_capacity {
        // Base reluctance to open a new bin while others can fit.
        score += 55.0;
        // But large items (hard to place later) justify a fresh bin.
        if item_size > bin_capacity / 2 {
            score -= 35.0;
        }
        // Early in the stream, having few bins, a new bin is cheaper.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 20.0 * (1.0 - progress);
        // If the mean residual of open bins is large, prefer reusing them.
        score += (mean_residual / bin_capacity as f64) * 30.0;
    }

    // Mild penalty for spreading across too many open bins.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small to be useful later
    // are heavily penalized. A residual gap is "dead" if it is smaller than
    // the smallest plausible item and also smaller than the lookahead item.
    let dead_threshold = 12u32.max(next_item_size.min(bin_capacity));
    if post_residual > 0 && post_residual < dead_threshold {
        // Dead space penalty grows non-linearly as the gap shrinks.
        let tightness = (dead_threshold - post_residual) as f64 / dead_threshold as f64;
        score += 40.0 + 60.0 * tightness * tightness;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 50.0;
    } else {
        // Usable leftover: mild reward proportional to how well it matches
        // the next item's size (a gap that can host the lookahead item is gold).
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0 + 0.2 * (post_residual - next_item_size) as f64;
        }
    }

    // Open-bin pressure: prefer keeping the number of open bins low, but
    // allow opening new bins early in the stream when few bins exist.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 6.0 * open_bins_count as f64 * (0.3 + 0.7 * progress);

    // Last-chance bonus: if this is the only bin that fits, strongly favor it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: make the empty bin attractive only when existing
    // residuals are large (poor fits everywhere) or the item is big relative
    // to typical remaining space.
    if bin_residual == bin_capacity {
        let poor_fits = mean_residual < item_size as f64 * 0.6;
        let big_item = item_size > 60;
        if poor_fits || big_item {
            score -= 25.0;
        } else {
            // Default: discourage opening a new bin when decent fits exist.
            score += 15.0 + 2.0 * open_bins_count as f64;
        }
    }

    // Mild alignment with global mean residual: prefer bins whose residual is
    // close to the item (tight packing across the fleet).
    score += 0.1 * (bin_residual as f64 - item_size as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post residual exactly fits next item
    if next_item_size > 0 {
        if post_residual as u32 == next_item_size {
            score -= 200.0; // perfect chain: fill bin completely over two items
        } else if next_item_size <= post_residual {
            // next item fits: reward tightness of the two-step fill
            let two_step_waste = (post_residual as i64 - next_item_size as i64).abs() as f64;
            score -= 60.0 * (1.0 - two_step_waste / bin_capacity as f64);
        } else {
            // next item cannot use the leftover: penalize dead space creation
            score += 15.0 + 0.25 * (next_item_size as f64 - post_residual as f64).min(60.0);
        }
    } else {
        // last item: strongly prefer minimal leftover
        score += 20.0;
    }

    // Reward tight fits relative to mean residual of open bins
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 25.0 * tightness;

    // Penalize bins whose post residual is far below mean residual (creating outlier dead space)
    if (post_residual as f64) < mean_residual {
        score += 0.15 * (mean_residual - post_residual as f64);
    } else {
        score -= 0.05 * (post_residual as f64 - mean_residual);
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: only attractive when current item is large
    // (poor candidates for reuse) or no open bins can fit
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 150.0; // must open a new bin anyway
        } else {
            // opening a new bin wastes (capacity - item); penalize unless item is big
            let waste = (bin_capacity - item_size) as f64;
            score += waste * 1.2;
            // mild preference for new bins late in the stream to spread load
            let progress = step_index as f64 / total_items.max(1) as f64;
            score += 10.0 * (1.0 - progress);
        }
    }

    // Slight preference for bins with smaller current residual (best-fit flavor)
    score += 0.05 * bin_residual as f64;

    // Discourage accumulating too many open bins
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: quadratic penalty for wasted space relative to capacity.
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += 8.0 * waste_frac * waste_frac * (bin_capacity as f64);

    // Reward bins whose residual is close to the item (best-fit style sharpening).
    let fit_gap = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 4.0 * fit_gap;

    // Lookahead: if the next item exactly fits the post-residual, strongly favor this bin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            score -= 6.0;
        } else {
            // Next item cannot use the leftover; penalize proportionally to dead space.
            score += 3.0 * (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0 + 0.5 * item_size as f64;
    }

    // New-bin candidate handling: discourage opening a new bin when decent fits exist,
    // but encourage it when the item is large and fits are poor.
    if bin_residual == bin_capacity {
        let good_fit_exists = mean_residual > item_size as f64 * 1.3;
        if good_fit_exists {
            score += 25.0;
        } else {
            score -= 5.0 + 0.2 * item_size as f64;
        }
        // Early in stream, opening bins is cheap; late, prefer consolidation.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Prefer bins with below-average residual (keeps large residuals available
    // for large future items).
    let avg = if mean_residual.is_finite() && mean_residual > 0.0 { mean_residual } else { bin_capacity as f64 };
    score -= 2.0 * ((bin_residual as f64 - avg) / bin_capacity as f64);

    // Slight preference for using more-opened bins rather than proliferating bins.
    score -= 0.5 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.35 * progress * progress);

    // Penalize dead space quadratically as stream progresses
    score += 18.0 * norm_pr * norm_pr * (0.4 + 0.6 * progress);

    // Reward tight fits (small post_residual) with cubic bonus
    score -= 12.0 * (1.0 - norm_pr).powi(3) * (1.0 - progress);

    // Lookahead: reward bins whose post_residual can fit the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0 + 4.0 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 {
        score += 3.0 * (next_item_size as f64 / cap);
    }

    // Last-chance bin bonus: avoid opening new bins unnecessarily
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 8.0;
    }

    // Mild preference toward consolidating into existing bins vs new bin
    if bin_residual < bin_capacity {
        score -= 2.0;
    }

    // Penalize bins far from mean residual (fragmentation indicator)
    score += 0.05 * (pr - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how "usable" the leftover is
    // class 0: post_residual == 0 (perfect closure) -> big reward
    // class 1: post_residual divisible by 10 (aligned with typical item granularity)
    // class 2: small leftovers (<= 9) -> dead space
    // class 3: large leftovers -> still useful
    let post_class: u32 = if post_residual == 0 {
        0
    } else if post_residual % 10 == 0 {
        1
    } else if post_residual < 10 {
        2
    } else {
        3
    };

    match post_class {
        0 => { score -= 60.0; }
        1 => { score -= 25.0; }
        2 => { score += 18.0; }
        _ => {}
    }

    // Integer-division threshold: leftover in "half capacity" units
    let half_units = post_residual / (bin_capacity / 2);
    score -= half_units as f64 * 12.0;

    // Lookahead coupling: does the next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Harmonic match: next item exactly consumes a class-aligned chunk
            let leftover_after_next = post_residual - next_item_size;
            if leftover_after_next % 10 == 0 {
                score -= 30.0;
            } else {
                score -= 10.0;
            }
        } else {
            // next item won't fit here; penalize slightly less if bin nearly closed anyway
            score += 8.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: only attractive when current bin is a bad fit
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // base cost of opening a bin
        score = bin_capacity as f64 * 0.55 + 5.0;
        if post_class == 2 || (next_item_size > 0 && next_item_size > post_residual && post_residual < 10) {
            score -= 45.0; // opening fresh bin better than leaving dead space
        }
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    }

    // Progress-aware: early in stream, be more willing to open bins / spread load
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 5.0 * (is_new_bin as i32 as f64);

    // Mean residual coupling: if this bin's residual is far below mean, it's tight; prefer it
    let diff = mean_residual - bin_residual as f64;
    score += diff * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Strict dead-space avoidance ---
    // Post-residual gaps below the minimum item size are "dead" unless exactly small.
    let dead_threshold: f64 = 10.0;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        // Unusable sliver: heavily penalize proportionally to how tiny it is.
        score += (dead_threshold - post_residual as f64) * 8.0;
    } else if post_residual == 0 {
        // Perfect fill: strong reward.
        score -= 60.0;
    } else {
        // Usable residual: mild quadratic penalty to prefer tight fits.
        let pr = post_residual as f64;
        score += 0.02 * pr * pr;
    }

    // Reward bins whose post-residual can still hold the next item (lookahead synergy).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // Post-residual too small for lookahead: mild penalty (future dead space).
        score += 6.0;
    }

    // --- Open-bins-count pressure ---
    // When many bins are open, discourage spreading; when few are open, encourage consolidation.
    let ob = open_bins_count as f64;
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = ob * (0.5 + progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: pay the open-bin pressure cost, but discounted if
        // no good fit exists among open bins.
        score += 10.0 + pressure;
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    } else {
        // Reward using existing bins, scaled by how scarce fits are.
        score -= 8.0 + 4.0 * pressure / (ob + 1.0);
        if fitting_bins_count == 1 {
            // Last-chance bin: strong reward to avoid opening a new bin.
            score -= 25.0;
        }
    }

    // Mean-residual coupling: prefer bins close to the mean residual (balanced packing).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect two-step match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Post residual can host next item with slack -> still good.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 - 0.4 * slack;
    } else if next_item_size > 0 && post_residual > 0 {
        // Dead space: next item cannot fit here.
        let dead = post_residual as f64;
        score += dead * 0.8;
        // Harshly penalize tiny dead space (unusable slivers).
        if dead < 10.0 {
            score += 40.0;
        }
    }

    // Compare against mean residual: prefer bins that end below-average residual.
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin before opening a new one: reward using it if fit is decent.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New empty bin candidate: penalize unless residual is large / item huge,
    // so we prefer reusing existing bins when reasonable.
    if bin_residual == bin_capacity {
        score += 55.0;
        // But if item is large relative to capacity, opening fresh is fine.
        score -= (item_size as f64 / bin_capacity as f64) * 45.0;
        // Late in the stream, avoid proliferating bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    // Slight bonus for tight fits overall.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong preference for tight fits (classic best-fit baseline).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Exact fit is gold.
    if post_residual == 0 {
        score -= 200.0;
    }

    // Dead-space penalty: residuals too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item,
    // penalize bins where this placement blocks the natural follow-up fit.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0;
        } else {
            score += 8.0;
        }
        // Bonus if post-residual matches next item almost exactly.
        let gap = (post_residual as i64 - next_item_size as i64).unsigned_abs();
        score -= 10.0 * (1.0 - gap as f64 / (bin_capacity as f64)).max(0.0);
    } else {
        // Last item: any fit anywhere is fine; prefer fullest bins.
        score -= 5.0 * tightness;
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Time horizon: early in the stream, be conservative (keep bins flexible);
    // late in the stream, close out bins aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let flexibility = 1.0 - progress;
    score += flexibility * 6.0 * (post_residual as f64 / bin_capacity as f64);

    // Global state coupling: many open bins with high mean residual ->
    // encourage consolidating into existing bins, discourage new bins.
    if bin_residual == bin_capacity {
        // New-bin candidate baseline: raw post_residual equals capacity.
        score = bin_capacity as f64;
        score += 30.0 * flexibility;                    // opening early is costly
        score += 2.0 * open_bins_count as f64;          // avoid bin proliferation
        score += 0.5 * mean_residual;                   // lots of slack already -> reuse
        if next_item_size > 0 && next_item_size > bin_capacity {
            score += 100.0;
        }
        // Exception: if no existing bin leaves a good post-fit for next item,
        // a fresh bin becomes attractive.
        if next_item_size > 0 && fitting_bins_count >= 1 {
            let best_possible_gap = bin_residual.saturating_sub(item_size);
            if best_possible_gap < next_item_size && item_size + next_item_size <= bin_capacity {
                score -= 60.0;
            }
        }
        // Late stream: prefer closing items into existing bins.
        score += 20.0 * progress;
    }

    // Mild preference for bins that are already relatively full vs. average.
    let rel_fullness = 1.0 - (bin_residual as f64) / (bin_capacity as f64);
    score -= 8.0 * rel_fullness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear coupling: post_residual weighted by stream progress
    let pr_norm = pr / cap;
    score += 6.0 * pr_norm * pr_norm * (1.0 + progress);

    // Tight fits rewarded more as stream advances
    let fit_tightness = 1.0 - (pr / cap);
    score -= 12.0 * fit_tightness * fit_tightness * (0.5 + progress);

    // Penalize dead space relative to mean residual (smooth quadratic)
    let dev = pr - mean_residual;
    score += 0.05 * dev * dev / (cap * 0.01);

    // Last-chance bonus (smooth)
    let last_chance = if fitting_bins_count == 1 { 1.0 } else { 0.0 };
    score -= 8.0 * last_chance * (0.5 + 0.5 * progress);

    // Lookahead: reward leaving space for the next item, smoothly
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        let gap = pr - ns;
        if gap >= 0.0 {
            let g = gap / cap;
            score -= 5.0 * (g * (2.0 - g));
        } else {
            score += 3.0 * (-gap / cap);
        }
    }

    // Mild pressure to prefer existing bins over new bins as bins accumulate
    if bin_residual == bin_capacity {
        score += 4.0 + 2.0 * (open_bins_count as f64).ln().max(0.0) + 5.0 * progress;
    } else {
        score -= 2.0 * (1.0 + open_bins_count as f64).ln();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues near capacity fractions
    // determine how "dead" the leftover space is.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Fraction of capacity remaining after placement (0..1).
    let frac = pr / cap;

    // Harmonic classes: capacity/1, /2, /3, /4 boundaries.
    // Residuals just below a harmonic point (e.g. 50, 33, 25) are prime
    // targets for mid-size items; residuals just above are awkward.
    let harmonics = [cap / 2.0, cap / 3.0, cap / 4.0, cap / 5.0];
    for h in harmonics.iter() {
        let d = pr - h;
        if d >= 0.0 && d <= 8.0 {
            // Just above a harmonic split: leftover can host a small item later.
            score -= 6.0 * (1.0 - d / 8.0);
        } else if d < 0.0 && d >= -8.0 {
            // Just below: dead space, hard to fill.
            score += 5.0 * (1.0 + d / 8.0);
        }
    }

    // Integer-division threshold on post_residual: classify leftover
    // into usable bands by what could fit (items are 1..=100).
    if post_residual < 10 {
        score += 30.0; // nearly unusable dead space
    } else if post_residual < 25 {
        score += 8.0;
    }

    // Lookahead coupling: if next item fits exactly in the post residual,
    // strongly reward; if it nearly fits, penalize creating a near-miss.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if ni <= pr {
            let slack = pr - ni;
            if slack <= 4.0 {
                score -= 12.0; // perfect follow-up fit
            }
        } else {
            let miss = ni - pr;
            if miss <= 6.0 {
                score += 10.0; // near-miss: next item will need another bin anyway
            }
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when all open
    // residuals are small and the item is large.
    if bin_residual == bin_capacity {
        let avg_tight = mean_residual / cap;
        let progress = step_index as f64 / total_items.max(1) as f64;
        if avg_tight < 0.15 || item_size as f64 > 0.8 * cap {
            score -= 10.0 + 20.0 * (1.0 - avg_tight);
        } else {
            score += 25.0 * (1.0 - progress) + 10.0;
        }
    }

    // Mild preference for tighter bins overall (best-fit flavor).
    score -= (bin_capacity - bin_residual) as f64 * 0.05;

    // Prefer bins whose residual differs from the mean (keep diversity of sizes).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // smallest possible item (1) are pure waste; but any residual below
    // a "useful gap" threshold is increasingly penalized quadratically.
    let useful_gap = 20.0f64;
    let pr = post_residual as f64;
    if pr > 0.0 && pr < useful_gap {
        let waste = (useful_gap - pr) / useful_gap;
        score += 60.0 * waste * waste;
    }

    // Reward near-perfect fits strongly (post_residual very small).
    if post_residual == 0 {
        score -= 120.0; // perfect fill
    } else if pr <= 5.0 {
        score -= 40.0;
    }

    // Open-bin pressure: discourage spreading across many bins;
    // favor compacting into existing bins when bin count is high.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (2.0 + 6.0 * progress);

    // Mean-residual coupling: bins far below mean residual are good
    // consolidation targets (they are "loose"); bins far above mean
    // (nearly full) should be preserved for small items.
    let dev = (bin_residual as f64 - mean_residual) / (bin_capacity as f64);
    score += 30.0 * dev;

    // Last-chance bonus: if this is the ONLY bin that fits, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual,
    // this placement chains perfectly; reward it.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 70.0;
        } else if next_item_size <= post_residual {
            score -= 15.0;
        } else {
            // next item won't fit here anyway; slight penalty for
            // leaving a gap that chains poorly.
            let gap = (next_item_size - post_residual) as f64;
            score += 5.0 * (gap / bin_capacity as f64);
        }
    }

    // New-bin candidate handling: an empty bin gets a moderate opening
    // cost so it's chosen only when existing bins are poor fits.
    if bin_residual == bin_capacity {
        score += 35.0 + 10.0 * open_bins_count as f64;
        // but if no open bin fits well, allow opening: the dead-space
        // penalties above already push bad fits up.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer bins where the next item also fits (perfect 2-step chain).
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 60.0 + 0.5 * (post_residual - next_item_size) as f64;
    } else if next_item_size > 0 {
        // Next item won't chain: penalize large dead space relative to next item.
        score += 0.15 * (next_item_size as f64).min(post_residual as f64);
    }

    // Penalize leaving residuals that are likely unusable (small slivers).
    if post_residual > 0 && post_residual < 15 {
        score += 40.0;
    }

    // Reward tight fits: post_residual near zero is excellent.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Compare against mean residual: prefer consuming from bins with larger
    // residuals than average (keep tight bins for small items).
    if (bin_residual as f64) > mean_residual {
        score -= 8.0;
    } else {
        score += 8.0;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is bad
    // or lookahead suggests keeping space free is valuable.
    if bin_residual == bin_capacity {
        score += 55.0;
        if next_item_size > 0 && item_size + next_item_size > bin_residual {
            score -= 30.0; // fresh bin helps the 2-item sequence
        }
    }

    // Late in the stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (post_residual == 0 as u32 as bool) as i32 as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize (subtract) when post_residual is small relative to capacity.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 3.0 * tightness * tightness * (bin_capacity as f64);

    // Penalize dead space: residuals too small for any future item (min size 1, but typical 10..80).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual < item_size.min(80) && post_residual < 20 {
        score += 8.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly in the post_residual, reward this placement.
    if next_item_size > 0 {
        if post_residual as i64 == next_item_size as i64 {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            score -= 6.0;
        } else {
            // Next item won't fit here; slight penalty for wasting usable space.
            score += (next_item_size as f64 - post_residual as f64) * 0.15;
        }
    }

    // Global state coupling: many open bins with large mean residual -> discourage new bins,
    // encourage packing into existing ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when open bins have slack and early in stream.
        score += 10.0 + mean_residual * 0.5 + (1.0 - progress) * 20.0 + (open_bins_count as f64) * 2.0;
    } else {
        // Existing bin: reward more when open bins are plentiful and residuals are high.
        score -= (open_bins_count as f64).ln().max(0.0) * 2.0 + mean_residual * 0.1;
    }

    // Time horizon: late in the stream, prioritize closing bins tightly (avoid many partial bins).
    if progress > 0.8 {
        score += post_residual as f64 * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fill = 1.0 - post / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let p = 0.5 + 0.5 * progress;
    let mut score = post * (1.0 + 0.6 * p * fill * fill);

    // Penalize dead space more as stream progresses (quadratic in progress)
    score += 8.0 * (post / cap).powi(2) * (0.3 + 0.7 * progress);

    // Reward tight fits smoothly
    let tight = (item_size as f64 / bin_residual.max(1) as f64).min(1.0);
    score -= 6.0 * tight * tight * (1.0 + progress);

    // Last-chance bonus: strongly prefer the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Lookahead: reward leaving room for the next item (smooth interaction)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fits_next = if post >= nxt { 1.0 } else { 0.0 };
        let gap = ((post - nxt).abs()) / cap;
        score -= 4.0 * fits_next * (1.0 - gap) * (1.0 - progress);
        score += 3.0 * (1.0 - fits_next) * (0.5 + 0.5 * progress);
    }

    // Mild penalty for bin proliferation late in stream
    score += 0.15 * open_bins_count as f64 * progress;

    // New-bin candidate: encourage when open bins have poor fit potential
    if bin_residual == bin_capacity {
        let poor = (mean_residual - item_size as f64).abs() / cap;
        score += 5.0 - 6.0 * poor * (1.0 + progress);
        if fitting_bins_count <= 1 {
            score -= 8.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead-space danger via integer division
    let post = post_residual;
    if post > 0 {
        // residual classes: /10 buckets — small leftovers are "dead" unless tiny
        let class = post / 10;
        let rem = post % 10;
        // penalize awkward leftovers (not multiples of 10, since sizes 10..80)
        if rem != 0 {
            score += (10 - rem) as f64 * 0.6;
        }
        // dead space: leftover too small for minimum item (1..100 range, use 10 as soft floor)
        if post < 10 {
            score += 30.0 * (10 - post) as f64 / 10.0;
        } else if post < 20 {
            score += 8.0;
        }
        // harmonic bonus: leftover divisible by 25 or 50 pairs well with mid items
        if post % 50 == 0 {
            score -= 6.0;
        } else if post % 25 == 0 {
            score -= 3.0;
        }
        // perfect fit
        if post == 0 {
            score -= 25.0;
        }
        // class coupling with next item: leftover exactly matches lookahead
        if next_item_size > 0 {
            if post == next_item_size {
                score -= 15.0;
            } else if post >= next_item_size {
                score -= 4.0 * (1.0 - ((post - next_item_size) as f64 / 40.0).min(1.0));
            } else {
                score += (next_item_size - post) as f64 * 0.4;
            }
        }
    }

    // tight fit reward
    let tightness = item_size as f64 / bin_residual as f64;
    score -= tightness * 12.0;

    // last chance bin: strongly favor using it
    if fitting_bins_count == 1 {
        score -= 18.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // new-bin candidate: only attractive when current fit is bad or many items remain
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let bad_fit = post_residual < 10 || (next_item_size > 0 && next_item_size > post_residual && post_residual < 25);
        if bad_fit {
            score -= 10.0 + 10.0 * (1.0 - progress);
        } else {
            score += 20.0 + 15.0 * open_bins_count as f64;
        }
    }

    // mild pressure toward consolidating bins when many are open
    score += 0.05 * open_bins_count as f64;
    score -= 0.02 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold any
    // future item (sizes >= 1, but practically >= ~10) are pure waste.
    let dead_threshold: f64 = 10.0;
    let pr = post_residual as f64;
    if pr > 0.0 && pr < dead_threshold {
        // Hard penalty for unusable slivers.
        score += (dead_threshold - pr) * 8.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Reward tight fits generally: the smaller the post_residual relative to
    // the bin, the better — scale the base score down for tight placements.
    let tightness = pr / bin_capacity as f64;
    score -= (1.0 - tightness) * 10.0;

    // Last-chance pressure: if this is the only bin that fits, strongly favor
    // using it instead of opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins; a new-bin candidate (bin_residual == bin_capacity) gets
    // penalized proportionally to how many bins are already open.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 6.0 + 12.0;
    }

    // Coupling with mean residual: if the average open-bin residual is small,
    // the stream is nearly packed; avoid fragmenting — penalize moderate
    // leftovers more.
    if pr > 0.0 && mean_residual < 20.0 && bin_residual != bin_capacity {
        score += (20.0 - mean_residual) * 0.8;
    }

    // Lookahead: if the next item would fit into the resulting post_residual,
    // reward this placement (keeps bins productive).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item won't fit in the leftover: mild penalty for dead space.
        score += pr * 0.5;
    }

    // Late in the stream, be extra conservative about opening new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual) — already encoded by starting from post_residual.
    // Normalize post_residual against capacity for relative terms.
    let post_frac = post_residual as f64 / bin_capacity as f64;

    // --- 2-step lookahead: reward when post_residual exactly matches next item (perfect chain) ---
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0; // perfect 2-step chain
        } else if post_residual > next_item_size {
            // next item fits but leaves slack: mild reward proportional to how snug
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item does NOT fit in this bin's leftover: dead space penalty
            let waste = (next_item_size - post_residual) as f64;
            score += 10.0 + 0.5 * waste;
        }
    } else {
        // last item: just minimize post_residual (already base), tiny bonus for closing out cleanly
        score -= 5.0 * (1.0 - post_frac);
    }

    // --- Mean-residual coupling: prefer bins whose post_residual pushes them toward the mean
    // (keeps a balanced pool of medium residuals that future items can use) ---
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // --- Last-chance bonus: if this is the ONLY bin that fits, strongly prefer using it ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // --- New-bin candidate handling: brand-new empty bin gets a calibrated penalty so we
    // only open a new bin when open bins would waste a lot of space ---
    if bin_residual == bin_capacity {
        // residual of empty bin = capacity; base score already = capacity (100).
        // Penalize more when open bins exist and mean residual is large (plenty of room around).
        score += 20.0 + 0.3 * mean_residual;
        // But if the item is huge relative to typical slack, opening fresh is fine:
        // reduce penalty when item_size is large fraction of capacity.
        score -= 0.2 * item_size as f64;
        // If the next item is also large, a fresh bin gives flexibility for the pair.
        if next_item_size >= 50 {
            score -= 15.0;
        }
    }

    // --- Fragmentation guard: leftovers that are tiny but nonzero are hard to fill ---
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // --- Late-stream tightening: as the stream progresses, be greedier about tight fits ---
    let progress = if total_items > 1 { step_index as f64 / (total_items as f64 - 1.0) } else { 0.0 };
    score *= 1.0 + 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item fills a large fraction of residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 18.0 * fit_ratio * fit_ratio;

    // Penalize leaving small unusable slivers (dead space), but only when not a perfect fit.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Lookahead: bonus if the next item can fit into the post residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 8.0;
        } else if next_item_size <= bin_residual {
            // next item fits current residual but not post residual: slight penalty
            score += 3.0;
        }
        // Reward exact pairing: item + next item fills the bin
        if item_size + next_item_size == bin_residual {
            score -= 15.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin wastes capacity of open bins.
    if bin_residual == bin_capacity {
        // Prefer new bin only when existing bins fit poorly (large post_residual among fitters)
        // and there is meaningful lookahead pressure.
        let waste_pressure = if next_item_size > 0 && next_item_size > post_residual { 6.0 } else { 0.0 };
        score += 20.0 + open_bins_count as f64 * 1.5 - waste_pressure;
        // Late in stream, opening new bins is less costly (fewer future items to fill them)
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * progress;
    } else {
        // Mild preference for using already-open bins as stream progresses
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 4.0 * progress;
    }

    // Global state coupling: if mean residual is high, encourage consuming from fuller bins
    // (bins with residual below mean are "fuller", placing there consolidates space).
    let dev = mean_residual - bin_residual as f64;
    score += 0.05 * dev;

    // Reward consolidating into bins that are already mostly full
    let fullness = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 6.0 * fullness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Smooth non-linear penalty on post_residual: quadratic dead-space term
    let pr = post_residual as f64;
    let norm_pr = pr / bin_capacity as f64;
    score += 20.0 * norm_pr * norm_pr;

    // Reward tight fits (small post_residual) more strongly as stream progresses
    let tightness = 1.0 - norm_pr;
    score -= 15.0 * tightness * tightness * (0.5 + progress);

    // Penalize bins whose residual is far from the mean residual (avoid fragmentation)
    let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += 8.0 * dev * dev;

    // Coupling with next item: reward leaving space that fits the lookahead item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            let slack = (pr - nx) / bin_capacity as f64;
            score -= 10.0 * (1.0 - slack) * (1.0 + progress);
        } else {
            score += 6.0 * (nx - pr) / bin_capacity as f64;
        }
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Mild penalty on opening new bins late in the stream when bins are open
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 10.0 + 20.0 * progress;
    }

    // Small normalization with open bins count to encourage filling existing bins
    score -= (open_bins_count as f64).ln().max(0.0) * (pr / bin_capacity as f64) * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class: classify post_residual into capacity-fraction buckets.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let quarter = (post_residual * 4) / bin_capacity; // integer division 0..4
    let harmonic_bonus: f64 = match quarter {
        0 => 0.0,                       // tiny dead space, fine
        1 => -6.0,                      // ~25% residual, decent class
        2 => 4.0,                       // half-full leftover: wasteful
        3 => 10.0,                      // ~75% residual: very wasteful
        _ => 0.0,
    };
    score += harmonic_bonus;

    // Modulo arithmetic: residuals that are multiples of common small sizes
    // (harmonic divisors) are more likely to be filled by future items.
    let harmonics: [u32; 5] = [10, 20, 25, 50, bin_capacity / 2];
    let mut harmonic_fit = 0;
    for h in harmonics.iter() {
        if *h > 0 && post_residual % h == 0 && post_residual > 0 {
            harmonic_fit += 1;
        }
    }
    score -= 2.0 * harmonic_fit as f64;

    // Lookahead: reward if next item fits the post-residual (chain packing).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 8.0;
            // exact chain: post_residual becomes 0 after next item
            if next_item_size == post_residual {
                score -= 10.0;
            }
        } else {
            score += 3.0;
        }
    } else {
        // last item: strongly prefer emptying the bin
        if post_residual == 0 {
            score -= 50.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // Prefer tight fits relative to item size.
    score += (item_size as f64) * 0.15 * (pr / cap);

    // Penalize spreading across many open bins when mean residual is high.
    score += 0.05 * (open_bins_count as f64) * (mean_residual / cap);

    // Progression: later in the stream, be more aggressive about closing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * pr * 0.1;

    // New-bin candidate: only attractive when current fit is terrible.
    if bin_residual == bin_capacity {
        let bad_fit = pr > cap * 0.5 && next_item_size > 0 && next_item_size > post_residual;
        if bad_fit {
            score -= 15.0;
        } else {
            score += 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (1..=9) are heavily penalized.
    if post_residual > 0 && post_residual <= 9 {
        score += 40.0 * (10.0 - post_residual as f64);
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 15 {
        score -= 8.0;
    }

    // New-bin candidate: penalize so we prefer existing bins unless fit is bad.
    if bin_residual == bin_capacity {
        score += 12.0 + mean_residual * 0.15;
        // Opening a new bin is attractive if this item would leave big dead space elsewhere.
        if post_residual > 25 {
            score -= 15.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Lookahead: if next item fits in the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 3.0; // creates dead space relative to lookahead
    }

    // Open-bin pressure: mildly discourage proliferating bins.
    score += open_bins_count as f64 * 0.05;

    // Slight late-stream tightening: prefer tighter fits as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect 2-step lookahead match: item + next item exactly fills bin.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 60.0 / (1.0 + diff);
        if post_residual == next_item_size {
            score -= 40.0;
        }
        // Penalize leaving space that the next item cannot use
        if post_residual < next_item_size {
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    } else {
        // Last item: reward tight fits
        score -= 20.0 / (1.0 + post_residual as f64);
    }

    // Prefer filling bins whose residual is close to mean (avoid fragmentation)
    score -= 0.3 * (post_residual as f64 - mean_residual).abs().signum() * (post_residual as f64 - mean_residual).abs().min(30.0);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin unless the fit would be very tight
    if bin_residual == bin_capacity {
        let tightness = (bin_capacity - item_size) as f64;
        score += 15.0 + 0.4 * tightness;
        if next_item_size > 0 && (bin_residual - item_size) >= next_item_size {
            score -= 20.0; // new bin can also serve next item
        }
    }

    // Early in stream, allow more bins; late in stream, consolidate
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 10.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: heavily discount small post_residual.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 40.0 * fit_ratio * fit_ratio;

    // Penalize dead space that is too small for typical future items
    // (residual chunks below ~30 are hard to reuse).
    if post_residual > 0 && post_residual < 30 {
        score += (30 - post_residual) as f64 * 1.5;
    }

    // Lookahead coupling: if the next item fits exactly in the post
    // residual, strongly reward this placement (perfect chaining).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            // Next item fits: mild reward proportional to leftover slack.
            score -= 8.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item won't fit here: penalize leaving awkward gaps.
            score += 4.0 * (next_item_size as f64 - post_residual as f64).min(20.0);
        }
    }

    // Last-chance bonus: if this is the only bin that fits, using it
    // avoids opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Opening a new bin is attractive early in the stream (many items
    // remain to exploit fresh capacity) or when current fit is bad.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Early: cheap to open bins; late: expensive.
        score += 10.0 + 60.0 * progress;
        // If many bins are already open, discourage opening more.
        score += 1.5 * open_bins_count as f64;
        // If mean residual across open bins is large, plenty of room
        // exists elsewhere; opening a new bin is wasteful.
        score += 0.3 * mean_residual;
    } else {
        // Reward using bins whose residual is already small (consolidation).
        score -= 0.1 * (bin_capacity as f64 - bin_residual as f64);
        // Prefer bins below mean residual (tighter-than-average bins).
        score -= 0.2 * (mean_residual - bin_residual as f64);
    }

    // Global load balancing: when many bins are open, keep residuals
    // uniform to maximize future packing options.
    if !is_new_bin {
        let spread = (bin_residual as f64 - mean_residual).abs();
        score += 0.15 * spread;
    }

    // Slight time-adaptive tightening: as the stream progresses,
    // prioritize waste minimization more strongly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.5 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits, with non-linear penalty on large residuals
    let mut score = pr as f64 + 20.0 * norm_pr * norm_pr * cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let coupling = norm_pr * (1.0 - progress) * (progress - 0.5) * (progress - 0.5);
    score += 60.0 * coupling;

    // Dead-space penalty grows quadratically when residual can't fit typical next item
    let dead = (next_item_size as f64 - pr).max(0.0) / cap;
    score += 35.0 * dead * dead * cap;

    // Reward last-chance bins (smooth exponential-like via repeated multiplication)
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - norm_pr);
    }

    // Slight penalty when bin residual deviates from mean residual (fragmentation)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 10.0 * dev * dev * cap;

    // Mild preference for consolidating into fewer bins as stream progresses
    score += progress * 2.0 * open_bins_count as f64 * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues divisible by common
    // item sizes (10, 20, 25, 50) are "usable" dead space; odd/prime-ish
    // residues are dead. Reward usable classes, penalize dead ones.
    let pr = post_residual;
    if pr == 0 {
        score -= 40.0; // perfect fit
    } else {
        let usable = (pr % 10 == 0) as f64 + (pr % 20 == 0) as f64
            + (pr % 25 == 0) as f64 + (pr % 50 == 0) as f64;
        score -= 6.0 * usable;
        // dead-space penalty grows for small unusable residues
        if usable == 0.0 && pr < 10 {
            score += 12.0;
        }
    }

    // Capacity fraction thresholds via integer division on residual.
    let cap_frac = (bin_residual * 100) / bin_capacity; // 0..100
    if cap_frac <= 25 {
        score -= 5.0; // nearly-full bin: good to fill it
    } else if cap_frac >= 75 {
        score += 4.0; // wasting a mostly-empty bin on this item
    }

    // Lookahead coupling: does next_item_size fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // next item chains nicely; stronger if it leaves another
            // harmonic-friendly residue
            score -= 8.0;
            let npr = pr - next_item_size;
            if npr % 10 == 0 || npr == 0 {
                score -= 5.0;
            }
        } else {
            score += 6.0; // this placement strands the lookahead item
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }
    // Many fitting bins: mild penalty to encourage consolidation elsewhere.
    if fitting_bins_count > 3 {
        score += 1.5 * (fitting_bins_count as f64 - 3.0).min(4.0);
    }

    // New-bin candidate handling: only attractive when no open bin is tight.
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64) * (mean_residual / bin_capacity as f64);
        if pressure < 1.0 {
            score -= 10.0; // little residual pressure -> open fresh bin
        } else {
            score += 20.0 + pressure; // keep using open bins
        }
    }

    // Stream progression: late in the stream, avoid opening bins with
    // large leftover residues that will never be filled.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (pr as f64) * 0.15;

    // Mean-residual coupling: when mean residual is low, prefer bins
    // close to the mean (harmonic alignment).
    let dev = (pr as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that no item can use are pure waste.
    // Treat anything below the typical minimum item size (10) as dead space.
    if post_residual < 10 && !(bin_residual == bin_capacity && item_size == 0) {
        score += 25.0 * (10 - post_residual) as f64;
    }

    // Penalize post_residual that cannot fit the NEXT item (lookahead k=2),
    // but only if the next item is real and larger than the gap.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0;
    }
    // Reward a gap that exactly or nearly accommodates the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 10.0 * (1.0 - slack / bin_capacity as f64);
    }

    // Reward tight fits: small post_residual relative to item size is good.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 8.0 * fit_ratio;

    // Perfect fit: zero post_residual is ideal.
    if post_residual == 0 {
        score -= 20.0;
    }

    // Last-chance pressure: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Open-bin pressure: when many bins are open, discourage spreading to new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let bin_pressure = open_bins_count as f64 / (1.0 + progress * 10.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when open bins are plentiful and
        // residuals are still usable.
        score += 30.0 + 2.0 * bin_pressure + mean_residual * 0.5;
    } else {
        // Mild reward for using existing bins when open_bins_count is high.
        score -= 0.5 * bin_pressure;
    }

    // Prefer bins whose residual is close to the mean (keep residuals uniform),
    // unless a tight fit overrides.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    }

    // Aggressive 2-step lookahead: if the next item fits exactly into the
    // remaining space, this is a great chain placement.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 55.0;
        } else if post_residual > next_item_size && post_residual - next_item_size <= 10 {
            score -= 30.0;
        } else if next_item_size > post_residual && next_item_size <= bin_residual {
            // Next item won't fit here after placing; mild penalty unless
            // this bin would otherwise be stranded.
            score += 8.0;
        }
        // Penalize leaving a gap that neither the next item nor small future
        // items (min size 1) can use well.
        if post_residual > 0 && next_item_size > post_residual {
            score += (post_residual as f64) * 0.3;
        }
    }

    // Relative-to-mean residual coupling: prefer bins tighter than average
    // when the fit is decent, to consolidate remaining space.
    let residual_f = post_residual as f64;
    if residual_f > mean_residual {
        score += (residual_f - mean_residual) * 0.4;
    } else {
        score -= (mean_residual - residual_f) * 0.15;
    }

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item fits
    // badly everywhere. Empty-bin score starts at capacity; make it
    // competitive only when the item is large relative to open space.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 / bin_capacity as f64;
        score += 30.0 * (1.0 - large_item);
        if open_bins_count == 0 {
            score -= 100.0; // must open the first bin
        }
    }

    // Early in the stream, be slightly more willing to open fresh bins for
    // good long-term structure.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity && progress < 0.3 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward near-perfect fits.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // Lookahead: if the next item fits exactly into the post residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // Reward partial compatibility, scaled by how much slack remains for the future.
            let slack = (post_residual - next_item_size) as f64;
            score -= 100.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here anyway; mild penalty proportional to overshoot.
            let over = (next_item_size - post_residual) as f64;
            score += 10.0 * (over / bin_capacity as f64);
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item, favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 150.0;
    }

    // Penalize opening a new bin when decent open bins exist, unless the item
    // is large and would leave a badly fragmented residual elsewhere.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let open_f = open_bins_count as f64;
        // Base cost of a fresh bin grows with number of open bins and stream progress.
        score += 80.0 + 20.0 * open_f + 60.0 * progress;
        // But if the item is huge relative to mean residual, opening a new bin
        // may be the only clean option: discount the penalty.
        let mean_fit_gap = (mean_residual - item_size as f64).max(0.0);
        if mean_fit_gap < 10.0 {
            score -= 120.0;
        }
        // If the next item is small, a fresh bin with large residual is attractive.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 60.0;
        }
    } else {
        // Reward using bins whose residual is far from the mean (rebalance residuals),
        // scaled with stream progress so late placements consolidate.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let dev = (bin_residual as f64 - mean_residual).abs();
        score -= 5.0 * (dev / bin_capacity as f64) * (0.5 + progress);
    }

    // Mild global pressure: many open bins -> encourage filling existing ones.
    score -= 2.0 * open_bins_count as f64 * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized residual
    // Progress-dependent weighting: early stream tolerates waste, late stream punishes it.
    let w = 0.5 + 1.5 * progress * progress;
    score += w * (x * x) * cap * 0.5;

    // Cubic dead-space penalty amplified by progress.
    score += progress * (x * x * x) * cap * 0.8;

    // Reward tight fits: quadratic bonus when post_residual is small.
    score -= (1.0 - x) * (1.0 - x) * (1.0 + progress) * 12.0;

    // Last-chance bin: strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize mildly early, more when good fits exist elsewhere.
    if bin_residual == bin_capacity {
        let base = 8.0 + 20.0 * (1.0 - progress);
        let fit_pressure = if fitting_bins_count > 0 { fitting_bins_count as f64 } else { 0.0 };
        score += base + fit_pressure * 3.0;
        // If next item is large relative to residual, opening a new bin is more attractive.
        if next_item_size > 0 {
            let lookahead_ratio = next_item_size as f64 / cap;
            score -= lookahead_ratio * 10.0 * progress;
        }
    }

    // Lookahead coupling: if next item exactly fills this bin's post-residual, reward.
    if next_item_size > 0 && post_residual > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= (1.0 - diff / cap).max(0.0) * 15.0;
    }

    // Mean residual context: bins far below mean residual are less attractive late.
    let dev = (mean_residual - pr) / cap;
    score += progress * dev * 6.0;

    // Mild penalty for spreading across many bins.
    score += (open_bins_count as f64).ln().max(0.0) * (1.0 - progress) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: residues mod small integers
    // capture "nice" leftovers that pair well with common item sizes.
    let post = post_residual as i64;
    let cap = bin_capacity as f64;

    // Reward post-residuals divisible by 10 (harmonic with item granularity)
    if post % 10 == 0 { score -= 6.0; }
    if post % 25 == 0 { score -= 4.0; }
    if post % 50 == 0 { score -= 3.0; }

    // Penalize dead space in awkward residue classes
    let awkward = post % 10 != 0 && (post % 10 > 5 || post % 10 < 2);
    if awkward { score += 4.0; }

    // Perfect fit bonus
    if post_residual == 0 { score -= 25.0; }

    // Tight fill fraction reward (nonlinear)
    let fill = (bin_residual as f64 - post_residual as f64) / cap;
    score -= 8.0 * fill * fill;

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 && (post_residual as u64) >= (next_item_size as u64) {
        let gap = post_residual - next_item_size;
        if gap == 0 { score -= 18.0; }
        else { score -= 6.0 * (1.0 - (gap as f64) / 20.0).max(0.0); }
    } else if next_item_size > 0 && (next_item_size as u64) > (post_residual as u64) {
        // next item cannot use this bin's leftover: mild penalty for wasting space
        score += 3.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: penalize opening a bin when open bins exist and fit
    if bin_residual == bin_capacity {
        score += 20.0 + 0.5 * open_bins_count as f64;
        // But allow new bin if current item is large and mean residual is small
        score -= 0.3 * mean_residual;
    }

    // Small bonus for keeping mean residual balanced (avoid fragmentation)
    let dev = (mean_residual - post_residual as f64).abs();
    score += 0.05 * dev;

    // Slight late-stream consolidation pressure
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 2.0 * progress * (post_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the minimum item are worthless.
    if post_residual < 10 && post_residual > 0 {
        score += 60.0; // pure dead space penalty
    } else if post_residual == 0 {
        score -= 25.0; // perfect fit reward
    }

    // Dead space relative to next item: gap that even the next item cannot use.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 30.0;
    }

    // Reward tight fits (small post_residual relative to capacity).
    score -= (bin_capacity - post_residual) as f64 * 0.3;

    // Open-bin pressure: discourage opening new bins when stream is early,
    // but allow it late when bins are congested.
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize early, relax later; also penalize if many open bins.
        score += 40.0 * (1.0 - progress) + open_bins_count as f64 * 3.0;
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Slight preference for bins already below average residual (consolidating fullness).
    score += (mean_residual - bin_residual as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: penalize large post_residual quadratically.
    score += 0.05 * (post_residual as f64) * (post_residual as f64);

    // Lookahead: reward bins whose post_residual matches next_item_size well.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 12.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Post residual unusable by next item: penalize proportionally.
        score += 4.0 + 0.5 * (next_item_size as f64 - post_residual as f64);
    }

    // Compare against mean residual: bins tighter than average are good targets.
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: strongly prefer using it to avoid opening new bins.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Late in stream: prefer filling existing bins over opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize, less so early when many bins may be needed.
        score += 15.0 + 30.0 * progress;
    } else {
        score -= 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Reward tight fits (small post residual relative to capacity)
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * tightness * 30.0;

    // Lookahead coupling: penalize leaving a residual that neither fits the
    // next item nor is zero (wasted dead space), reward residuals that fit it
    if next_item_size > 0 && post_residual > 0 {
        if (post_residual as u32) >= next_item_size {
            score -= 8.0 + 0.25 * next_item_size as f64;
        } else {
            score += 10.0 + 0.4 * next_item_size as f64;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Many fitting bins: mild penalty for wasting space when alternatives exist
    if fitting_bins_count > 2 {
        score += 3.0 * (fitting_bins_count as f64 - 2.0).min(5.0);
    }

    // Global state: if mean residual is large, prefer consolidating into
    // already-loose bins; if mean residual is small, be more tolerant
    let mr = mean_residual.max(0.0);
    score -= 0.15 * mr * (1.0 - tightness);

    // Open-bin pressure: with many open bins, discourage new bins implicitly
    // by rewarding placement in existing bins
    score -= 2.0 * (open_bins_count.min(20) as f64).sqrt();

    // Time horizon: early in the stream, be conservative (keep bins flexible);
    // late in the stream, aggressively fill bins
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 15.0 * (1.0 - t) * tightness;
    score -= 20.0 * t * tightness;

    // New-bin candidate: penalize opening a fresh bin unless the item is large
    // and no good fit exists
    if bin_residual == bin_capacity {
        score += 25.0 + 0.5 * item_size as f64;
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
        if item_size >= 60 {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let res = bin_residual as f64;
    let fit_ratio = item_size as f64 / cap;

    // Base: penalize leftover space, with non-linear polynomial coupling to stream progress.
    // Early on, leftover space is tolerable (bins can still be filled); late, it is waste.
    let mut score = post * (1.0 + 1.5 * progress * progress);

    // Smooth non-linear interaction: normalized post-residual cubed term amplifies
    // punishment of large dead space as the stream matures.
    let norm_post = post / cap;
    score += 30.0 * norm_post * norm_post * norm_post * (0.3 + 0.7 * progress);

    // Reward tight fits (small post_residual relative to item) more strongly over time.
    let tightness = 1.0 - (post / res.max(1.0));
    score -= 8.0 * tightness * tightness * (0.5 + progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin (smoothly weighted by progress).
    if fitting_bins_count == 1 {
        score -= 12.0 + 10.0 * progress;
    }

    // Slight preference for bins below mean residual (consolidating space).
    score += 0.05 * (mean_residual - res);

    // Lookahead coupling: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && (next_item_size as f64) <= post {
        score -= 4.0 + 3.0 * progress;
    } else if next_item_size > 0 {
        // If next item is close to fitting, mildly penalize blocking it.
        let gap = (next_item_size as f64 - post) / cap;
        score += 3.0 * gap * gap;
    }

    // New-bin candidate handling: an empty bin has high post_residual; make it a
    // moderate fallback that loses to good fits but wins over terrible fits.
    if bin_residual == bin_capacity {
        score = cap * (0.55 + 0.25 * progress) + 10.0 * norm_post * norm_post;
        // Prefer opening a new bin late in the stream when open bins are fragmented.
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: perfect fits (class 0) are golden.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let class = post_residual % 10;

    // Reward exact or near-exact fits (post_residual near 0 or divisible by 10).
    if class == 0 {
        score -= 30.0;
    } else if class == 1 || class == 9 {
        score -= 12.0;
    } else if class == 5 {
        score -= 6.0;
    } else {
        score += 4.0; // awkward residual classes penalized
    }

    // Harmonic fraction of capacity consumed: reward bins filled past half.
    let fill_frac = (bin_capacity - post_residual) as f64 / cap;
    if fill_frac >= 0.9 {
        score -= 25.0;
    } else if fill_frac >= 0.75 {
        score -= 15.0;
    } else if fill_frac < 0.5 {
        score += 8.0;
    }

    // Lookahead coupling: if the next item can exactly fill this bin's post_residual,
    // strongly favor this bin (chained perfect fit).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            let chain = post_residual % next_item_size;
            score -= (10.0 - chain as f64).max(0.0);
        } else {
            // Next item cannot use this residual: penalize small dead space less
            // when residual is large enough to be useful later.
            score += 3.0;
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless it enables a great fit.
    if bin_residual == bin_capacity {
        score += 5.0;
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 15.0; // new bin supports a fresh pair
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative, must open
        }
    }

    // Stream progression: later in the stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= fill_frac * 10.0 * progress;

    // Many open bins: discourage leaving many half-empty bins around.
    score += (mean_residual - pr).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // (below the minimum plausible item size) are heavily penalized.
    let min_item = 1u32;
    let unusable_zone = 10u32; // gap below which a residual is nearly dead space
    if post_residual > 0 && post_residual < unusable_zone {
        score += (unusable_zone - post_residual) as f64 * 6.0;
    }
    if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 25.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: penalize opening new bins when many are already open,
    // scaled by stream progression.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure from open bins and mean residual.
        score += 20.0 + (open_bins_count as f64 * (1.0 + progress) * 2.0);
        // If the next item could combine with this one in a fresh bin, slightly soften.
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 5.0;
        }
    } else {
        // Reward filling bins that are already well-utilized (low residual relative to mean).
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        }
        // Lookahead coupling: if the post-residual exactly accommodates the next item,
        // reward this placement (chains well).
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 12.0;
        } else if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
            // Post-residual too small for the known next item: penalize as dead space.
            score += (next_item_size - post_residual) as f64 * 2.0;
        }
    }

    // Mild general preference for tighter fits beyond raw residual.
    score += (item_size as f64 / bin_capacity as f64) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction of the stream
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Strong 2-step lookahead: reward when post_residual closely matches next item size
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect match: next item fills the bin almost exactly -> big reward
        if (post_residual as i64 - next_item_size as i64).abs() <= 2 {
            score -= 40.0;
        } else {
            // Penalize residuals that are slightly larger than next item (dead space),
            // reward residuals either much larger (still usable) or exact fit
            score += 0.35 * gap;
            // If next item would NOT fit after placement, this residual is dead for one step
            if post_residual < next_item_size {
                score += 0.5 * (next_item_size - post_residual) as f64;
            }
        }
    } else {
        // Last item: just minimize leftover
        score += 0.0;
    }

    // Relative-to-mean coupling: prefer bins whose post residual stays near mean residual
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Tight fit reward: item nearly fills the bin
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 10.0 * fill_ratio;

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when the fit into existing bins is poor
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin
        score += 30.0;
        // But if item is large and would leave tiny residuals elsewhere, opening is fine
        if item_size > 60 {
            score -= 20.0;
        }
        // Late in the stream, prefer consolidating into open bins
        score += 20.0 * progress;
        // Many open bins: discourage opening more
        score += 2.0 * open_bins_count as f64;
    }

    // Waste penalty: large unusable residuals are bad
    if post_residual > 0 && post_residual < 10 {
        score -= 15.0; // tiny residual = bin is effectively "closed", that's good
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core best-fit: reward tight fits non-linearly.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Strong reward for exact fill.
    if post_residual == 0 {
        score -= 40.0;
    }
    // Penalize tiny dead space that likely becomes unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead: if the next item fits in this bin's post-residual, reward;
    // if next item is large and post_residual is too small to matter, penalize.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 10.0 + 0.3 * next_item_size as f64;
        } else {
            score += 0.15 * (next_item_size as f64 - post_residual as f64).min(40.0);
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // otherwise a new bin gets opened.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Time horizon: early in the stream, prefer keeping residuals flexible;
    // late in the stream, pack tightly and avoid opening new bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 8.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);
    if progress > 0.8 && bin_residual == bin_capacity {
        score += 20.0; // discourage opening new bins near the end
    }

    // Global state: many open bins with high mean residual -> prefer reusing
    // a bin whose residual is close to the mean (keeps distribution balanced).
    if open_bins_count > 1 {
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.1 * dev;
        if bin_residual as f64 > mean_residual {
            score -= 3.0; // favor bins with more room among many open bins
        }
    }

    // New-bin candidate handling: an empty bin is attractive early (fresh,
    // flexible) but wasteful when good fits exist or many bins are open.
    if bin_residual == bin_capacity {
        score += 6.0 + 2.0 * open_bins_count as f64;
        if fit_ratio > 0.6 {
            score += 30.0; // item fits an open bin well -> don't open a new one
        }
        if progress < 0.3 {
            score -= 5.0; // early stream: new bins are cheap
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: quadratic penalty on leftover space (waste grows super-linearly)
    let mut score = pr * (1.0 + 2.0 * norm_pr * norm_pr);

    // Smooth stream-progress coupling: later in the stream, waste matters more
    let progress_weight = 1.0 + 1.5 * progress * progress;
    score *= progress_weight;

    // Cubic coupling of post_residual with mean residual: penalize bins whose
    // leftover diverges from the fleet average (dead-space fragmentation)
    let dev = (pr - mean_residual) / cap;
    score += 20.0 * dev * dev * dev.abs();

    // Reward filling a bin nearly exactly (smooth bump near zero residual)
    score -= 30.0 * (-pr as f64 / 8.0).exp();

    // Last-chance bonus: if this is the only fitting bin, strongly favor it
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * progress;
    } else {
        // mild penalty when many bins compete, prefer tightest anyway
        score += 2.0 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // New-bin candidate handling: empty bin (residual == capacity)
    if bin_residual == bin_capacity {
        // Opening a new bin is penalized, but attractive when the item is large
        // and no good fit exists (post_residual == capacity - item is large,
        // meaning item is small -> keep items in open bins instead).
        let fill = item_size as f64 / cap;
        score = cap - item_size as f64; // small items => high score (bad)
        score -= 40.0 * fill * fill;    // large items => opening a bin is fine
        score += 10.0 * (open_bins_count as f64).sqrt(); // discourage bin sprawl
        // late in stream, prefer reusing open bins
        score += 20.0 * progress;
        // if next item could use the fresh bin's remainder, soften penalty
        if next_item_size > 0 && next_item_size as f64 <= pr {
            score -= 12.0;
        }
    } else {
        // Lookahead synergy: if next item fits exactly in post_residual, reward
        if next_item_size > 0 && (post_residual as i64 - next_item_size as i64) == 0 {
            score -= 35.0;
        } else if next_item_size > 0 && next_item_size as u32 <= post_residual {
            score -= 8.0;
        } else if next_item_size > post_residual && next_item_size > 0 {
            // next item won't fit here; slight penalty for stranding space
            score += 5.0 * norm_pr;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: which 10-wide slot it falls into.
    let res_class = post_residual / 10;
    let res_mod = post_residual % 10;

    // Residuals in classes that commonly match item sizes (0..=8 => 10..=90 usable)
    // are valuable; tiny unusable slivers (class 0 with nonzero mod) are dead space.
    if post_residual == 0 {
        score -= 60.0; // perfect closure, strongly reward
    } else if res_class == 0 {
        score += 45.0; // sliver < 10, almost surely dead space
    } else {
        // Reward residuals that are multiples of 10 (align with typical item sizes)
        if res_mod == 0 {
            score -= 12.0;
        }
        // Reward larger residual classes mildly (more future utility)
        score -= (res_class as f64) * 2.5;
    }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 55.0;
        } else if next_item_size < post_residual {
            // reward proportionally to how well next item uses the leftover
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 20.0 * fill;
        } else {
            // next item won't fit here: mild penalty for mismatch
            score += 8.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: an empty bin should only win when no open bin
    // offers a decent fit. Penalize it by the health of the open-bin population.
    if bin_residual == bin_capacity {
        // Base penalty so it loses against any reasonable fit...
        score += 30.0;
        // ...but relax the penalty when few bins can fit the item (scarcity),
        // and when open bins are already crowded (low mean residual).
        let scarcity = (3usize.saturating_sub(fitting_bins_count)) as f64;
        score -= scarcity * 12.0;
        let crowded = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        score -= crowded * 25.0;
        // Late in the stream, opening fresh bins is cheaper (fewer future regrets)
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= progress * 15.0;
    }

    // Slight preference for filling more-completed bins (waste-avoidance).
    let fill_frac = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 10.0 * fill_frac * fill_frac;

    // Mean-residual coupling: prefer bins deviating favorably from the average,
    // pushing selection toward bins whose residual is closer to typical sizes.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold the
    // smallest plausible future item (<= 10) are pure waste. Penalize them hard.
    if post_residual < 10 && post_residual > 0 {
        score += 25.0 + (10 - post_residual) as f64 * 2.0;
    }

    // Semi-dead space: gaps that only fit tiny items are partially wasted.
    if post_residual >= 10 && post_residual < 20 {
        score += 6.0;
    }

    // Reward near-perfect fills (tight packing is ideal).
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Reward bins that are mostly full already (prefer filling existing bins
    // over spreading load). Best-fit core: lower post_residual already wins,
    // but add a bonus proportional to how full the bin becomes.
    let fill_ratio = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= fill_ratio * 8.0;

    // Open-bin pressure: with many open bins, strongly prefer compacting into
    // existing bins rather than opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (open_bins_count as f64) * (0.5 + 0.5 * progress);

    // Last-chance bin: if this is the ONLY bin that fits, strongly prefer it
    // over opening a new bin, unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
        if post_residual < 15 {
            score -= 8.0;
        }
    }

    // Lookahead: if the next item can use the post_residual exactly-ish,
    // reward leaving that gap; otherwise penalize leaving a gap next item
    // cannot use.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.3;
        } else if post_residual > 0 && next_item_size > post_residual {
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // New-bin candidate: an empty bin is only attractive when the item fits
    // badly everywhere else. Its raw post_residual is high (capacity - item),
    // but give it a mild bias so it's chosen only when genuinely better.
    if bin_residual == bin_capacity {
        score += 5.0 + mean_residual * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact / near-exact fits (dead-space elimination).
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 3 {
        score -= 120.0;
    } else if post_residual <= 10 {
        score -= 40.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item well.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual as f64 >= nxt {
            let gap = post_residual as f64 - nxt;
            // Perfect chain: next item exactly fills the remainder.
            if gap == 0.0 {
                score -= 150.0;
            } else if gap <= 10.0 {
                score -= 60.0 - gap * 2.0;
            } else {
                // Mild reward, decaying with gap.
                score -= (20.0 - gap * 0.5).max(0.0);
            }
        } else {
            // Next item cannot fit here; penalize proportionally to the shortfall,
            // but less harshly near the end of the stream (no future to plan for).
            let shortfall = nxt - post_residual as f64;
            let progress = step_index as f64 / total_items.max(1) as f64;
            score += shortfall * (1.0 - 0.5 * progress);
        }
    }

    // Relative-to-mean coupling: bins tighter than average are better targets.
    let rel = post_residual as f64 - mean_residual;
    score += rel * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: prefer opening a new bin only when no open bin
    // offers a decent fit. Base new-bin score slightly above a mediocre fit.
    if bin_residual == bin_capacity {
        score += 10.0 + open_bins_count as f64 * 0.5;
        // But if next item is large and current item is small, new bin is attractive.
        if next_item_size > 0 && post_residual as f64 >= next_item_size as f64 {
            score -= 30.0;
        }
    }

    // Mild preference for consolidating into fewer bins as the stream progresses.
    score += open_bins_count as f64 * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item nearly fills the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize small dead space that no typical item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: penalize if post_residual can't fit the next item but is close to it
    // (wasted opportunity); reward if next item fits perfectly into post_residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let next_tightness = next_item_size as f64 / post_residual as f64;
            score -= 12.0 * next_tightness;
        } else {
            let gap = (next_item_size - post_residual) as f64;
            score += 0.15 * gap;
        }
    } else {
        // Last item: fill anything available.
        score -= 40.0;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate handling: opening a new bin is expensive when many bins are open
    // or early in the stream; make the empty bin slightly unattractive by default.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 8.0 + 10.0 * (1.0 - progress) + 0.5 * open_bins_count as f64;
        // But if mean residual across open bins is small (all bins nearly full),
        // a new bin becomes reasonable.
        score -= 0.3 * (bin_capacity as f64 - mean_residual);
    }

    // Mild preference for placing into bins with below-average residual
    // (consolidate fullness, keep larger residuals available).
    if bin_residual < bin_capacity {
        let diff = mean_residual - bin_residual as f64;
        score += 0.05 * diff;
    }

    // Slight reward for using more of the bin overall.
    score -= 0.1 * (bin_capacity - post_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (small post residual), with non-linear penalty growth
    let mut score = pr + 40.0 * norm_pr * norm_pr;

    // Smooth stream-progress coupling: tighten fit preference as stream progresses
    score *= 1.0 + 0.6 * progress * (1.0 - progress) * 4.0 * norm_pr;

    // Lookahead: reward bins whose post residual accommodates the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            let slack = (pr - nx) / cap;
            score -= 25.0 * (1.0 - slack * slack) * (1.0 - 0.5 * progress);
        } else {
            // penalize residuals that waste space relative to next item
            score += 8.0 * (nx - pr) / cap;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0 + 20.0 * (1.0 - progress);
    }

    // Mild penalty proportional to crowd of open bins with large mean residual
    score += 0.05 * open_bins_count as f64 * (mean_residual / cap).max(0.0);

    // New-bin candidate: neutral baseline with slight discouragement unless residuals are messy
    if bin_residual == bin_capacity {
        score = cap * (1.0 + 0.3 * progress) + 0.02 * open_bins_count as f64;
        if next_item_size > 0 && (next_item_size as f64) > mean_residual {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into small
    // "harmonic" residue classes (near-zero or near-capacity fractions) are
    // either perfect fits or dead space. Penalize dead space aggressively.
    let frac = post_residual as f64 / bin_capacity as f64;

    // Perfect fit: zero residual -> huge reward.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Dead-space penalty grows superlinearly for unusable leftovers.
        // Leftover < 10 (min item) is pure waste.
        if post_residual < 10 {
            score += 50.0;
        }
        // Harmonic class via integer division thresholds on post_residual.
        let class = post_residual / 10; // 0..9 classes
        match class {
            0 => score += 30.0,             // 1..9 : unusable
            1 => score -= 5.0,              // 10..19: fits tiny items
            2 => score -= 10.0,             // 20..29
            3 => score -= 12.0,             // 30..39
            4 => score -= 10.0,             // 40..49
            5 => score -= 6.0,              // 50..59
            6 => score += 4.0,              // 60..69: hard to fill
            7 => score += 10.0,
            8 => score += 18.0,
            _ => score += 25.0,             // 90+: nearly empty bin placement
        }
        // Modulo coupling: leftover that matches common item sizes (multiples
        // of 5/10) is reusable; odd leftovers are less useful.
        if post_residual % 10 == 0 {
            score -= 8.0;
        } else if post_residual % 5 == 0 {
            score -= 3.0;
        } else {
            score += 2.0;
        }
    }

    // Lookahead: if next item fits exactly into the post residual, reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // Reward proportionally to how well next item fills leftover.
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 20.0 * fill;
        } else {
            // Next item won't fit here: leftover likely dead -> penalize
            // proportionally to leftover size.
            score += frac * 15.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when no
    // open bin fits well. Base cost of opening a new bin:
    if bin_residual == bin_capacity {
        score = 55.0 + frac * 10.0;
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 25.0 * progress;
        // If many bins fit the item, opening a new one is wasteful.
        if fitting_bins_count > 0 {
            score += 30.0 * (fitting_bins_count as f64).min(5.0);
        }
        // If next item is large, a fresh bin is more valuable.
        if next_item_size >= 50 {
            score -= 20.0;
        }
    }

    // Mild preference for tighter bins (best-fit flavor) scaled by occupancy.
    score += frac * 5.0;

    // Tie-break with mean residual: placing into a bin below-average residual
    // (a fuller bin) is slightly favored.
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 3.0;
    }

    // Encourage packing into existing bins when many are open (fragmentation).
    score += (open_bins_count as f64).ln().max(0.0) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: heavily penalize small unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 60.0;
    } else if post_residual >= next_item_size as f64 && next_item_size > 0 {
        // Residual can host the next item: reward.
        score -= 15.0;
    }

    // Dead space relative to capacity: penalize wasted fraction.
    score += (post_residual as f64 / bin_capacity as f64) * 8.0;

    // Open bins pressure: discourage opening new bins when many are open.
    if bin_residual == bin_capacity {
        score += 6.0 + (open_bins_count as f64) * 0.8;
    } else {
        score -= 2.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Tight-fit reward: item fills most of the bin.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    if fill_ratio > 0.8 {
        score -= 10.0;
    }

    // Early stream: be more conservative about opening bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity && progress < 0.3 {
        score += 5.0;
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (low dead space).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // 2-step lookahead: reward if next item exactly fills the post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chain: bin fully consumed over two steps
        } else if next_item_size <= post_residual {
            // next item fits: reward proportionally to how well it uses leftover
            let fill = next_item_size as f64 / (post_residual as f64).max(1.0);
            score -= 25.0 * fill;
        } else {
            // next item won't fit here; penalize large unusable leftovers
            score += 0.15 * (post_residual as f64);
        }
    }

    // Relative-to-mean coupling: prefer bins with residual below mean (more filled bins).
    score += 0.5 * (bin_residual as f64 - mean_residual);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Penalize opening a new bin unless no good fit exists elsewhere.
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline penalty grows with number of open bins
        score += 20.0 + 2.0 * (open_bins_count as f64);
        // But if the item is large and would leave big fragmentation anywhere,
        // a fresh bin becomes attractive when item is huge relative to typical residual.
        if item_size as f64 > mean_residual + 20.0 && fitting_bins_count <= 1 {
            score -= 25.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 15.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = 0.0;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let pr = post_residual as f64 / bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let progress_sq = progress * progress;
    let progress_cb = progress_sq * progress;

    // Non-linear polynomial coupling: reward tight fits more strongly later in the stream.
    let tightness = 1.0 - pr;
    score -= (1.0 + 2.5 * progress_sq + 4.0 * progress_cb) * tightness * tightness * (item_size as f64);

    // Penalize residual that is small but not zero (dead space) with smooth quadratic term.
    if post_residual > 0 {
        let dead = pr * (1.0 - pr);
        score += 6.0 * dead * (1.0 + progress);
    }

    // Last-chance bonus: strongly favor the unique fitting bin.
    if fitting_bins_count == 1 {
        score -= 8.0 + 10.0 * progress_sq;
    }

    // Lookahead: reward bins whose post residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64 / bin_capacity as f64;
        score -= 3.0 * (1.0 - slack * slack) * (0.5 + 0.5 * progress);
    }

    // Mild penalty proportional to crowding of open bins.
    score += 0.05 * (open_bins_count as f64).ln().max(0.0);

    // New-bin candidate: prefer opening a new bin early or when fit is poor.
    if bin_residual == bin_capacity {
        let fit_quality = item_size as f64 / bin_capacity as f64;
        score -= 2.0 * (1.0 - fit_quality) * (1.0 - progress);
        score += 3.0 * progress_cb;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: modulo classes over capacity
    let pr = post_residual;
    let class = pr % 10;
    // Penalize residuals that fall in "dead" classes (too small to fit anything, 1..9)
    if pr > 0 && pr < 10 {
        score += 25.0; // unusable sliver
    } else if pr == 0 {
        score -= 15.0; // perfect closure
    } else {
        // fractional-capacity coupling: reward small post residuals quadratically
        score -= (1.0 - (pr as f64 / bin_capacity as f64)).powi(3) * 10.0;
        // modulo-10 class penalty: residuals congruent to small classes are less reusable
        score += (class as f64) * 0.4;
    }

    // Integer-division threshold: can this bin also fit the next item?
    if next_item_size > 0 {
        if pr >= next_item_size {
            score -= 12.0; // keeps lookahead feasible
            // extra harmony: post residual nearly exactly next item size
            let gap = pr - next_item_size;
            if gap < 5 {
                score -= 6.0;
            }
        } else {
            score += 4.0;
        }
    } else {
        // last item: strongly prefer closing bins
        score -= 20.0;
    }

    // Last-chance bin: this is the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: only attractive when item is large relative to capacity
    if bin_residual == bin_capacity {
        let frac = item_size as f64 / bin_capacity as f64;
        score = 100.0 - frac * 40.0;
        if next_item_size > pr.min(bin_residual) && next_item_size > 0 {
            score += 5.0;
        }
        // discourage spreading when many bins are already open and mean residual is healthy
        if mean_residual > item_size as f64 * 1.2 && open_bins_count > 2 {
            score += 15.0;
        }
    }

    // Progress coupling: later in stream, tighten packing (favor small post residuals more)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 3.0 + progress * (post_residual as f64) * 0.1;

    // Tight-fit reward: item nearly fills the bin
    if item_size as f64 / bin_residual as f64 > 0.9 {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // possible future item are "dead" — penalize them quadratically.
    let dead_threshold: f64 = 9.0; // nothing useful fits in <= 9 units
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * (dead_threshold - post_residual as f64) * 2.0;
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 25.0;
    }

    // Tight fit bonus: fraction of bin used by this placement
    let fill = item_size as f64 / bin_capacity as f64;
    score -= fill * 10.0;

    // If this bin is the ONLY bin that fits, strongly prefer using it
    // over opening a new bin (avoid wasting residual capacity).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if the next item fits in the post residual, reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // next item won't fit here; mild penalty for stranding space
        score += 3.0;
    }

    // Open-bin pressure: with many open bins, favor filling existing ones
    // (especially low-residual ones) rather than spreading out.
    if bin_residual != bin_capacity {
        score -= open_bins_count as f64 * 1.5;
    }

    // New-bin candidate handling: make an empty bin attractive only when
    // the item is large and no open bin offers a good fit.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let tightness = 1.0 - (mean_residual / bin_capacity as f64);
        // Penalize new bins normally...
        score += 15.0 + open_bins_count as f64 * 0.5;
        // ...but relax the penalty for large items late in the stream
        // when open bins are already tight.
        let large_item = (item_size as f64 / bin_capacity as f64) > 0.6;
        if large_item && tightness < 0.35 {
            score -= 20.0 * (1.0 - progress) + 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next_item_size -> strong reward.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 60.0 * (1.0 / (1.0 + diff * 0.15));
        // Bonus if next item fits exactly after this placement.
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // Penalize if next item will NOT fit in the resulting residual.
        if post_residual < next_item_size && post_residual > 0 {
            score += 12.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Prefer bins whose residual is below mean (tighter bins get filled first).
    score -= 0.8 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Penalize creating small dead space (< 10, unusable for items >= 1... keep moderate).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // New-bin candidate: only attractive when no good fit exists (high mean residual waste).
    if bin_residual == bin_capacity {
        score += 30.0;
        if fitting_bins_count == 1 && next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
    }

    // Early in stream, slightly prefer consolidating into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 5.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual).
    let tight = (bin_residual - post_residual) as f64 / bin_capacity as f64;
    score -= 12.0 * tight * tight;

    // Penalize very small post_residual only if it's not zero (dead space trade-off):
    // zero residual is perfect; tiny residuals (1..=5) are also great.
    if post_residual == 0 {
        score -= 20.0;
    } else if post_residual <= 5 {
        score -= 8.0;
    } else if post_residual < 10 {
        score -= 3.0;
    } else {
        // Larger leftover: mild penalty growing with dead space.
        score += (post_residual as f64 - 10.0) * 0.15;
    }

    // Lookahead: if the next item fits in post_residual, reward this bin (chaining).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 10.0 + 0.1 * next_item_size as f64;
        } else if next_item_size == post_residual {
            score -= 15.0;
        } else {
            // Next item won't fit here: small penalty for wasting space the chain could use.
            score += 2.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin, more so when open bins exist
    // and mean residual is large enough to absorb the item.
    if bin_residual == bin_capacity {
        let load_frac = item_size as f64 / bin_capacity as f64;
        let mut penalty = 18.0;
        if open_bins_count > 0 {
            penalty += mean_residual.min(item_size as f64) * 0.5;
            // If mean residual across open bins is large, opening new bins is wasteful.
            if mean_residual > item_size as f64 {
                penalty += 10.0;
            }
        }
        // Early in stream, opening bins is cheaper (bins get consolidated later).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        penalty *= 1.0 - 0.3 * progress;
        // Large items relative to capacity are fine to start fresh.
        penalty -= 6.0 * load_frac;
        score += penalty.max(0.0);
    }

    // Prefer filling bins that are already heavily loaded (fewer partially filled bins).
    let used = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 6.0 * used;

    // Mild penalty for spreading across many open bins when a tighter option exists.
    score += 0.05 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: penalize residual, weighted by smooth progress coupling
    let mut score = pr * (1.0 + 0.6 * progress * norm_pr);

    // Non-linear quadratic/cubic coupling of normalized post-residual with progress
    score += 12.0 * norm_pr * norm_pr * (0.5 + progress);
    score -= 8.0 * norm_pr * norm_pr * norm_pr * (1.0 - progress);

    // Reward tight fits (small post_residual) more strongly later in the stream
    score -= (1.0 - norm_pr).powi(3) * 10.0 * (0.4 + 0.6 * progress);

    // Last-chance bin: strong reward to use it
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - norm_pr);
    }

    // Lookahead: reward if next item fits into resulting post_residual
    if next_item_size > 0 && post_residual >= next_item_size {
        let fit_quality = next_item_size as f64 / (pr + 1.0);
        score -= 15.0 * fit_quality * (1.0 - fit_quality);
    } else if next_item_size > 0 {
        // next item cannot fit here: mild penalty scaled by dead space
        score += 4.0 * norm_pr * (1.0 - progress);
    }

    // Mean residual coupling: prefer bins close to mean residual (keeps flexibility)
    let dev = (pr - mean_residual) / cap;
    score += 5.0 * dev * dev * (1.0 - progress);

    // Slight preference for opening new bins when many open bins have low mean residual
    if bin_residual == bin_capacity {
        score += 3.0 + 2.0 * progress;
        if mean_residual < 15.0 {
            score -= 6.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: perfect fits (residual 0) are golden.
    if post_residual == 0 {
        score -= 500.0;
    } else {
        // Penalize residuals that are "dead" — too small for any plausible future item (1..=100 range).
        if post_residual < 5 {
            score += 60.0 * (5 - post_residual) as f64;
        }
        // Modulo arithmetic on post_residual: residuals that are multiples of common
        // item granularity (e.g. multiples of 10) are reusable, reward them.
        if post_residual % 10 == 0 {
            score -= 25.0;
        }
        if post_residual % 25 == 0 {
            score -= 15.0;
        }
        // Integer-division class: post_residual / item_size ratio — how many copies
        // of the current item would still fit. Higher reuse = better bin.
        let copies = post_residual / item_size.max(1);
        score -= 8.0 * copies.min(5) as f64;
    }

    // Lookahead coupling: if the next item fits exactly into the post residual,
    // this placement sets up a perfect follow-up — strong reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 120.0;
        } else if post_residual > next_item_size {
            let gap = post_residual - next_item_size;
            score -= 30.0;
            if gap % 10 == 0 {
                score -= 10.0;
            }
            if gap < 5 {
                score += 20.0; // near-dead leftover after next placement
            }
        } else {
            // Next item cannot use this residual: penalize proportional to wasted potential.
            let unusable = (next_item_size - post_residual) as f64;
            score += 0.15 * unusable.min(80.0);
        }
    }

    // Last-chance bin: if this is the only open bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: penalize opening a fresh bin when decent fits exist,
    // but allow it if all open bins would leave tiny dead space.
    if bin_residual == bin_capacity {
        let tight_fit_exists = fitting_bins_count > 0 && (item_size as f64 / bin_capacity as f64) > 0.0
            && mean_residual < item_size as f64 + 8.0;
        if tight_fit_exists {
            score += 200.0;
        } else {
            score += 90.0 - 2.0 * open_bins_count.min(20) as f64;
        }
    }

    // Mean residual context: prefer bins with residuals below the mean (tight packing),
    // penalize dumping into already-loose bins.
    let dev = mean_residual - bin_residual as f64;
    score += 0.3 * dev.max(0.0) - 0.1 * dev.min(0.0).abs();

    // Stream progression: late in the stream, be greedier about tight fits.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 20.0 * progress * (bin_capacity - post_residual) as f64 / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    let min_useful = 10u32;
    if post_residual > 0 && post_residual < min_useful {
        score += 60.0;
    } else if post_residual == 0 {
        // Perfect fit is highly desirable.
        score -= 40.0;
    }

    // Non-linear penalty on wasted fraction of the bin.
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += 15.0 * waste_frac * waste_frac;

    // Reward tight fits (small post residual relative to item size).
    if item_size > 0 {
        let tightness = post_residual as f64 / item_size as f64;
        score += 8.0 * tightness;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new ones
    // (new-bin candidate has bin_residual == bin_capacity).
    if bin_residual == bin_capacity {
        score += 12.0 + 3.0 * open_bins_count as f64;
    }

    // Lookahead: if next item fits into the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Post residual too small for the known next item: dead space penalty.
        score += 10.0;
    }

    // Mean residual coupling: prefer bins whose residual is below average
    // (consolidate space into fewer bins).
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    } else {
        score += 4.0;
    }

    // Slight preference to fill older/more filled bins as the stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * waste_frac;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item nearly fills the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 14.0 * fit_ratio * fit_ratio;

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Penalize leaving dead space that is too small for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 18.0;
    }

    // Lookahead: reward bins whose post-residual can still host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0 + 0.1 * next_item_size as f64;
    } else if next_item_size > 0 {
        // Post-residual useless for next item: mild penalty scaled by remaining stream.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 4.0 * (1.0 - progress);
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Compare against global mean residual: placing into a below-average-residual
    // bin (tighter bin) is preferable; above-average (loose) bins slightly penalized.
    score += 0.5 * (mean_residual - bin_residual as f64);

    // New-bin candidate handling: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let poor_fit = fitting_bins_count == 0
            || (bin_residual - item_size) as f64 > mean_residual.max(1.0);
        if poor_fit {
            score -= 20.0;
        } else {
            // Opening a new bin when good fits exist wastes capacity.
            score += 30.0 + 2.0 * open_bins_count as f64;
        }
    }

    // Mild pressure to consolidate into fewer bins as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let prn = pr / cap;

    // Base: post residual, with non-linear penalty for medium dead space
    let mut score = pr;

    // Smooth polynomial coupling of residual with stream progress:
    // early on, large residuals are fine (bins still fillable);
    // late in the stream, penalize leftover space more strongly.
    let dead_penalty = prn * prn * (1.0 - prn);
    score += 30.0 * dead_penalty * (0.4 + 1.2 * progress);

    // Reward tight fits: subtract a smooth function of small post residual
    let tightness = (1.0 - prn).powi(3);
    score -= 12.0 * tightness * (1.0 - progress);

    // Perfect / near-perfect fit gets a strong smooth reward
    if pr <= 2 {
        score -= 25.0 * (1.0 - progress);
    }

    // Lookahead coupling: if next item fits the post residual, reward this placement
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let fill_ratio = nxt / pr.max(1.0);
            score -= 15.0 * fill_ratio * (1.0 - fill_ratio) * 4.0;
        } else {
            // post residual too small for the next item: mild penalty
            score += 6.0 * (nxt - pr) / cap;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Many open bins: prefer consolidating into existing bins over new ones
    let bin_pressure = open_bins_count as f64 / (1.0 + open_bins_count as f64);
    score += 5.0 * bin_pressure * (prn - mean_residual / cap.max(1.0)).abs();

    // Slight preference for fuller bins overall
    score -= 4.0 * (1.0 - prn);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of post_residual: how "usable" is the leftover space? ---
    // Class 0: residual divisible by 10 (harmonizes with typical item sizes) -> reward.
    let class = post_residual % 10;
    if class == 0 {
        score -= 4.0;
    } else if class >= 5 {
        score += (class as f64) * 0.6; // awkward leftover, penalize
    } else {
        score += (class as f64) * 0.25;
    }

    // Perfect fit is always excellent.
    if post_residual == 0 {
        score -= 30.0;
    }

    // --- Integer-division thresholds on post_residual ---
    // Leftovers below the minimum item size (assume ~1..100, but tiny slivers are dead space)
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // nearly dead space
    }
    // Mid-range leftovers (10..=30) are highly reusable
    if post_residual >= 10 && post_residual <= 30 {
        score -= 6.0;
    }

    // --- Lookahead coupling: can the next item fit into post_residual? ---
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Great: chain placement possible; reward proportional to tightness of the chain
            let chain_tightness = (post_residual - next_item_size) as f64;
            score -= 8.0 + chain_tightness * 0.1;
            // Harmonic bonus if next item also lands on a divisible residual
            if (post_residual - next_item_size) % 10 == 0 {
                score -= 3.0;
            }
        } else if post_residual > 0 {
            // Next item won't fit here: leftover risk depends on how small it is
            score += (next_item_size as f64) * 0.05;
        }
    } else {
        // Last item: prefer tightest packing, opening a bin is terrible
        score += 5.0;
    }

    // --- Last-chance bin: if this is the only bin that fits, strongly favor using it ---
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when existing residuals are bad
        // (high mean residual spread / many awkward bins) or many bins already open.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let penalty = 12.0
            + mean_residual * 0.15
            + (open_bins_count as f64) * 0.4
            + progress * 5.0;
        score += penalty;
        // A new bin is decent if the item is large relative to capacity
        if item_size > bin_capacity / 2 {
            score -= 6.0;
        }
    }

    // --- Prefer filling bins that are already relatively full ---
    let fill_ratio = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= fill_ratio * 5.0;

    // Slight preference against spreading across too many open bins
    score += (open_bins_count as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // smallest plausible item (1..=9) are pure waste -> heavy penalty.
    if post_residual >= 1 && post_residual <= 9 {
        score += 60.0 + (10 - post_residual) as f64 * 8.0;
    }
    // Medium dead space (10..=19) is partially unusable too.
    else if post_residual >= 10 && post_residual <= 19 {
        score += 12.0 + (20 - post_residual) as f64 * 1.5;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 25.0;

    // Perfect fill is ideal.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last chance bin: strongly favor using it instead of opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bins pressure: when many bins are open, discourage opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.6 + 0.8 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline slightly above using an existing decent bin,
        // but reduced when existing residuals are large/wasteful.
        score = bin_capacity as f64 - 5.0 + pressure
            + (mean_residual - post_residual as f64).max(0.0) * 0.3;
        // If next item is large and this fresh bin gives it a home, mild bonus.
        if next_item_size > bin_capacity / 2 {
            score -= 8.0;
        }
    } else {
        // Favor bins whose residual is close to the item (best-fit flavor).
        score += (bin_residual as f64 - item_size as f64) * 0.4;
        // Lookahead: if the next item fits the post-residual exactly-ish, reward.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        } else if next_item_size > post_residual as u32 && post_residual > 0 {
            score += 5.0;
        }
        // Mild penalty for spreading across many bins when residuals are similar.
        score += mean_residual * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs();
        if diff == 0 {
            score -= 60.0; // chain a second item perfectly
        } else {
            // Penalize leftover space that cannot host the next item.
            if post_residual < next_item_size {
                score += (next_item_size - post_residual) as f64 * 0.35;
            } else {
                // Larger slack than next item: mild penalty growing with slack.
                score += diff as f64 * 0.08;
            }
        }
    } else {
        // Last item: strongly prefer tightest fit.
        score += (bin_capacity as f64 - post_residual as f64) * 0.5;
    }

    // Reward using a bin whose residual is already small (tight packing).
    if (bin_residual as f64) < mean_residual {
        score -= (mean_residual - bin_residual as f64) * 0.25;
    } else {
        score += (bin_residual as f64 - mean_residual as f64) * 0.15;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: prefer keeping item in an existing bin unless fit is bad.
    if bin_residual == bin_capacity {
        // Penalize opening new bins, more so as stream progresses and bins exist.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 30.0 + 40.0 * progress;
        // But if next item is large and current bins are fragmented, opening is ok.
        if next_item_size > 0 && next_item_size as f64 > mean_residual {
            score -= 20.0;
        }
    }

    // Slight bonus for filling bins that are nearly full.
    let fill = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 0.91;
