pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let item = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: raw waste, with slight discount as stream progresses (commit to open bins late).
    let mut score = pr * (1.0 - 0.35 * progress);

    // Non-linear polynomial coupling of post_residual with capacity fraction.
    let x = pr / cap;
    score += 18.0 * x * x * (1.0 - x) * cap * 0.1;
    score -= 12.0 * x * (1.0 - x) * (1.0 - progress);

    // Reward tight fits: small post_residual relative to item.
    if item > 0.0 {
        score -= 20.0 * (1.0 - pr / (pr + item)).powi(2);
    }

    // Penalize bins deviating from mean residual (smooth quadratic coupling).
    let dev = pr - mean_residual;
    score += 0.05 * dev * dev / (mean_residual.abs() + 1.0);

    // Last-chance bin: strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if next item fits post_residual, reward; else penalize mildly.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            score -= 10.0 * (1.0 - (pr - nx) / cap);
        } else {
            score += 4.0 * (nx - pr) / cap;
        }
    }

    // New-bin candidate: baseline with mild stream-dependent penalty.
    if bin_residual == bin_capacity {
        score = cap * (0.55 + 0.35 * progress) + 3.0 * (open_bins_count as f64).sqrt();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: integer division into bands of 10
    let post_class = post_residual / 10;
    // Reward tight fits: lower post_residual class preferred (already via base), add non-linear bonus
    score -= (10 - post_class.min(10)) as f64 * 2.0;

    // Penalize dead space in low harmonic classes (small unusable residues)
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Modulo coupling: residues that pair with common item sizes (mod 10) are more usable
    let mod_class = post_residual % 10;
    if mod_class == 0 {
        score -= 5.0; // residue divisible by 10 is highly reusable
    } else if mod_class >= 5 {
        score -= 2.0;
    }

    // Lookahead: check if next item fits exactly into post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0; // perfect chain fit
        } else if next_item_size <= post_residual {
            score -= 8.0; // next item still fits
        } else {
            score += 5.0; // next item won't fit here -> bin closes
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fits are terrible
    if bin_residual == bin_capacity {
        score += 25.0;
        // But if mean residual across open bins is very low and stream is early, opening fresh can help
        let progress = step_index as f64 / total_items.max(1) as f64;
        if mean_residual < 12.0 && open_bins_count > 0 && progress < 0.7 {
            score -= 35.0;
        }
    }

    // Mild pressure toward consolidating when many bins are open
    score += open_bins_count as f64 * 0.05;

    // Fraction-of-capacity coupling on item size
    let frac = item_size as f64 / bin_capacity as f64;
    score -= frac * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small nonzero gaps are the worst outcome.
    // A residual that no future item (min size 1) can use is pure waste, but
    // tiny residuals (1..=9) are especially toxic since typical items are >=10.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + 6.0 * (10 - post_residual) as f64; // gap of 1 is worse than gap of 9
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Coupling with open_bins_count pressure: when many bins are open,
    // consolidating into existing bins matters more; penalize opening new bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let bin_pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: accept it only when existing bins would leave bad gaps.
        score += 15.0 + bin_pressure;
        if post_residual >= 10 || post_residual == 0 {
            score -= 10.0; // fresh bin keeps large usable residual
        }
    } else {
        // Fitting into an existing bin is generally good; extra bonus when it's
        // the last chance (fitting_bins_count == 1) to avoid opening a bin.
        if fitting_bins_count == 1 {
            score -= 30.0;
        }
        // Prefer bins whose residual is close to being consumed (tight packing).
        score -= 0.3 * (bin_capacity as f64 - bin_residual as f64);
    }

    // Lookahead: if the next item fits exactly into the post_residual, reward heavily.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 70.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0;
    }

    // Mean-residual coupling: placing into a bin with below-average residual
    // (i.e., an already full-ish bin) is preferred to keep large gaps elsewhere.
    let bin_res_f = bin_residual as f64;
    if mean_residual > 0.0 && bin_res_f < mean_residual {
        score -= 0.5 * (mean_residual - bin_res_f);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Aggressive 2-step lookahead: reward when next item fits the post residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 12.0 * (1.0 - slack / (bin_capacity as f64));
    } else if next_item_size > post_residual {
        // Penalize leaving a residual that the next item cannot use,
        // scaled by how badly it misses.
        let miss = (next_item_size - post_residual) as f64;
        score += 0.35 * miss.min(40.0);
    }

    // Exact match of post_residual to next item is a jackpot.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 15.0;
    }

    // Compare post_residual against mean residual: avoid fragmenting when
    // this bin's leftover is far below the average usable space.
    let res_f = post_residual as f64;
    if mean_residual > 0.0 {
        let ratio = res_f / mean_residual;
        if ratio < 0.5 {
            score += 8.0 * (0.5 - ratio);
        } else if ratio > 1.5 {
            score -= 4.0 * (ratio - 1.5).min(2.0);
        }
    }

    // Last chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Prefer denser packing when many bins are open.
    if open_bins_count > 4 {
        score -= 1.5 * (open_bins_count as f64).ln();
    }

    // Early in the stream, be more willing to keep bins compact;
    // later, prioritize closing bins out (small post_residual).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 6.0 * (1.0 - progress) * (res_f / bin_capacity as f64);

    // New-bin candidate: make it moderately attractive only when nothing
    // fits well (its post_residual equals capacity - item_size, a mid value).
    if bin_residual == bin_capacity {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (nonlinear).
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 60.0 * tight * tight;

    // Penalize small dead space that is hard to reuse (post_residual < typical small item).
    if post_residual > 0 && post_residual < 12 {
        score += 18.0;
    }

    // Lookahead: if next item fits into post_residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 25.0;
        // extra reward for near-exact chain fit
        let chain_gap = post_residual as f64 - next_item_size as f64;
        if chain_gap < 10.0 {
            score -= 12.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual && next_item_size <= bin_capacity {
        // next item won't fit here after placement; slight penalty unless this bin is nearly full
        if post_residual < 20 {
            score -= 4.0;
        } else {
            score += 6.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: prefer new bin only when item is large and few bins fit.
    if bin_residual == bin_capacity {
        // base cost of opening a bin
        score += 45.0;
        // large items pack better in fresh bins
        if item_size > 50 {
            score -= 20.0;
        }
        if fitting_bins_count == 1 {
            score += 25.0; // keep existing last-chance bin attractive
        }
        // late in stream, prefer closing out open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
        // many open bins with high mean residual: new bin less attractive
        score += 2.0 * (open_bins_count as f64).sqrt();
        if mean_residual > item_size as f64 {
            score += 10.0;
        }
    }

    // Prefer bins with residual close to mean (balanced packing) mildly.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Slight bonus for filling bins as stream progresses (reduce open-bin count).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Base: tight fit preferred (small post_residual), with non-linear polynomial coupling
    let mut score = pr * (1.0 + 0.8 * progress * progress);

    // Strong reward for very small residuals (near-perfect fit), smooth via cubic term
    let tightness = 1.0 - (pr / cap);
    score -= 25.0 * tightness * tightness * tightness;

    // Penalize residuals that are too small to fit typical future items (dead space)
    let min_future = if next_item_size > 0 { next_item_size.min(100) as f64 } else { 10.0 };
    if pr < min_future {
        score += (min_future - pr) * (1.5 + progress);
    } else {
        // Reward residuals that can still host the lookahead item
        score -= 2.0 * (1.0 - pr / cap);
    }

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0 + 30.0 * progress;
    }

    // New-bin candidate handling: mildly penalize opening new bins early,
    // but allow it when open bins are fragmented (high mean residual spread)
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - pr).abs();
        score += 15.0 - 10.0 * progress + 0.1 * open_bins_count as f64;
        // If no open bin fits well, opening a new bin is attractive
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
        if fragmentation > 30.0 {
            score -= 5.0;
        }
    }

    // Prefer bins whose residual deviates from the mean in a useful way (large residual used well)
    score -= 0.05 * (bin_residual as f64 - mean_residual) * (1.0 - progress);

    // Mild penalty for spreading across many bins
    score += 0.02 * open_bins_count as f64 * (0.5 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how "clean" the leftover space is.
    // Residuals that are exact fractions of capacity (50, 25, 20, 10) are reusable.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Reward residuals that divide capacity evenly (harmonic fractions)
    if post_residual > 0 && bin_capacity % post_residual == 0 {
        score -= 12.0 * (post_residual as f64 / cap);
    }
    // Penalize odd residuals that don't divide capacity (likely dead space)
    if post_residual > 0 && bin_capacity % post_residual != 0 {
        score += 4.0 * (1.0 - pr / cap);
    }

    // Modulo classes on post_residual relative to common item sizes (10..80 grid)
    let m = post_residual % 10;
    if m != 0 {
        score += 2.0 + 0.1 * m as f64; // off-grid leftovers are harder to fill
    } else {
        score -= 3.0; // on-grid residuals align with typical item sizes
    }

    // Perfect fit: huge reward
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead coupling: if next item fits exactly in the post residual, reward
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // Harmonic bonus if slack is a nice fraction
            if slack > 0.0 && bin_capacity as u32 % (slack as u32) == 0 {
                score -= 6.0;
            }
            score += 0.05 * slack;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless residuals elsewhere are large
    if bin_residual == bin_capacity {
        score += 25.0 + 0.3 * mean_residual;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // reserving a fresh bin for a big next item can help
        }
    }

    // Tight-fit reward: prefer bins where the item fills most of the residual
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 8.0 * fill_ratio * fill_ratio;

    // Late-stream consolidation: prefer tighter bins as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 0.15 * pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to ever hold
    // anything (min item size 1, but tiny gaps < 8 are near-worthless)
    // are heavily penalized with a non-linear surge.
    let gap = post_residual as f64;
    if gap > 0.0 && gap < 8.0 {
        score += 40.0 * (8.0 - gap) / 8.0;
    }
    // Penalize "awkward" gaps that few realistic items can fill.
    if gap > 0.0 && gap < 20.0 {
        score += 6.0 * (20.0 - gap) / 20.0;
    }

    // Reward perfect / near-perfect fits.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Lookahead coupling: if the next item fits in the post residual,
    // reward this placement (creates useful future capacity).
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 12.0 - 0.4 * slack.min(30.0);
    } else if next_item_size > 0 {
        // Next item won't fit here: slight penalty proportional to gap.
        score += 2.0;
    }

    // Open-bin pressure: discourage spreading across many bins when
    // mean residual is already healthy; encourage consolidation.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (1.0 - progress) * 0.05;
    score += pressure;

    // Last-chance bin: strongly favor using the only bin that fits,
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: neutral baseline, slightly worse than a good
    // existing fit, better than a bad fit. Penalize opening bins early
    // in the stream when consolidation is still possible.
    if bin_residual == bin_capacity {
        score += 10.0 + 20.0 * (1.0 - progress);
        // If no open bin fits well, allow new bin more readily.
        if fitting_bins_count == 0 {
            score -= 8.0;
        }
    }

    // Prefer bins whose residual is close to mean (balanced packing),
    // slightly penalizing outliers.
    score += 0.02 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual equals next item size -> huge reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }
    // Near match: next item still fits in the residual.
    else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 50.0 + (post_residual - next_item_size) as f64 * 0.3;
    }
    // Next item does NOT fit residual: penalize leftover that becomes dead space.
    else if next_item_size > 0 {
        score += 30.0 + post_residual as f64 * 0.5;
    }

    // Reward tight fits overall (small post_residual relative to capacity).
    score -= (bin_capacity - post_residual) as f64 * 0.2;

    // Compare against mean residual: leaving less than average is good.
    score += (post_residual as f64 - mean_residual) * 0.4;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Prefer filling existing bins over opening new ones, especially late in stream.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += 60.0 + 100.0 * progress;
    } else {
        score -= 10.0 + 20.0 * progress;
    }

    // Bonus if this placement keeps bin nearly full.
    if post_residual < 10 {
        score -= 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fills
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 5 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    }

    // Lookahead: favor bins whose leftover can host the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0 + 0.2 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // penalize dead space the next item cannot use
        score += 0.5 * post_residual as f64;
    }

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // Prefer fuller bins relative to mean residual of open bins
    score += (mean_residual - bin_residual as f64) * 0.6;

    // Penalize opening a new bin, more so late in the stream
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 40.0 + 60.0 * progress + 2.0 * open_bins_count as f64;
    }

    // Mild consolidation pressure: fewer open bins is better
    score += 0.05 * open_bins_count as f64;

