}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Core: quadratic penalty on waste, sharpened by stream progress
    let mut score = pr + 0.035 * pr * pr / cap;

    // Smooth non-linear coupling: waste hurts more as the stream progresses
    score += 0.9 * (pr / cap) * (pr / cap) * progress * (1.0 - 0.5 * progress);

    // Perfect-fit reward (smooth, no hard cutoff)
    let tightness = 1.0 - pr / cap;
    score -= 2.5 * tightness * tightness * tightness;

    // Lookahead: bonus if the residual can host the next item (smooth kernel)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = pr - nxt;
        if gap >= 0.0 {
            let k = gap / cap;
            score -= 1.2 * (1.0 - k * k);
        } else {
            // residual too small for next item: penalize proportionally
            score += 0.8 * (-gap / cap) * (1.0 + progress);
        }
    }

    // Last-chance bin: strong reward to use the only fitting bin
    if fitting_bins_count == 1 {
        score -= 3.0;
    }

    // New-bin candidate: penalize opening a bin unless item is large / waste would be big elsewhere
    if bin_residual == bin_capacity {
        let openness = 1.0 - it / cap;
        score += 4.0 + 3.0 * openness * openness - 2.0 * progress;
        // if many bins already open, slightly discourage more
        score += 0.05 * open_bins_count as f64;
    }

    // Mild preference toward bins below mean residual (consolidating slack)
    score += 0.15 * ((mean_residual - bin_residual as f64) / cap).clamp(-1.0, 1.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
