    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 45.0;
    } else if post_residual <= 10 {
        score -= 20.0;
    }

    // Modulo-10 harmonic band: residuals that are multiples of 10 are reusable
    // by the common item-size classes (multiples of 10).
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 12.0;
    }

    // Integer-division thresholds on post_residual: penalize dead zones.
    let dead = post_residual / 10; // coarse class 0..10
    if dead == 0 && post_residual > 0 {
        score += 8.0; // tiny sliver 1..9 mostly unusable
    }
    if dead >= 4 && dead <= 7 {
