            let pair = post_residual - next_item_size;
            if pair % 10 == 0 {
                score -= 25.0;
            } else {
                score -= 12.0;
            }
        } else if next_item_size <= bin_residual && item_size + next_item_size <= bin_capacity {
            // pair fits in bin jointly (already covered) small bonus
            score -= 3.0;
        } else {
            // next item won't fit here after placement: penalize unless
