        score += progress * 15.0;
        // Many open bins: discourage opening more.
        score += open_bins_count as f64 * 2.5;
        // If next item is large and current bin would be nearly emptied, new bin is fine.
        if next_item_size >= 60 && item_size >= 60 {
            score -= 10.0;
        }
    }

    // Mean-residual coupling: if this bin's residual is far below mean, it is a
    // tight bin; reward using it to close it out.
    let dev = mean_residual - bin_residual as f64;
    if dev > 0.0 {
        score -= dev * 0.3;
    } else {
        score += (-dev) * 0.15;
    }

    // Fractional harmonic refinement on post_residual classes (quarters of capacity).
    if frac <= 0.25 && post_residual > 0 {
        score -= 5.0;
    } else if frac >= 0.5 && frac < 0.75 {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals in (0, 10) are unusable since
    // minimum item size is ~10; treat them as fully wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10.0 - post_residual as f64);
    } else if post_residual == 0 {
        // Perfect closure is highly desirable.
        score -= 25.0;
    }

    // Reward tight fits: fraction of residual consumed.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * fit_ratio;

    // Pressure from number of open bins: discourage spreading when many bins open.
    score += 0.6 * open_bins_count as f64;

    // If this bin is the only fitting bin, strongly favor using it (last chance).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are crowded
    // or would leave dead space.
    if bin_residual == bin_capacity {
        score += 55.0;
        if open_bins_count == 0 {
            score -= 60.0; // must open a bin
        }
        // If lookahead item would fit in a fresh bin's future residual, slightly soften.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 12.0;
        }
    }

    // Lookahead synergy: prefer bins where post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }
    // Penalize leaving a residual just below the next item (near-dead gap).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < 10 {
        score += 10.0;
    }

    // Mean residual coupling: when mean residual is high, prefer tightening fat bins.
    score -= 0.15 * (mean_residual - post_residual as f64);

    // Early stream: slightly prefer reusing bins to keep bin count low.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * (1.0 - progress) * (open_bins_count as f64 / 10.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Tight fit reward (small dead space proportionally cheap).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 2.0 * tightness;

    // 2-step lookahead: reward if the next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size < post_residual {
            // Next item fits: mildly good, penalize leftover after the next placement.
            let post2 = post_residual - next_item_size;
            score += 0.5 * post2 as f64;
            if post2 == 0 {
                score -= 150.0;
            }
        } else {
            // Next item won't fit here: this bin becomes dead space; penalize.
            score += 0.8 * post_residual as f64;
        }
    }

    // Relative to mean residual: prefer bins tighter than average.
    score += 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate: penalize so we only open a new bin when open bins fit badly.
    if bin_residual == bin_capacity {
        score += 120.0 + 0.5 * item_size as f64;
        // If the item is large relative to capacity, opening fresh is less bad.
        if item_size as f64 > 0.7 * bin_capacity as f64 {
            score -= 100.0;
        }
    }

    // Late in the stream: consolidate harder, avoid opening bins.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += 50.0 * progress;
    } else {
        score -= 30.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post-residual) non-linearly.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize creating tiny dead space that nothing can use later.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward;
    // if this placement wastes space the next item could have used, penalize.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            score -= 6.0;
        } else if next_item_size <= bin_residual && post_residual < next_item_size {
            // this placement destroys a slot usable by the next item
            score += 10.0;
        }
    }

    // New-bin candidate handling: opening a new bin is generally bad unless
    // no open bin fits well. Make the empty bin attractive only when the
    // item is large relative to capacity or fits poorly elsewhere.
    if bin_residual == bin_capacity {
        let pressure = item_size as f64 / bin_capacity as f64;
        let crowded = open_bins_count as f64 / (step_index as f64 + 1.0).max(1.0);
        // default mild penalty so existing bins win ties
        score += 15.0;
        // if the item is big or many bins exist relative to progress, allow new bin
        score -= 20.0 * pressure * (1.0 + crowded);
        // if the mean residual of open bins is small (they are all nearly full),
        // opening a new bin is reasonable
        score -= mean_residual * 0.3;
    }

    // Mild reward for filling bins that are already mostly consumed.
    let used_fraction = 1.0 - bin_residual as f64 / bin_capacity as f64;
    score -= 5.0 * used_fraction;

    // Late in the stream, prefer consolidation into few bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 4.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early stream: mild tightening. Late stream: strong tightening to close bins.
    let p2 = progress * progress;
    let p3 = p2 * progress;
    let tighten = 0.8 * p2 + 1.5 * p3;
    score -= tighten * (cap - pr).max(0.0) * (pr / cap);

    // Penalize wasted residual relative to mean residual of open bins (smooth quadratic).
    let waste = pr - mean_residual.max(0.0);
    score += 0.05 * waste * waste / cap;

    // Reward filling a bin nearly perfectly: cubic bonus in fill fraction.
    let fill = 1.0 - pr / cap;
    score -= 10.0 * fill * fill * fill;

    // Last-chance bin: strong reward to avoid opening a new bin needlessly.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 6.0 * (1.0 + progress);
    }

    // Lookahead: penalize leaving residual just below next item size (dead space),
    // reward residual that exactly accommodates the next item.
    if next_item_size > 0 && next_item_size <= bin_capacity {
        let n = next_item_size as f64;
        if pr >= n {
            let slack = pr - n;
            score -= 3.0 * (1.0 - slack / cap) * (0.5 + 0.5 * progress);
        } else {
            let gap = n - pr;
            score += 0.15 * gap * gap / cap;
        }
    }

    // New-bin candidate: penalize opening a bin unless it's genuinely better
    // than any fit; penalty eases as stream progresses and bins fragment.
    if bin_residual == bin_capacity {
        let base = 8.0 + 4.0 * (1.0 - progress);
        let frag = if open_bins_count > 0 { mean_residual / cap } else { 1.0 };
        score += base * (0.4 + 0.6 * frag);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: modulo arithmetic on capacity fractions
    let pr = post_residual as u32;
    let class = pr % 10; // residue class mod 10
    // Residues that are "useful" for typical item sizes (multiples of 5/10 align with common sizes)
    let class_bonus: f64 = match class {
        0 => 18.0,  // perfectly aligned residual
        5 => 10.0,  // half-aligned
        2 | 4 | 6 | 8 => 4.0,
        _ => 0.0,
    };
    score -= class_bonus;

    // Integer-division threshold: how many "unit slots" of 10 fit in post residual
    let slots = pr / 10;
    score -= (slots as f64) * 3.0;

    // Coupling with next item: reward if next item fits exactly or nearly in post residual
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 25.0; // perfect chained fit
        } else if next_item_size <= pr {
            let gap = pr - next_item_size;
            score -= 12.0 * (1.0 - gap as f64 / 20.0).max(0.0);
        } else {
            // next item cannot fit here; penalize small unusable leftovers
            if pr < 10 {
                score += 15.0; // dead space
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Prefer filling bins below mean residual (tighter bins first)
    let res_frac = post_residual as f64 / cap;
    score += 8.0 * (res_frac - mean_residual / cap);

    // New-bin candidate handling: only attractive early in the stream or when
    // post_residual class is poor and item would leave big waste elsewhere
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // Opening a new bin: penalize more as stream progresses and when open bins exist
        score += 30.0 + 40.0 * progress + 2.0 * open_bins_count as f64;
        // But if current bin fit is terrible (large post residual in bad class), allow opening
        if pr > 40 && class > 5 {
            score -= 35.0;
        }
        if next_item_size > 0 && next_item_size > pr && pr < 15 {
            score -= 25.0; // current placement would strand next item
        }
    }

    // Slight preference to keep few bins open when residuals are large
    score -= (mean_residual / cap) * (open_bins_count as f64).ln().max(0.0) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A residual that is too small to ever hold a plausible future item is "dead".
    let min_item = 1u32;
    if post_residual < min_item {
        // perfect fit, zero waste -> strong reward
        score -= 50.0;
    } else if post_residual <= 10 {
        // tiny gap, likely dead space -> strong penalty
        score += 40.0 + (10 - post_residual) as f64 * 3.0;
    } else {
        // smooth dead-space curve: penalize residuals that are small but nonzero
        let r = post_residual as f64;
        score += 12.0 * (-(r / 25.0)).exp();
    }

    // Reward tight fits: the smaller the waste relative to item, the better.
    let waste_ratio = post_residual as f64 / bin_capacity as f64;
    score -= 30.0 * (1.0 - waste_ratio);

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage opening yet another one.
    let new_bin = bin_residual == bin_capacity;
    if new_bin {
        let pressure = 6.0 * (open_bins_count as f64).ln().max(0.0);
        score += 15.0 + pressure;
        // If next item is small and this bin would be fresh, slight relief
        if next_item_size > 0 && next_item_size <= item_size {
            score -= 5.0;
        }
    } else {
        // mild reward for keeping bin count low by reusing bins
        score -= 2.0 * (open_bins_count as f64 / (open_bins_count as f64 + 4.0));
    }

    // Mean-residual coupling: if this bin's residual is far below the mean,
    // it is already fragmented; prefer filling fragmented bins first.
    let residual_diff = mean_residual - bin_residual as f64;
    score += 0.15 * residual_diff;

    // Lookahead: if next item could exactly fit the post-residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // next item fits in the gap -> gap is not dead
        score -= 8.0;
    }

    // Stream progression: late in the stream, be more aggressive about closing
    // bins tightly (dead space matters more when few items remain).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual <= 10 {
        score += 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: if next item exactly fills the new residual, strong reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 800.0;
        } else if next_item_size <= post_residual {
            score -= 120.0 - (post_residual - next_item_size) as f64 * 2.0;
        } else {
            // next item won't fit here: penalize large dead space
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    } else {
        // last item: prefer minimal residual
        score += 0.0;
    }

    // Relative-to-mean coupling: bins tighter than average are more valuable to preserve
    let rel = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += rel * 60.0;

    // Last-chance bin bonus: if this is the only bin that fits, avoid opening new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // Penalize opening a new bin when decent fits exist (unless stream is young)
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let pressure = if fitting_bins_count > 0 { 180.0 * (1.0 - progress).max(0.2) } else { -50.0 };
        score += pressure;
    }

    // Prefer filling bins that are already quite full (small residual waste)
    score += (bin_residual as f64 / bin_capacity as f64) * 20.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let mut score = post_residual as f64;

    // Lookahead: reward bins that can also host the next item (chain fit)
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 4.0 + next_item_size as f64 * 0.05;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // penalize leaving a sliver too small for the upcoming item (dead space)
        score += 2.0 + (next_item_size - post_residual) as f64 * 0.03;
    }

    // Last-chance bin: strongly reward using the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 3.0 + item_size as f64 * 0.02;
    }

    // New-bin candidate: mild penalty so good existing fits win,
    // penalty grows over time (avoid bin sprawl late in stream)
    if bin_residual == bin_capacity {
        score += 2.0 + 3.0 * progress + 0.05 * open_bins_count as f64;
    }

    // Non-linear dead-space penalty: cubic in wasted fraction
    if post_residual > 0 {
        let frac = post_residual as f64 / bin_capacity as f64;
        score += frac.powi(3) * 5.0;
    }

    // Prefer bins whose residual deviates below the mean (tighter bins first)
    score += 0.01 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let base = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let poly = base * base * (1.0 + 3.0 * progress) + base * (1.0 - progress) * 0.5;

    // Reward tight fits: subtract when post_residual is small relative to capacity.
    let mut score = poly * cap * 0.5;

    // Prefer filling bins with larger residual when many bins are open (bin consolidation).
    score += (open_bins_count as f64) * base * 2.0;

    // Coupling with mean residual: penalize bins far from the mean (encourages uniformity).
    let mean_norm = mean_residual / cap;
    score += (base - mean_norm).abs() * cap * 0.3;

    // Lookahead: if next item fits perfectly in the post residual, reward strongly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (pr - nxt).abs() < 1.0 {
            score -= 25.0;
        } else if nxt <= pr {
            score -= (1.0 - (pr - nxt) / cap) * 10.0;
        } else {
            // Next item won't fit here; mildly penalize leaving a large unusable gap.
            score += base * 5.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0 + 20.0 * (1.0 - base);
    }

    // Penalize opening a brand-new bin, more so early in the stream when consolidation matters.
    if bin_residual == bin_capacity {
        score += 60.0 * (1.0 - 0.5 * progress) + (open_bins_count as f64) * 3.0;
        // Allow new bin if it would be nearly filled by current + next item.
        if next_item_size > 0 && (item_size as f64 + next_item_size as f64) >= cap * 0.95 {
            score -= 70.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bucket by capacity fractions (1/4, 1/2, 3/4)
    let q = post_residual * 4 / bin_capacity;
    match q {
        0 => score -= 30.0,              // near-perfect fill
        1 => score -= 5.0,               // small dead space
        2 => score += 8.0,               // half-ish residual: reusable
        _ => score += 20.0,              // large residual wasted on big item
    }

    // Integer-division class: residual mod common item sizes (10, 20, 25, 50)
    let harmonics = [(10u32, 6.0f64), (20, 5.0), (25, 5.0), (50, 4.0)];
    for (m, w) in harmonics.iter() {
        let r = post_residual % m;
        if r == 0 {
            score -= w; // residual aligns with harmonic class -> likely reusable
        } else if r <= 3 {
            score += w * 0.8; // tiny unusable sliver
        }
    }

    // Lookahead coupling: can next item exactly fill post_residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // perfect chain
        } else if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            score -= 10.0 - (slack as f64).min(10.0);
            // harmonic check on chain residual
            if (post_residual - next_item_size) % 10 == 0 {
                score -= 6.0;
            }
        } else {
            score += 12.0; // next item won't fit here
        }
    }

    // Last-chance bin before opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only prefer it when residuals are fragmented
    if bin_residual == bin_capacity {
        let frag = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        score = 45.0 + 25.0 * frag + (open_bins_count as f64) * 0.5;
        if next_item_size > 0 && next_item_size >= 60 {
            score -= 10.0; // big item coming: fresh bin valuable
        }
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Stream progression: be greedier early, more conservative late
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.15 * (1.0 - t) - 0.10 * t;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps (< 10 or < next item).
    let dead_threshold = 10u32;
    if post_residual < dead_threshold {
        score += 50.0; // dead space, gap unusable forever
    }

    // Lookahead: strongly reward bins whose post_residual fits the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= (next_item_size as f64) * 0.8;
        } else if post_residual > 0 {
            score += 8.0; // gap can't fit lookahead: likely dead
        }
        // Perfect chain: item + next item exactly fills the bin
        if item_size + next_item_size == bin_residual {
            score -= 25.0;
        }
    } else {
        // Last item: reward near-perfect fills heavily
        if post_residual == 0 {
            score -= 60.0;
        }
    }

    // Reward exact fills
    if post_residual == 0 {
        score -= 40.0;
    }

    // Open-bin pressure: fewer open bins preferred; discourage spreading load
    score += (open_bins_count as f64) * 0.5;

    // Last-chance bin: if this is the only bin that fits, avoid opening a new one
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: make it unattractive unless it enables a much better packing
    if bin_residual == bin_capacity {
        score += 15.0;
        // but a new bin is fine late in the stream if open bins are tight
        let progress = step_index as f64 / total_items.max(1) as f64;
        if post_residual as f64 >= (bin_capacity as f64 - mean_residual) * 0.5 {
            score -= 5.0 * progress;
        }
    }

    // Mild tightness reward relative to mean residual
    score -= (mean_residual - post_residual as f64).max(0.0) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual already favored).

    // Aggressive 2-step lookahead: strongly reward when the next item
    // exactly fills the post_residual (perfect 2-item chain).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chain: item + next item fill bin
        } else if next_item_size < post_residual {
            // next item fits, but leaves another gap: partial reward
            let two_step_waste = (post_residual - next_item_size) as f64;
            score -= 25.0 - 0.5 * two_step_waste;
        } else {
            // next item cannot use the leftover: penalize dead space,
            // worse when the gap is small (unusable sliver)
            let gap = post_residual as f64;
            if gap > 0.0 && gap < next_item_size as f64 {
                let sliver = (next_item_size - post_residual) as f64;
                score += 0.6 * sliver.min(30.0);
            }
        }
    }

    // Compare residual against mean residual of open bins:
    // using a bin with below-average residual consolidates space.
    if (post_residual as f64) < mean_residual {
        score -= 4.0;
    } else {
        score += 2.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    // or the stream is early and many items remain.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let open_pressure = open_bins_count as f64;
        // Opening a new bin is cheap early / when many bins already open,
        // expensive when few bins exist late in the stream.
        score += 8.0 + 30.0 * (1.0 - progress) * (1.0 / (1.0 + open_pressure));
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0; // fresh bin accommodates the lookahead item too
        }
    }

    // Slight preference for keeping many open bins consolidated when
    // mean residual is high (bins are mostly empty anyway).
    score += 0.05 * (mean_residual - post_residual as f64).abs();

    score
}
